begin;
alter table public.exams disable trigger trg_exams_sync_bank;
do $do$ declare r jsonb; e jsonb; h text; begin
  for r in select * from jsonb_array_elements($j$[{"id":601541,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Hiện tượng phóng xạ. Chu kì bán rã","answer":1,"options":["0,21.10<sup>−3</sup> s–1.","0,105.10<sup>−3</sup> s–1.","0,42.10<sup>−3</sup> s–1.","0,84.10<sup>−3</sup> s–1."],"question":"Dược chất phóng xạ flortaucipir (chứa  ${}_9^{18}F$ là đồng vị phóng xạ β+) được tiêm vào bệnh nhân chụp PET. Biết cứ sau 110 phút lượng 189 F trong dược chất giảm đi một nửa. Hằng số phóng xạ của  ${}_9^{18}F$ là","difficulty":"de","explanation":"Hằng số phóng xạ của  ${}_9^{18}F$ là:  $\\lambda =\\frac{ln2}{T}=\\frac{ln2}{110.60}\\approx 0,105.10^{−3}\\left(s^{−1}\\right)$","difficultySource":"ai"},"ex":[{"exam":311,"idx":12,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Hiện tượng phóng xạ. Chu kì bán rã","answer":1,"options":["0,21.10<sup>−3</sup> s–1.","0,105.10<sup>−3</sup> s–1.","0,42.10<sup>−3</sup> s–1.","0,84.10<sup>−3</sup> s–1."],"question":"Dược chất phóng xạ flortaucipir (chứa  ${}_9^{18}F$ là đồng vị phóng xạ β+) được tiêm vào bệnh nhân chụp PET. Biết cứ sau 110 phút lượng 189 F trong dược chất giảm đi một nửa. Hằng số phóng xạ của  ${}_9^{18}F$ là","difficulty":"de","explanation":"Hằng số phóng xạ của  ${}_9^{18}F$ là:  $\\lambda =\\frac{ln2}{T}=\\frac{ln2}{110.60}\\approx 0,105.10^{−3}\\left(s^{−1}\\right)$","difficultySource":"ai"}}]},{"id":601547,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Iodine  ${}_{53}^{131}I$ là chất phóng xạ beta có chu kì bán rã 8,0 ngày, được sử dụng để điều trị các bệnh lý tuyến giáp vì các tế bào tuyến giáp có xu hướng hấp thụ iodine. Sau khi vào cơ thể,  ${}_{53}^{131}I$ chủ yếu đi đến tuyến giáp mà không đến các cơ quan khác của cơ thể và phát ra bức xạ beta tiêu diệt các tế bào tuyến giáp (trong đó có tế bào bất thường) nhưng không ảnh hưởng nhiều đến các mô của cơ quan khác trong cơ thể. Một bệnh nhân ung thư tuyến giáp có liều dùng cho một lần xạ trị là 9,2 µg ${}_{53}^{131}I$ .","difficulty":"trung-binh","statements":[{"text":"Sau khi uống  ${}_{53}^{131}I$ bệnh nhân có thể tiếp xúc gần với mọi người không cần cách li.","answer":false},{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$ là 1,0.10<sup>−6</sup> s–1 (lấy 2 chữ số có nghĩa).","answer":true},{"text":"Độ phóng xạ ban đầu của  ${}_{53}^{131}I$ trong cơ thể người bệnh là 1,1 Ci (lấy 2 chữ số có nghĩa).","answer":true},{"text":"Sau 5 ngày lượng  ${}_{53}^{131}I$ còn lại trong cơ thể người bệnh là 6,3 µg (lấy 2 chữ số có nghĩa).","answer":false}],"explanation":"a) sai<br>a) Sai. Sau khi uống  ${}_{53}^{131}I$  bệnh nhân cần cách li với mọi người xung quanh.<br>b) đúng<br>b) Đúng. Hằng số phóng xạ của  ${}_{53}^{131}I$  là  $\\lambda =\\frac{ln2}{T}=\\frac{ln2}{8.24.60.60}\\approx 1,0.10^{−6}\\left(s^{−1}\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>c) Đúng. Độ phóng xạ ban đầu của  ${}_{53}^{131}I$  trong cơ thể người bệnh là:<br>$H_0=\\lambda .N_0=\\lambda .\\frac{m}{M}.N_A=\\frac{1.10^{−6}.\\frac{9,2.10^{−6}}{131}.6,02.10^{23}}{3,7.10^{10}}\\approx 1,1\\left(Ci\\right)$<br>d) sai<br>d) Sai. Sau 5 ngày lượng  ${}_{53}^{131}I$  còn lại trong cơ thể người bệnh là:<br>$m=m_0.2^{−\\frac{t}{T}}=9,2.2^{−\\frac{5}{8}}=6,0\\left(\\mu g\\right)$","difficultySource":"ai"},"ex":[{"exam":311,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Iodine  ${}_{53}^{131}I$ là chất phóng xạ beta có chu kì bán rã 8,0 ngày, được sử dụng để điều trị các bệnh lý tuyến giáp vì các tế bào tuyến giáp có xu hướng hấp thụ iodine. Sau khi vào cơ thể,  ${}_{53}^{131}I$ chủ yếu đi đến tuyến giáp mà không đến các cơ quan khác của cơ thể và phát ra bức xạ beta tiêu diệt các tế bào tuyến giáp (trong đó có tế bào bất thường) nhưng không ảnh hưởng nhiều đến các mô của cơ quan khác trong cơ thể. Một bệnh nhân ung thư tuyến giáp có liều dùng cho một lần xạ trị là 9,2 µg ${}_{53}^{131}I$ .","difficulty":"trung-binh","statements":[{"text":"Sau khi uống  ${}_{53}^{131}I$ bệnh nhân có thể tiếp xúc gần với mọi người không cần cách li.","answer":false},{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$ là 1,0.10<sup>−6</sup> s–1 (lấy 2 chữ số có nghĩa).","answer":true},{"text":"Độ phóng xạ ban đầu của  ${}_{53}^{131}I$ trong cơ thể người bệnh là 1,1 Ci (lấy 2 chữ số có nghĩa).","answer":true},{"text":"Sau 5 ngày lượng  ${}_{53}^{131}I$ còn lại trong cơ thể người bệnh là 6,3 µg (lấy 2 chữ số có nghĩa).","answer":false}],"explanation":"a) sai<br>a) Sai. Sau khi uống  ${}_{53}^{131}I$  bệnh nhân cần cách li với mọi người xung quanh.<br>b) đúng<br>b) Đúng. Hằng số phóng xạ của  ${}_{53}^{131}I$  là  $\\lambda =\\frac{ln2}{T}=\\frac{ln2}{8.24.60.60}\\approx 1,0.10^{−6}\\left(s^{−1}\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>c) Đúng. Độ phóng xạ ban đầu của  ${}_{53}^{131}I$  trong cơ thể người bệnh là:<br>$H_0=\\lambda .N_0=\\lambda .\\frac{m}{M}.N_A=\\frac{1.10^{−6}.\\frac{9,2.10^{−6}}{131}.6,02.10^{23}}{3,7.10^{10}}\\approx 1,1\\left(Ci\\right)$<br>d) sai<br>d) Sai. Sau 5 ngày lượng  ${}_{53}^{131}I$  còn lại trong cơ thể người bệnh là:<br>$m=m_0.2^{−\\frac{t}{T}}=9,2.2^{−\\frac{5}{8}}=6,0\\left(\\mu g\\right)$","difficultySource":"ai"}}]},{"id":601549,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Hình ảnh dưới đây là ống phát tia X, khi sợi nung FF' được đốt nóng, electron bức xạ nhiệt ra khỏi cathode (K), khi ra khỏi cathode electron được tăng tốc bởi điện trường mạnh giữa cathode và anode (A), electron thu được động năng lớn và đập vào anode tạo ra tia X. Do hiệu suất phát tia X của ống rất thấp chỉ là 1,0%, phần năng lượng còn lại làm nóng anode vì vậy luôn có dòng nước chảy vào và chảy ra để làm nguội anode. Biết hiệu điện thế UAK =1,0.10<sup>4</sup> V cường độ dòng điện qua ống I = 10 A, nhiệt độ nước chảy vào 250C, nhiệt độ nước chảy ra 550C, nhiệt dung riêng của nước là 4200 J/kg.K, khối lượng riêng của nước 1000 kg/m3.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045706065-hinh-9.jpg\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Độ tăng nhiệt độ của nước khi ra khỏi anode là 303 K.","answer":false},{"text":"Công suất tiêu thụ điện năng của ống 105 W.","answer":true},{"text":"Nhiệt lượng mà anode truyền cho dòng nước trong mỗi giây là 100 kJ.","answer":false},{"text":"Lưu lượng nước chảy vào làm mát anode là 0,79 lít/giây (lấy hai chữ số có nghĩa).","answer":true}],"explanation":"a) sai<br>a) Sai. Độ tăng nhiệt độ của nước khi ra khỏi anode là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Delta t(^0C)=\\Delta T(K)=55−25=30$<br>b) đúng<br>b) Đúng. Công suất tiêu thụ điện năng của ống là: P = U.I = 1.104.10 = 10(W)<br>c) sai<br>c) Sai. Nhiệt lượng mà anode truyền cho dòng nước trong mỗi giây là<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Q = 0,99.P.t = 0,99.105.1 = 99000 (J) = 99(kJ)<br>d) đúng<br>d) Đúng. Ta có:  $Q=m.c.\\Delta t\\Rightarrow m=\\frac{Q}{c.\\Delta t}=\\frac{99000}{4200.30}\\approx 0,79\\left(kg/s\\right)=0,79\\left(lit/s\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":311,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Hình ảnh dưới đây là ống phát tia X, khi sợi nung FF' được đốt nóng, electron bức xạ nhiệt ra khỏi cathode (K), khi ra khỏi cathode electron được tăng tốc bởi điện trường mạnh giữa cathode và anode (A), electron thu được động năng lớn và đập vào anode tạo ra tia X. Do hiệu suất phát tia X của ống rất thấp chỉ là 1,0%, phần năng lượng còn lại làm nóng anode vì vậy luôn có dòng nước chảy vào và chảy ra để làm nguội anode. Biết hiệu điện thế UAK =1,0.10<sup>4</sup> V cường độ dòng điện qua ống I = 10 A, nhiệt độ nước chảy vào 250C, nhiệt độ nước chảy ra 550C, nhiệt dung riêng của nước là 4200 J/kg.K, khối lượng riêng của nước 1000 kg/m3.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045706065-hinh-9.jpg\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Độ tăng nhiệt độ của nước khi ra khỏi anode là 303 K.","answer":false},{"text":"Công suất tiêu thụ điện năng của ống 105 W.","answer":true},{"text":"Nhiệt lượng mà anode truyền cho dòng nước trong mỗi giây là 100 kJ.","answer":false},{"text":"Lưu lượng nước chảy vào làm mát anode là 0,79 lít/giây (lấy hai chữ số có nghĩa).","answer":true}],"explanation":"a) sai<br>a) Sai. Độ tăng nhiệt độ của nước khi ra khỏi anode là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Delta t(^0C)=\\Delta T(K)=55−25=30$<br>b) đúng<br>b) Đúng. Công suất tiêu thụ điện năng của ống là: P = U.I = 1.104.10 = 10(W)<br>c) sai<br>c) Sai. Nhiệt lượng mà anode truyền cho dòng nước trong mỗi giây là<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Q = 0,99.P.t = 0,99.105.1 = 99000 (J) = 99(kJ)<br>d) đúng<br>d) Đúng. Ta có:  $Q=m.c.\\Delta t\\Rightarrow m=\\frac{Q}{c.\\Delta t}=\\frac{99000}{4200.30}\\approx 0,79\\left(kg/s\\right)=0,79\\left(lit/s\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":601550,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Một nhóm học sinh làm thí nghiệm gồm các dụng cụ như hình bên để khảo sát sự phụ thuộc của áp suất p của một lượng khí (đo được nhờ áp kế) theo nhiệt độ tuyệt đối T (đo được nhờ nhiệt kế điện tử) của nó ở một thể tích không đổi, thu được kết quả như ở bảng sau đây:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045706226-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Các thao tác thí nghiệm: Cố định pit-tông, bật bếp điện để đun nóng nước, khuấy đều nước, đọc số chỉ của áp kế và nhiệt độ tương ứng ở các thời điểm, ghi vào bảng số liệu.","answer":true},{"text":"Áp suất tỉ lệ thuận với nhiệt độ tuyệt đối, trong đó hệ số tỉ lệ có giá trị 4,0 kPa/K (sai số không quá 5%).","answer":false},{"text":"Đồ thị biểu diễn mối liên hệ giữa p và T có dạng như hình vẽ.","answer":true},{"text":"Mật độ phân tử khí trong xi lanh ở thí nghiệm trên là 2,5.10<sup>26</sup> hạt/m3 (lấy hai chữ số có nghĩa và sai số  không quá 5%).","answer":true}],"explanation":"a) đúng<br>a) Đúng. Các thao tác thí nghiệm: Cố định pit-tông, bật bếp điện để đun nóng nước, khuấy đều nước, đọc số chỉ của áp kế và nhiệt độ tương ứng ở các thời điểm, ghi vào bảng số liệu.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>b) Sai. Áp suất tỉ lệ thuận với nhiệt độ tuyệt đối, trong đó hệ số tỉ lệ có giá trị:<br>$k=\\frac{\\Delta p}{\\Delta T}=\\frac{1090−1060}{310−300}=3\\left(kPa/K\\right)$<br>c) đúng<br>c) Đúng.<br>d) đúng<br>d) Đúng. Ta có:  $pV=nRT\\Rightarrow \\frac{n}{V}=\\frac{p}{RT}\\Rightarrow \\frac{n.N_A}{V}=\\frac{p}{RT}.N_A=\\frac{1090.10^3}{8,31.310}.6,02.10^{23}\\approx 2,5.10^{26}\\left(hat/m^3\\right)$","difficultySource":"ai"},"ex":[{"exam":311,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Một nhóm học sinh làm thí nghiệm gồm các dụng cụ như hình bên để khảo sát sự phụ thuộc của áp suất p của một lượng khí (đo được nhờ áp kế) theo nhiệt độ tuyệt đối T (đo được nhờ nhiệt kế điện tử) của nó ở một thể tích không đổi, thu được kết quả như ở bảng sau đây:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045706226-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Các thao tác thí nghiệm: Cố định pit-tông, bật bếp điện để đun nóng nước, khuấy đều nước, đọc số chỉ của áp kế và nhiệt độ tương ứng ở các thời điểm, ghi vào bảng số liệu.","answer":true},{"text":"Áp suất tỉ lệ thuận với nhiệt độ tuyệt đối, trong đó hệ số tỉ lệ có giá trị 4,0 kPa/K (sai số không quá 5%).","answer":false},{"text":"Đồ thị biểu diễn mối liên hệ giữa p và T có dạng như hình vẽ.","answer":true},{"text":"Mật độ phân tử khí trong xi lanh ở thí nghiệm trên là 2,5.10<sup>26</sup> hạt/m3 (lấy hai chữ số có nghĩa và sai số  không quá 5%).","answer":true}],"explanation":"a) đúng<br>a) Đúng. Các thao tác thí nghiệm: Cố định pit-tông, bật bếp điện để đun nóng nước, khuấy đều nước, đọc số chỉ của áp kế và nhiệt độ tương ứng ở các thời điểm, ghi vào bảng số liệu.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>b) Sai. Áp suất tỉ lệ thuận với nhiệt độ tuyệt đối, trong đó hệ số tỉ lệ có giá trị:<br>$k=\\frac{\\Delta p}{\\Delta T}=\\frac{1090−1060}{310−300}=3\\left(kPa/K\\right)$<br>c) đúng<br>c) Đúng.<br>d) đúng<br>d) Đúng. Ta có:  $pV=nRT\\Rightarrow \\frac{n}{V}=\\frac{p}{RT}\\Rightarrow \\frac{n.N_A}{V}=\\frac{p}{RT}.N_A=\\frac{1090.10^3}{8,31.310}.6,02.10^{23}\\approx 2,5.10^{26}\\left(hat/m^3\\right)$","difficultySource":"ai"}}]},{"id":601554,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phản ứng phân hạch, phản ứng nhiệt hạch","answer":"942","question":"Mỗi phản ứng nhiệt hạch  ${}_1^2D+{}_1^2D\\rightarrow {}_2^3He+{}_0^1n$ toả ra 17,6 MeV. Nước biển có chứa 0,0150% nước nặng D2O là nhiên liệu cho phản ứng nhiệt hạch trên. Khi tổng hợp  ${}_2^3He$  từ 2,00 kg nước biển bằng phản ứng trên thì năng lượng toả ra tương đương đốt cháy hoàn toàn a (kg) than đá. Biết mỗi kg than đá đốt cháy hoàn toàn toả ra năng lượng 27,0.10<sup>6</sup> J. Lấy e = 1,60.10<sup>−19</sup>C và khối lượng mol của D2O là 20,0 g/mol. Giá trị của a là bao nhiêu (lấy 3 chữ số có nghĩa)?","difficulty":"kho","explanation":"Khối lượng nước nặng có trong 2kg nước biển là: 2000.0,015% = 0,3 (g)<br>Vì số phản ứng bằng số hạt nước nặng nên:  $N=\\frac{0,3}{20}.N_A$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Ta có:  $\\frac{0,3}{20}.6,02.10^{23}.17,6.1,6.10^{−13}=a.27.10^6\\Rightarrow a\\approx 942\\left(kg\\right)$","difficultySource":"ai"},"ex":[{"exam":311,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Phản ứng phân hạch, phản ứng nhiệt hạch","answer":"942","question":"Mỗi phản ứng nhiệt hạch  ${}_1^2D+{}_1^2D\\rightarrow {}_2^3He+{}_0^1n$ toả ra 17,6 MeV. Nước biển có chứa 0,0150% nước nặng D2O là nhiên liệu cho phản ứng nhiệt hạch trên. Khi tổng hợp  ${}_2^3He$  từ 2,00 kg nước biển bằng phản ứng trên thì năng lượng toả ra tương đương đốt cháy hoàn toàn a (kg) than đá. Biết mỗi kg than đá đốt cháy hoàn toàn toả ra năng lượng 27,0.10<sup>6</sup> J. Lấy e = 1,60.10<sup>−19</sup>C và khối lượng mol của D2O là 20,0 g/mol. Giá trị của a là bao nhiêu (lấy 3 chữ số có nghĩa)?","difficulty":"kho","explanation":"Khối lượng nước nặng có trong 2kg nước biển là: 2000.0,015% = 0,3 (g)<br>Vì số phản ứng bằng số hạt nước nặng nên:  $N=\\frac{0,3}{20}.N_A$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Ta có:  $\\frac{0,3}{20}.6,02.10^{23}.17,6.1,6.10^{−13}=a.27.10^6\\Rightarrow a\\approx 942\\left(kg\\right)$","difficultySource":"ai"}}]},{"id":602337,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Các tính chất của phân rã phóng xạ được ứng dụng để chế tạo Pin nguyên tử. Pin nguyên tử có độ tin cậy cao, dung lượng pin có thể duy trì ở mức cao trong thời gian dài khi sử dụng nguồn phóng xạ có chu kì bán rã lớn. Pin thường được sử dụng cho các nhiệm vụ đòi hỏi yêu cầu cao như thiết bị y tế, các chuyến du hành vũ trụ dài ngày. Một Pin nguyên tử có các thông số kĩ thuật cho ở hình bên.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045712016-hinh-17.jpg\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Thông số 2,5 Ci cho biết độ phóng xạ của lượng chất phóng xạ tại thời điểm ban đầu đưa vào pin.","answer":true},{"text":"Pin nguyên tử này sử dụng đồng vị phóng xạ 238Pu.","answer":true},{"text":"Pin được sử dụng cho thiết bị điều hòa nhịp tim trong cơ thể bệnh nhân. Suất điện động của pin tỉ lệ thuận với độ phóng xạ. Người ta sẽ thay pin khi công suất giảm 50% so với giá trị công suất ban đầu. Sau 43,3 năm người bệnh cần mổ để thay pin nguyên tử cho thiết bị điều hòa điện tim. Biết 1 năm có 365 ngày; NA = 6,2.10<sup>23</sup> mol‒1; 1 Ci = 3,7.10<sup>10</sup> Bq.","answer":true},{"text":"Biết chu kì bán rã của đồng vị phóng xạ sử dụng là 87,7 năm. Khối lượng tối thiểu của đồng vị phóng xạ đưa vào pin xấp xỉ là 0,05 g.","answer":false}],"explanation":"a) đúng<br>Thông số 2,5 Ci cho biết độ phóng xạ của lượng chất phóng xạ tại thời điểm ban đầu đưa vào pin.<br>b) đúng<br>Dựa vào thông tỉnh trên hình vẽ.<br>c) đúng<br>Công suất của pin tỉ lệ với bình phương suất điện động. Công suất giảm đi 50% = 0,5 thì suất điện động giảm đi  $\\sqrt{0,5}$ lần. Giá trị này cũng là độ giảm của độ phóng xạ.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Do vậy thời gian cần thay pin là t = T log20,71 ≈ 43,3 năm.<br>d) sai<br>Thông tin trên vỏ hộp cho thấy độ phóng xạ của mẫu là:<br>$\\begin{aligned}\\end{aligned}H=2,5Ci=\\lambda N\\Rightarrow N=\\frac{\\frac{2,5.3,7.10^{10}}{ln2}}{87,7.365.24.3600}\\approx 3,69.10^{20}Website: thukhoadaihoc.vn$<br>Khối lượng tối thiểu của đồng vị phóng xạ được cho vào pin nguyên tử:<br>$\\begin{aligned}\\end{aligned}m=\\frac{N}{N_A}M=\\frac{3,69.10^{20}}{6,02.10^{23}}.238\\approx 0,15gWebsite: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":312,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Các tính chất của phân rã phóng xạ được ứng dụng để chế tạo Pin nguyên tử. Pin nguyên tử có độ tin cậy cao, dung lượng pin có thể duy trì ở mức cao trong thời gian dài khi sử dụng nguồn phóng xạ có chu kì bán rã lớn. Pin thường được sử dụng cho các nhiệm vụ đòi hỏi yêu cầu cao như thiết bị y tế, các chuyến du hành vũ trụ dài ngày. Một Pin nguyên tử có các thông số kĩ thuật cho ở hình bên.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045712016-hinh-17.jpg\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Thông số 2,5 Ci cho biết độ phóng xạ của lượng chất phóng xạ tại thời điểm ban đầu đưa vào pin.","answer":true},{"text":"Pin nguyên tử này sử dụng đồng vị phóng xạ 238Pu.","answer":true},{"text":"Pin được sử dụng cho thiết bị điều hòa nhịp tim trong cơ thể bệnh nhân. Suất điện động của pin tỉ lệ thuận với độ phóng xạ. Người ta sẽ thay pin khi công suất giảm 50% so với giá trị công suất ban đầu. Sau 43,3 năm người bệnh cần mổ để thay pin nguyên tử cho thiết bị điều hòa điện tim. Biết 1 năm có 365 ngày; NA = 6,2.10<sup>23</sup> mol‒1; 1 Ci = 3,7.10<sup>10</sup> Bq.","answer":true},{"text":"Biết chu kì bán rã của đồng vị phóng xạ sử dụng là 87,7 năm. Khối lượng tối thiểu của đồng vị phóng xạ đưa vào pin xấp xỉ là 0,05 g.","answer":false}],"explanation":"a) đúng<br>Thông số 2,5 Ci cho biết độ phóng xạ của lượng chất phóng xạ tại thời điểm ban đầu đưa vào pin.<br>b) đúng<br>Dựa vào thông tỉnh trên hình vẽ.<br>c) đúng<br>Công suất của pin tỉ lệ với bình phương suất điện động. Công suất giảm đi 50% = 0,5 thì suất điện động giảm đi  $\\sqrt{0,5}$ lần. Giá trị này cũng là độ giảm của độ phóng xạ.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Do vậy thời gian cần thay pin là t = T log20,71 ≈ 43,3 năm.<br>d) sai<br>Thông tin trên vỏ hộp cho thấy độ phóng xạ của mẫu là:<br>$\\begin{aligned}\\end{aligned}H=2,5Ci=\\lambda N\\Rightarrow N=\\frac{\\frac{2,5.3,7.10^{10}}{ln2}}{87,7.365.24.3600}\\approx 3,69.10^{20}Website: thukhoadaihoc.vn$<br>Khối lượng tối thiểu của đồng vị phóng xạ được cho vào pin nguyên tử:<br>$\\begin{aligned}\\end{aligned}m=\\frac{N}{N_A}M=\\frac{3,69.10^{20}}{6,02.10^{23}}.238\\approx 0,15gWebsite: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":602338,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"264","question":"Trong một giờ thực hành, một bạn học sinh tiến hành thí nghiệm làm đông đặc nước không cần dùng tủ lạnh như sau. Dùng một bình đựng 0,300 kg nước tinh khiết ở 0°C, sau đó hút không khí và hơi nước trong bình ra ngoài. Lấy nhiệt nóng chảy riêng của nước là 3,34.10<sup>5</sup> J/kg và nhiệt hóa hơi riêng của nước là 2,48.10<sup>6</sup> J/kg. Bỏ qua sự trao đổi nhiệt với môi trường bên ngoài. Khối lượng nước được làm đông đặc trong bình là bao nhiêu g? (Làm tròn đến phần nguyên).","difficulty":"trung-binh","explanation":"Nhiệt lượng do nước thu vào để biến thành hơi đúng bằng nhiệt lượng do nước tỏa ra để đông đặc lại, ta có<br>$Q_{toa}=Q_{thu}\\Leftrightarrow m_d\\lambda =m_hL$<br>$\\begin{aligned}\\end{aligned}\\Leftrightarrow m_d.3,34.10^5=\\left(0,3−m_d\\right).2,48.10^6\\Rightarrow m_d\\approx 0,2643\\left(kg\\right)\\approx 264\\left(g\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":312,"idx":19,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"264","question":"Trong một giờ thực hành, một bạn học sinh tiến hành thí nghiệm làm đông đặc nước không cần dùng tủ lạnh như sau. Dùng một bình đựng 0,300 kg nước tinh khiết ở 0°C, sau đó hút không khí và hơi nước trong bình ra ngoài. Lấy nhiệt nóng chảy riêng của nước là 3,34.10<sup>5</sup> J/kg và nhiệt hóa hơi riêng của nước là 2,48.10<sup>6</sup> J/kg. Bỏ qua sự trao đổi nhiệt với môi trường bên ngoài. Khối lượng nước được làm đông đặc trong bình là bao nhiêu g? (Làm tròn đến phần nguyên).","difficulty":"trung-binh","explanation":"Nhiệt lượng do nước thu vào để biến thành hơi đúng bằng nhiệt lượng do nước tỏa ra để đông đặc lại, ta có<br>$Q_{toa}=Q_{thu}\\Leftrightarrow m_d\\lambda =m_hL$<br>$\\begin{aligned}\\end{aligned}\\Leftrightarrow m_d.3,34.10^5=\\left(0,3−m_d\\right).2,48.10^6\\Rightarrow m_d\\approx 0,2643\\left(kg\\right)\\approx 264\\left(g\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":602339,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"2022","question":"Một nhà máy điện hạt nhân dùng năng lượng phân hạch của hạt nhân  ${}_{92}^{235}U$  với hiệu suất 30%. Trung bình mỗi hạt  ${}_{92}^{235}U$  phân hạch tỏa ra năng lượng 200 MeV, mỗi tháng (30 ngày) hoạt động nhà máy tiêu thụ một khối lượng  ${}_{92}^{235}U$  nguyên chất là 213 kg. Cho biết số Avôgađrô NA = 6,023.10<sup>23</sup> mol‒1. Công suất phát điện của nhà máy là bao nhiêu MW? (Làm tròn đến phần nguyên).","difficulty":"kho","explanation":"Năng lượng nhiệt tạo ra do phân hạch toàn bộ Uranium là:<br>$W=N\\Delta E=\\frac{m}{M}N_A\\Delta E$<br>Công suất phát điện của nhà máy là:<br>$\\begin{aligned}\\end{aligned}H=\\frac{W_{Ci}}{W}=\\frac{Pt}{\\frac{m}{M}N_A\\Delta E}\\Leftrightarrow 0,3=\\frac{P.10^6.30.24.3600}{\\frac{213.10^3}{235}.6,023.10^{23}.200.1,6.10^{−13}}Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow P\\approx 2022\\left(MW\\right)$","difficultySource":"ai"},"ex":[{"exam":312,"idx":20,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"2022","question":"Một nhà máy điện hạt nhân dùng năng lượng phân hạch của hạt nhân  ${}_{92}^{235}U$  với hiệu suất 30%. Trung bình mỗi hạt  ${}_{92}^{235}U$  phân hạch tỏa ra năng lượng 200 MeV, mỗi tháng (30 ngày) hoạt động nhà máy tiêu thụ một khối lượng  ${}_{92}^{235}U$  nguyên chất là 213 kg. Cho biết số Avôgađrô NA = 6,023.10<sup>23</sup> mol‒1. Công suất phát điện của nhà máy là bao nhiêu MW? (Làm tròn đến phần nguyên).","difficulty":"kho","explanation":"Năng lượng nhiệt tạo ra do phân hạch toàn bộ Uranium là:<br>$W=N\\Delta E=\\frac{m}{M}N_A\\Delta E$<br>Công suất phát điện của nhà máy là:<br>$\\begin{aligned}\\end{aligned}H=\\frac{W_{Ci}}{W}=\\frac{Pt}{\\frac{m}{M}N_A\\Delta E}\\Leftrightarrow 0,3=\\frac{P.10^6.30.24.3600}{\\frac{213.10^3}{235}.6,023.10^{23}.200.1,6.10^{−13}}Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow P\\approx 2022\\left(MW\\right)$","difficultySource":"ai"}}]},{"id":602600,"nq":{"form":"ly_thuyet","type":"true_false","topic":"Cảm ứng từ và đơn vị tesla","question":"Một nhóm học sinh tiến hành thí nghiệm đo độ lớn thành phần nằm ngang của cảm ứng từ Trái Đất. Họ lựa chọn bộ thí nghiệm gồm khung dây tròn đặt trong mặt phẳng thẳng đứng có N vòng dây, kim nam chậm đặt ở tâm của khung dây, nguồn điện một chiều cấp điện cho khung dây, ampe kế. Ban đầu chưa có dòng điện, điều chỉnh khung dây sao cho trục nối hai cực của kim nam châm trùng với đường kính của khung dây. Cho dòng điện chạy vào các vòng dây có chiều như hình. Khi đó kim nam châm lệch so với hướng Đông Tây góc α. Trên hình mô tả hướng Đông, Tây, Nam, Bắc địa lý. Biết rằng độ lớn cảm ứng từ do dòng điện trong khung dây tròn tạo ra ở tâm tính theo công thức:  $B=2\\pi .10^{−7}.\\frac{N.i}{R}$ (R là bán kính khung dây, i là cường độ dòng điện trong mỗi vòng dây).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045716499-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Cực từ nam (S) của từ trường Trái Đất nằm về phía cực Bắc địa lý.","answer":true},{"text":"Đường sức do dòng điện trong khung dây tạo ra đi qua tâm có chiều từ Tây đến Đông.","answer":false},{"text":"Tanα tỉ lệ nghịch với cường độ dòng điện chạy trong khung dây.","answer":true},{"text":"Biết N = 200 vòng dây, ampe kế chỉ 25,0 mA, đường kính khung dây 18,0 cm, α = 450. Độ lớn thành phần nằm ngang của từ trường Trái Đất đo được là 3,50.10<sup>−5</sup>T.","answer":false}],"explanation":"a) đúng<br>Vì cực từ Nam của Trái Đất nằm gần cực Bắc địa lý.<br>b) sai<br>Áp dụng quy tắc bàn tay phải, vectơ cảm ứng từ do dòng điện tạo ra trong khung dây đi qua tâm có chiều từ Đông sang Tây.<br>c) đúng<br>Ta có:  $tan\\alpha =\\frac{B_T}{B}=\\frac{B_T.R}{2\\pi .10^{−7}.I.i}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>→ Với BT, R, N không đổi thì tang tỉ lệ nghịch với cường độ dòng điện chạy trong khung dây.<br>d) sai<br>Độ lớn thành phần nằm ngang của từ trường Trái Đất là:<br>$\\begin{aligned}\\end{aligned}B_T=\\frac{2\\pi .10^{−7}.N.i.tan\\alpha }{R}=\\frac{2\\pi .10^{−7}.200.10^{−3}.tan45^0}{9.10^{−2}}\\approx 3,49.10^{−5}\\left(T\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":313,"idx":20,"el":{"form":"ly_thuyet","type":"true_false","topic":"Cảm ứng từ và đơn vị tesla","question":"Một nhóm học sinh tiến hành thí nghiệm đo độ lớn thành phần nằm ngang của cảm ứng từ Trái Đất. Họ lựa chọn bộ thí nghiệm gồm khung dây tròn đặt trong mặt phẳng thẳng đứng có N vòng dây, kim nam chậm đặt ở tâm của khung dây, nguồn điện một chiều cấp điện cho khung dây, ampe kế. Ban đầu chưa có dòng điện, điều chỉnh khung dây sao cho trục nối hai cực của kim nam châm trùng với đường kính của khung dây. Cho dòng điện chạy vào các vòng dây có chiều như hình. Khi đó kim nam châm lệch so với hướng Đông Tây góc α. Trên hình mô tả hướng Đông, Tây, Nam, Bắc địa lý. Biết rằng độ lớn cảm ứng từ do dòng điện trong khung dây tròn tạo ra ở tâm tính theo công thức:  $B=2\\pi .10^{−7}.\\frac{N.i}{R}$ (R là bán kính khung dây, i là cường độ dòng điện trong mỗi vòng dây).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045716499-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Cực từ nam (S) của từ trường Trái Đất nằm về phía cực Bắc địa lý.","answer":true},{"text":"Đường sức do dòng điện trong khung dây tạo ra đi qua tâm có chiều từ Tây đến Đông.","answer":false},{"text":"Tanα tỉ lệ nghịch với cường độ dòng điện chạy trong khung dây.","answer":true},{"text":"Biết N = 200 vòng dây, ampe kế chỉ 25,0 mA, đường kính khung dây 18,0 cm, α = 450. Độ lớn thành phần nằm ngang của từ trường Trái Đất đo được là 3,50.10<sup>−5</sup>T.","answer":false}],"explanation":"a) đúng<br>Vì cực từ Nam của Trái Đất nằm gần cực Bắc địa lý.<br>b) sai<br>Áp dụng quy tắc bàn tay phải, vectơ cảm ứng từ do dòng điện tạo ra trong khung dây đi qua tâm có chiều từ Đông sang Tây.<br>c) đúng<br>Ta có:  $tan\\alpha =\\frac{B_T}{B}=\\frac{B_T.R}{2\\pi .10^{−7}.I.i}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>→ Với BT, R, N không đổi thì tang tỉ lệ nghịch với cường độ dòng điện chạy trong khung dây.<br>d) sai<br>Độ lớn thành phần nằm ngang của từ trường Trái Đất là:<br>$\\begin{aligned}\\end{aligned}B_T=\\frac{2\\pi .10^{−7}.N.i.tan\\alpha }{R}=\\frac{2\\pi .10^{−7}.200.10^{−3}.tan45^0}{9.10^{−2}}\\approx 3,49.10^{−5}\\left(T\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":602602,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"334","question":"Cho biết nhiệt nóng chảy riêng của nước đá là 334.103 J/kg. Khi một kilogam nước đá nóng chảy hoàn toàn ở nhiệt độ nóng chảy thì cần truyền nhiệt lượng là x.10<sup>3</sup> J. Giá trị của x là bao nhiêu?","difficulty":"de","explanation":"Nhiệt lượng cần truyền cho 1 kg nước đá để nó nóng chảy hoàn toàn là:<br>$Q=m\\lambda =1.334.10^3=334.10^3\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":313,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"334","question":"Cho biết nhiệt nóng chảy riêng của nước đá là 334.103 J/kg. Khi một kilogam nước đá nóng chảy hoàn toàn ở nhiệt độ nóng chảy thì cần truyền nhiệt lượng là x.10<sup>3</sup> J. Giá trị của x là bao nhiêu?","difficulty":"de","explanation":"Nhiệt lượng cần truyền cho 1 kg nước đá để nó nóng chảy hoàn toàn là:<br>$Q=m\\lambda =1.334.10^3=334.10^3\\left(J\\right)$","difficultySource":"ai"}}]},{"id":604391,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","answer":0,"options":["8,8.10<sup>25</sup>.","2,2.10<sup>25</sup>.","1.2.10<sup>25</sup>","4,4.10<sup>25</sup>."],"question":"Biết số Avogadro là NA = 6,022.10<sup>23</sup> mol-1, khối lượng mol của uranium  ${}_{92}^{238}U$ là 238 g/mol. Số neutron trong 238 gam  ${}_{92}^{238}U$  là","difficulty":"trung-binh","explanation":"Số neutron có trong 238g  ${}_{92}^{238}U$  là:<br>$N_n=\\left(A−Z\\right)N=\\left(A−Z\\right).\\frac{m}{M}.N_A=\\left(238−92\\right).\\frac{238}{238}.6,022.10^{23}\\approx 8,8.10^{25}$","difficultySource":"ai"},"ex":[{"exam":315,"idx":1,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Kí hiệu hạt nhân, số nuclôn, đồng vị","answer":0,"options":["8,8.10<sup>25</sup>.","2,2.10<sup>25</sup>.","1.2.10<sup>25</sup>","4,4.10<sup>25</sup>."],"question":"Biết số Avogadro là NA = 6,022.10<sup>23</sup> mol-1, khối lượng mol của uranium  ${}_{92}^{238}U$ là 238 g/mol. Số neutron trong 238 gam  ${}_{92}^{238}U$  là","difficulty":"trung-binh","explanation":"Số neutron có trong 238g  ${}_{92}^{238}U$  là:<br>$N_n=\\left(A−Z\\right)N=\\left(A−Z\\right).\\frac{m}{M}.N_A=\\left(238−92\\right).\\frac{238}{238}.6,022.10^{23}\\approx 8,8.10^{25}$","difficultySource":"ai"}}]},{"id":604404,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["23.105 J.","2,3.10<sup>6</sup> J.","23.106 J.","2,3.10<sup>5</sup> J."],"question":"Biết nhiệt hơi riêng của nước là L= 2,3.10<sup>6</sup> J/kg. Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 100 g nước ở 100°C là","difficulty":"de","explanation":"Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 100 g nước ở 100C là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Q =  mλ = 0,1.2,3.10<sup>6</sup> = 2,3.10<sup>5</sup> (J)","difficultySource":"ai"},"ex":[{"exam":315,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["23.105 J.","2,3.10<sup>6</sup> J.","23.106 J.","2,3.10<sup>5</sup> J."],"question":"Biết nhiệt hơi riêng của nước là L= 2,3.10<sup>6</sup> J/kg. Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 100 g nước ở 100°C là","difficulty":"de","explanation":"Nhiệt lượng cần cung cấp để làm bay hơi hoàn toàn 100 g nước ở 100C là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Q =  mλ = 0,1.2,3.10<sup>6</sup> = 2,3.10<sup>5</sup> (J)","difficultySource":"ai"}}]},{"id":604410,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Một lọ giác hơi (được cơ sở điều trị bằng phương pháp cổ truyền sử dụng) do chênh lệch áp suất trong và ngoài lọ nên dính vào bề mặt da lưng của người bệnh, điều này được tạo ra bằng cách ban đầu lọ được hơ nóng bên trong và nhanh chóng úp miệng hở của lọ vào vùng da cần tác động. Tại thời điểm áp vào da, không khí trong lọ được làm nóng đến nhiệt độ t = 3530C và nhiệt độ của không khí môi trường xung quanh là t0 = 27,0°C, Áp suất khí quyển po = 1,0.10<sup>3</sup> Pa. Diện tích phần miệng hở của lọ là S = 28,0 cm. Bỏ qua sự thay đổi thể tích không khí trong bình (do sự phồng của bề mặt phần da bên trong miệng hở của lọ).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045734761-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Áp suất khí trong lọ được áp vào da, khi có nhiệt độ bằng nhiệt độ của môi trường gần bằng 4,8.10<sup>4</sup> Pa.","answer":true},{"text":"Lực hút tối đa lên mặt da là 156 N.","answer":false},{"text":"Thực tế, do bề mặt da bị phồng lên bên trong miệng của lọ nên thể tích khí trong lọ bị giảm 10%. Chênh lệch áp suất khí trong lọ và ngoài lọ là 5,3.10<sup>4</sup> Pa.","answer":false},{"text":"Chênh lệch áp suất trong và ngoài lọ giác hơi tạo lực hút làm máu dưới da tăng cường đến nơi miệng lọ giác hơi bám vào, từ đó tạo ra tác dụng lưu thông khí huyết, kích thích hệ thống miễn dịch giúp cơ thể đối phó với vi khuẩn, virus.","answer":true}],"explanation":"a) đúng<br>Ban đầu, ở nhiệt độ 353°C thì áp suất của khí trong lọ = áp suất khí quyển = 105 Pa. Giả sử rằng thể tích không khí bên trong lọ không thay đổi, ta có áp suất của khí trong lọ khi bằng nhiệt độ môi trường là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$p=\\frac{T_0}{T}p_0=\\frac{27+27}{353+273}.10^5=\\frac{15}{313}.10^6\\approx 4,8.10^4\\left(Pa\\right)$<br>b) sai<br>Ta có: $F=\\Delta p.S\\Rightarrow F_{max}$  khi  $\\Delta p_{max}$ , tức là lúc áp suất bên trong lọ giác hơi bằng nhiệt độ môi tường<br>$\\Rightarrow F_{max}=\\left(p_0−p\\right)S=\\left(10^5−\\frac{15}{313}.10^6\\right).28.10^{−4}\\approx 145,8\\left(N\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) sai<br>Ta có:  $\\frac{pV}{T}=\\frac{p_0V_0}{T_0}\\Leftrightarrow \\frac{p.0,9V}{27+273}=\\frac{10^5V}{353+273}\\Rightarrow p\\approx 5,3.10^4\\left(Pa\\right)$<br>$\\Rightarrow \\Delta p=p_0−p=10^5−5,3.10^4=4,7.10^4\\left(Pa\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>Chênh lệch áp suất trong và ngoài lọ giác hơi tạo lực hút làm máu dưới da tăng cường đến nơi miệng lọ giác hơi bám vào, từ đó tạo ra tác dụng lưu thông khí huyết, kích thích hệ thống miễn dịch giúp cơ thể đối phó với vi khuẩn, virus.","difficultySource":"ai"},"ex":[{"exam":315,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Một lọ giác hơi (được cơ sở điều trị bằng phương pháp cổ truyền sử dụng) do chênh lệch áp suất trong và ngoài lọ nên dính vào bề mặt da lưng của người bệnh, điều này được tạo ra bằng cách ban đầu lọ được hơ nóng bên trong và nhanh chóng úp miệng hở của lọ vào vùng da cần tác động. Tại thời điểm áp vào da, không khí trong lọ được làm nóng đến nhiệt độ t = 3530C và nhiệt độ của không khí môi trường xung quanh là t0 = 27,0°C, Áp suất khí quyển po = 1,0.10<sup>3</sup> Pa. Diện tích phần miệng hở của lọ là S = 28,0 cm. Bỏ qua sự thay đổi thể tích không khí trong bình (do sự phồng của bề mặt phần da bên trong miệng hở của lọ).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045734761-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Áp suất khí trong lọ được áp vào da, khi có nhiệt độ bằng nhiệt độ của môi trường gần bằng 4,8.10<sup>4</sup> Pa.","answer":true},{"text":"Lực hút tối đa lên mặt da là 156 N.","answer":false},{"text":"Thực tế, do bề mặt da bị phồng lên bên trong miệng của lọ nên thể tích khí trong lọ bị giảm 10%. Chênh lệch áp suất khí trong lọ và ngoài lọ là 5,3.10<sup>4</sup> Pa.","answer":false},{"text":"Chênh lệch áp suất trong và ngoài lọ giác hơi tạo lực hút làm máu dưới da tăng cường đến nơi miệng lọ giác hơi bám vào, từ đó tạo ra tác dụng lưu thông khí huyết, kích thích hệ thống miễn dịch giúp cơ thể đối phó với vi khuẩn, virus.","answer":true}],"explanation":"a) đúng<br>Ban đầu, ở nhiệt độ 353°C thì áp suất của khí trong lọ = áp suất khí quyển = 105 Pa. Giả sử rằng thể tích không khí bên trong lọ không thay đổi, ta có áp suất của khí trong lọ khi bằng nhiệt độ môi trường là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$p=\\frac{T_0}{T}p_0=\\frac{27+27}{353+273}.10^5=\\frac{15}{313}.10^6\\approx 4,8.10^4\\left(Pa\\right)$<br>b) sai<br>Ta có: $F=\\Delta p.S\\Rightarrow F_{max}$  khi  $\\Delta p_{max}$ , tức là lúc áp suất bên trong lọ giác hơi bằng nhiệt độ môi tường<br>$\\Rightarrow F_{max}=\\left(p_0−p\\right)S=\\left(10^5−\\frac{15}{313}.10^6\\right).28.10^{−4}\\approx 145,8\\left(N\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) sai<br>Ta có:  $\\frac{pV}{T}=\\frac{p_0V_0}{T_0}\\Leftrightarrow \\frac{p.0,9V}{27+273}=\\frac{10^5V}{353+273}\\Rightarrow p\\approx 5,3.10^4\\left(Pa\\right)$<br>$\\Rightarrow \\Delta p=p_0−p=10^5−5,3.10^4=4,7.10^4\\left(Pa\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>Chênh lệch áp suất trong và ngoài lọ giác hơi tạo lực hút làm máu dưới da tăng cường đến nơi miệng lọ giác hơi bám vào, từ đó tạo ra tác dụng lưu thông khí huyết, kích thích hệ thống miễn dịch giúp cơ thể đối phó với vi khuẩn, virus.","difficultySource":"ai"}}]},{"id":604412,"nq":{"form":"bai_tap","type":"short_answer","topic":"Động năng trung bình phân tử và nhiệt độ","answer":"300","question":"Một khối khí helium có động năng tịnh tiến trung bình mỗi phân tử 6,21.10<sup>−21</sup> J. Biết hằng số Boltzmann k = 1,38.10<sup>−23</sup> (J/K). Nhiệt độ của khối khí khi đó là bao nhiêu Kelvin (K)?","difficulty":"trung-binh","explanation":"Nhiệt độ của khối khí đó là:  $\\overline{E}_d=1,5kT\\Leftrightarrow 6,21.10^{−21}=1,5.1,38.10^{−23}.T\\Rightarrow T=300\\left(K\\right)$","difficultySource":"ai"},"ex":[{"exam":315,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Động năng trung bình phân tử và nhiệt độ","answer":"300","question":"Một khối khí helium có động năng tịnh tiến trung bình mỗi phân tử 6,21.10<sup>−21</sup> J. Biết hằng số Boltzmann k = 1,38.10<sup>−23</sup> (J/K). Nhiệt độ của khối khí khi đó là bao nhiêu Kelvin (K)?","difficulty":"trung-binh","explanation":"Nhiệt độ của khối khí đó là:  $\\overline{E}_d=1,5kT\\Leftrightarrow 6,21.10^{−21}=1,5.1,38.10^{−23}.T\\Rightarrow T=300\\left(K\\right)$","difficultySource":"ai"}}]},{"id":607406,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["1,65.10<sup>7</sup> J.","66.104 J.","66.105 J.","1,65.10<sup>4</sup> J."],"question":"Biết nhiệt nóng chảy riêng của nước đá là 3,3.10<sup>5</sup> J/kg. Một viên nước đá khối lượng 50 g ở nhiệt độ 00C tan chảy hoàn toàn sẽ thu từ môi trường nhiệt lượng là","difficulty":"de","explanation":"Nhiệt lượng cần để làm tan chảy hoàn toàn một khối chất rắn ở nhiệt độ nóng chảy: Q = m·λ.<br>Thay số: Q = 0,05·3,3×10⁵ = 1,65×10⁴ J.<br>$Q=m\\lambda =0,05\\cdot 3,3\\cdot 10^5=1,65\\cdot 10^4 J$ .","difficultySource":"ai"},"ex":[{"exam":319,"idx":8,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["1,65.10<sup>7</sup> J.","66.104 J.","66.105 J.","1,65.10<sup>4</sup> J."],"question":"Biết nhiệt nóng chảy riêng của nước đá là 3,3.10<sup>5</sup> J/kg. Một viên nước đá khối lượng 50 g ở nhiệt độ 00C tan chảy hoàn toàn sẽ thu từ môi trường nhiệt lượng là","difficulty":"de","explanation":"Nhiệt lượng cần để làm tan chảy hoàn toàn một khối chất rắn ở nhiệt độ nóng chảy: Q = m·λ.<br>Thay số: Q = 0,05·3,3×10⁵ = 1,65×10⁴ J.<br>$Q=m\\lambda =0,05\\cdot 3,3\\cdot 10^5=1,65\\cdot 10^4 J$ .","difficultySource":"ai"}}]},{"id":607410,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông. Hiện tượng cảm ứng điện từ","answer":1,"options":["8,6.10<sup>−8</sup> V.","10-5 V.","2.10<sup>−5</sup> V.","1,7.10<sup>−5</sup> V."],"question":"Để theo dõi hơi thở của một bệnh nhân trong bệnh viện, bác sĩ dùng một dây đai mông được quấn quanh ngực bệnh nhân. Dây đai là một cuộn dây gồm 200 vòng. Khi bệnh nhân hít vào thì diện tích bao quanh bởi cuộn dây tăng lên 40,0 cm2. Biết từ trường Trái Đất là 40,0 µT và có hướng tạo một góc 30° so với mặt phẳng của cuộn dây. Nếu thời gian bệnh nhân thực hiện một lần hít vào là 1,6 giây thì độ lớn suất điện động cảm ứng trung bình trong cuộn dây là","difficulty":"trung-binh","explanation":"Suất điện động cảm ứng trung bình: e = |ΔΦ/Δt| = |N·B·ΔS·cosα|/Δt, với α là góc giữa B và pháp tuyến mặt phẳng cuộn dây.<br>Vì từ trường hợp một góc 30° với MẶT PHẲNG cuộn dây nên góc với pháp tuyến là 90°−30°=60°. Thay số: e = 200·40×10⁻⁶·40×10⁻⁴·cos60°/1,6 = 10⁻⁵ V.<br>$\\begin{aligned}\\end{aligned}e=\\left|\\frac{\\Delta \\phi }{\\Delta t}\\right|=\\left|\\frac{N\\cdot B\\cdot \\Delta S\\cdot cos\\alpha }{\\Delta t}\\right|=\\frac{200\\cdot 40\\cdot 10^{−6}\\cdot 40\\cdot 10^{−4}\\cdot cos\\left(90^{^{\\circ}}−30^{^{\\circ}}\\right)}{1,6}=10^{−5} V. Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":319,"idx":12,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông. Hiện tượng cảm ứng điện từ","answer":1,"options":["8,6.10<sup>−8</sup> V.","10-5 V.","2.10<sup>−5</sup> V.","1,7.10<sup>−5</sup> V."],"question":"Để theo dõi hơi thở của một bệnh nhân trong bệnh viện, bác sĩ dùng một dây đai mông được quấn quanh ngực bệnh nhân. Dây đai là một cuộn dây gồm 200 vòng. Khi bệnh nhân hít vào thì diện tích bao quanh bởi cuộn dây tăng lên 40,0 cm2. Biết từ trường Trái Đất là 40,0 µT và có hướng tạo một góc 30° so với mặt phẳng của cuộn dây. Nếu thời gian bệnh nhân thực hiện một lần hít vào là 1,6 giây thì độ lớn suất điện động cảm ứng trung bình trong cuộn dây là","difficulty":"trung-binh","explanation":"Suất điện động cảm ứng trung bình: e = |ΔΦ/Δt| = |N·B·ΔS·cosα|/Δt, với α là góc giữa B và pháp tuyến mặt phẳng cuộn dây.<br>Vì từ trường hợp một góc 30° với MẶT PHẲNG cuộn dây nên góc với pháp tuyến là 90°−30°=60°. Thay số: e = 200·40×10⁻⁶·40×10⁻⁴·cos60°/1,6 = 10⁻⁵ V.<br>$\\begin{aligned}\\end{aligned}e=\\left|\\frac{\\Delta \\phi }{\\Delta t}\\right|=\\left|\\frac{N\\cdot B\\cdot \\Delta S\\cdot cos\\alpha }{\\Delta t}\\right|=\\frac{200\\cdot 40\\cdot 10^{−6}\\cdot 40\\cdot 10^{−4}\\cdot cos\\left(90^{^{\\circ}}−30^{^{\\circ}}\\right)}{1,6}=10^{−5} V. Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":607417,"nq":{"form":"ly_thuyet","type":"true_false","topic":"Cấu trúc hạt nhân","question":"Vào năm 1911, Ernest Rutherford và các cộng sự đã tiến hành thí nghiệm tán xạ hạt alpha. Ông sử dụng chùm hạt alpha (chùm hạt nhân 42He ) bắn phá vào một lá vàng rất mỏng đặt trong hộp chân không. Hình dưới đây minh hoạ kết quả thí nghiệm.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045758694-hinh-5.webp\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Một tỉ lệ rất nhỏ (chỉ 1 trong khoảng 104) hạt alpha bị lệch hướng lớn hơn 90° vì chúng va chạm gần như trực diện với hạt nhân nguyên tử vàng.","answer":true},{"text":"Một tỉ lệ nhỏ hạt alpha bị lệch hướng so với ban đầu vì chúng tương tác với các electron trong các nguyên tử vàng.","answer":false},{"text":"Phần lớn hạt alpha xuyên thẳng qua lá vàng mà không bị lệch hướng vì các nguyên tử vàng trung hoà điện.","answer":false},{"text":"Điện tích của hạt alpha là -3,2.10<sup>−19</sup> C.","answer":false}],"explanation":"a) Đúng — Chỉ một tỉ lệ rất nhỏ (khoảng 1/10⁴) hạt alpha bị lệch hướng lớn hơn 90° vì chúng va chạm gần như trực diện với hạt nhân nguyên tử vàng (kích thước hạt nhân rất nhỏ so với nguyên tử nên xác suất này rất thấp).<br>b) Sai — Hạt alpha bị lệch hướng là do lực đẩy Coulomb với HẠT NHÂN mang điện dương, không phải do tương tác với các electron (electron có khối lượng quá nhỏ, không đủ làm lệch hạt alpha).<br>c) Sai — Phần lớn hạt alpha xuyên thẳng qua lá vàng vì phần lớn không gian bên trong nguyên tử là RỖNG (hạt nhân chỉ chiếm một phần rất nhỏ thể tích nguyên tử), không phải vì nguyên tử trung hòa điện.<br>d) Sai — Hạt alpha chính là hạt nhân Heli (2 proton, 2 neutron) nên mang điện tích DƯƠNG: q = +2e = +3,2×10⁻¹⁹ C, không phải điện tích âm.<br>a) đúng<br>Một tỉ lệ rất nhỏ (chỉ 1 trong khoảng 104) hạt alpha bị lệch hướng lớn hơn 90° vì chúng va chạm gần như trực diện với hạt nhân nguyên tử vàng.<br>b) sai<br>Tương tác với hạt nhân<br>c) sai<br>Phần lớn hạt alpha xuyên thẳng qua lá vàng mà không bị lệch hướng vì phần lớn không gian bên trong nguyên tử là rỗng<br>d) sai<br>$\\alpha$  là hạt nhân He mang điện tích dương","difficultySource":"ai"},"ex":[{"exam":319,"idx":19,"el":{"form":"ly_thuyet","type":"true_false","topic":"Cấu trúc hạt nhân","question":"Vào năm 1911, Ernest Rutherford và các cộng sự đã tiến hành thí nghiệm tán xạ hạt alpha. Ông sử dụng chùm hạt alpha (chùm hạt nhân 42He ) bắn phá vào một lá vàng rất mỏng đặt trong hộp chân không. Hình dưới đây minh hoạ kết quả thí nghiệm.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045758694-hinh-5.webp\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Một tỉ lệ rất nhỏ (chỉ 1 trong khoảng 104) hạt alpha bị lệch hướng lớn hơn 90° vì chúng va chạm gần như trực diện với hạt nhân nguyên tử vàng.","answer":true},{"text":"Một tỉ lệ nhỏ hạt alpha bị lệch hướng so với ban đầu vì chúng tương tác với các electron trong các nguyên tử vàng.","answer":false},{"text":"Phần lớn hạt alpha xuyên thẳng qua lá vàng mà không bị lệch hướng vì các nguyên tử vàng trung hoà điện.","answer":false},{"text":"Điện tích của hạt alpha là -3,2.10<sup>−19</sup> C.","answer":false}],"explanation":"a) Đúng — Chỉ một tỉ lệ rất nhỏ (khoảng 1/10⁴) hạt alpha bị lệch hướng lớn hơn 90° vì chúng va chạm gần như trực diện với hạt nhân nguyên tử vàng (kích thước hạt nhân rất nhỏ so với nguyên tử nên xác suất này rất thấp).<br>b) Sai — Hạt alpha bị lệch hướng là do lực đẩy Coulomb với HẠT NHÂN mang điện dương, không phải do tương tác với các electron (electron có khối lượng quá nhỏ, không đủ làm lệch hạt alpha).<br>c) Sai — Phần lớn hạt alpha xuyên thẳng qua lá vàng vì phần lớn không gian bên trong nguyên tử là RỖNG (hạt nhân chỉ chiếm một phần rất nhỏ thể tích nguyên tử), không phải vì nguyên tử trung hòa điện.<br>d) Sai — Hạt alpha chính là hạt nhân Heli (2 proton, 2 neutron) nên mang điện tích DƯƠNG: q = +2e = +3,2×10⁻¹⁹ C, không phải điện tích âm.<br>a) đúng<br>Một tỉ lệ rất nhỏ (chỉ 1 trong khoảng 104) hạt alpha bị lệch hướng lớn hơn 90° vì chúng va chạm gần như trực diện với hạt nhân nguyên tử vàng.<br>b) sai<br>Tương tác với hạt nhân<br>c) sai<br>Phần lớn hạt alpha xuyên thẳng qua lá vàng mà không bị lệch hướng vì phần lớn không gian bên trong nguyên tử là rỗng<br>d) sai<br>$\\alpha$  là hạt nhân He mang điện tích dương","difficultySource":"ai"}}]},{"id":607418,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Dùng quạt hơi nước để làm mát căn phòng có kích thước 4 m<br>× 5 m × 4 m. Khi quạt hoạt động, không khí trong phòng được quạt hút vào sau đó đi qua tấm làm mát đã được làm ướt tạo để ra hiện tượng bay hơi nước. Biết lưu lượng nước bay hơi từ quạt là 0,5 g/s; nhiệt hóa hơi riêng của nước ở nhiệt độ phòng (không đổi) là 2,25.10<sup>6</sup> J/kg; khối lượng riêng của không khí trong phòng là 1,2 kg/m3 và nhiệt dung riêng của không khí là 1005 J/kg.K.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045758982-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Giả sử toàn bộ nhiệt lượng lấy từ không khí trong phòng dùng để làm bay hơi nước. Sau 10 phút mở quạt, nhiệt độ phòng giảm đi 7°C.","answer":true},{"text":"Khi nước bay hơi thì nước đã toả nhiệt ra không khí xung quanh.","answer":false},{"text":"Khối lượng của không khí trong phòng là 65 kg.","answer":false},{"text":"Khối lượng của nước bay hơi trong thời gian 10 phút là 0,3 kg.","answer":true}],"explanation":"a) Đúng — Nhiệt lượng cần để bay hơi lượng nước trong 10 phút: m_n = 0,5·600 = 300 g = 0,3 kg; Q = m_n·L = 0,3·2,25×10⁶ = 675000 J. Khối lượng không khí trong phòng: m_kk = V·D = (4·5·4)·1,2 = 96 kg. Độ giảm nhiệt độ: Δt = Q/(m_kk·c_kk) = 675000/(96·1005) ≈ 7°C, khớp phát biểu.<br>b) Sai — Khi nước bay hơi (chuyển từ lỏng sang khí), nước phải NHẬN nhiệt (nhiệt hóa hơi) từ không khí xung quanh, không phải tỏa nhiệt.<br>c) Sai — Khối lượng không khí trong phòng: m_kk = V·D = 4·5·4·1,2 = 96 kg, không phải 65 kg.<br>d) Đúng — Khối lượng nước bay hơi trong 10 phút = 600 s: m = (lưu lượng)·t = 0,5 g/s·600 s = 300 g = 0,3 kg.<br>a) đúng<br>$\\begin{aligned}\\end{aligned}m_n=0,5\\cdot 10\\cdot 60=300 g=0,3 kgWebsite: thukhoadaihoc.vn$<br>b) sai<br>Nước đã nhận nhiệt<br>c) sai<br>$m_{kk}=VD=4\\cdot 5\\cdot 4\\cdot 1,2=96 kg$<br>d) đúng<br>$m_{kk}c_{kk}\\Delta t=m_nL\\Rightarrow 96.1005.\\Delta t=0,3.2,25.10^6\\Rightarrow \\Delta t\\approx 7^{^{\\circ}}C$","difficultySource":"ai"},"ex":[{"exam":319,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Dùng quạt hơi nước để làm mát căn phòng có kích thước 4 m<br>× 5 m × 4 m. Khi quạt hoạt động, không khí trong phòng được quạt hút vào sau đó đi qua tấm làm mát đã được làm ướt tạo để ra hiện tượng bay hơi nước. Biết lưu lượng nước bay hơi từ quạt là 0,5 g/s; nhiệt hóa hơi riêng của nước ở nhiệt độ phòng (không đổi) là 2,25.10<sup>6</sup> J/kg; khối lượng riêng của không khí trong phòng là 1,2 kg/m3 và nhiệt dung riêng của không khí là 1005 J/kg.K.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045758982-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Giả sử toàn bộ nhiệt lượng lấy từ không khí trong phòng dùng để làm bay hơi nước. Sau 10 phút mở quạt, nhiệt độ phòng giảm đi 7°C.","answer":true},{"text":"Khi nước bay hơi thì nước đã toả nhiệt ra không khí xung quanh.","answer":false},{"text":"Khối lượng của không khí trong phòng là 65 kg.","answer":false},{"text":"Khối lượng của nước bay hơi trong thời gian 10 phút là 0,3 kg.","answer":true}],"explanation":"a) Đúng — Nhiệt lượng cần để bay hơi lượng nước trong 10 phút: m_n = 0,5·600 = 300 g = 0,3 kg; Q = m_n·L = 0,3·2,25×10⁶ = 675000 J. Khối lượng không khí trong phòng: m_kk = V·D = (4·5·4)·1,2 = 96 kg. Độ giảm nhiệt độ: Δt = Q/(m_kk·c_kk) = 675000/(96·1005) ≈ 7°C, khớp phát biểu.<br>b) Sai — Khi nước bay hơi (chuyển từ lỏng sang khí), nước phải NHẬN nhiệt (nhiệt hóa hơi) từ không khí xung quanh, không phải tỏa nhiệt.<br>c) Sai — Khối lượng không khí trong phòng: m_kk = V·D = 4·5·4·1,2 = 96 kg, không phải 65 kg.<br>d) Đúng — Khối lượng nước bay hơi trong 10 phút = 600 s: m = (lưu lượng)·t = 0,5 g/s·600 s = 300 g = 0,3 kg.<br>a) đúng<br>$\\begin{aligned}\\end{aligned}m_n=0,5\\cdot 10\\cdot 60=300 g=0,3 kgWebsite: thukhoadaihoc.vn$<br>b) sai<br>Nước đã nhận nhiệt<br>c) sai<br>$m_{kk}=VD=4\\cdot 5\\cdot 4\\cdot 1,2=96 kg$<br>d) đúng<br>$m_{kk}c_{kk}\\Delta t=m_nL\\Rightarrow 96.1005.\\Delta t=0,3.2,25.10^6\\Rightarrow \\Delta t\\approx 7^{^{\\circ}}C$","difficultySource":"ai"}}]},{"id":607419,"nq":{"form":"bai_tap","type":"true_false","topic":"Lực từ. Cảm ứng từ","question":"Uranium trong tự nhiên có 2 đồng vị chính là  ${}_{92}^{235}U$ và ${}_{92}^{238}U$ . Trong đó  ${}_{92}^{235}U$ chiếm một phần rất nhỏ nhưng lại là nhiên liệu phổ biến của các nhà máy điện hạt nhân. Một trong những cách làm giàu  ${}_{92}^{235}U$ mà các nhà khoa học đã sử dụng là tách  ${}_{92}^{235}U$  ra khỏi  ${}_{92}^{238}U$  như sau: cho các ion chứa hạt nhân là  ${}_{92}^{235}U$  và  ${}_{92}^{238}U$  (có cùng điện tích q = 1,6.10<sup>−19</sup> C) tăng tốc đến cùng tốc độ v = 3.10<sup>5</sup> m/s, sau đó cho chúng chuyển động vào từ trường đều có cảm ứng từ B = 0,25 T theo phương vuông góc với đường sức từ. Bỏ qua tác dụng của trọng lực. Khi đó, lực từ tác dụng lên các ion có độ lớn F = Bv|q|, có phương vuông góc với vận tốc của các ion làm chúng chuyển động theo những nửa đường tròn có bán kính khác nhau như hình bên. Biết các ion chứa hạt nhân  ${}_{92}^{235}U$ và  ${}_{92}^{238}U$ có khối lượng lần lượt là 3,9.10<sup>−25</sup> kg và 3,95.10<sup>−25</sup> kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045759164-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Khoảng cách giữa các ion chứa hạt nhân  ${}_{92}^{235}U$ và  ${}_{92}^{238}U$ khi cùng chuyển động được nửa vòng tròn là 0,075m","answer":true},{"text":"Khi các ion chuyển động tròn thì lực hướng tâm là lực từ.","answer":true},{"text":"Bán kính quỹ đạo của các ion trong vùng từ trường được tính theo công thức  $r=\\frac{mB}{\\left|q\\right|.v}$","answer":false},{"text":"Tốc độ của các ion bị thay đổi do tác dụng của lực từ.","answer":false}],"explanation":"a) Đúng — Bán kính quỹ đạo mỗi ion: r = mv/(|q|B). Khoảng cách hai điểm ra sau nửa vòng tròn: d = 2(r₂₃₈−r₂₃₅) = [2v/(|q|B)]·(m₂₃₈−m₂₃₅) = [2·3×10⁵/(1,6×10⁻¹⁹·0,25)]·(3,95−3,9)×10⁻²⁵ = 0,075 m, khớp phát biểu.<br>b) Đúng — Trong từ trường đều, lực từ (lực Lorentz) tác dụng lên ion chuyển động luôn vuông góc với vận tốc và đóng vai trò lực hướng tâm giữ ion chuyển động tròn.<br>c) Sai — Từ điều kiện lực hướng tâm |q|vB = mv²/r, suy ra công thức đúng là r = mv/(|q|·B), không phải r = mB/(|q|·v) như phát biểu nêu.<br>d) Sai — Vì lực từ luôn vuông góc với vận tốc nên không sinh công, động năng của ion không đổi, do đó tốc độ của các ion KHÔNG bị thay đổi trong suốt quá trình chuyển động tròn.<br>a) sai<br>$F\\perp v$  nên lực từ không sinh công  $\\Rightarrow$  động năng không nổi  $\\Rightarrow$  tốc độ không đổi<br>b) đúng<br>Khi các ion chuyển động tròn thì lực hướng tâm là lực từ.<br>c) sai<br>$F=ma_{ht}\\Rightarrow |q|vB=m\\cdot \\frac{v^2}{r}\\Rightarrow r=\\frac{mv}{|q|B}$<br>$Website: thukhoadaihoc.vn$<br>d) đúng<br>$\\begin{aligned}\\end{aligned}d=2\\left(r_{U238}−r_{U235}\\right)=\\frac{2v}{|q|B}\\left(m_{U238}−m_{U235}\\right)=\\frac{2\\cdot 3\\cdot 10^5}{1,6\\cdot 10^{−19}\\cdot 0,25}\\cdot (3,95−3,9)\\cdot 10^{−25}=0,075mWebsite: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":319,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Lực từ. Cảm ứng từ","question":"Uranium trong tự nhiên có 2 đồng vị chính là  ${}_{92}^{235}U$ và ${}_{92}^{238}U$ . Trong đó  ${}_{92}^{235}U$ chiếm một phần rất nhỏ nhưng lại là nhiên liệu phổ biến của các nhà máy điện hạt nhân. Một trong những cách làm giàu  ${}_{92}^{235}U$ mà các nhà khoa học đã sử dụng là tách  ${}_{92}^{235}U$  ra khỏi  ${}_{92}^{238}U$  như sau: cho các ion chứa hạt nhân là  ${}_{92}^{235}U$  và  ${}_{92}^{238}U$  (có cùng điện tích q = 1,6.10<sup>−19</sup> C) tăng tốc đến cùng tốc độ v = 3.10<sup>5</sup> m/s, sau đó cho chúng chuyển động vào từ trường đều có cảm ứng từ B = 0,25 T theo phương vuông góc với đường sức từ. Bỏ qua tác dụng của trọng lực. Khi đó, lực từ tác dụng lên các ion có độ lớn F = Bv|q|, có phương vuông góc với vận tốc của các ion làm chúng chuyển động theo những nửa đường tròn có bán kính khác nhau như hình bên. Biết các ion chứa hạt nhân  ${}_{92}^{235}U$ và  ${}_{92}^{238}U$ có khối lượng lần lượt là 3,9.10<sup>−25</sup> kg và 3,95.10<sup>−25</sup> kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045759164-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Khoảng cách giữa các ion chứa hạt nhân  ${}_{92}^{235}U$ và  ${}_{92}^{238}U$ khi cùng chuyển động được nửa vòng tròn là 0,075m","answer":true},{"text":"Khi các ion chuyển động tròn thì lực hướng tâm là lực từ.","answer":true},{"text":"Bán kính quỹ đạo của các ion trong vùng từ trường được tính theo công thức  $r=\\frac{mB}{\\left|q\\right|.v}$","answer":false},{"text":"Tốc độ của các ion bị thay đổi do tác dụng của lực từ.","answer":false}],"explanation":"a) Đúng — Bán kính quỹ đạo mỗi ion: r = mv/(|q|B). Khoảng cách hai điểm ra sau nửa vòng tròn: d = 2(r₂₃₈−r₂₃₅) = [2v/(|q|B)]·(m₂₃₈−m₂₃₅) = [2·3×10⁵/(1,6×10⁻¹⁹·0,25)]·(3,95−3,9)×10⁻²⁵ = 0,075 m, khớp phát biểu.<br>b) Đúng — Trong từ trường đều, lực từ (lực Lorentz) tác dụng lên ion chuyển động luôn vuông góc với vận tốc và đóng vai trò lực hướng tâm giữ ion chuyển động tròn.<br>c) Sai — Từ điều kiện lực hướng tâm |q|vB = mv²/r, suy ra công thức đúng là r = mv/(|q|·B), không phải r = mB/(|q|·v) như phát biểu nêu.<br>d) Sai — Vì lực từ luôn vuông góc với vận tốc nên không sinh công, động năng của ion không đổi, do đó tốc độ của các ion KHÔNG bị thay đổi trong suốt quá trình chuyển động tròn.<br>a) sai<br>$F\\perp v$  nên lực từ không sinh công  $\\Rightarrow$  động năng không nổi  $\\Rightarrow$  tốc độ không đổi<br>b) đúng<br>Khi các ion chuyển động tròn thì lực hướng tâm là lực từ.<br>c) sai<br>$F=ma_{ht}\\Rightarrow |q|vB=m\\cdot \\frac{v^2}{r}\\Rightarrow r=\\frac{mv}{|q|B}$<br>$Website: thukhoadaihoc.vn$<br>d) đúng<br>$\\begin{aligned}\\end{aligned}d=2\\left(r_{U238}−r_{U235}\\right)=\\frac{2v}{|q|B}\\left(m_{U238}−m_{U235}\\right)=\\frac{2\\cdot 3\\cdot 10^5}{1,6\\cdot 10^{−19}\\cdot 0,25}\\cdot (3,95−3,9)\\cdot 10^{−25}=0,075mWebsite: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":613741,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Các tia phóng xạ α, β, γ","answer":1,"options":["Tia  $\\gamma$","Tia  $\\alpha$","Tia  $\\beta^+$","Tia  $\\beta^−$"],"question":"Trong không khí, tia phóng xạ nào sau đây có tốc độ nhỏ nhất?","difficulty":"de","explanation":"Tia α chính là các hạt nhân He được phóng ra từ hạt nhân với tốc độ khoảng 2.10<sup>7</sup> m/s, trong khi đó các tia β-, β+ phóng ra với tốc độ rất lớn, có thể đạt xấp xỉ bằng tốc độ ánh sáng, tia γ là sóng điện từ có bước sóng cực ngắn, tốc độ 3.10<sup>8</sup> m/s","difficultySource":"ai"},"ex":[{"exam":325,"idx":15,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Các tia phóng xạ α, β, γ","answer":1,"options":["Tia  $\\gamma$","Tia  $\\alpha$","Tia  $\\beta^+$","Tia  $\\beta^−$"],"question":"Trong không khí, tia phóng xạ nào sau đây có tốc độ nhỏ nhất?","difficulty":"de","explanation":"Tia α chính là các hạt nhân He được phóng ra từ hạt nhân với tốc độ khoảng 2.10<sup>7</sup> m/s, trong khi đó các tia β-, β+ phóng ra với tốc độ rất lớn, có thể đạt xấp xỉ bằng tốc độ ánh sáng, tia γ là sóng điện từ có bước sóng cực ngắn, tốc độ 3.10<sup>8</sup> m/s","difficultySource":"ai"}}]},{"id":614504,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":1,"options":["2,4.10<sup>−6</sup> Wb .","4,2.10<sup>−4</sup> Wb .","2,4.10<sup>−4</sup> Wb .","4,2.10<sup>−6</sup> Wb ."],"question":"Một khung dây phẳng diện tích S= 40 cm2 đặt trong từ trường đều có vectơ cảm ứng từ B hợp với mặt phẳng khung dây một góc α = 60° và có độ lớn B = 0,12 T. Từ thông qua khung dây này là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ thông qua diện tích $S$ đặt trong từ trường đều được xác định bởi $\\Phi = B.S.\\cos\\alpha_n$, trong đó $\\alpha_n$ là góc giữa vectơ cảm ứng từ $\\vec{B}$ và vectơ pháp tuyến $\\vec{n}$ của mặt phẳng khung dây.</p><p class=\"text-base leading-relaxed my-2\">Đề cho $\\vec{B}$ hợp với mặt phẳng khung một góc $60^\\circ$, nên góc với pháp tuyến là $\\alpha_n = 90^\\circ - 60^\\circ = 30^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị diện tích: $S = 40\\ \\text{cm}^2 = 40.10^{-4}\\ \\text{m}^2 = 4.10^{-3}\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$\\Phi = 0,12 \\cdot 4.10^{-3} \\cdot \\cos 30^\\circ$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\Phi = 4,8.10^{-4} \\cdot \\dfrac{\\sqrt{3}}{2} \\approx 4,2.10^{-4}\\ \\text{Wb}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: từ thông qua khung dây là $4,2.10^{-4}\\ \\text{Wb}$, đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":328,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":1,"options":["2,4.10<sup>−6</sup> Wb .","4,2.10<sup>−4</sup> Wb .","2,4.10<sup>−4</sup> Wb .","4,2.10<sup>−6</sup> Wb ."],"question":"Một khung dây phẳng diện tích S= 40 cm2 đặt trong từ trường đều có vectơ cảm ứng từ B hợp với mặt phẳng khung dây một góc α = 60° và có độ lớn B = 0,12 T. Từ thông qua khung dây này là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ thông qua diện tích $S$ đặt trong từ trường đều được xác định bởi $\\Phi = B.S.\\cos\\alpha_n$, trong đó $\\alpha_n$ là góc giữa vectơ cảm ứng từ $\\vec{B}$ và vectơ pháp tuyến $\\vec{n}$ của mặt phẳng khung dây.</p><p class=\"text-base leading-relaxed my-2\">Đề cho $\\vec{B}$ hợp với mặt phẳng khung một góc $60^\\circ$, nên góc với pháp tuyến là $\\alpha_n = 90^\\circ - 60^\\circ = 30^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị diện tích: $S = 40\\ \\text{cm}^2 = 40.10^{-4}\\ \\text{m}^2 = 4.10^{-3}\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$\\Phi = 0,12 \\cdot 4.10^{-3} \\cdot \\cos 30^\\circ$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\Phi = 4,8.10^{-4} \\cdot \\dfrac{\\sqrt{3}}{2} \\approx 4,2.10^{-4}\\ \\text{Wb}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: từ thông qua khung dây là $4,2.10^{-4}\\ \\text{Wb}$, đáp án B.</p>","difficultySource":"ai"}}]},{"id":614505,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":2,"options":["107520 J.","78000 J.","185520 J.","29520 kJ."],"question":"Biết nhôm có nhiệt dung riêng 896 J/(kg.K) và nhiệt nóng chảy riêng là 3,9.10<sup>5</sup> J/kg. Nhiệt lượng cần cung cấp cho miếng nhôm khối lượng 200 g ở nhiệt độ 580C để nó hóa lỏng hoàn toàn ở nhiệt độ 658°C là:","difficulty":"trung-binh","explanation":"*  $Q=m\\left(c\\Delta T+\\lambda \\right)=0,2.\\left[896.\\left(658−58\\right)+3,9.10^5\\right]=185520\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":328,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":2,"options":["107520 J.","78000 J.","185520 J.","29520 kJ."],"question":"Biết nhôm có nhiệt dung riêng 896 J/(kg.K) và nhiệt nóng chảy riêng là 3,9.10<sup>5</sup> J/kg. Nhiệt lượng cần cung cấp cho miếng nhôm khối lượng 200 g ở nhiệt độ 580C để nó hóa lỏng hoàn toàn ở nhiệt độ 658°C là:","difficulty":"trung-binh","explanation":"*  $Q=m\\left(c\\Delta T+\\lambda \\right)=0,2.\\left[896.\\left(658−58\\right)+3,9.10^5\\right]=185520\\left(J\\right)$","difficultySource":"ai"}}]},{"id":614509,"nq":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một khối khí lí tưởng biến đổi trạng thái theo một chu trình ở hình bên. Biết thể tích và áp suất của khí ở trạng thái (1) là 1 lít và 3.10<sup>5</sup> Pa<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045831487-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quá trình (3) ‒ (1) là quá trình đẳng tích.","answer":true},{"text":"Thể tích của khí ở trạng thái (2) là 3 lít.","answer":true},{"text":"Công khối khí thực hiện trong một chu trình là 200 J.","answer":true},{"text":"Nhiệt độ khí ở trạng thái (2) là lớn nhất.","answer":true}],"explanation":"a) đúng<br>Quá trình (3) ‒ (1) là quá trình đẳng tích.<br>b) đúng<br>Từ hình vẽ  $\\Rightarrow V_2=3V_1=3\\left(lit\\right)$<br>c) đúng<br>* Từ hình vẽ  $\\Rightarrow p_3=\\frac{p_1}{3}=10^5Pa$<br>*  $A=S_{123}=\\frac{1}{2}\\left(p_1−p_3\\right).\\left(V_2−V_1\\right)=\\frac{1}{2}.\\left(3−1\\right).10^5.\\left(3−1\\right).10^{−3}=200\\left(J\\right)$<br>d) đúng<br>* Từ (3) → (1): Đẳng tích  $\\frac{p}{T}=hsp_3<p_1\\rightarrow T_3<T_1$<br>* Từ (1) → (2): Đẳng áp:  $\\frac{V}{T}=hsV_1<V_2\\rightarrow T_1<T_2$","difficultySource":"ai"},"ex":[{"exam":328,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một khối khí lí tưởng biến đổi trạng thái theo một chu trình ở hình bên. Biết thể tích và áp suất của khí ở trạng thái (1) là 1 lít và 3.10<sup>5</sup> Pa<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045831487-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quá trình (3) ‒ (1) là quá trình đẳng tích.","answer":true},{"text":"Thể tích của khí ở trạng thái (2) là 3 lít.","answer":true},{"text":"Công khối khí thực hiện trong một chu trình là 200 J.","answer":true},{"text":"Nhiệt độ khí ở trạng thái (2) là lớn nhất.","answer":true}],"explanation":"a) đúng<br>Quá trình (3) ‒ (1) là quá trình đẳng tích.<br>b) đúng<br>Từ hình vẽ  $\\Rightarrow V_2=3V_1=3\\left(lit\\right)$<br>c) đúng<br>* Từ hình vẽ  $\\Rightarrow p_3=\\frac{p_1}{3}=10^5Pa$<br>*  $A=S_{123}=\\frac{1}{2}\\left(p_1−p_3\\right).\\left(V_2−V_1\\right)=\\frac{1}{2}.\\left(3−1\\right).10^5.\\left(3−1\\right).10^{−3}=200\\left(J\\right)$<br>d) đúng<br>* Từ (3) → (1): Đẳng tích  $\\frac{p}{T}=hsp_3<p_1\\rightarrow T_3<T_1$<br>* Từ (1) → (2): Đẳng áp:  $\\frac{V}{T}=hsV_1<V_2\\rightarrow T_1<T_2$","difficultySource":"ai"}}]},{"id":614519,"nq":{"form":"bai_tap","type":"short_answer","topic":"Lực từ. Cảm ứng từ","answer":"1,2","question":"Một electron chuyển động tròn đều trong từ trường có B = 3.10‒5T chỉ do tác dụng của lực từ. Biết lực từ tác dụng lên electron có độ lớn là e .v.B và me = 9,1.10<sup>−31</sup> kg. Thời gian để electron chuyển động được một vòng là x.10‒6s. Tìm giá trị của x (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"* Electron chuyển động tròn đều nên lực từ đóng vai trò là lực hướng tâm.<br>$F_{ht}=F_t\\Rightarrow m.\\omega^2r=\\left|e\\right|vB$  (với  $v=\\omega r$ )<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045832542-hinh-15.png\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>* Thời gian electron chuyển động 1 vòng là  $t=T=\\frac{2\\pi }{\\omega }=1,2.10^{−6}s=x.10^{−6}s\\Rightarrow x=1,2$","difficultySource":"ai"},"ex":[{"exam":328,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Lực từ. Cảm ứng từ","answer":"1,2","question":"Một electron chuyển động tròn đều trong từ trường có B = 3.10‒5T chỉ do tác dụng của lực từ. Biết lực từ tác dụng lên electron có độ lớn là e .v.B và me = 9,1.10<sup>−31</sup> kg. Thời gian để electron chuyển động được một vòng là x.10‒6s. Tìm giá trị của x (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"* Electron chuyển động tròn đều nên lực từ đóng vai trò là lực hướng tâm.<br>$F_{ht}=F_t\\Rightarrow m.\\omega^2r=\\left|e\\right|vB$  (với  $v=\\omega r$ )<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045832542-hinh-15.png\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>* Thời gian electron chuyển động 1 vòng là  $t=T=\\frac{2\\pi }{\\omega }=1,2.10^{−6}s=x.10^{−6}s\\Rightarrow x=1,2$","difficultySource":"ai"}}]},{"id":615837,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":"11,5","question":"Hương vị của bia Hà nội đã trở thành một thương hiệu mà nhiều người yêu thích. Mở nắp một chai bia rồi rót 200 g bia vào cốc. Cho vào cốc 40 g nước đá ở nhiệt độ -2,80C thì ta sẽ được một cốc bia mát. Biết nhiệt dung riêng của bia là 3830 J/kg.K; nhiệt dung riêng của nước đá là 1800 J/kg.K; nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg; nhiệt dung riêng của nước là 4200 J/kg.K. Ban đầu bia có nhiệt độ là 320C. Bỏ qua sự trao đổi nhiệt với môi trường và sự trao đổi nhiệt với thành cốc. Sau khi nước đá tan hết, nhiệt độ của cốc bia là bao nhiêu 0C? (lấy đến một con số sau dấu phẩy).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045839334-hinh-20.jpg\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$Q=mc\\Delta t$<br>$Q_{thu}=0,04.1800.2,8+0,04.3,4.10^5+0,04.4200\\left(t_{cb}−0\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}Q_{toa}=0,2.3830.\\left(30−t_{cb}\\right)Website: thukhoadaihoc.vn$<br>$\\Rightarrow Q_{toa}=Q_{thu}\\Rightarrow t_{cb}=11,5^0C$","difficultySource":"ai"},"ex":[{"exam":329,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":"11,5","question":"Hương vị của bia Hà nội đã trở thành một thương hiệu mà nhiều người yêu thích. Mở nắp một chai bia rồi rót 200 g bia vào cốc. Cho vào cốc 40 g nước đá ở nhiệt độ -2,80C thì ta sẽ được một cốc bia mát. Biết nhiệt dung riêng của bia là 3830 J/kg.K; nhiệt dung riêng của nước đá là 1800 J/kg.K; nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg; nhiệt dung riêng của nước là 4200 J/kg.K. Ban đầu bia có nhiệt độ là 320C. Bỏ qua sự trao đổi nhiệt với môi trường và sự trao đổi nhiệt với thành cốc. Sau khi nước đá tan hết, nhiệt độ của cốc bia là bao nhiêu 0C? (lấy đến một con số sau dấu phẩy).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045839334-hinh-20.jpg\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$Q=mc\\Delta t$<br>$Q_{thu}=0,04.1800.2,8+0,04.3,4.10^5+0,04.4200\\left(t_{cb}−0\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}Q_{toa}=0,2.3830.\\left(30−t_{cb}\\right)Website: thukhoadaihoc.vn$<br>$\\Rightarrow Q_{toa}=Q_{thu}\\Rightarrow t_{cb}=11,5^0C$","difficultySource":"ai"}}]},{"id":621419,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Để đúc các vật bằng thép, người ta phải nấu chảy thép trong lò. Khối thép được đưa vào lò với nhiệt độ ban đầu là 200C. Để cung cấp nhiệt lượng, người ta đã đốt hết 200 kg than đá với năng suất tỏa nhiệt là 2,7.10<sup>7</sup> J/kg. Cho biết thép có nhiệt nóng chảy riêng là λ = 83,7.10<sup>3</sup> J/kg, nhiệt độ nóng chảy là 14000C, nhiệt dung riêng ở thể rắn là c = 460 J/(kg.K). Hiệu suất của lò là 60% (nghĩa là 60% nhiệt lượng cung cấp cho lò được dùng vào việc đun nóng thép cho đến khi thép nóng chảy).","difficulty":"kho","statements":[{"text":"Nhiệt lượng thực tế truyền cho thép là 3,24.10<sup>9</sup> J.","answer":true},{"text":"Hiệu suất của lò càng cao thì lượng thép nung chảy từ cùng một lượng than sẽ càng nhiều.","answer":true},{"text":"Khối lượng của mẻ thép bị nấu chảy là 4830,5 kg.","answer":false},{"text":"Nhiệt lượng cần thiết để nung chảy thép chỉ phụ thuộc vào nhiệt dung riêng của thép.","answer":false}],"explanation":"a) đúng; b) đúng<br>$Q_{dd}=qm=2,7\\cdot 10^7.200=5,4.10^9 J$<br>$Q_t=HQ_{dd}=0,6.5,4.10^9=3,24.10^9 J\\Rightarrow$<br>c) sai; d) sai<br>$\\begin{aligned}\\end{aligned}Q_t=m_tc\\Delta t+m_t\\lambda \\Rightarrow 3,24\\cdot 10^9=m_t\\cdot 460\\cdot (1400−20)+m_t\\cdot 83,7\\cdot 10^3\\Rightarrow m_t\\approx 4509,4 kgWebsite: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":335,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Để đúc các vật bằng thép, người ta phải nấu chảy thép trong lò. Khối thép được đưa vào lò với nhiệt độ ban đầu là 200C. Để cung cấp nhiệt lượng, người ta đã đốt hết 200 kg than đá với năng suất tỏa nhiệt là 2,7.10<sup>7</sup> J/kg. Cho biết thép có nhiệt nóng chảy riêng là λ = 83,7.10<sup>3</sup> J/kg, nhiệt độ nóng chảy là 14000C, nhiệt dung riêng ở thể rắn là c = 460 J/(kg.K). Hiệu suất của lò là 60% (nghĩa là 60% nhiệt lượng cung cấp cho lò được dùng vào việc đun nóng thép cho đến khi thép nóng chảy).","difficulty":"kho","statements":[{"text":"Nhiệt lượng thực tế truyền cho thép là 3,24.10<sup>9</sup> J.","answer":true},{"text":"Hiệu suất của lò càng cao thì lượng thép nung chảy từ cùng một lượng than sẽ càng nhiều.","answer":true},{"text":"Khối lượng của mẻ thép bị nấu chảy là 4830,5 kg.","answer":false},{"text":"Nhiệt lượng cần thiết để nung chảy thép chỉ phụ thuộc vào nhiệt dung riêng của thép.","answer":false}],"explanation":"a) đúng; b) đúng<br>$Q_{dd}=qm=2,7\\cdot 10^7.200=5,4.10^9 J$<br>$Q_t=HQ_{dd}=0,6.5,4.10^9=3,24.10^9 J\\Rightarrow$<br>c) sai; d) sai<br>$\\begin{aligned}\\end{aligned}Q_t=m_tc\\Delta t+m_t\\lambda \\Rightarrow 3,24\\cdot 10^9=m_t\\cdot 460\\cdot (1400−20)+m_t\\cdot 83,7\\cdot 10^3\\Rightarrow m_t\\approx 4509,4 kgWebsite: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":626714,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":0,"options":["1298 kJ .","1130 kJ .","168 kJ .","2596 kJ ."],"question":"Biết nhiệt dung riêng của nước là 4200 J/(kg.K), nhiệt hóa hơi riêng của nước ở 1000C là 2,26.10<sup>6</sup> J/ kg. Nhiệt lượng cần thiết để làm cho 500 g nước ở 200C chuyển hoàn toàn thành hơi nước ở 1000C là","difficulty":"trung-binh","explanation":"$Q=mc\\Delta t+mL=0,5.4200.\\left(100−20\\right)+0,5.2,26.10^6=1298000\\left(J\\right)=1298\\left(kJ\\right)$","difficultySource":"ai"},"ex":[{"exam":343,"idx":1,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":0,"options":["1298 kJ .","1130 kJ .","168 kJ .","2596 kJ ."],"question":"Biết nhiệt dung riêng của nước là 4200 J/(kg.K), nhiệt hóa hơi riêng của nước ở 1000C là 2,26.10<sup>6</sup> J/ kg. Nhiệt lượng cần thiết để làm cho 500 g nước ở 200C chuyển hoàn toàn thành hơi nước ở 1000C là","difficulty":"trung-binh","explanation":"$Q=mc\\Delta t+mL=0,5.4200.\\left(100−20\\right)+0,5.2,26.10^6=1298000\\left(J\\right)=1298\\left(kJ\\right)$","difficultySource":"ai"}}]},{"id":626733,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","question":"Một nhà máy điện hạt nhân dùng nhiên liệu uranium ${}_{92}^{235}U$ . Biết công suất phát điện là 500 MW và hiệu suất chuyển hóa năng lượng hạt nhân thành điện năng là 20%. Cho rằng khi một hạt nhân uranium  ${}_{92}^{235}U$  phân hạch thì tỏa ra năng lượng là 3,20.10<sup>−11</sup>J . Biết khối lượng mol của  ${}_{92}^{235}U$  là 235 g/mol.","difficulty":"kho","statements":[{"text":"Phản ứng hạt nhân được khai thác bên trong các nhà máy điện hạt nhân hầu hết là phản ứng phân hạch.","answer":true},{"text":"Năng lượng điện nhà máy cung cấp trong 1 giờ là 0,50.109J","answer":false},{"text":"Năng lượng 1g  ${}_{92}^{235}U$  phân hạch tỏa ra là 1,93.10<sup>14</sup>MeV","answer":false},{"text":"Nếu nhà máy hoạt động liên tục trong 365 ngày thì lượng uranium  ${}_{92}^{235}U$  cần dùng là 926 kg .","answer":false}],"explanation":"a) đúng<br>Phản ứng hạt nhân được khai thác bên trong các nhà máy điện hạt nhân hầu hết là phản ứng phân hạch.<br>b) sai<br>$A=Pt=500.10^6.60.60=1,8.10^{12}J$<br>c) sai<br>$n=\\frac{m}{M}=\\frac{1}{235}mol$<br>$N=nN_A=\\frac{1}{235}.6,02.10^{23}\\approx 2,562.10^{21}$<br>$Q=N\\Delta E=2,562.3,3.10^{−11}\\approx 8,2.10^{10}J\\approx 5,125.10^{23}\\left(MeV\\right)$<br>d) sai<br>$A_d=Pt_d=500.10^6.365.24.60.60=1,5768.10^{16}\\left(J\\right)$<br>$Q_d=\\frac{A_d}{H}=\\frac{1,5768.10^{16}}{0,2}=7,884.10^{16}\\left(J\\right)$<br>$m_U=\\frac{Q_d}{Q}=\\frac{7,8984.10^{16}}{8,2.10^{10}}\\approx 9,6.10^5g=9,6.10^2kg$","difficultySource":"ai"},"ex":[{"exam":343,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","question":"Một nhà máy điện hạt nhân dùng nhiên liệu uranium ${}_{92}^{235}U$ . Biết công suất phát điện là 500 MW và hiệu suất chuyển hóa năng lượng hạt nhân thành điện năng là 20%. Cho rằng khi một hạt nhân uranium  ${}_{92}^{235}U$  phân hạch thì tỏa ra năng lượng là 3,20.10<sup>−11</sup>J . Biết khối lượng mol của  ${}_{92}^{235}U$  là 235 g/mol.","difficulty":"kho","statements":[{"text":"Phản ứng hạt nhân được khai thác bên trong các nhà máy điện hạt nhân hầu hết là phản ứng phân hạch.","answer":true},{"text":"Năng lượng điện nhà máy cung cấp trong 1 giờ là 0,50.109J","answer":false},{"text":"Năng lượng 1g  ${}_{92}^{235}U$  phân hạch tỏa ra là 1,93.10<sup>14</sup>MeV","answer":false},{"text":"Nếu nhà máy hoạt động liên tục trong 365 ngày thì lượng uranium  ${}_{92}^{235}U$  cần dùng là 926 kg .","answer":false}],"explanation":"a) đúng<br>Phản ứng hạt nhân được khai thác bên trong các nhà máy điện hạt nhân hầu hết là phản ứng phân hạch.<br>b) sai<br>$A=Pt=500.10^6.60.60=1,8.10^{12}J$<br>c) sai<br>$n=\\frac{m}{M}=\\frac{1}{235}mol$<br>$N=nN_A=\\frac{1}{235}.6,02.10^{23}\\approx 2,562.10^{21}$<br>$Q=N\\Delta E=2,562.3,3.10^{−11}\\approx 8,2.10^{10}J\\approx 5,125.10^{23}\\left(MeV\\right)$<br>d) sai<br>$A_d=Pt_d=500.10^6.365.24.60.60=1,5768.10^{16}\\left(J\\right)$<br>$Q_d=\\frac{A_d}{H}=\\frac{1,5768.10^{16}}{0,2}=7,884.10^{16}\\left(J\\right)$<br>$m_U=\\frac{Q_d}{Q}=\\frac{7,8984.10^{16}}{8,2.10^{10}}\\approx 9,6.10^5g=9,6.10^2kg$","difficultySource":"ai"}}]},{"id":626735,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"98","question":"Một thợ hàn dùng bình có thể tích 0,075 m3 đổ đầy oxygen (khối lượng mol 32 g/mol ) ở áp suất đo được là 4,01.10<sup>5</sup> Pa và nhiệt độ 370C. Bình chứa có một kẽ hở nhỏ, theo thời gian một phần oxygen sẽ rò rỉ ra ngoài. Vào một ngày khi nhiệt độ là 220C, áp suất của oxygen trong bình là 2,81.10<sup>5</sup>. Khối lượng oxygen thoát ra ngoài là bao nhiêu gam (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"$\\frac{pV}{T}=nR=\\frac{m}{M}R\\Rightarrow m=\\frac{pVM}{RT}$<br>$\\Rightarrow \\Delta m=\\frac{VM}{R}\\left(\\frac{p_1}{T_1}−\\frac{p_2}{T_2}\\right)=\\frac{0,075.32.10^{−3}}{8,31}.\\left(\\frac{4,01.10^5}{37+273}−\\frac{2,81.10^5}{22+273}\\right)\\approx 0,098kg=98g$","difficultySource":"ai"},"ex":[{"exam":343,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"98","question":"Một thợ hàn dùng bình có thể tích 0,075 m3 đổ đầy oxygen (khối lượng mol 32 g/mol ) ở áp suất đo được là 4,01.10<sup>5</sup> Pa và nhiệt độ 370C. Bình chứa có một kẽ hở nhỏ, theo thời gian một phần oxygen sẽ rò rỉ ra ngoài. Vào một ngày khi nhiệt độ là 220C, áp suất của oxygen trong bình là 2,81.10<sup>5</sup>. Khối lượng oxygen thoát ra ngoài là bao nhiêu gam (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"$\\frac{pV}{T}=nR=\\frac{m}{M}R\\Rightarrow m=\\frac{pVM}{RT}$<br>$\\Rightarrow \\Delta m=\\frac{VM}{R}\\left(\\frac{p_1}{T_1}−\\frac{p_2}{T_2}\\right)=\\frac{0,075.32.10^{−3}}{8,31}.\\left(\\frac{4,01.10^5}{37+273}−\\frac{2,81.10^5}{22+273}\\right)\\approx 0,098kg=98g$","difficultySource":"ai"}}]},{"id":627224,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":3,"options":["6,7.10<sup>−3</sup>T","1,8.10<sup>−3</sup>T","1,5 T.","0,60 T."],"question":"Một dây dẫn dài 50 cm được đặt vuông góc với một từ trường đều. Cường độ dòng điện chạy trong dây dẫn là 10,0 A, lực do từ trường tác dụng lên dây dẫn là 3,0 N. Độ lớn cảm ứng từ của từ trường là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đoạn dây dẫn đặt vuông góc với từ trường đều nên góc giữa dòng điện và cảm ứng từ là $\\alpha = 90^\\circ$, $\\sin\\alpha = 1$.</p><p class=\"text-base leading-relaxed my-2\">Lực từ tác dụng lên đoạn dây dẫn (lực Ampère): $F = B\\,I\\,l\\,\\sin\\alpha$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra cảm ứng từ: $B = \\dfrac{F}{I\\,l}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $l = 50\\text{ cm} = 0{,}50\\text{ m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $B = \\dfrac{3{,}0}{10{,}0 \\cdot 0{,}50} = 0{,}60\\text{ T}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy độ lớn cảm ứng từ là $B = 0{,}60\\text{ T}$, đáp án D.</p>","difficultySource":"ai"},"ex":[{"exam":345,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":3,"options":["6,7.10<sup>−3</sup>T","1,8.10<sup>−3</sup>T","1,5 T.","0,60 T."],"question":"Một dây dẫn dài 50 cm được đặt vuông góc với một từ trường đều. Cường độ dòng điện chạy trong dây dẫn là 10,0 A, lực do từ trường tác dụng lên dây dẫn là 3,0 N. Độ lớn cảm ứng từ của từ trường là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đoạn dây dẫn đặt vuông góc với từ trường đều nên góc giữa dòng điện và cảm ứng từ là $\\alpha = 90^\\circ$, $\\sin\\alpha = 1$.</p><p class=\"text-base leading-relaxed my-2\">Lực từ tác dụng lên đoạn dây dẫn (lực Ampère): $F = B\\,I\\,l\\,\\sin\\alpha$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra cảm ứng từ: $B = \\dfrac{F}{I\\,l}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $l = 50\\text{ cm} = 0{,}50\\text{ m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $B = \\dfrac{3{,}0}{10{,}0 \\cdot 0{,}50} = 0{,}60\\text{ T}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy độ lớn cảm ứng từ là $B = 0{,}60\\text{ T}$, đáp án D.</p>","difficultySource":"ai"}}]},{"id":627230,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật bảo toàn động lượng trong va chạm","answer":0,"options":["3,2 m/s.","4 m/s .","5 m/s.","40 m/s ."],"question":"Biết diện tích tiết diện của ống bằng 8.10<sup>−5</sup> m2; khối lượng của cục giấy bằng 100 g . Giả sử thời gian tác dụng của lực nén lên cục giấy là 0,01 s thì nó được bắn đi với tốc độ bằng","difficulty":"trung-binh","explanation":"$F=\\left(p^/−p_0\\right)S=\\left(5.10^5−10^5\\right).8.10^{−5}=32N$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Biến thiên động lượng = xung lượng của lực<br>$\\Rightarrow mV=F.\\Delta t\\Rightarrow 0,1.v=32.0,01\\Rightarrow v=3,2\\left(m/s\\right)$","difficultySource":"ai"},"ex":[{"exam":345,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật bảo toàn động lượng trong va chạm","answer":0,"options":["3,2 m/s.","4 m/s .","5 m/s.","40 m/s ."],"question":"Biết diện tích tiết diện của ống bằng 8.10<sup>−5</sup> m2; khối lượng của cục giấy bằng 100 g . Giả sử thời gian tác dụng của lực nén lên cục giấy là 0,01 s thì nó được bắn đi với tốc độ bằng","difficulty":"trung-binh","explanation":"$F=\\left(p^/−p_0\\right)S=\\left(5.10^5−10^5\\right).8.10^{−5}=32N$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Biến thiên động lượng = xung lượng của lực<br>$\\Rightarrow mV=F.\\Delta t\\Rightarrow 0,1.v=32.0,01\\Rightarrow v=3,2\\left(m/s\\right)$","difficultySource":"ai"}}]},{"id":627231,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":1,"options":["1,61.10<sup>19</sup> Bq","3,87.10<sup>13</sup> Bq","3,87.10<sup>19</sup> Bq","1,61.10<sup>12</sup> Bq"],"question":"Chất phóng xạ chứa đồng vị  ${}_{11}^{24}Na$  được sử dụng làm chất đánh dấu điện giải có chu kì bán rã là 15,00 giờ. Một bệnh nhân được tiêm 5,00ml dược chất chứa  ${}_{11}^{24}Na$ với nồng độ 1,002.10<sup>−3</sup> mol/ℓ. Cho số Avogadro là NA = 6,02.10<sup>23</sup> mol−1. Độ phóng xạ của liều dược chất tại thời điểm tiêm là","difficulty":"trung-binh","explanation":"$n=CV=1,002.10^{−3}.5.10^{−3}=5,01.10^{−6}\\left(mol\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$N=nN_A=5,01.10^{−6}.6,02.10^{23}=3,01602.10^{18}$<br>$\\begin{aligned}\\end{aligned}H=\\lambda N=\\frac{ln2}{T}.N=\\frac{ln2}{15.60.60}.3,01602.10^{18}\\approx 3,87.10^{13}BqWebsite: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":345,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":1,"options":["1,61.10<sup>19</sup> Bq","3,87.10<sup>13</sup> Bq","3,87.10<sup>19</sup> Bq","1,61.10<sup>12</sup> Bq"],"question":"Chất phóng xạ chứa đồng vị  ${}_{11}^{24}Na$  được sử dụng làm chất đánh dấu điện giải có chu kì bán rã là 15,00 giờ. Một bệnh nhân được tiêm 5,00ml dược chất chứa  ${}_{11}^{24}Na$ với nồng độ 1,002.10<sup>−3</sup> mol/ℓ. Cho số Avogadro là NA = 6,02.10<sup>23</sup> mol−1. Độ phóng xạ của liều dược chất tại thời điểm tiêm là","difficulty":"trung-binh","explanation":"$n=CV=1,002.10^{−3}.5.10^{−3}=5,01.10^{−6}\\left(mol\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$N=nN_A=5,01.10^{−6}.6,02.10^{23}=3,01602.10^{18}$<br>$\\begin{aligned}\\end{aligned}H=\\lambda N=\\frac{ln2}{T}.N=\\frac{ln2}{15.60.60}.3,01602.10^{18}\\approx 3,87.10^{13}BqWebsite: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":627235,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Để xác định nhiệt nóng chảy riêng của nước đá, có thể tiến hành thí nghiệm theo sơ đồ nguyên lí như hình dưới đây. Dòng điện làm nóng dây điện trở trong một nhiệt lượng kế và làm nước đá nóng chảy. Lượng nước thu được sau khi toàn bộ nước đá nóng chảy được đem đi cân thì thấy nó có khối lượng 15 g . Công suất điện tiêu thụ được xác định bằng oát kế là 24 W . Thời gian đun được xác định bằng đồng hồ là 180 s . Bỏ qua sự trao đổi nhiệt với môi trường xung quanh.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046058552-hinh-7.jpg\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Ở áp suất tiêu chuẩn, nưởc đá tinh khiết nóng chảy ở nhiệt độ 1000C.","answer":false},{"text":"Khi nóng chảy hoàn toàn, thể tích nước tạo thành lớn hơn tổng thể tích nước đá ban đầu.","answer":false},{"text":"Nhiệt lượng nước đá nhận được từ dây điện trở trong thời gian đun là 4320 J .","answer":true},{"text":"Nhiệt nóng chảy riêng λ của nước đá đo được là 3,3.10<sup>5</sup> J/kg","answer":false}],"explanation":"a) sai<br>Ở áp suất tiêu chuẩn, nước đá tinh khiết nóng chảy ở nhiệt độ 00C.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>Thể tích nước nhỏ hơn thể tích nước đá<br>c) đúng<br>Q = Pt = 24.180 = 4320 J<br>d) sai<br>$\\lambda =\\frac{Q}{m}=\\frac{4320}{0,015}=2,88.10^5 J/kg$","difficultySource":"ai"},"ex":[{"exam":345,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Để xác định nhiệt nóng chảy riêng của nước đá, có thể tiến hành thí nghiệm theo sơ đồ nguyên lí như hình dưới đây. Dòng điện làm nóng dây điện trở trong một nhiệt lượng kế và làm nước đá nóng chảy. Lượng nước thu được sau khi toàn bộ nước đá nóng chảy được đem đi cân thì thấy nó có khối lượng 15 g . Công suất điện tiêu thụ được xác định bằng oát kế là 24 W . Thời gian đun được xác định bằng đồng hồ là 180 s . Bỏ qua sự trao đổi nhiệt với môi trường xung quanh.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046058552-hinh-7.jpg\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Ở áp suất tiêu chuẩn, nưởc đá tinh khiết nóng chảy ở nhiệt độ 1000C.","answer":false},{"text":"Khi nóng chảy hoàn toàn, thể tích nước tạo thành lớn hơn tổng thể tích nước đá ban đầu.","answer":false},{"text":"Nhiệt lượng nước đá nhận được từ dây điện trở trong thời gian đun là 4320 J .","answer":true},{"text":"Nhiệt nóng chảy riêng λ của nước đá đo được là 3,3.10<sup>5</sup> J/kg","answer":false}],"explanation":"a) sai<br>Ở áp suất tiêu chuẩn, nước đá tinh khiết nóng chảy ở nhiệt độ 00C.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>Thể tích nước nhỏ hơn thể tích nước đá<br>c) đúng<br>Q = Pt = 24.180 = 4320 J<br>d) sai<br>$\\lambda =\\frac{Q}{m}=\\frac{4320}{0,015}=2,88.10^5 J/kg$","difficultySource":"ai"}}]},{"id":627478,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":0,"options":["1,68 kg.","18,7 kg.","18,7 g.","1,68 g ."],"question":"Một bình chứa khí nitreugen (N2) có thể tích 1 m3, ở áp suất 1,5.10<sup>5</sup> Pavà nhiệt độ 270C. Biết 1 mol khí N2 có khối lượng 28 g . Khối lượng khí nitreugen trong bình gần nhất với giá trị nào sau đây?","difficulty":"trung-binh","explanation":"$\\frac{pV}{T}=nR\\Rightarrow \\frac{1,5.10^5.1}{27+273}=n.8,31\\Rightarrow n\\approx 60,168\\left(mol\\right)$<br>$m=nM=60,168.28\\approx 1,68.10^3g=1,68\\left(kg\\right)$","difficultySource":"ai"},"ex":[{"exam":346,"idx":11,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":0,"options":["1,68 kg.","18,7 kg.","18,7 g.","1,68 g ."],"question":"Một bình chứa khí nitreugen (N2) có thể tích 1 m3, ở áp suất 1,5.10<sup>5</sup> Pavà nhiệt độ 270C. Biết 1 mol khí N2 có khối lượng 28 g . Khối lượng khí nitreugen trong bình gần nhất với giá trị nào sau đây?","difficulty":"trung-binh","explanation":"$\\frac{pV}{T}=nR\\Rightarrow \\frac{1,5.10^5.1}{27+273}=n.8,31\\Rightarrow n\\approx 60,168\\left(mol\\right)$<br>$m=nM=60,168.28\\approx 1,68.10^3g=1,68\\left(kg\\right)$","difficultySource":"ai"}}]},{"id":627481,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật phóng xạ và chu kì bán rã","answer":2,"options":["16.1024 hạt.","48.1024 hạt.","60.1024 hạt.","4.10<sup>24</sup> hạt."],"question":"Trong một trung tâm nghiên cứu y học hạt nhân, các nhà khoa học đang theo dõi sự phân rã của một mẫu chất phóng xạ dùng để điều trị ung thư. Sự thay đổi số hạt nhân chất phóng xạ theo thời gian được mô tả theo đồ thị hình bên. Sau 32 ngày kể từ thời điểm khảo sát, số hạt nhân phóng xạ đã bị phân rã là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046064842-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"$N=N_0.2^{−\\frac{t_1}{T}}\\Rightarrow 16=64.2^{−\\frac{16}{T}}\\Rightarrow T=8$ (ngày)<br>$\\Delta N=N_0\\left(1−2^{−\\frac{t_2}{T}}\\right)=64.10^{24}.\\left(1−2^{\\frac{−32}{8}}\\right)=60.10^{24}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":346,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật phóng xạ và chu kì bán rã","answer":2,"options":["16.1024 hạt.","48.1024 hạt.","60.1024 hạt.","4.10<sup>24</sup> hạt."],"question":"Trong một trung tâm nghiên cứu y học hạt nhân, các nhà khoa học đang theo dõi sự phân rã của một mẫu chất phóng xạ dùng để điều trị ung thư. Sự thay đổi số hạt nhân chất phóng xạ theo thời gian được mô tả theo đồ thị hình bên. Sau 32 ngày kể từ thời điểm khảo sát, số hạt nhân phóng xạ đã bị phân rã là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046064842-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"$N=N_0.2^{−\\frac{t_1}{T}}\\Rightarrow 16=64.2^{−\\frac{16}{T}}\\Rightarrow T=8$ (ngày)<br>$\\Delta N=N_0\\left(1−2^{−\\frac{t_2}{T}}\\right)=64.10^{24}.\\left(1−2^{\\frac{−32}{8}}\\right)=60.10^{24}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":627488,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Các nhà khoa học sử dụng phương pháp xác định tuổi bằng đồng vị  ${}_6^{14}C$ để xác định niên đại của một cổ vật làm bằng gỗ. Khi cây còn sống, nhờ sự trao đổi chất với môi trường nên tỉ số giữa số nguyên tử  ${}_6^{14}C$ và số nguyên tử  ${}_6^{12}C$ có trong cây luôn không đổi. Khi cây chết, sự trao đổi chất không còn nữa, ti số giữa số nguyên tử  ${}_6^{14}C$ và số nguyên tử  ${}_6^{12}C$ có trong gỗ giảm đi do  ${}_6^{14}C$ là chất phóng xạ β− với chu kì bán rã 5730 năm. Một mảnh gỗ của cổ vật có số phân rã của  ${}_6^{14}C$  trong 1 giờ là 547 . Biết rằng, mảnh gỗ cùng khối lượng của cây cùng loại khi mới chặt có số phân rã của  ${}_6^{14}C$  trong 1 giờ là 855 .","difficulty":"kho","statements":[{"text":"Hằng số phóng xạ của  ${}_6^{14}C$ là 1,21.10<sup>−4</sup> s-1","answer":false},{"text":"Phương pháp xác định tuổi bằng đồng vị  ${}_6^{14}C$ cũng có thể dùng để xác định tuổi của các mẫu xương từ thời cổ đại.","answer":true},{"text":"Tuổi của cổ vật là 3692 năm (làm tròn kết quả đến chữ số hàng đơn vị).","answer":true},{"text":"Hạt nhân  ${}_6^{14}C$ phóng ra hạt electron để biến đổi thành hạt nhân  ${}_7^{14}N$","answer":true}],"explanation":"a) sai<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{5730.365.24.60.60}\\approx 3,8.10^{−12}s^{−1}$<br>b) đúng<br>Phương pháp xác định tuổi bằng đồng vị  cũng có thể dùng để xác định tuổi của các mẫu xương từ thời cổ đại.<br>c) đúng<br>$\\left\\{\\begin{aligned}\\Delta N_1=N_0.\\left(1−2^{−\\frac{\\Delta t}{T}}\\right) <br>\\Delta N_2=N_0.2^{−\\frac{t}{T}}.\\left(1−2^{−\\frac{\\Delta t}{T}}\\right)\\end{aligned}\\right.\\Rightarrow \\frac{\\Delta N_1}{\\Delta N_2}=2^{\\frac{t}{T}}\\Rightarrow \\frac{855}{547}=2^{\\frac{t}{5730}}\\Rightarrow t\\approx 3692$  (năm)<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>${}_6^{14}C\\rightarrow_{−1}^0e+_7^{14}N$","difficultySource":"ai"},"ex":[{"exam":346,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Các nhà khoa học sử dụng phương pháp xác định tuổi bằng đồng vị  ${}_6^{14}C$ để xác định niên đại của một cổ vật làm bằng gỗ. Khi cây còn sống, nhờ sự trao đổi chất với môi trường nên tỉ số giữa số nguyên tử  ${}_6^{14}C$ và số nguyên tử  ${}_6^{12}C$ có trong cây luôn không đổi. Khi cây chết, sự trao đổi chất không còn nữa, ti số giữa số nguyên tử  ${}_6^{14}C$ và số nguyên tử  ${}_6^{12}C$ có trong gỗ giảm đi do  ${}_6^{14}C$ là chất phóng xạ β− với chu kì bán rã 5730 năm. Một mảnh gỗ của cổ vật có số phân rã của  ${}_6^{14}C$  trong 1 giờ là 547 . Biết rằng, mảnh gỗ cùng khối lượng của cây cùng loại khi mới chặt có số phân rã của  ${}_6^{14}C$  trong 1 giờ là 855 .","difficulty":"kho","statements":[{"text":"Hằng số phóng xạ của  ${}_6^{14}C$ là 1,21.10<sup>−4</sup> s-1","answer":false},{"text":"Phương pháp xác định tuổi bằng đồng vị  ${}_6^{14}C$ cũng có thể dùng để xác định tuổi của các mẫu xương từ thời cổ đại.","answer":true},{"text":"Tuổi của cổ vật là 3692 năm (làm tròn kết quả đến chữ số hàng đơn vị).","answer":true},{"text":"Hạt nhân  ${}_6^{14}C$ phóng ra hạt electron để biến đổi thành hạt nhân  ${}_7^{14}N$","answer":true}],"explanation":"a) sai<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{5730.365.24.60.60}\\approx 3,8.10^{−12}s^{−1}$<br>b) đúng<br>Phương pháp xác định tuổi bằng đồng vị  cũng có thể dùng để xác định tuổi của các mẫu xương từ thời cổ đại.<br>c) đúng<br>$\\left\\{\\begin{aligned}\\Delta N_1=N_0.\\left(1−2^{−\\frac{\\Delta t}{T}}\\right) <br>\\Delta N_2=N_0.2^{−\\frac{t}{T}}.\\left(1−2^{−\\frac{\\Delta t}{T}}\\right)\\end{aligned}\\right.\\Rightarrow \\frac{\\Delta N_1}{\\Delta N_2}=2^{\\frac{t}{T}}\\Rightarrow \\frac{855}{547}=2^{\\frac{t}{5730}}\\Rightarrow t\\approx 3692$  (năm)<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>${}_6^{14}C\\rightarrow_{−1}^0e+_7^{14}N$","difficultySource":"ai"}}]},{"id":627489,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"0,64","question":"Một nhà máy điện hạt nhân dùng nguyên liệu  ${}_{92}^{235}U$ , có công suất phát điện 600 MW. Cho biết mỗi hạt nhân  ${}_{92}^{235}U$ bị phân hạch toả ra năng lượng trung bình là 200 MeV . Hiệu suất nhà máy điện hạt nhân này là 36%. Biết khối lượng mol nguyên tử của  ${}_{92}^{235}U$ là 235 g/mol, 1eV = 1,6.10<sup>−19</sup>J. Khối lượng nguyên liệu cần cung cấp cho nhà máy trong 1 năm là bao nhiêu tấn (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"kho","explanation":"$A=Pt=600.10^6.365.24.60.60=1,89216.10^{16}J$<br>$Q=\\frac{A}{H}=\\frac{1,89216.10^{16}}{0,36}=5,256.10^{16}J$<br>$N=\\frac{Q}{\\Delta E}=\\frac{5,256.10^{16}}{200.1,6.10^{−13}}=1,6425.10^{27}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}n=\\frac{N}{N_A}=\\frac{1,6425.10^{27}}{6,02.10^{23}}\\approx 2728,4 molWebsite: thukhoadaihoc.vn$<br>$m=nM=2728,4.0,235\\approx 641kg\\approx 0,64$  tấn","difficultySource":"ai"},"ex":[{"exam":346,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"0,64","question":"Một nhà máy điện hạt nhân dùng nguyên liệu  ${}_{92}^{235}U$ , có công suất phát điện 600 MW. Cho biết mỗi hạt nhân  ${}_{92}^{235}U$ bị phân hạch toả ra năng lượng trung bình là 200 MeV . Hiệu suất nhà máy điện hạt nhân này là 36%. Biết khối lượng mol nguyên tử của  ${}_{92}^{235}U$ là 235 g/mol, 1eV = 1,6.10<sup>−19</sup>J. Khối lượng nguyên liệu cần cung cấp cho nhà máy trong 1 năm là bao nhiêu tấn (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"kho","explanation":"$A=Pt=600.10^6.365.24.60.60=1,89216.10^{16}J$<br>$Q=\\frac{A}{H}=\\frac{1,89216.10^{16}}{0,36}=5,256.10^{16}J$<br>$N=\\frac{Q}{\\Delta E}=\\frac{5,256.10^{16}}{200.1,6.10^{−13}}=1,6425.10^{27}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}n=\\frac{N}{N_A}=\\frac{1,6425.10^{27}}{6,02.10^{23}}\\approx 2728,4 molWebsite: thukhoadaihoc.vn$<br>$m=nM=2728,4.0,235\\approx 641kg\\approx 0,64$  tấn","difficultySource":"ai"}}]},{"id":628982,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":2,"options":["1,1.10<sup>25</sup>","5,4.10<sup>25</sup>","1,1.10<sup>22</sup>","5,4.10<sup>22</sup>"],"question":"Biết không khí có khối lượng mol là M = 29 g/mol và khối lượng riêng D = 1,29 kg/m3; NA = 6,02.10<sup>23</sup>. Khi một học sinh hít một hơi thật sâu thì hít vào khoảng 400 cm3 không khí. Một hơi hít sâu như vậy có bao nhiêu phân tử không khí được hít vào?","difficulty":"trung-binh","explanation":"Phương pháp:<br>Sử dụng các công thức:  $\\left\\{\\begin{aligned}m=VD <br>N=n.N_A=\\frac{m}{M}.N_A\\end{aligned}\\right.$<br>Cách giải:<br>Khối lượng không khí được hút vào là:<br>$m=VD=400.10^{−6}.1,29=5,16.10^{−4}\\left(kg\\right)=0,516\\left(g\\right)$<br>Số phân tử không khí được hít vào là:<br>$N=\\frac{m}{M}.N_A=\\frac{0,516}{29}.6,02.10^{23}\\approx 1,1.10^{22}$  (phân tử)","difficultySource":"ai"},"ex":[{"exam":347,"idx":0,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":2,"options":["1,1.10<sup>25</sup>","5,4.10<sup>25</sup>","1,1.10<sup>22</sup>","5,4.10<sup>22</sup>"],"question":"Biết không khí có khối lượng mol là M = 29 g/mol và khối lượng riêng D = 1,29 kg/m3; NA = 6,02.10<sup>23</sup>. Khi một học sinh hít một hơi thật sâu thì hít vào khoảng 400 cm3 không khí. Một hơi hít sâu như vậy có bao nhiêu phân tử không khí được hít vào?","difficulty":"trung-binh","explanation":"Phương pháp:<br>Sử dụng các công thức:  $\\left\\{\\begin{aligned}m=VD <br>N=n.N_A=\\frac{m}{M}.N_A\\end{aligned}\\right.$<br>Cách giải:<br>Khối lượng không khí được hút vào là:<br>$m=VD=400.10^{−6}.1,29=5,16.10^{−4}\\left(kg\\right)=0,516\\left(g\\right)$<br>Số phân tử không khí được hít vào là:<br>$N=\\frac{m}{M}.N_A=\\frac{0,516}{29}.6,02.10^{23}\\approx 1,1.10^{22}$  (phân tử)","difficultySource":"ai"}}]},{"id":628990,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["Khối đồng cần thu nhiệt lượng 1,8.10<sup>5</sup> J để hoá lỏng.","Mỗi kilôgam đồng toả ra nhiệt lượng 1,8.10<sup>5</sup> J khi hoá lỏng hoàn toàn.","Khối đồng sẽ toả ra 1,8.10<sup>5</sup> J khi nóng chảy hoàn toàn.","Mỗi kilôgam đồng cần thu nhiệt lượng 1,8.10<sup>5</sup> J để hoá lỏng hoàn toàn ở nhiệt độ nóng chảy."],"question":"Nhiệt nóng chảy riêng của đồng là 1,8.10<sup>5</sup> J/kg. Câu nào dưới đây là đúng?","difficulty":"de","explanation":"Phương pháp:<br>Nhiệt nóng chảy riêng của một chất rắn có độ lớn bằng nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn 1kg chất rắn đó ở nhiệt độ nóng chảy.<br>Cách giải:<br>Nhiệt nóng chảy riêng của đồng là 1,8.10<sup>5</sup> J/kg<br>$\\Rightarrow$  Mỗi kilogam đồng cần thu nhiệt lượng là 1,8.10<sup>5</sup>J để hóa lỏng hoàn toàn ở nhiệt độ nóng chảy.","difficultySource":"ai"},"ex":[{"exam":347,"idx":8,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["Khối đồng cần thu nhiệt lượng 1,8.10<sup>5</sup> J để hoá lỏng.","Mỗi kilôgam đồng toả ra nhiệt lượng 1,8.10<sup>5</sup> J khi hoá lỏng hoàn toàn.","Khối đồng sẽ toả ra 1,8.10<sup>5</sup> J khi nóng chảy hoàn toàn.","Mỗi kilôgam đồng cần thu nhiệt lượng 1,8.10<sup>5</sup> J để hoá lỏng hoàn toàn ở nhiệt độ nóng chảy."],"question":"Nhiệt nóng chảy riêng của đồng là 1,8.10<sup>5</sup> J/kg. Câu nào dưới đây là đúng?","difficulty":"de","explanation":"Phương pháp:<br>Nhiệt nóng chảy riêng của một chất rắn có độ lớn bằng nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn 1kg chất rắn đó ở nhiệt độ nóng chảy.<br>Cách giải:<br>Nhiệt nóng chảy riêng của đồng là 1,8.10<sup>5</sup> J/kg<br>$\\Rightarrow$  Mỗi kilogam đồng cần thu nhiệt lượng là 1,8.10<sup>5</sup>J để hóa lỏng hoàn toàn ở nhiệt độ nóng chảy.","difficultySource":"ai"}}]},{"id":629004,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"0,2","question":"Vào mùa hè, một số người thường có thói quen uống trà đá. Để có một cốc trà đá chất lượng, người chủ quán rót khoảng 0,250 kg trà nóng ở 80,0°C vào cốc, sau đó cho tiếp m kg nước đá 0°C. Cuối cùng được cốc trà đá ở nhiệt độ phù hợp nhất là 10,0°C. Bỏ qua hao phí do trao đổi nhiệt với môi trường và cốc. Nhiệt dung riêng<br>của nước là 4,20 kJ/(kg.K); nhiệt nóng chảy của nước đá là 3,33.10<sup>5</sup> J/kg. Giá trị của m là bao nhiêu kg? (Viết kết quả đến một chữ số sau dấu phẩy thập phân).","difficulty":"trung-binh","explanation":"Phương pháp:<br>Nhiệt lượng làm tăng nhiệt độ của vật mà không chuyển thể: Q = mc∆T<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Nhiệt lượng làm nóng chảy vật hoàn toàn ở nhiệt độ nóng chảy: Q = mλ<br>Phương trình cân bằng nhiệt: Qtoa = Qthu<br>Cách giải:<br>Nhiệt lượng nước trà tỏa ra là:<br>$Q_{toa}=m_n.c_n.\\left(t_n−t\\right)=0,25.4200.\\left(80−10\\right)=73500\\left(J\\right)$<br>Nhiệt lượng nước đá thu vào là:<br>$Q_{thu}=m\\lambda +m.c_n.\\left(t−t_{nd}\\right)=m.3,33.10^5+m.4200.10$<br>$\\Rightarrow Q_{thu}=37500m$<br>Ta có phương trình cân bằng nhiệt:<br>$Q_{thu}=Q_{toa}\\Rightarrow 375000m=73500$<br>$\\Rightarrow m=0,196kg$","difficultySource":"ai"},"ex":[{"exam":347,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"0,2","question":"Vào mùa hè, một số người thường có thói quen uống trà đá. Để có một cốc trà đá chất lượng, người chủ quán rót khoảng 0,250 kg trà nóng ở 80,0°C vào cốc, sau đó cho tiếp m kg nước đá 0°C. Cuối cùng được cốc trà đá ở nhiệt độ phù hợp nhất là 10,0°C. Bỏ qua hao phí do trao đổi nhiệt với môi trường và cốc. Nhiệt dung riêng<br>của nước là 4,20 kJ/(kg.K); nhiệt nóng chảy của nước đá là 3,33.10<sup>5</sup> J/kg. Giá trị của m là bao nhiêu kg? (Viết kết quả đến một chữ số sau dấu phẩy thập phân).","difficulty":"trung-binh","explanation":"Phương pháp:<br>Nhiệt lượng làm tăng nhiệt độ của vật mà không chuyển thể: Q = mc∆T<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Nhiệt lượng làm nóng chảy vật hoàn toàn ở nhiệt độ nóng chảy: Q = mλ<br>Phương trình cân bằng nhiệt: Qtoa = Qthu<br>Cách giải:<br>Nhiệt lượng nước trà tỏa ra là:<br>$Q_{toa}=m_n.c_n.\\left(t_n−t\\right)=0,25.4200.\\left(80−10\\right)=73500\\left(J\\right)$<br>Nhiệt lượng nước đá thu vào là:<br>$Q_{thu}=m\\lambda +m.c_n.\\left(t−t_{nd}\\right)=m.3,33.10^5+m.4200.10$<br>$\\Rightarrow Q_{thu}=37500m$<br>Ta có phương trình cân bằng nhiệt:<br>$Q_{thu}=Q_{toa}\\Rightarrow 375000m=73500$<br>$\\Rightarrow m=0,196kg$","difficultySource":"ai"}}]},{"id":629478,"nq":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng áp và định luật Charles","question":"Có thể sử dụng bộ dụng cụ thí nghiệm như hình bên để tìm hiểu mối liên hệ giữa thể tích và nhiệt độ của một lượng khí xác định khi áp suất không đổi.<br>Lần đo\tNhiệt độ của khí trong xilanh t(0C)\tThể tích khí trong xilanh V (ml)<br>1\t45\t75<br>2\t41\t74<br>3\t37\t73<br>4\t32\t72<br>5\t28\t71<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046110001-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Khối khí trong xilanh gần đúng với khí lí tưởng.","answer":true},{"text":"Với kết quả thí nghiệm thu được ở bảng trên, công thức liên hệ giữa thể tích và nhiệt độ tuyệt đối là  V/T = 236.10<sup>−3</sup> (V đo bằng ml).","answer":true},{"text":"Trình tự thí nghiệm: Nén và giữ áp suất của khí trong xilanh không đổi, ghi lại các giá trị của thể tích và nhiệt độ của khí trong xilanh, lặp lại các thao tác.","answer":true},{"text":"Biết áp suất của khí trong xi lanh là 105 Pa, số phân tử khí trong xilanh là 1,71.10<sup>24</sup>.","answer":false}],"explanation":"a) đúng<br>$pV↓=nRT↓$<br>Với 1 lượng khí nhiệt độ không quá cao, áp suất không quá thấp → gần đúng với khí lý tưởng<br>b) đúng<br>Lần 1:  $45K\\Rightarrow 318K$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}\\frac{75}{318}=235,85.10^{−3}\\approx 236.10^{−3}Website: thukhoadaihoc.vn$<br>c) đúng<br>Trình tự thí nghiệm: Nén và giữ áp suất của khí trong xilanh không đổi, ghi lại các giá trị của thể tích và nhiệt độ của khí trong xilanh, lặp lại các thao tác.<br>d) sai<br>$pV=n.R.T\\Rightarrow 10^5.\\frac{V}{T}=n.8,31$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow 10^5.236.10^{−3}.10^{−6}=n.8,31Website: thukhoadaihoc.vn$<br>$\\Rightarrow n=2,84.10^3\\left(mol\\right)$<br>$\\Rightarrow n.N_A=1,71.10^{21}$  (phân tử)","difficultySource":"ai"},"ex":[{"exam":348,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng áp và định luật Charles","question":"Có thể sử dụng bộ dụng cụ thí nghiệm như hình bên để tìm hiểu mối liên hệ giữa thể tích và nhiệt độ của một lượng khí xác định khi áp suất không đổi.<br>Lần đo\tNhiệt độ của khí trong xilanh t(0C)\tThể tích khí trong xilanh V (ml)<br>1\t45\t75<br>2\t41\t74<br>3\t37\t73<br>4\t32\t72<br>5\t28\t71<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046110001-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Khối khí trong xilanh gần đúng với khí lí tưởng.","answer":true},{"text":"Với kết quả thí nghiệm thu được ở bảng trên, công thức liên hệ giữa thể tích và nhiệt độ tuyệt đối là  V/T = 236.10<sup>−3</sup> (V đo bằng ml).","answer":true},{"text":"Trình tự thí nghiệm: Nén và giữ áp suất của khí trong xilanh không đổi, ghi lại các giá trị của thể tích và nhiệt độ của khí trong xilanh, lặp lại các thao tác.","answer":true},{"text":"Biết áp suất của khí trong xi lanh là 105 Pa, số phân tử khí trong xilanh là 1,71.10<sup>24</sup>.","answer":false}],"explanation":"a) đúng<br>$pV↓=nRT↓$<br>Với 1 lượng khí nhiệt độ không quá cao, áp suất không quá thấp → gần đúng với khí lý tưởng<br>b) đúng<br>Lần 1:  $45K\\Rightarrow 318K$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}\\frac{75}{318}=235,85.10^{−3}\\approx 236.10^{−3}Website: thukhoadaihoc.vn$<br>c) đúng<br>Trình tự thí nghiệm: Nén và giữ áp suất của khí trong xilanh không đổi, ghi lại các giá trị của thể tích và nhiệt độ của khí trong xilanh, lặp lại các thao tác.<br>d) sai<br>$pV=n.R.T\\Rightarrow 10^5.\\frac{V}{T}=n.8,31$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow 10^5.236.10^{−3}.10^{−6}=n.8,31Website: thukhoadaihoc.vn$<br>$\\Rightarrow n=2,84.10^3\\left(mol\\right)$<br>$\\Rightarrow n.N_A=1,71.10^{21}$  (phân tử)","difficultySource":"ai"}}]},{"id":629482,"nq":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"2,52","question":"Hô hấp ký là một kỹ thuật thăm dò chức năng hô hấp bằng cách đo thể tích thông khí mà bệnh nhân có thể hít vào và thở ra với gắng sức tối đa. Dùng để tầm soát, chẩn đoán và theo dõi những bệnh lý hô hấp như hen suyễn, bệnh phổi tắc nghẽn mãn tính... cũng như những tình trạng, bệnh lý hoặc thuốc có ảnh hưởng đến chức năng hô hấp. Một bệnh nhân đến thăm khám tại bệnh viện và Bác sĩ sử dụng các kết quả hô hấp ký để xác định bạn có bị bệnh phổi tắc nghẽn mạn tính hay không và COPD nặng đến mức nào. Khi thở ra, dung tích của phổi là 2,50 lít và áp suất của không khí trong phổi là 101,75.10<sup>3</sup> Pa. Cho biết khi hít vào, áp suất này trở thành 101,04.10<sup>3</sup> Pa. Dung tích của phổi khi hít vào là bao nhiêu lít? Coi nhiệt độ khí trong phổi không đổi. (Kết quả làm tròn đến chữ số hàng phần trăm).","difficulty":"de","explanation":"$p_1V_1=p_2V_2$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow 2,5.101,75=101,04.V_2\\Rightarrow V_2=2,517\\left(lit\\right)\\approx 2,52\\left(lit\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":348,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"2,52","question":"Hô hấp ký là một kỹ thuật thăm dò chức năng hô hấp bằng cách đo thể tích thông khí mà bệnh nhân có thể hít vào và thở ra với gắng sức tối đa. Dùng để tầm soát, chẩn đoán và theo dõi những bệnh lý hô hấp như hen suyễn, bệnh phổi tắc nghẽn mãn tính... cũng như những tình trạng, bệnh lý hoặc thuốc có ảnh hưởng đến chức năng hô hấp. Một bệnh nhân đến thăm khám tại bệnh viện và Bác sĩ sử dụng các kết quả hô hấp ký để xác định bạn có bị bệnh phổi tắc nghẽn mạn tính hay không và COPD nặng đến mức nào. Khi thở ra, dung tích của phổi là 2,50 lít và áp suất của không khí trong phổi là 101,75.10<sup>3</sup> Pa. Cho biết khi hít vào, áp suất này trở thành 101,04.10<sup>3</sup> Pa. Dung tích của phổi khi hít vào là bao nhiêu lít? Coi nhiệt độ khí trong phổi không đổi. (Kết quả làm tròn đến chữ số hàng phần trăm).","difficulty":"de","explanation":"$p_1V_1=p_2V_2$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow 2,5.101,75=101,04.V_2\\Rightarrow V_2=2,517\\left(lit\\right)\\approx 2,52\\left(lit\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":629483,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"2,9","question":"Vận động viên chạy Marathon mất rất nhiều nước trong khi thi đấu. Các vận động viên thường chỉ có thể chuyển hóa khoảng 20% năng lượng hóa học dự trữ trong cơ thể thành năng lượng dùng cho các hoạt động của cơ thể, đặc biệt là hoạt động chạy. Phần năng lượng còn lại chuyển thành nhiệt thải ra ngoài nhờ sự bay hơi của nước qua hô hấp và da để giữ cho nhiệt độ của cơ thể không đổi. Nếu vận động viên dùng hết 9 MJ trong cuộc thi thì có khoảng bao nhiêu lít nước đã thoát ra khỏi cơ thể? Coi nhiệt độ cơ thể của vận động viên hoàn toàn không đổi và nhiệt hóa hơi riêng của nước trong cơ thể vận động viên là 2,45.10<sup>6</sup> J/kg. Lấy khối lượng riêng của mồ hôi là 1 kg/lít. (Kết quả làm tròn đến chữ số hàng phần mười).","difficulty":"de","explanation":"$Q_{nhiet}=9.10^6.80%=m.L=m.2,45.10^6$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow m=2,9387\\left(kg\\right)$<br>$V=2,9\\left(lit\\right)$","difficultySource":"ai"},"ex":[{"exam":348,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"2,9","question":"Vận động viên chạy Marathon mất rất nhiều nước trong khi thi đấu. Các vận động viên thường chỉ có thể chuyển hóa khoảng 20% năng lượng hóa học dự trữ trong cơ thể thành năng lượng dùng cho các hoạt động của cơ thể, đặc biệt là hoạt động chạy. Phần năng lượng còn lại chuyển thành nhiệt thải ra ngoài nhờ sự bay hơi của nước qua hô hấp và da để giữ cho nhiệt độ của cơ thể không đổi. Nếu vận động viên dùng hết 9 MJ trong cuộc thi thì có khoảng bao nhiêu lít nước đã thoát ra khỏi cơ thể? Coi nhiệt độ cơ thể của vận động viên hoàn toàn không đổi và nhiệt hóa hơi riêng của nước trong cơ thể vận động viên là 2,45.10<sup>6</sup> J/kg. Lấy khối lượng riêng của mồ hôi là 1 kg/lít. (Kết quả làm tròn đến chữ số hàng phần mười).","difficulty":"de","explanation":"$Q_{nhiet}=9.10^6.80%=m.L=m.2,45.10^6$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow m=2,9387\\left(kg\\right)$<br>$V=2,9\\left(lit\\right)$","difficultySource":"ai"}}]},{"id":630579,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một học sinh làm thí nghiệm xác định nhiệt nóng chảy riêng của nước đá với bộ dụng cụ gồm: Biến áp nguồn; nhiệt lượng kế có dây nung công suất P =10 W; cân điện tử; cốc hứng nước có khối lượng 50 g ; giá đõ. Bố trí thí nghiệm như hình bên, tiến hành và quan sát thí nghiệm qua hai giai đoạn liên tiếp:<br>Giai doạn 1: Cho khối nước đá đang tan vào nhiệt lượng kế, bật nguồn điện để dây nung nóng lên làm nước đá nóng chảy, cốc hứng nước đặt trên cân điện tử hứng nước chảy ra từ nhiệt<br>lượng kế và quan sát số chỉ của cân. Sau một thời gian kể từ khi cấp điện cho dây nung, tại thời điểm t1, thấy số chi của cân là 60 g .<br>Giai đoạn 2: Tiếp tục quan sát thì nhận thấy, sau thời gian 15 phút kế tiếp kể từ thời điểm t1, số chỉ của cân tăng đến 87 g .<br>Cho rằng toàn bộ nhiệt lượng tỏa ra từ dây nung đều truyền cho nước đá trong nhiệt lượng kế và toàn bộ nước đá tan ra đều chảy vào cốc, bỏ qua sự trao đổi nhiệt với môi trường.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046117071-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Ở điều kiện tiêu chuẩn, nước đá tan ở nhiệt độ 00C.","answer":true},{"text":"Quá trình nước đá đang tan là quá trình tỏa nhiệt.","answer":false},{"text":"Số chỉ của cân là khối lượng của nước chảy xuống từ bình nhiệt lượng kế.","answer":false},{"text":"Nhiệt nóng chảy riêng của nước đá đo được trong thí nghiệm này là 3,3.10<sup>5</sup> J/kg","answer":true}],"explanation":"a) đúng<br>Ở điều kiện tiêu chuẩn, nước đá tan ở nhiệt độ 00C.<br>b) sai<br>Quá trình nước đá đang tan là quá trình thu nhiệt.<br>c) sai<br>Có cả khối lượng của cốc hứng nước<br>d) đúng<br>$\\lambda =\\frac{P\\Delta t}{\\Delta m}=\\frac{10.15.60}{\\left(87−60\\right).10^{−3}}\\approx 3,3.10^5\\left(J/kg\\right)$","difficultySource":"ai"},"ex":[{"exam":349,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một học sinh làm thí nghiệm xác định nhiệt nóng chảy riêng của nước đá với bộ dụng cụ gồm: Biến áp nguồn; nhiệt lượng kế có dây nung công suất P =10 W; cân điện tử; cốc hứng nước có khối lượng 50 g ; giá đõ. Bố trí thí nghiệm như hình bên, tiến hành và quan sát thí nghiệm qua hai giai đoạn liên tiếp:<br>Giai doạn 1: Cho khối nước đá đang tan vào nhiệt lượng kế, bật nguồn điện để dây nung nóng lên làm nước đá nóng chảy, cốc hứng nước đặt trên cân điện tử hứng nước chảy ra từ nhiệt<br>lượng kế và quan sát số chỉ của cân. Sau một thời gian kể từ khi cấp điện cho dây nung, tại thời điểm t1, thấy số chi của cân là 60 g .<br>Giai đoạn 2: Tiếp tục quan sát thì nhận thấy, sau thời gian 15 phút kế tiếp kể từ thời điểm t1, số chỉ của cân tăng đến 87 g .<br>Cho rằng toàn bộ nhiệt lượng tỏa ra từ dây nung đều truyền cho nước đá trong nhiệt lượng kế và toàn bộ nước đá tan ra đều chảy vào cốc, bỏ qua sự trao đổi nhiệt với môi trường.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046117071-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Ở điều kiện tiêu chuẩn, nước đá tan ở nhiệt độ 00C.","answer":true},{"text":"Quá trình nước đá đang tan là quá trình tỏa nhiệt.","answer":false},{"text":"Số chỉ của cân là khối lượng của nước chảy xuống từ bình nhiệt lượng kế.","answer":false},{"text":"Nhiệt nóng chảy riêng của nước đá đo được trong thí nghiệm này là 3,3.10<sup>5</sup> J/kg","answer":true}],"explanation":"a) đúng<br>Ở điều kiện tiêu chuẩn, nước đá tan ở nhiệt độ 00C.<br>b) sai<br>Quá trình nước đá đang tan là quá trình thu nhiệt.<br>c) sai<br>Có cả khối lượng của cốc hứng nước<br>d) đúng<br>$\\lambda =\\frac{P\\Delta t}{\\Delta m}=\\frac{10.15.60}{\\left(87−60\\right).10^{−3}}\\approx 3,3.10^5\\left(J/kg\\right)$","difficultySource":"ai"}}]},{"id":630581,"nq":{"form":"bai_tap","type":"true_false","topic":"Liều chiếu xạ và tác hại của phóng xạ","question":"Một nhân viên phòng thí nghiệm hằng ngày tiếp xúc với một nguồn phóng xạ  ${}_{27}^{60}Co$  phát đẳng hướng có độ phóng xạ ban đầu ở mức 1,48.10<sup>9</sup>Bq. Người này luôn đứng cách xa nguồn 4 m và làm việc 4 h mỗi ngày. Phần diện tích cơ thể tiếp xúc với tia phóng xạ là 1,5 m2 . Mỗi hạt nhân  ${}_{27}^{60}Co$  khi phân rã phát ra một hạt γ có năng lượng 2,50MeV . Cơ thể người nhân viên sẽ hấp thụ 50% lượng tia γ tiếp xúc cơ thể. Biết chu kì bán rã của hạt nhân  ${}_{27}^{60}Co$  là 5,27 năm.","difficulty":"kho","statements":[{"text":"Để tăng cường sự an toàn, người này cần sử dụng các tấm chắn nguồn phóng xạ đủ tốt.","answer":true},{"text":"Sau 10,54 năm thì độ phóng xạ của  ${}_{27}^{60}Co$  còn lại bằng 0,74.109 Bq","answer":false},{"text":"Khối lượng nguồn  ${}_{27}^{60}Co$  ban đầu là 34,5 µg.","answer":false},{"text":"Liều hấp thụ phóng xạ D được định nghĩa là năng lượng hấp thụ phóng xạ trên một đơn vị khối lượng của vật hấp thụ phóng xạ. Liều hấp thụ phóng xạ có đơn vị là 1 Gy =1 J / kg. Biết khối lượng của nhân viên bằng 70 kg . Trong một ngày làm việc, lượng hấp thụ bức xạ của người này là 4,5.10<sup>−4</sup> Gy.","answer":true}],"explanation":"a) đúng<br>Để tăng cường sự an toàn, người này cần sử dụng các tấm chắn nguồn phóng xạ đủ tốt.<br>b) sai<br>$H=H_0.2^{−\\frac{t}{T}}=1,48.10^9.2^{−\\frac{10,54}{5,27}}=0,37.10^9Bq$<br>c) sai<br>$\\begin{aligned}\\end{aligned}H_0=\\lambda N_0=\\frac{ln2}{T}.N_0\\Rightarrow 1,48.10^9=\\frac{ln2}{5,27.365.24.60.60}.N_0\\Rightarrow N_0\\approx 3,55.10^{17}Website: thukhoadaihoc.vn$<br>$n_0=\\frac{N_0}{N_A}=\\frac{3,55.10^{17}}{6,02.10^{23}}\\approx 5,9.10^{−7}mol$<br>$m_0=n_0M=5,9.10^{−7}.60\\approx 3,54.10^{−5}g=35,4\\left(\\mu g\\right)$<br>d) đúng<br>$\\Delta N=N_0\\left(1−2^{−\\frac{t}{T}}\\right)=3,55.10^{17}.\\left(1−2^{\\frac{−4}{5,27365.24}}\\right)\\approx 2,13.10^{13}$<br>$\\begin{aligned}\\end{aligned}Q=0,5.\\Delta N.E.\\frac{S}{4\\pi r^2}=0,5.2,13.10^{13}.2,5.1,6.10^{−13}.\\frac{1,5}{4\\pi .4^2}\\approx 0,0318\\left(J\\right)Website: thukhoadaihoc.vn$<br>$D=\\frac{Q}{m}=\\frac{0,0318}{70}\\approx 4,5.10^{−4}Gy$","difficultySource":"ai"},"ex":[{"exam":349,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Liều chiếu xạ và tác hại của phóng xạ","question":"Một nhân viên phòng thí nghiệm hằng ngày tiếp xúc với một nguồn phóng xạ  ${}_{27}^{60}Co$  phát đẳng hướng có độ phóng xạ ban đầu ở mức 1,48.10<sup>9</sup>Bq. Người này luôn đứng cách xa nguồn 4 m và làm việc 4 h mỗi ngày. Phần diện tích cơ thể tiếp xúc với tia phóng xạ là 1,5 m2 . Mỗi hạt nhân  ${}_{27}^{60}Co$  khi phân rã phát ra một hạt γ có năng lượng 2,50MeV . Cơ thể người nhân viên sẽ hấp thụ 50% lượng tia γ tiếp xúc cơ thể. Biết chu kì bán rã của hạt nhân  ${}_{27}^{60}Co$  là 5,27 năm.","difficulty":"kho","statements":[{"text":"Để tăng cường sự an toàn, người này cần sử dụng các tấm chắn nguồn phóng xạ đủ tốt.","answer":true},{"text":"Sau 10,54 năm thì độ phóng xạ của  ${}_{27}^{60}Co$  còn lại bằng 0,74.109 Bq","answer":false},{"text":"Khối lượng nguồn  ${}_{27}^{60}Co$  ban đầu là 34,5 µg.","answer":false},{"text":"Liều hấp thụ phóng xạ D được định nghĩa là năng lượng hấp thụ phóng xạ trên một đơn vị khối lượng của vật hấp thụ phóng xạ. Liều hấp thụ phóng xạ có đơn vị là 1 Gy =1 J / kg. Biết khối lượng của nhân viên bằng 70 kg . Trong một ngày làm việc, lượng hấp thụ bức xạ của người này là 4,5.10<sup>−4</sup> Gy.","answer":true}],"explanation":"a) đúng<br>Để tăng cường sự an toàn, người này cần sử dụng các tấm chắn nguồn phóng xạ đủ tốt.<br>b) sai<br>$H=H_0.2^{−\\frac{t}{T}}=1,48.10^9.2^{−\\frac{10,54}{5,27}}=0,37.10^9Bq$<br>c) sai<br>$\\begin{aligned}\\end{aligned}H_0=\\lambda N_0=\\frac{ln2}{T}.N_0\\Rightarrow 1,48.10^9=\\frac{ln2}{5,27.365.24.60.60}.N_0\\Rightarrow N_0\\approx 3,55.10^{17}Website: thukhoadaihoc.vn$<br>$n_0=\\frac{N_0}{N_A}=\\frac{3,55.10^{17}}{6,02.10^{23}}\\approx 5,9.10^{−7}mol$<br>$m_0=n_0M=5,9.10^{−7}.60\\approx 3,54.10^{−5}g=35,4\\left(\\mu g\\right)$<br>d) đúng<br>$\\Delta N=N_0\\left(1−2^{−\\frac{t}{T}}\\right)=3,55.10^{17}.\\left(1−2^{\\frac{−4}{5,27365.24}}\\right)\\approx 2,13.10^{13}$<br>$\\begin{aligned}\\end{aligned}Q=0,5.\\Delta N.E.\\frac{S}{4\\pi r^2}=0,5.2,13.10^{13}.2,5.1,6.10^{−13}.\\frac{1,5}{4\\pi .4^2}\\approx 0,0318\\left(J\\right)Website: thukhoadaihoc.vn$<br>$D=\\frac{Q}{m}=\\frac{0,0318}{70}\\approx 4,5.10^{−4}Gy$","difficultySource":"ai"}}]},{"id":630584,"nq":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"15,7","question":"Một mẫu đá được các nhà du hành mang về từ Mặt Trăng chứa đồng vị phóng xạ potassium  ${}_{19}^{40}K$ với chu kì bán rã là 1,25.10<sup>9</sup> năm có độ phóng xạ 112µCi. Xem một năm có 365 ngày, 1Ci = 3,70. 10<sup>10</sup> Bq. Khối lượng của  ${}_{19}^{40}K$ có trong mẫu đá đó là bao nhiêu gam (làm tròn kết quả đến hàng phần mười)?","difficulty":"trung-binh","explanation":"$H=\\lambda N=\\frac{ln2}{T}.N$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow 112.10^6.3,7.10^{10}=\\frac{ln2}{1,25.10^9.365.24.60.60}.NWebsite: thukhoadaihoc.vn$<br>$\\Rightarrow N\\approx 2,3567.10^{23}$<br>$n=\\frac{N}{N_A}=\\frac{2,3567.10^{23}}{6,02.10^{23}}\\approx 0,39148mol$<br>$m=nM=0,39148.40\\approx 15,7\\left(g\\right)$","difficultySource":"ai"},"ex":[{"exam":349,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"15,7","question":"Một mẫu đá được các nhà du hành mang về từ Mặt Trăng chứa đồng vị phóng xạ potassium  ${}_{19}^{40}K$ với chu kì bán rã là 1,25.10<sup>9</sup> năm có độ phóng xạ 112µCi. Xem một năm có 365 ngày, 1Ci = 3,70. 10<sup>10</sup> Bq. Khối lượng của  ${}_{19}^{40}K$ có trong mẫu đá đó là bao nhiêu gam (làm tròn kết quả đến hàng phần mười)?","difficulty":"trung-binh","explanation":"$H=\\lambda N=\\frac{ln2}{T}.N$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow 112.10^6.3,7.10^{10}=\\frac{ln2}{1,25.10^9.365.24.60.60}.NWebsite: thukhoadaihoc.vn$<br>$\\Rightarrow N\\approx 2,3567.10^{23}$<br>$n=\\frac{N}{N_A}=\\frac{2,3567.10^{23}}{6,02.10^{23}}\\approx 0,39148mol$<br>$m=nM=0,39148.40\\approx 15,7\\left(g\\right)$","difficultySource":"ai"}}]},{"id":630585,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"2,3","question":"Bóng thám không là một thiết bị được sử dụng phổ biến trong ngành khí tượng để thu thập dữ liệu về các thông số thời tiết. Bóng thường được bơm khí hiếm nhẹ hơn không khí, nhờ đó có thể bay lên các tầng không khí khác nhau. Người ta chế tạo một bóng thám không có thể tăng bán kính lên tới 3 m khi bay ở tầng khí quyển có áp suất 0,3.105 Pa và nhiệt độ 200 K . Bóng được bơm ở mặt đất có áp suất 1,02.10<sup>5</sup> Pa và nhiệt độ 300 K . Bỏ qua áp suất phụ gây bởi vỏ quả bóng. Bán kính của bóng khi vừa bơm xong bằng bao nhiêu mét (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"$\\frac{pV}{T}=\\frac{p.\\frac{4}{3}\\pi R^3}{T}=const$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow \\frac{0,3.10^5.3^3}{200}=\\frac{1,02.10^5.R^3}{300}\\Rightarrow T\\approx 2,3mWebsite: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":349,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"2,3","question":"Bóng thám không là một thiết bị được sử dụng phổ biến trong ngành khí tượng để thu thập dữ liệu về các thông số thời tiết. Bóng thường được bơm khí hiếm nhẹ hơn không khí, nhờ đó có thể bay lên các tầng không khí khác nhau. Người ta chế tạo một bóng thám không có thể tăng bán kính lên tới 3 m khi bay ở tầng khí quyển có áp suất 0,3.105 Pa và nhiệt độ 200 K . Bóng được bơm ở mặt đất có áp suất 1,02.10<sup>5</sup> Pa và nhiệt độ 300 K . Bỏ qua áp suất phụ gây bởi vỏ quả bóng. Bán kính của bóng khi vừa bơm xong bằng bao nhiêu mét (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"$\\frac{pV}{T}=\\frac{p.\\frac{4}{3}\\pi R^3}{T}=const$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow \\frac{0,3.10^5.3^3}{200}=\\frac{1,02.10^5.R^3}{300}\\Rightarrow T\\approx 2,3mWebsite: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":631740,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình trạng thái khí lí tưởng","answer":"1,87","question":"Biết khối lượng riêng của không khí ở 0oC và áp suất 1,01.10<sup>5</sup> Pa là 1,29 kg/m3. Coi không khí là khí lí tưởng. Khối lượng riêng của không khí ở 100oC và áp suất 2.10<sup>5</sup> Pa là bao nhiêu kg/m3 (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"Xét cùng một lượng khí, ta có  $m=\\rho_0V_0=\\rho V\\Rightarrow \\frac{V_0}{V}=\\frac{\\rho }{\\rho_0}$ .<br>Kết hợp với phương trình trạng thái ta được<br>$\\frac{p_0V_0}{T_0}=\\frac{pV}{T}\\Rightarrow \\frac{V_0}{V}=\\frac{\\rho }{\\rho_0}=\\frac{p}{p_0}.\\frac{T_0}{T}$  $\\Rightarrow \\rho =\\rho_0\\frac{p}{p_0}.\\frac{T_0}{T}=1,29.\\frac{2.10^5}{1,01.10^5}.\\frac{273}{373}\\approx 1,87 kg/m^3$ .","difficultySource":"ai"},"ex":[{"exam":350,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình trạng thái khí lí tưởng","answer":"1,87","question":"Biết khối lượng riêng của không khí ở 0oC và áp suất 1,01.10<sup>5</sup> Pa là 1,29 kg/m3. Coi không khí là khí lí tưởng. Khối lượng riêng của không khí ở 100oC và áp suất 2.10<sup>5</sup> Pa là bao nhiêu kg/m3 (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"Xét cùng một lượng khí, ta có  $m=\\rho_0V_0=\\rho V\\Rightarrow \\frac{V_0}{V}=\\frac{\\rho }{\\rho_0}$ .<br>Kết hợp với phương trình trạng thái ta được<br>$\\frac{p_0V_0}{T_0}=\\frac{pV}{T}\\Rightarrow \\frac{V_0}{V}=\\frac{\\rho }{\\rho_0}=\\frac{p}{p_0}.\\frac{T_0}{T}$  $\\Rightarrow \\rho =\\rho_0\\frac{p}{p_0}.\\frac{T_0}{T}=1,29.\\frac{2.10^5}{1,01.10^5}.\\frac{273}{373}\\approx 1,87 kg/m^3$ .","difficultySource":"ai"}}]},{"id":632625,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":1,"options":["0,333 m.","3,0 m.","30,3 m.","3.10<sup>4</sup> m."],"question":"Để có thể nghe tin tức từ Đài Tiếng nói Nhân dân Thành phố Hồ Chí Minh (VOH), người ta thường điều chỉnh tần số của radio đến giá trị 99,9 MHz. Biết sóng radio là sóng điện từ truyền trong không khí với tốc độ xấp xỉ 3.10<sup>8</sup> m/s. Bước sóng của sóng Radio này gần bằng","difficulty":"de","explanation":"Bước sóng:  $\\lambda =\\frac{v}{f}=\\frac{{3.10}^8}{{99,9.10}^6}\\approx 3,0 m$<br>Sử dụng các thông tin sau cho câu 10 và câu 11: Trong đời sống hiện đại, bếp từ ngày càng được người tiêu dùng ưa chuộng nhờ tính an toàn cao và khả năng đun nấu nhanh. Khi bếp được bật, dòng điện xoay chiều chạy qua cuộn dây đặt dưới mặt bếp, sinh ra từ trường biến thiên. Nếu đặt một chảo kim loại có tính nhiễm từ lên mặt bếp, đáy chảo sẽ nóng lên nhanh chóng.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046144191-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":351,"idx":8,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":1,"options":["0,333 m.","3,0 m.","30,3 m.","3.10<sup>4</sup> m."],"question":"Để có thể nghe tin tức từ Đài Tiếng nói Nhân dân Thành phố Hồ Chí Minh (VOH), người ta thường điều chỉnh tần số của radio đến giá trị 99,9 MHz. Biết sóng radio là sóng điện từ truyền trong không khí với tốc độ xấp xỉ 3.10<sup>8</sup> m/s. Bước sóng của sóng Radio này gần bằng","difficulty":"de","explanation":"Bước sóng:  $\\lambda =\\frac{v}{f}=\\frac{{3.10}^8}{{99,9.10}^6}\\approx 3,0 m$<br>Sử dụng các thông tin sau cho câu 10 và câu 11: Trong đời sống hiện đại, bếp từ ngày càng được người tiêu dùng ưa chuộng nhờ tính an toàn cao và khả năng đun nấu nhanh. Khi bếp được bật, dòng điện xoay chiều chạy qua cuộn dây đặt dưới mặt bếp, sinh ra từ trường biến thiên. Nếu đặt một chảo kim loại có tính nhiễm từ lên mặt bếp, đáy chảo sẽ nóng lên nhanh chóng.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046144191-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":633132,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Đọc đồ thị các đẳng quá trình","answer":2,"options":["Hình 1 và hình 4.","Hình 2 và hình 4.","Hình 1 và hình 3.","Hình 3 và hình 4."],"question":"Một bình kín chứa một khối khí lí tưởng ở nhiệt độ 27 C và áp suất 4.10<sup>5</sup> Pa. Người ta cung cấp nhiệt cho khối khí, làm nhiệt độ của nó tăng thêm 150 C. Những hình nào sau đây biểu diễn đúng sự biến đổi trạng thái của khối khí? Biết thể tích thực của bình kín là 3 lít.<br>Hình 1<br>Hình 2<br>Hình 3<br>Hình 4<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046154314-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046154499-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046154660-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046154829-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Do bình kín nên quá trình biến đổi trạng thái của khối khí lí tưởng là quá trình đẳng tích. Khi đó, ta có:<br>$\\frac{p_1}{T_1}=\\frac{p_2}{T_2}$    $p_2=\\frac{p_1.T_2}{T_1}=\\frac{4.{10}^5.\\left(27+150+273\\right)}{27+273}=6.{10}^5$  Pa.<br>Những hình biểu diễn đúng sự biến đổi trạng thái của khối khí là hình 1, hình 3.<br>Hình 2 sai ở số liệu  $T_2=423$  K và  $p_2=5,6.{10}^5$  Pa.<br>Hình 4 sai ở số liệu  $p_1=4$  Pa và  $p_2=6$  Pa.","difficultySource":"ai"},"ex":[{"exam":352,"idx":8,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Đọc đồ thị các đẳng quá trình","answer":2,"options":["Hình 1 và hình 4.","Hình 2 và hình 4.","Hình 1 và hình 3.","Hình 3 và hình 4."],"question":"Một bình kín chứa một khối khí lí tưởng ở nhiệt độ 27 C và áp suất 4.10<sup>5</sup> Pa. Người ta cung cấp nhiệt cho khối khí, làm nhiệt độ của nó tăng thêm 150 C. Những hình nào sau đây biểu diễn đúng sự biến đổi trạng thái của khối khí? Biết thể tích thực của bình kín là 3 lít.<br>Hình 1<br>Hình 2<br>Hình 3<br>Hình 4<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046154314-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046154499-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046154660-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046154829-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Do bình kín nên quá trình biến đổi trạng thái của khối khí lí tưởng là quá trình đẳng tích. Khi đó, ta có:<br>$\\frac{p_1}{T_1}=\\frac{p_2}{T_2}$    $p_2=\\frac{p_1.T_2}{T_1}=\\frac{4.{10}^5.\\left(27+150+273\\right)}{27+273}=6.{10}^5$  Pa.<br>Những hình biểu diễn đúng sự biến đổi trạng thái của khối khí là hình 1, hình 3.<br>Hình 2 sai ở số liệu  $T_2=423$  K và  $p_2=5,6.{10}^5$  Pa.<br>Hình 4 sai ở số liệu  $p_1=4$  Pa và  $p_2=6$  Pa.","difficultySource":"ai"}}]},{"id":633146,"nq":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng áp và định luật Charles","answer":"387","question":"Để mở nút một chai thủy tinh bị kẹt, một học sinh đã hơ nóng phần chứa không khí (xem là khí lí tưởng) trong chai. Ban đầu, không khí trong chai có áp suất bằng áp suất khí quyển 1,0.10<sup>5</sup> Pa và nhiệt độ là 27 °C. Biết rằng để nút chai bật ra, chênh lệch áp suất giữa không khí trong chai và bên ngoài phải đạt tối thiểu là 1,2.10<sup>5</sup> Pa. Bỏ qua sự thay đổi thể tích của chai và giả sử quá trình đun nóng xảy ra đủ chậm để áp suất bên trong luôn đồng đều. Học sinh cần làm nóng không khí trong chai đến nhiệt độ ít nhất bằng bao nhiêu C để nút chai bật ra?","difficulty":"trung-binh","explanation":"Do bỏ qua sự thay đổi thể tích của chai nên khối khí thực hiện quá trình đẳng tích, ta có:<br>$\\frac{p_1}{T_1}=\\frac{p_2}{T_2}$    $p_2=\\frac{p_1.T_2}{T_1}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Để làm bật nút chai thì  $p_2-p_1\\ge 1,2.{10}^5$    $p_2\\ge p_1+1,2.{10}^5$<br>Suy ra:  $\\frac{p_1.T_2}{T_1}\\ge p_1+1,2.{10}^5$    $T_2\\ge T_1+\\frac{T_1}{p_1}.1,2.{10}^5$<br>$T_2\\ge 27+273+\\frac{27+273}{1,0.{10}^5}.1,2.{10}^5$<br>$T_2\\ge 660$  K.<br>$t_2\\ge 387 ℃$ .<br>Vậy học sinh cần làm nóng không khí trong chai đến nhiệt độ ít nhất bằng 387 C để nút chai bật ra.","difficultySource":"ai"},"ex":[{"exam":352,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng áp và định luật Charles","answer":"387","question":"Để mở nút một chai thủy tinh bị kẹt, một học sinh đã hơ nóng phần chứa không khí (xem là khí lí tưởng) trong chai. Ban đầu, không khí trong chai có áp suất bằng áp suất khí quyển 1,0.10<sup>5</sup> Pa và nhiệt độ là 27 °C. Biết rằng để nút chai bật ra, chênh lệch áp suất giữa không khí trong chai và bên ngoài phải đạt tối thiểu là 1,2.10<sup>5</sup> Pa. Bỏ qua sự thay đổi thể tích của chai và giả sử quá trình đun nóng xảy ra đủ chậm để áp suất bên trong luôn đồng đều. Học sinh cần làm nóng không khí trong chai đến nhiệt độ ít nhất bằng bao nhiêu C để nút chai bật ra?","difficulty":"trung-binh","explanation":"Do bỏ qua sự thay đổi thể tích của chai nên khối khí thực hiện quá trình đẳng tích, ta có:<br>$\\frac{p_1}{T_1}=\\frac{p_2}{T_2}$    $p_2=\\frac{p_1.T_2}{T_1}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Để làm bật nút chai thì  $p_2-p_1\\ge 1,2.{10}^5$    $p_2\\ge p_1+1,2.{10}^5$<br>Suy ra:  $\\frac{p_1.T_2}{T_1}\\ge p_1+1,2.{10}^5$    $T_2\\ge T_1+\\frac{T_1}{p_1}.1,2.{10}^5$<br>$T_2\\ge 27+273+\\frac{27+273}{1,0.{10}^5}.1,2.{10}^5$<br>$T_2\\ge 660$  K.<br>$t_2\\ge 387 ℃$ .<br>Vậy học sinh cần làm nóng không khí trong chai đến nhiệt độ ít nhất bằng 387 C để nút chai bật ra.","difficultySource":"ai"}}]},{"id":633664,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật phóng xạ và chu kì bán rã","answer":2,"options":["2.","4.","3.","1."],"question":"Platin  ${}_{78}^{197}Pt$  là đồng vị phóng xạ β- biến đổi thành  ${}_{79}^{197}Au$  bền, với chu kì bán rã là T = 20 h. Ban đầu (t = 0), một mẫu chất chứa 8.10<sup>20</sup> hạt nhân  ${}_{78}^{197}Pt$  , sau thời gian t số hạt nhân  ${}_{79}^{197}Au$  được tạo ra do phóng xạ là N. Ở hình bên, nếu vẽ đúng đồ thị biểu diễn sự phụ thuộc của N vào t thì đồ thị này sẽ đi qua điểm nào?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046176932-hinh-1.png\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Số hạt nhân  ${}_{79}^{197}Au$  được tạo ra đúng bằng số hạt  ${}_{78}^{197}Pt$   phân rã<br>$N_{Au}=\\Delta N=N_0\\left(1−2^{−\\frac{t}{T}}\\right)=8.10^{20}\\left(1−2^{−\\frac{t}{20}}\\right)\\Rightarrow \\left\\{\\begin{aligned}t=20\\Rightarrow \\Delta N=4.10^{20}\\Rightarrow Sai <br>t=40\\Rightarrow \\Delta N=6.10^{20}\\Rightarrow Sai <br>t=60\\Rightarrow \\Delta N=7.10^{20} <br>t=80\\Rightarrow \\Delta N=7,5.10^{20}\\Rightarrow Sai\\end{aligned}\\right.$","difficultySource":"ai"},"ex":[{"exam":355,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật phóng xạ và chu kì bán rã","answer":2,"options":["2.","4.","3.","1."],"question":"Platin  ${}_{78}^{197}Pt$  là đồng vị phóng xạ β- biến đổi thành  ${}_{79}^{197}Au$  bền, với chu kì bán rã là T = 20 h. Ban đầu (t = 0), một mẫu chất chứa 8.10<sup>20</sup> hạt nhân  ${}_{78}^{197}Pt$  , sau thời gian t số hạt nhân  ${}_{79}^{197}Au$  được tạo ra do phóng xạ là N. Ở hình bên, nếu vẽ đúng đồ thị biểu diễn sự phụ thuộc của N vào t thì đồ thị này sẽ đi qua điểm nào?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046176932-hinh-1.png\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Số hạt nhân  ${}_{79}^{197}Au$  được tạo ra đúng bằng số hạt  ${}_{78}^{197}Pt$   phân rã<br>$N_{Au}=\\Delta N=N_0\\left(1−2^{−\\frac{t}{T}}\\right)=8.10^{20}\\left(1−2^{−\\frac{t}{20}}\\right)\\Rightarrow \\left\\{\\begin{aligned}t=20\\Rightarrow \\Delta N=4.10^{20}\\Rightarrow Sai <br>t=40\\Rightarrow \\Delta N=6.10^{20}\\Rightarrow Sai <br>t=60\\Rightarrow \\Delta N=7.10^{20} <br>t=80\\Rightarrow \\Delta N=7,5.10^{20}\\Rightarrow Sai\\end{aligned}\\right.$","difficultySource":"ai"}}]},{"id":633665,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":0,"options":["34.103 J.","0,34.103 J.","340.105 J.","34.107 J."],"question":"Biết nhiệt nóng chảy riêng của nước đá λ = 3,4.10<sup>5</sup> J/kg. Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn 100 g nước đã 0°C bằng bao nhiêu?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Làm nóng chảy hoàn toàn chất rắn ở đúng nhiệt độ nóng chảy: $Q=\\lambda m$.</p><p class=\"text-base leading-relaxed my-2\">$m=100\\ \\text{g}=0{,}1$ kg</p><p class=\"text-base leading-relaxed my-2\">$Q=3{,}4\\cdot10^5\\cdot0{,}1=3{,}4\\cdot10^4\\ \\text{J}=34\\cdot10^3$ J</p><p class=\"text-base leading-relaxed my-2\">Sai vì: $0{,}34\\cdot10^3$ J $=340$ J nhỏ hơn đáp số $100$ lần (ứng với $m=1$ g). $340\\cdot10^5$ J $=3{,}4\\cdot10^7$ J ứng với $m=100$ kg, tức dùng $100$ thay vì đổi ra kg. $34\\cdot10^7$ J $=3{,}4\\cdot10^8$ J ứng với $m=1000$ kg.</p><p class=\"text-base leading-relaxed my-2\">Chọn A.</p>","difficultySource":"ai"},"ex":[{"exam":355,"idx":11,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":0,"options":["34.103 J.","0,34.103 J.","340.105 J.","34.107 J."],"question":"Biết nhiệt nóng chảy riêng của nước đá λ = 3,4.10<sup>5</sup> J/kg. Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn 100 g nước đã 0°C bằng bao nhiêu?","difficulty":"de","explanation":"$Q=m\\lambda =0,1.3,4.10^5=34.10^3J$","difficultySource":"ai"}}]},{"id":633672,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Đồng vị sắt (Iron)  ${}_{26}^{59}Fe$ là chất phóng xạ β- với chu kỳ bán rã 44,5 ngày, được sử dụng trong y học. Để có được một nhận định y khoa chính xác về tình trạng thiếu sắt trong cơ thể bệnh nhân, người ta cho bệnh nhân uống một loại đồ uống chứa underline 0,25.10<sup>−12</sup> kg đồng vị  ${}_{26}^{59}Fe$ . Khi bệnh nhân bị thiếu sắt ở mức độ nghiêm trọng, cơ thể sẽ hấp thụ hoàn toàn đồng vị sắt này và hầu như không thải ra ngoài. Sau 15 ngày, độ phóng xạ của  ${}_{26}^{59}Fe$ trong cơ thể được đo lại. Lấy khối lượng mol của  ${}_{26}^{59}Fe$  là 58,93 g/mol.","difficulty":"kho","statements":[{"text":"Hạt nhân  ${}_{26}^{59}Fe$  sau khi phóng xạ β- thì biến thành hạt nhân ${}_{27}^{59}Co$ .","answer":true},{"text":"Trong đồ uống của bệnh nhân có chứa 2.55.1012 hạt nhân ${}_{26}^{59}Fe$ .","answer":true},{"text":"Lượng  ${}_{26}^{59}Fe$  trong đồ uống của bệnh nhân có độ phóng xạ 0,46 MBq.","answer":true},{"text":"Sau 15 ngày được đưa vào cơ thể bệnh nhân, lượng  ${}_{26}^{59}Fe$  bị đào thải là 10%, một phần đã bị phân rã, phần còn lại có độ phóng xạ là 0,39 MBq.","answer":false}],"explanation":"a) đúng<br>${}_{26}^{59}Fe\\rightarrow_{−1}^0e+_{27}^{59}Co$<br>b) đúng<br>$n=\\frac{m}{M}=\\frac{0,25.10^{−12}.10^3}{59}=4,24.10^{−12}mol$<br>$N=nN_A=4,24.10^{−12}.6,02.10^{23}\\approx 2,55.10^{12}$<br>c) đúng<br>$H_0=\\lambda N_0=\\frac{ln2}{T}.N_0=\\frac{ln2}{44,5.24.60.60}.2,55.10^{12}\\approx 0,46.10^6Bq=0,46MBq$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>$H=0,9H_0.2^{−\\frac{t}{T}}=0,9.0,46.2^{−\\frac{15}{44,5}}\\approx 0,328MBq$","difficultySource":"ai"},"ex":[{"exam":355,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Đồng vị sắt (Iron)  ${}_{26}^{59}Fe$ là chất phóng xạ β- với chu kỳ bán rã 44,5 ngày, được sử dụng trong y học. Để có được một nhận định y khoa chính xác về tình trạng thiếu sắt trong cơ thể bệnh nhân, người ta cho bệnh nhân uống một loại đồ uống chứa underline 0,25.10<sup>−12</sup> kg đồng vị  ${}_{26}^{59}Fe$ . Khi bệnh nhân bị thiếu sắt ở mức độ nghiêm trọng, cơ thể sẽ hấp thụ hoàn toàn đồng vị sắt này và hầu như không thải ra ngoài. Sau 15 ngày, độ phóng xạ của  ${}_{26}^{59}Fe$ trong cơ thể được đo lại. Lấy khối lượng mol của  ${}_{26}^{59}Fe$  là 58,93 g/mol.","difficulty":"kho","statements":[{"text":"Hạt nhân  ${}_{26}^{59}Fe$  sau khi phóng xạ β- thì biến thành hạt nhân ${}_{27}^{59}Co$ .","answer":true},{"text":"Trong đồ uống của bệnh nhân có chứa 2.55.1012 hạt nhân ${}_{26}^{59}Fe$ .","answer":true},{"text":"Lượng  ${}_{26}^{59}Fe$  trong đồ uống của bệnh nhân có độ phóng xạ 0,46 MBq.","answer":true},{"text":"Sau 15 ngày được đưa vào cơ thể bệnh nhân, lượng  ${}_{26}^{59}Fe$  bị đào thải là 10%, một phần đã bị phân rã, phần còn lại có độ phóng xạ là 0,39 MBq.","answer":false}],"explanation":"a) đúng<br>${}_{26}^{59}Fe\\rightarrow_{−1}^0e+_{27}^{59}Co$<br>b) đúng<br>$n=\\frac{m}{M}=\\frac{0,25.10^{−12}.10^3}{59}=4,24.10^{−12}mol$<br>$N=nN_A=4,24.10^{−12}.6,02.10^{23}\\approx 2,55.10^{12}$<br>c) đúng<br>$H_0=\\lambda N_0=\\frac{ln2}{T}.N_0=\\frac{ln2}{44,5.24.60.60}.2,55.10^{12}\\approx 0,46.10^6Bq=0,46MBq$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>$H=0,9H_0.2^{−\\frac{t}{T}}=0,9.0,46.2^{−\\frac{15}{44,5}}\\approx 0,328MBq$","difficultySource":"ai"}}]},{"id":633678,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phản ứng phân hạch, phản ứng nhiệt hạch","answer":"3,62","question":"Năng lượng tỏa ra từ Mặt Trời chủ yếu bắt nguồn từ các phản ứng nhiệt hạch trong lõi Mặt Trời, theo phương trình: $4_1^1H\\rightarrow_2^4He+2_0^1e+2v$ , mỗi phản ứng tỏa năng lượng 4,28.10<sup>−12</sup> J. Giả sử 2% năng lượng của phản ứng nhiệt hạch bị các hạt neutrino (v) mang đi và không góp phần vào năng lượng bức xạ của Mặt Trời. Công suất bức xạ của Mặt Trời là 3,8.1026 J/s. Trong thời gian 1 giây có x.10<sup>38</sup> hạt nhân  ${}_1^1H$  được tiêu thụ trong lõi Mặt Trời. Tính x (làm quả đến chữ số hàng phần trăm).","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\end{aligned}N_{H_2}=4N=\\frac{4Q}{\\Delta E}=\\frac{4Pt}{H\\Delta E}=\\frac{4.3,8.10^{26}}{0,98.4,28.10^{−12}}\\approx 3,62.10^{38}Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":355,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Phản ứng phân hạch, phản ứng nhiệt hạch","answer":"3,62","question":"Năng lượng tỏa ra từ Mặt Trời chủ yếu bắt nguồn từ các phản ứng nhiệt hạch trong lõi Mặt Trời, theo phương trình: $4_1^1H\\rightarrow_2^4He+2_0^1e+2v$ , mỗi phản ứng tỏa năng lượng 4,28.10<sup>−12</sup> J. Giả sử 2% năng lượng của phản ứng nhiệt hạch bị các hạt neutrino (v) mang đi và không góp phần vào năng lượng bức xạ của Mặt Trời. Công suất bức xạ của Mặt Trời là 3,8.1026 J/s. Trong thời gian 1 giây có x.10<sup>38</sup> hạt nhân  ${}_1^1H$  được tiêu thụ trong lõi Mặt Trời. Tính x (làm quả đến chữ số hàng phần trăm).","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\end{aligned}N_{H_2}=4N=\\frac{4Q}{\\Delta E}=\\frac{4Pt}{H\\Delta E}=\\frac{4.3,8.10^{26}}{0,98.4,28.10^{−12}}\\approx 3,62.10^{38}Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":633911,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nguyên tắc tạo ra dòng điện xoay chiều","answer":1,"options":["120 V.","169,6 V.","129,5 V.","189,6 V."],"question":"Một khung dây dẫn phẳng, dẹt có 200 vòng, mỗi vòng có diện tích 600 cm2. Khung dây quay đều quanh trục nằm trong mặt phẳng khung dây với tốc độ 50 vòng/s trong một từ trường đều có vectơ cảm ứng từ vuông góc với trục quay và có độ lớn 4,5.10<sup>−2</sup> T. Suất điện động cực đại xuất hiện trong khung dây gần nhất với giá trị nào sau đây?","difficulty":"de","explanation":"$\\omega =2\\pi f=2\\pi .50=100\\pi \\left(rad/s\\right)$<br>$E_0=NBS\\omega =200.4,5.10^{−2}.600.10^{−4}.100\\pi \\approx 169,6V$","difficultySource":"ai"},"ex":[{"exam":356,"idx":5,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nguyên tắc tạo ra dòng điện xoay chiều","answer":1,"options":["120 V.","169,6 V.","129,5 V.","189,6 V."],"question":"Một khung dây dẫn phẳng, dẹt có 200 vòng, mỗi vòng có diện tích 600 cm2. Khung dây quay đều quanh trục nằm trong mặt phẳng khung dây với tốc độ 50 vòng/s trong một từ trường đều có vectơ cảm ứng từ vuông góc với trục quay và có độ lớn 4,5.10<sup>−2</sup> T. Suất điện động cực đại xuất hiện trong khung dây gần nhất với giá trị nào sau đây?","difficulty":"de","explanation":"$\\omega =2\\pi f=2\\pi .50=100\\pi \\left(rad/s\\right)$<br>$E_0=NBS\\omega =200.4,5.10^{−2}.600.10^{−4}.100\\pi \\approx 169,6V$","difficultySource":"ai"}}]},{"id":633915,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Cường độ điện trường của điện tích điểm","answer":0,"options":["8,75.10<sup>6</sup> V/m.","8750 V/m.","8,75.10<sup>8</sup> V/m","8,75 V/m."],"question":"Hình bên là tế bào cơ thể mực ống khi đang nghỉ ngơi, không kích thích. Người ta sử dụng một máy đo điện thế (điện kế) cực nhạy để đo điện thế nghỉ của tế bào thần kinh. Đặt điện cực thứ nhất của máy lên mặt ngoài của màng tế bào, còn điện cực thứ hai thì đâm xuyên qua màng tế bào đến tiếp xúc với tế bào chất. Mặt trong của màng tế bào trong cơ thể sống mang điện tích âm, mặt ngoài mang điện tích dương, hiệu điện thế giữa hai mặt này bằng 70 mV. Màng tế bào dày 8 nm. Cường độ điện trường bên trong màng tế bào bằng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046183329-hinh-2.jpg\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Màng tế bào coi như điện trường đều giữa hai mặt: $E=\\dfrac{U}{d}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $U=70$ mV $=0{,}07$ V, $d=8$ nm $=8\\cdot10^{-9}$ m.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow E=\\dfrac{0{,}07}{8\\cdot10^{-9}}=8{,}75\\cdot10^{6}$ V/m. Chọn A.</p>","difficultySource":"ai"},"ex":[{"exam":356,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Cường độ điện trường của điện tích điểm","answer":0,"options":["8,75.10<sup>6</sup> V/m.","8750 V/m.","8,75.10<sup>8</sup> V/m","8,75 V/m."],"question":"Hình bên là tế bào cơ thể mực ống khi đang nghỉ ngơi, không kích thích. Người ta sử dụng một máy đo điện thế (điện kế) cực nhạy để đo điện thế nghỉ của tế bào thần kinh. Đặt điện cực thứ nhất của máy lên mặt ngoài của màng tế bào, còn điện cực thứ hai thì đâm xuyên qua màng tế bào đến tiếp xúc với tế bào chất. Mặt trong của màng tế bào trong cơ thể sống mang điện tích âm, mặt ngoài mang điện tích dương, hiệu điện thế giữa hai mặt này bằng 70 mV. Màng tế bào dày 8 nm. Cường độ điện trường bên trong màng tế bào bằng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046183329-hinh-2.jpg\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"$E=\\frac{U}{d}=\\frac{70.10^{−3}}{8.10^{−9}}=8,75.10^6\\left(V/m\\right)$","difficultySource":"ai"}}]},{"id":633924,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Đồng vị Iodine ( ${}_{53}^{131}I$ ) là chất phóng xạ β- được sử dụng trong y học để điều trị các bệnh liên quan đến tuyến giáp. Chất này có chu kỳ bán rã là 8 ngày. Một bệnh nhân được chỉ định sử dụng liều Iodine-131 với độ phóng xạ ban đầu là H = 5,2.1008 Bq. Coi rằng 85% lượng Iodine ( ${}_{53}^{131}I$ ) trong liều đó sẽ tập trung tại tuyến giáp. Bệnh nhân được kiểm tra tuyến giáp lần thứ nhất ngay sau khi dùng liều và lần thứ hai sau 48 giờ. Lấy NA = 6,02.10<sup>23</sup> mol–1 và khối lượng mol của 23là 131 g/mol.","difficulty":"kho","statements":[{"text":"Hạt nhân  ${}_{53}^{131}I$  phát ra hạt positron để biến đổi thành hạt nhân ${}_{54}^{131}Xe$ .","answer":false},{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$  xấp xỉ là 1,3.10<sup>−6</sup> s-1","answer":false},{"text":"Khối lượng ban đầu của  ${}_{53}^{131}I$  có trong liều mà bệnh nhân đã sử dụng xấp xỉ là 0,113μg.","answer":true},{"text":"Sau khi dùng liều 48 giờ, lượng  ${}_{53}^{131}I$  đã lắng đọng tại tuyến giáp có độ phóng xạ xấp xỉ là 6,91.10<sup>6</sup>Βq.","answer":false}],"explanation":"a) sai<br>${}_{53}^{131}I\\rightarrow_{54}^{131}Xe+_{−1}^0\\Rightarrow$  Electron chứ không phải postrion<br>b) sai<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{8.24.60.60}\\approx 1,0.10^{−6}.s^{−1}$<br>c) đúng<br>$H_0=\\lambda N_0\\Rightarrow 5,2.10^8=1,0.10^{−6}N_0\\Rightarrow N_0=5,2.10^{14}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$n_0=\\frac{N_0}{N_A}=\\frac{5,2.10^{14}}{6,02.10^{23}}\\approx 8,64.10^{−10}mol$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$m_0=n_0.M=8,64.10^{−10}.131\\approx 0,1113.10^{−6}g=0,113\\mu g$<br>d) sai<br>$H=0,85H_0.2^{−\\frac{t}{T}}=0,85.5,2.10^8.2^{−\\frac{48}{8.24}}\\approx 3,72.10^8Bq$  H","difficultySource":"ai"},"ex":[{"exam":356,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Đồng vị Iodine ( ${}_{53}^{131}I$ ) là chất phóng xạ β- được sử dụng trong y học để điều trị các bệnh liên quan đến tuyến giáp. Chất này có chu kỳ bán rã là 8 ngày. Một bệnh nhân được chỉ định sử dụng liều Iodine-131 với độ phóng xạ ban đầu là H = 5,2.1008 Bq. Coi rằng 85% lượng Iodine ( ${}_{53}^{131}I$ ) trong liều đó sẽ tập trung tại tuyến giáp. Bệnh nhân được kiểm tra tuyến giáp lần thứ nhất ngay sau khi dùng liều và lần thứ hai sau 48 giờ. Lấy NA = 6,02.10<sup>23</sup> mol–1 và khối lượng mol của 23là 131 g/mol.","difficulty":"kho","statements":[{"text":"Hạt nhân  ${}_{53}^{131}I$  phát ra hạt positron để biến đổi thành hạt nhân ${}_{54}^{131}Xe$ .","answer":false},{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$  xấp xỉ là 1,3.10<sup>−6</sup> s-1","answer":false},{"text":"Khối lượng ban đầu của  ${}_{53}^{131}I$  có trong liều mà bệnh nhân đã sử dụng xấp xỉ là 0,113μg.","answer":true},{"text":"Sau khi dùng liều 48 giờ, lượng  ${}_{53}^{131}I$  đã lắng đọng tại tuyến giáp có độ phóng xạ xấp xỉ là 6,91.10<sup>6</sup>Βq.","answer":false}],"explanation":"a) sai<br>${}_{53}^{131}I\\rightarrow_{54}^{131}Xe+_{−1}^0\\Rightarrow$  Electron chứ không phải postrion<br>b) sai<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{8.24.60.60}\\approx 1,0.10^{−6}.s^{−1}$<br>c) đúng<br>$H_0=\\lambda N_0\\Rightarrow 5,2.10^8=1,0.10^{−6}N_0\\Rightarrow N_0=5,2.10^{14}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$n_0=\\frac{N_0}{N_A}=\\frac{5,2.10^{14}}{6,02.10^{23}}\\approx 8,64.10^{−10}mol$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$m_0=n_0.M=8,64.10^{−10}.131\\approx 0,1113.10^{−6}g=0,113\\mu g$<br>d) sai<br>$H=0,85H_0.2^{−\\frac{t}{T}}=0,85.5,2.10^8.2^{−\\frac{48}{8.24}}\\approx 3,72.10^8Bq$  H","difficultySource":"ai"}}]},{"id":633927,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một ấm điện có công suất 1000 W chứa 300 g nước ở 20°Cđược đun đến khi sôi ở 100°C. Cho  nhiệt dung riêng và nhiệt hóa hơi riêng của nước lần lượt là 4,2.10<sup>3</sup> J/kg.K; 2,26.10<sup>6</sup> J/kg. Bỏ qua nhiệt lượng làm nóng vỏ ấm và nhiệt lượng tỏa ra môi trường. Coi ấm điện hoạt động bình thường trong suốt thời gian đun.","difficulty":"trung-binh","statements":[{"text":"Khi đun nước bằng ấm điện thì có sự chuyển hóa năng lượng từ điện năng thành nhiệt năng để làm nóng nước.","answer":true},{"text":"Trong quá trình đun nước, nước trong ấm truyền nhiệt lượng.","answer":false},{"text":"Thời gian từ lúc đun đến lúc nước bắt đầu sôi 100,8 s.","answer":true},{"text":"Sau khi nước đạt đến nhiệt độ sôi, người ta để ấm tiếp tục đun nước sôi trong 7 phút 32 s.","answer":true}],"explanation":"a) đúng<br>Khi đun nước bằng ấm điện thì có sự chuyển hóa năng lượng từ điện năng thành nhiệt năng để làm nóng nước.<br>b) sai<br>Nước trong ấm nhận nhiệt lượng<br>c) đúng<br>$Q=mc\\Delta t=0,3.4,2.10^3.\\left(100−20\\right)=100800\\left(J\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$t=\\frac{Q}{P}=\\frac{100800}{1000}=100,8s$<br>d) đúng<br>$Q_h=Pt_h=1000.\\left(7.60+32\\right)=452000J$<br>Khối lượng nước hoá hơi:  $m_h=\\frac{Q_h}{L}=\\frac{452000}{2,26.10^6}=0,2kg=200g$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Khối lượng nước còn lại trong ấm:  $m−m_h=300−200=100g$","difficultySource":"ai"},"ex":[{"exam":356,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một ấm điện có công suất 1000 W chứa 300 g nước ở 20°Cđược đun đến khi sôi ở 100°C. Cho  nhiệt dung riêng và nhiệt hóa hơi riêng của nước lần lượt là 4,2.10<sup>3</sup> J/kg.K; 2,26.10<sup>6</sup> J/kg. Bỏ qua nhiệt lượng làm nóng vỏ ấm và nhiệt lượng tỏa ra môi trường. Coi ấm điện hoạt động bình thường trong suốt thời gian đun.","difficulty":"trung-binh","statements":[{"text":"Khi đun nước bằng ấm điện thì có sự chuyển hóa năng lượng từ điện năng thành nhiệt năng để làm nóng nước.","answer":true},{"text":"Trong quá trình đun nước, nước trong ấm truyền nhiệt lượng.","answer":false},{"text":"Thời gian từ lúc đun đến lúc nước bắt đầu sôi 100,8 s.","answer":true},{"text":"Sau khi nước đạt đến nhiệt độ sôi, người ta để ấm tiếp tục đun nước sôi trong 7 phút 32 s.","answer":true}],"explanation":"a) đúng<br>Khi đun nước bằng ấm điện thì có sự chuyển hóa năng lượng từ điện năng thành nhiệt năng để làm nóng nước.<br>b) sai<br>Nước trong ấm nhận nhiệt lượng<br>c) đúng<br>$Q=mc\\Delta t=0,3.4,2.10^3.\\left(100−20\\right)=100800\\left(J\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$t=\\frac{Q}{P}=\\frac{100800}{1000}=100,8s$<br>d) đúng<br>$Q_h=Pt_h=1000.\\left(7.60+32\\right)=452000J$<br>Khối lượng nước hoá hơi:  $m_h=\\frac{Q_h}{L}=\\frac{452000}{2,26.10^6}=0,2kg=200g$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Khối lượng nước còn lại trong ấm:  $m−m_h=300−200=100g$","difficultySource":"ai"}}]},{"id":633929,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"1,5","question":"Hình bên mô tả một chiếc bàn là hơi nước. Nước từ một bình chứa nhỏ giọt vào một tấm kim loại được nung nóng bằng điện. Bộ phận làm nóng tiêu thụ công suất điện P (kW). Giả sử rằng toàn bộ năng lượng từ bộ phận làm nóng được truyền đến tấm kim loại. Tấm kim loại được duy trì ở nhiệt độ làm việc của nó. Nước ở 30°C nhỏ giọt vào tấm kim loại làm hơi nước ở 100°C liên tục thoát ra từ bàn là. Nhiệt hóa hơi riêng của nước là 2,26.10<sup>6</sup> J/kg, nhiệt dung riêng của nước là 4200 J/kg.K, bỏ qua mọi hao phí do tỏa nhiệt ra môi trường. Mỗi phút bàn là tạo ra được 35,2 gam hơi nước thì P có giá trị bằng bao nhiêu? Kết quả làm tròn đến chữ số hàng phần mười.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046184377-hinh-7.jpg\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$Q=mc\\Delta t+mL=35,2.10^{−3}.4200.\\left(100−30\\right)+35,2.10^{−3}.2,26.10^6=89900,8J$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$P=\\frac{Q}{t}=\\frac{89900,8}{60}=1498W\\approx 1,5kW$","difficultySource":"ai"},"ex":[{"exam":356,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"1,5","question":"Hình bên mô tả một chiếc bàn là hơi nước. Nước từ một bình chứa nhỏ giọt vào một tấm kim loại được nung nóng bằng điện. Bộ phận làm nóng tiêu thụ công suất điện P (kW). Giả sử rằng toàn bộ năng lượng từ bộ phận làm nóng được truyền đến tấm kim loại. Tấm kim loại được duy trì ở nhiệt độ làm việc của nó. Nước ở 30°C nhỏ giọt vào tấm kim loại làm hơi nước ở 100°C liên tục thoát ra từ bàn là. Nhiệt hóa hơi riêng của nước là 2,26.10<sup>6</sup> J/kg, nhiệt dung riêng của nước là 4200 J/kg.K, bỏ qua mọi hao phí do tỏa nhiệt ra môi trường. Mỗi phút bàn là tạo ra được 35,2 gam hơi nước thì P có giá trị bằng bao nhiêu? Kết quả làm tròn đến chữ số hàng phần mười.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046184377-hinh-7.jpg\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$Q=mc\\Delta t+mL=35,2.10^{−3}.4200.\\left(100−30\\right)+35,2.10^{−3}.2,26.10^6=89900,8J$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$P=\\frac{Q}{t}=\\frac{89900,8}{60}=1498W\\approx 1,5kW$","difficultySource":"ai"}}]},{"id":633930,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"0,95","question":"Một xi lanh đặt thẳng đứng có tiết diện không đều như hình vẽ. Giữa hai pit tông có 1 mol khí lí tưởng. Các pit tông được nối với nhau bằng một thanh cứng nhẹ. Pit tông trên có tiết diện lớn hơn pit tông dưới một lượng ΔS =10 cm2. Áp suất khí quyển p0 =1,013.10<sup>5</sup> N/m2. Giả sử khí không lọt ra ngoài, lúc đầu hệ đang cân bằng. Hỏi phải làm nóng khí trong xi lanh thêm bao nhiêu 0C để các pit tông dịch chuyển lên trên một đoạn ℓ = 6 cm. Biết khối lượng tổng cộng của hai pit tông là m = 3kg.Cho hằng số khí lí tưởng R = 8,31 J / mol.K, g = 10 $m/s^2$. Kết quả được làm tròn đến chữ số hàng phần trăm.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046184534-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Xét hệ khi cân bằng có tổng các lực hướng lên = tổng các lực hướng xuống<br>$p_0S_2+pS_1=p_0S_1+pS_2+\\left(m_1+m_2\\right)g$<br>$\\Rightarrow p\\left(S_1−S_2\\right)=p_0\\left(S_1−S_2\\right)+\\left(m_1+m_2\\right)g$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow p=p_0+\\frac{\\left(m_1+m_2\\right)g}{\\Delta S}=1,013.10^5.\\frac{3.10}{10.10^{−4}}=131300Pa$<br>$\\begin{aligned}\\end{aligned}\\frac{pV}{T}=nR\\Rightarrow T=\\frac{pV}{nR}\\Rightarrow \\Delta T=\\frac{p\\left(V^/−V\\right)}{nR}=\\frac{p.ℓ.\\Delta S}{nR}=\\frac{131300.0,06.10.10^{−4}}{1.8,31}\\approx 0,95Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":356,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"0,95","question":"Một xi lanh đặt thẳng đứng có tiết diện không đều như hình vẽ. Giữa hai pit tông có 1 mol khí lí tưởng. Các pit tông được nối với nhau bằng một thanh cứng nhẹ. Pit tông trên có tiết diện lớn hơn pit tông dưới một lượng ΔS =10 cm2. Áp suất khí quyển p0 =1,013.10<sup>5</sup> N/m2. Giả sử khí không lọt ra ngoài, lúc đầu hệ đang cân bằng. Hỏi phải làm nóng khí trong xi lanh thêm bao nhiêu 0C để các pit tông dịch chuyển lên trên một đoạn ℓ = 6 cm. Biết khối lượng tổng cộng của hai pit tông là m = 3kg.Cho hằng số khí lí tưởng R = 8,31 J / mol.K, g = 10 m/s2. Kết quả được làm tròn đến chữ số hàng phần trăm.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046184534-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"Xét hệ khi cân bằng có tổng các lực hướng lên = tổng các lực hướng xuống<br>$p_0S_2+pS_1=p_0S_1+pS_2+\\left(m_1+m_2\\right)g$<br>$\\Rightarrow p\\left(S_1−S_2\\right)=p_0\\left(S_1−S_2\\right)+\\left(m_1+m_2\\right)g$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow p=p_0+\\frac{\\left(m_1+m_2\\right)g}{\\Delta S}=1,013.10^5.\\frac{3.10}{10.10^{−4}}=131300Pa$<br>$\\begin{aligned}\\end{aligned}\\frac{pV}{T}=nR\\Rightarrow T=\\frac{pV}{nR}\\Rightarrow \\Delta T=\\frac{p\\left(V^/−V\\right)}{nR}=\\frac{p.ℓ.\\Delta S}{nR}=\\frac{131300.0,06.10.10^{−4}}{1.8,31}\\approx 0,95Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":633932,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"16","question":"Tàu sân bay Hoa Kì Carl Vinson thăm cảng Đà Nẵng năm 2018 hoạt động nhờ hai lò phản ứng hạt nhân có công suất mỗi lò là 550 MW. Lõi nhiên liệu của lò có thể hoạt động liên tục trong 25 năm ở công suất nêu trên với hiệu suất 30%. Nhiên liệu mà lò phản ứng hạt nhân của tàu sử dụng là  ${}_{92}^{235}U$ và phản ứng xảy ra theo phương trình  ${}_{92}^{235}U+n\\rightarrow_{42}^{95}Mo+_{57}^{139}La+2n+7e$ . Hai nơtron sinh ra sau phản ứng bị thanh điều khiển hấp thụ một nơtron.<br>Biết mU  $\\approx$   234,99 amu; mMo  $\\approx$  94,88 amu; mLa  $\\approx$ 138,87 amu; mn  $\\approx$ . 1,0087 amu. Coi một năm có 365 ngày. Lấy NA = 6,02.10<sup>23</sup> mol–1 và khối lượng mol của  ${}_{92}^{235}U$  là 235 g / mol.Bỏ qua khối lượng êlectron, lấy 1 amu = 931,5 MeV/c2. Biết rằng năng lượng một phản ứng hạt nhân tỏa ra hay thu vào bằng độ chênh lệch giữa tổng khối lượng các hạt nhân trước phản ứng và tổng khối lượng các hạt nhân sau phản ứng nhân với c2 (c là tốc độ ánh sáng trong chân không). Khối lượng nhiên liệu của một lò phản ứng dùng trong 25 năm bằng bao nhiêu tấn (làm tròn kết quả đến chữ số hàng đơn vị)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046184899-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"$\\Delta E=\\left(m_U+m_n−m_{Mo}−m_{La}−2m_n\\right)c^2$<br>$\\Rightarrow \\Delta E=\\left(234,99+1,0087−94,88−138,87−2.1,0087\\right).931,5=215,45595\\left(MeV\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q=\\frac{A}{H}=\\frac{4,3362.10^{17}}{0,3}=1,4454.10^{18}J$<br>$\\begin{aligned}\\end{aligned}N=\\frac{Q}{\\Delta E}=\\frac{1,4454.10^{18}}{215,45595.1,6.10^{−13}}\\approx 4,19285.10^{28}Website: thukhoadaihoc.vn$<br>$n=\\frac{N}{N_A}=\\frac{1,19285.10^{28}}{6,02.10^{23}}=69,6.10^3\\left(mol\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$m=nM=69,6.10^3.235\\approx 16.10^6g=16$  tấn","difficultySource":"ai"},"ex":[{"exam":356,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"16","question":"Tàu sân bay Hoa Kì Carl Vinson thăm cảng Đà Nẵng năm 2018 hoạt động nhờ hai lò phản ứng hạt nhân có công suất mỗi lò là 550 MW. Lõi nhiên liệu của lò có thể hoạt động liên tục trong 25 năm ở công suất nêu trên với hiệu suất 30%. Nhiên liệu mà lò phản ứng hạt nhân của tàu sử dụng là  ${}_{92}^{235}U$ và phản ứng xảy ra theo phương trình  ${}_{92}^{235}U+n\\rightarrow_{42}^{95}Mo+_{57}^{139}La+2n+7e$ . Hai nơtron sinh ra sau phản ứng bị thanh điều khiển hấp thụ một nơtron.<br>Biết mU  $\\approx$   234,99 amu; mMo  $\\approx$  94,88 amu; mLa  $\\approx$ 138,87 amu; mn  $\\approx$ . 1,0087 amu. Coi một năm có 365 ngày. Lấy NA = 6,02.10<sup>23</sup> mol–1 và khối lượng mol của  ${}_{92}^{235}U$  là 235 g / mol.Bỏ qua khối lượng êlectron, lấy 1 amu = 931,5 MeV/c2. Biết rằng năng lượng một phản ứng hạt nhân tỏa ra hay thu vào bằng độ chênh lệch giữa tổng khối lượng các hạt nhân trước phản ứng và tổng khối lượng các hạt nhân sau phản ứng nhân với c2 (c là tốc độ ánh sáng trong chân không). Khối lượng nhiên liệu của một lò phản ứng dùng trong 25 năm bằng bao nhiêu tấn (làm tròn kết quả đến chữ số hàng đơn vị)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046184899-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"$\\Delta E=\\left(m_U+m_n−m_{Mo}−m_{La}−2m_n\\right)c^2$<br>$\\Rightarrow \\Delta E=\\left(234,99+1,0087−94,88−138,87−2.1,0087\\right).931,5=215,45595\\left(MeV\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q=\\frac{A}{H}=\\frac{4,3362.10^{17}}{0,3}=1,4454.10^{18}J$<br>$\\begin{aligned}\\end{aligned}N=\\frac{Q}{\\Delta E}=\\frac{1,4454.10^{18}}{215,45595.1,6.10^{−13}}\\approx 4,19285.10^{28}Website: thukhoadaihoc.vn$<br>$n=\\frac{N}{N_A}=\\frac{1,19285.10^{28}}{6,02.10^{23}}=69,6.10^3\\left(mol\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$m=nM=69,6.10^3.235\\approx 16.10^6g=16$  tấn","difficultySource":"ai"}}]},{"id":634951,"nq":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"375","question":"Một bơm tay có chiều cao h = 50 cm, tiết diện đáy S = 4 cm². Người ta dùng bơm này để đưa không khí vào trong săm xe đạp (săm xe chưa có không khí). Biết thời gian mỗi lần bơm hết 2,5 s và áp suất bằng áp suất khí quyển bằng 105 N/m²; trong khi bơm xem như nhiệt độ của không khí không đổi. Để đưa vào săm 6 lít khí có áp suất 5.10<sup>5</sup> N/m² thì cần thời gian bao nhiêu giây(s).","difficulty":"trung-binh","explanation":"Trong khi bơm xem như nhiệt độ của không khí không đổi → Đẳng nhiệt  $T=const$<br>$\\begin{aligned}\\end{aligned}\\Delta V=h.S=0,5.4.10^{−4}=2.10^{−4}\\left(m^3\\right)=0,2\\left(lit\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>0,2 lít ở áp suất  $10^5 \\left(N/m^2\\right)$<br>Trong khi 6 lít ở áp suất 5.10<sup>5</sup> N/m²<br>$\\Rightarrow$  Áp suất khác nhau<br>$N.\\Delta V.p_0=V^/p^/\\Rightarrow \\left(N.0,2\\right).10^5=6.5.10^5\\Rightarrow N=150$  (lần bơm) (N là số lần bơm)<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Mỗi lần bơm hết 2,5s<br>$\\begin{aligned}\\end{aligned}\\Rightarrow t=N.2,5=150.2,5=375\\left(s\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":357,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"375","question":"Một bơm tay có chiều cao h = 50 cm, tiết diện đáy S = 4 cm². Người ta dùng bơm này để đưa không khí vào trong săm xe đạp (săm xe chưa có không khí). Biết thời gian mỗi lần bơm hết 2,5 s và áp suất bằng áp suất khí quyển bằng 105 N/m²; trong khi bơm xem như nhiệt độ của không khí không đổi. Để đưa vào săm 6 lít khí có áp suất 5.10<sup>5</sup> N/m² thì cần thời gian bao nhiêu giây(s).","difficulty":"trung-binh","explanation":"Trong khi bơm xem như nhiệt độ của không khí không đổi → Đẳng nhiệt  $T=const$<br>$\\begin{aligned}\\end{aligned}\\Delta V=h.S=0,5.4.10^{−4}=2.10^{−4}\\left(m^3\\right)=0,2\\left(lit\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>0,2 lít ở áp suất  $10^5 \\left(N/m^2\\right)$<br>Trong khi 6 lít ở áp suất 5.10<sup>5</sup> N/m²<br>$\\Rightarrow$  Áp suất khác nhau<br>$N.\\Delta V.p_0=V^/p^/\\Rightarrow \\left(N.0,2\\right).10^5=6.5.10^5\\Rightarrow N=150$  (lần bơm) (N là số lần bơm)<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Mỗi lần bơm hết 2,5s<br>$\\begin{aligned}\\end{aligned}\\Rightarrow t=N.2,5=150.2,5=375\\left(s\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":634955,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":3,"options":["0,67.105 Pa","0,5.105 Pa","1,5.10<sup>5</sup> Pa","0,33.105 Pa"],"question":"Một lượng khí lí tưởng chứa trong xi lanh có pittong di chuyển không ma sát như hình vẽ. Pittong có tiết diện S = 30 cm2. Ban đầu khối khí có thể tích V1 = 240 cm3, áp suất p1 = 105 Pa . Sau đó, ta kéo pittong di chuyển chậm sang phải một đoạn 4 cm để nhiệt độ khối khí không đổi. Áp suất khí trong xi lanh khi đó đã giảm đi<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046214262-hinh-1.png\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$pV=const\\Rightarrow p_1V_1=p_2\\left(V_1+Sx\\right)$<br>$\\Rightarrow 10^5.240=p_2.\\left(240+30.4\\right)\\Rightarrow p_2\\approx 0,67.10^5Pa$<br>$\\Delta p=p_1−p_2=10^5−0,67.10^5=0,33.10^5Pa$","difficultySource":"ai"},"ex":[{"exam":358,"idx":0,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":3,"options":["0,67.105 Pa","0,5.105 Pa","1,5.10<sup>5</sup> Pa","0,33.105 Pa"],"question":"Một lượng khí lí tưởng chứa trong xi lanh có pittong di chuyển không ma sát như hình vẽ. Pittong có tiết diện S = 30 cm2. Ban đầu khối khí có thể tích V1 = 240 cm3, áp suất p1 = 105 Pa . Sau đó, ta kéo pittong di chuyển chậm sang phải một đoạn 4 cm để nhiệt độ khối khí không đổi. Áp suất khí trong xi lanh khi đó đã giảm đi<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046214262-hinh-1.png\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$pV=const\\Rightarrow p_1V_1=p_2\\left(V_1+Sx\\right)$<br>$\\Rightarrow 10^5.240=p_2.\\left(240+30.4\\right)\\Rightarrow p_2\\approx 0,67.10^5Pa$<br>$\\Delta p=p_1−p_2=10^5−0,67.10^5=0,33.10^5Pa$","difficultySource":"ai"}}]},{"id":634975,"nq":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng áp và định luật Charles","question":"Sử dụng bộ thí nghiệm hình dưới để tìm mối liên hệ giữa thể tích và nhiệt độ của một lượng khí xác định khi áp suất không đổi. Biết áp kế luôn ở mức 0 ứng với áp suất bằng áp suất khí quyển, đơn vị đo của áp kế là Bar (1Bar = 105 Pa). Đổ nước nóng vào hộp chứa cho ngập hoàn toàn xylanh. Dịch chuyển pittong từ từ sao cho số chỉ của áp kế không đổi. Kết quả đo giá trị của phần thể tích khí và nhiệt độ ghi nhận ở bảng sau:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046215853-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Chất khí trong xylanh biến đổi đẳng áp khi thực hiện thí nghiệm ở các lần đo.","answer":true},{"text":"Với kết quả thu được ở bảng trên, công thức liên hệ giữa thể tích theo nhiệt độ là V = 0,236(t + 273), với V đo bằng ml,t đo bằng 0C.","answer":true},{"text":"Mật độ phân tử khí trong xylanh tăng từ lần đo thứ 1 đến lần đo thứ 5.","answer":true},{"text":"Lượng khí đã dùng trong thí nghiệm là 2,8.10<sup>−2</sup> mol.","answer":false}],"explanation":"a) đúng<br>Số chỉ áp kế không đổi<br>b) đúng<br>$\\begin{aligned}\\end{aligned}\\frac{V}{t+273}=\\frac{1}{5}.\\left(\\frac{75}{45+273}+\\frac{74}{41+273}+\\frac{73}{37+273}+\\frac{72}{32+273}+\\frac{71}{28+273}\\right)\\approx 0,236Website: thukhoadaihoc.vn$<br>c) đúng<br>$\\mu =\\frac{N}{V}\\overset{V↓}\\rightarrow\\mu ↑$<br>d) sai<br>$\\frac{pV}{t+273}=nR\\Rightarrow 10^5.0,236.10^{−6}=n.8,31\\Rightarrow n\\approx 2,8.10^{−3}mol$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":358,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng áp và định luật Charles","question":"Sử dụng bộ thí nghiệm hình dưới để tìm mối liên hệ giữa thể tích và nhiệt độ của một lượng khí xác định khi áp suất không đổi. Biết áp kế luôn ở mức 0 ứng với áp suất bằng áp suất khí quyển, đơn vị đo của áp kế là Bar (1Bar = 105 Pa). Đổ nước nóng vào hộp chứa cho ngập hoàn toàn xylanh. Dịch chuyển pittong từ từ sao cho số chỉ của áp kế không đổi. Kết quả đo giá trị của phần thể tích khí và nhiệt độ ghi nhận ở bảng sau:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046215853-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Chất khí trong xylanh biến đổi đẳng áp khi thực hiện thí nghiệm ở các lần đo.","answer":true},{"text":"Với kết quả thu được ở bảng trên, công thức liên hệ giữa thể tích theo nhiệt độ là V = 0,236(t + 273), với V đo bằng ml,t đo bằng 0C.","answer":true},{"text":"Mật độ phân tử khí trong xylanh tăng từ lần đo thứ 1 đến lần đo thứ 5.","answer":true},{"text":"Lượng khí đã dùng trong thí nghiệm là 2,8.10<sup>−2</sup> mol.","answer":false}],"explanation":"a) đúng<br>Số chỉ áp kế không đổi<br>b) đúng<br>$\\begin{aligned}\\end{aligned}\\frac{V}{t+273}=\\frac{1}{5}.\\left(\\frac{75}{45+273}+\\frac{74}{41+273}+\\frac{73}{37+273}+\\frac{72}{32+273}+\\frac{71}{28+273}\\right)\\approx 0,236Website: thukhoadaihoc.vn$<br>c) đúng<br>$\\mu =\\frac{N}{V}\\overset{V↓}\\rightarrow\\mu ↑$<br>d) sai<br>$\\frac{pV}{t+273}=nR\\Rightarrow 10^5.0,236.10^{−6}=n.8,31\\Rightarrow n\\approx 2,8.10^{−3}mol$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":634976,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Đồng vị phóng xạ Iodine  ${}_{53}^{131}I$ được sử dụng trong điều trị ung thư tuyến giáp có chu kì bán rã là 8,02 ngày. Một mẫu  ${}_{53}^{131}I$ nguyên chất mới sản xuất có khối lượng 125 g. Cho biết khối lượng mol nguyên tử của Iodine là 131 g/mol.","difficulty":"kho","statements":[{"text":"Hạt nhân Iodine  ${}_{53}^{131}I$ có 53 neutron và 131 proton.","answer":false},{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$ là 10−6 s−1.","answer":true},{"text":"Độ phóng xạ của mẫu  ${}_{53}^{131}I$ sau 14 ngày là 5,1.10<sup>16</sup> Bq.","answer":false},{"text":"Số hạt nhân  ${}_{53}^{131}I$ đã bị phân rã phóng xạ trong khoảng thời gian 14 ngày là 4.10<sup>23</sup>.","answer":true}],"explanation":"a) sai<br>Hạt nhân Iodine  ${}_{53}^{131}$  có 53 proton<br>b) đúng<br>$\\begin{aligned}\\end{aligned}\\lambda =\\frac{ln2}{T}=\\frac{ln2}{8,02.24.60.60}\\approx 10^{−6}s^{−1}Website: thukhoadaihoc.vn$<br>c) sai<br>$n=\\frac{m}{M}=\\frac{125}{131}mol$<br>$N_0=nN_A=\\frac{125}{131}.6,02.10^{23}\\approx 5,7.10^{23}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$H_0=\\lambda N_0=10^{−6}.5,7.10^{23}\\approx 5,7.10^{17}Bq$<br>d) đúng<br>$N=N_0\\left(1−2^{−\\frac{t}{T}}\\right)=5,7.10^{23}.\\left(1−2^{−\\frac{14}{8,02}}\\right)\\approx 4.10^{23}$","difficultySource":"ai"},"ex":[{"exam":358,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Đồng vị phóng xạ Iodine  ${}_{53}^{131}I$ được sử dụng trong điều trị ung thư tuyến giáp có chu kì bán rã là 8,02 ngày. Một mẫu  ${}_{53}^{131}I$ nguyên chất mới sản xuất có khối lượng 125 g. Cho biết khối lượng mol nguyên tử của Iodine là 131 g/mol.","difficulty":"kho","statements":[{"text":"Hạt nhân Iodine  ${}_{53}^{131}I$ có 53 neutron và 131 proton.","answer":false},{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$ là 10−6 s−1.","answer":true},{"text":"Độ phóng xạ của mẫu  ${}_{53}^{131}I$ sau 14 ngày là 5,1.10<sup>16</sup> Bq.","answer":false},{"text":"Số hạt nhân  ${}_{53}^{131}I$ đã bị phân rã phóng xạ trong khoảng thời gian 14 ngày là 4.10<sup>23</sup>.","answer":true}],"explanation":"a) sai<br>Hạt nhân Iodine  ${}_{53}^{131}$  có 53 proton<br>b) đúng<br>$\\begin{aligned}\\end{aligned}\\lambda =\\frac{ln2}{T}=\\frac{ln2}{8,02.24.60.60}\\approx 10^{−6}s^{−1}Website: thukhoadaihoc.vn$<br>c) sai<br>$n=\\frac{m}{M}=\\frac{125}{131}mol$<br>$N_0=nN_A=\\frac{125}{131}.6,02.10^{23}\\approx 5,7.10^{23}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$H_0=\\lambda N_0=10^{−6}.5,7.10^{23}\\approx 5,7.10^{17}Bq$<br>d) đúng<br>$N=N_0\\left(1−2^{−\\frac{t}{T}}\\right)=5,7.10^{23}.\\left(1−2^{−\\frac{14}{8,02}}\\right)\\approx 4.10^{23}$","difficultySource":"ai"}}]},{"id":634981,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"5,3","question":"Giả sử ở một ngôi sao, sau khi chuyển hóa toàn bộ hạt nhân hidro thành hạt nhân   ${}_2^4He$ , thì ngôi sao lúc này chỉ còn  ${}_2^4He$  với khối lượng 4,6.10<sup>32</sup> kg. Tiếp theo đó,  ${}_2^4He$  chuyển hóa thành hạt nhân  ${}_6^{12}C$ thông qua quá trình tổng hợp  ${}_2^4He+_2^4He\\rightarrow_6^{12}C+7,27MeV$ . Coi toàn bộ năng lượng tỏa ra từ quá trình tổng hợp này đều được phát ra với công suất trung bình là P = x.10<sup>30</sup>W. Cho: 1 năm = 365,25 ngày; khối lượng mol của nguyên tử helium là 4 g/mol; thời gian để chuyển hóa hết  ${}_2^4He$  ở ngôi sao này thành  ${}_6^{12}C$  vào khoảng 160 triệu năm. Tìm x (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"kho","explanation":"$n=\\frac{m}{M}=\\frac{4,6.10^{32}}{4.10^{−3}}=1,15.10^{25}mol$<br>$N_{He}=nN_A=1,15.10^{35}.6,02.10^{23}=6,923.10^{58}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$N=\\frac{N_{He}}{3}=\\frac{6,923.10^{58}}{3}\\approx 2,31.10^{58}$<br>$Q=N\\Delta E=2,31.10^{58}.7,27.1,6.10^{−13}\\approx 2,7.10^{46}J$<br>$\\begin{aligned}\\end{aligned}P=\\frac{Q}{t}=\\frac{2,7.10^{46}}{160.10^6.365,25.24.60.60}\\approx 5,3.10^{30}Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":358,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"5,3","question":"Giả sử ở một ngôi sao, sau khi chuyển hóa toàn bộ hạt nhân hidro thành hạt nhân   ${}_2^4He$ , thì ngôi sao lúc này chỉ còn  ${}_2^4He$  với khối lượng 4,6.10<sup>32</sup> kg. Tiếp theo đó,  ${}_2^4He$  chuyển hóa thành hạt nhân  ${}_6^{12}C$ thông qua quá trình tổng hợp  ${}_2^4He+_2^4He\\rightarrow_6^{12}C+7,27MeV$ . Coi toàn bộ năng lượng tỏa ra từ quá trình tổng hợp này đều được phát ra với công suất trung bình là P = x.10<sup>30</sup>W. Cho: 1 năm = 365,25 ngày; khối lượng mol của nguyên tử helium là 4 g/mol; thời gian để chuyển hóa hết  ${}_2^4He$  ở ngôi sao này thành  ${}_6^{12}C$  vào khoảng 160 triệu năm. Tìm x (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"kho","explanation":"$n=\\frac{m}{M}=\\frac{4,6.10^{32}}{4.10^{−3}}=1,15.10^{25}mol$<br>$N_{He}=nN_A=1,15.10^{35}.6,02.10^{23}=6,923.10^{58}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$N=\\frac{N_{He}}{3}=\\frac{6,923.10^{58}}{3}\\approx 2,31.10^{58}$<br>$Q=N\\Delta E=2,31.10^{58}.7,27.1,6.10^{−13}\\approx 2,7.10^{46}J$<br>$\\begin{aligned}\\end{aligned}P=\\frac{Q}{t}=\\frac{2,7.10^{46}}{160.10^6.365,25.24.60.60}\\approx 5,3.10^{30}Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":636383,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng áp và định luật Charles","answer":1,"options":["17,4.10<sup>5</sup> Pa","1,8.10<sup>5</sup> Pa","1,1.10<sup>5</sup> Pa","1,6.10<sup>5</sup> Pa"],"question":"Trong một số trường hợp, người ta có thể mở nút bấc chai rượu vang bằng cách hơ nóng cổ chai. Khi cổ chai được hơ nóng, không khí trong cổ chai giãn nở, tăng áp suất và đẩy nút bấc ra ngoài. Giả sử khí trong chai là xác định và coi là khí lí tưởng; ban đầu khí có áp suất bằng 1,4.10<sup>5</sup> Pa và có nhiệt độ bằng 70C. Khi khí được hơ nóng đến 87 oC thì nút chai bắt đầu dịch chuyển, coi thể tích khí trong chai không đổi. Áp suất của khí trong chai khi nút bấc bắt đầu dịch chuyển bằng bao nhiêu?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046222145-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"Đẳng tích:  $\\frac{p}{T}=const\\Rightarrow \\frac{1,4.10^5}{7+273}=\\frac{p}{87+273}\\Rightarrow p=1,8.10^5Pa$","difficultySource":"ai"},"ex":[{"exam":359,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng áp và định luật Charles","answer":1,"options":["17,4.10<sup>5</sup> Pa","1,8.10<sup>5</sup> Pa","1,1.10<sup>5</sup> Pa","1,6.10<sup>5</sup> Pa"],"question":"Trong một số trường hợp, người ta có thể mở nút bấc chai rượu vang bằng cách hơ nóng cổ chai. Khi cổ chai được hơ nóng, không khí trong cổ chai giãn nở, tăng áp suất và đẩy nút bấc ra ngoài. Giả sử khí trong chai là xác định và coi là khí lí tưởng; ban đầu khí có áp suất bằng 1,4.10<sup>5</sup> Pa và có nhiệt độ bằng 70C. Khi khí được hơ nóng đến 87 oC thì nút chai bắt đầu dịch chuyển, coi thể tích khí trong chai không đổi. Áp suất của khí trong chai khi nút bấc bắt đầu dịch chuyển bằng bao nhiêu?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046222145-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"de","explanation":"Đẳng tích:  $\\frac{p}{T}=const\\Rightarrow \\frac{1,4.10^5}{7+273}=\\frac{p}{87+273}\\Rightarrow p=1,8.10^5Pa$","difficultySource":"ai"}}]},{"id":636386,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm và đơn vị đo năng lượng","answer":0,"options":["0,65 µm.","0,72 µm.","0,62 µm.","0,75 µm."],"question":"Khi nguyên tử chuyển từ trạng thái dừng có năng lượng cao En xuống trạng thái dừng có năng lượng thấp Em thì phát ra một photon có năng lượng  $\\varepsilon =\\frac{hc}{\\lambda }=E_n−E_m$ (với h = 6,626.10<sup>−34</sup> J.s). Trong quang phổ vạch phát xạ của hydrogen, ở vùng ánh sáng nhìn thấy có bốn vạch đặc trưng là vạch đỏ, vạch lam, vạch chàm và vạch tím. Vạch đỏ ứng với photon phát ra khi nguyên tử chuyển từ trạng thái có năng lượng En= -1,5 eV xuống trạng thái có năng lượng Em = -3,4 eV. Bước sóng của vạch đỏ bằng bao nhiêu?","difficulty":"trung-binh","explanation":"$\\frac{hc}{\\lambda }=E_n−E_m\\Rightarrow \\frac{6,626.10^{−34}.3.10^8}{\\lambda }=\\left(−1,5+3,4\\right).1,6.10^{−19}$<br>$\\Rightarrow \\lambda \\approx 0,65.10^{−6}m=0,65\\left(\\mu m\\right)$","difficultySource":"ai"},"ex":[{"exam":359,"idx":17,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm và đơn vị đo năng lượng","answer":0,"options":["0,65 µm.","0,72 µm.","0,62 µm.","0,75 µm."],"question":"Khi nguyên tử chuyển từ trạng thái dừng có năng lượng cao En xuống trạng thái dừng có năng lượng thấp Em thì phát ra một photon có năng lượng  $\\varepsilon =\\frac{hc}{\\lambda }=E_n−E_m$ (với h = 6,626.10<sup>−34</sup> J.s). Trong quang phổ vạch phát xạ của hydrogen, ở vùng ánh sáng nhìn thấy có bốn vạch đặc trưng là vạch đỏ, vạch lam, vạch chàm và vạch tím. Vạch đỏ ứng với photon phát ra khi nguyên tử chuyển từ trạng thái có năng lượng En= -1,5 eV xuống trạng thái có năng lượng Em = -3,4 eV. Bước sóng của vạch đỏ bằng bao nhiêu?","difficulty":"trung-binh","explanation":"$\\frac{hc}{\\lambda }=E_n−E_m\\Rightarrow \\frac{6,626.10^{−34}.3.10^8}{\\lambda }=\\left(−1,5+3,4\\right).1,6.10^{−19}$<br>$\\Rightarrow \\lambda \\approx 0,65.10^{−6}m=0,65\\left(\\mu m\\right)$","difficultySource":"ai"}}]},{"id":636389,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Quạt hơi nước là thiết bị hoạt động dựa vào hiện tượng bay hơi nước để làm mát không khí. Bơm nước tuần hoàn liên tục qua tấm làm mát. Luồng gió bên ngoài phòng được quạt hút vào máy, đi qua tấm làm mát. Nước trên tấm làm mát sẽ hấp thụ nhiệt của khí nóng làm nước bay hơi và làm giảm nhiệt độ không khí. Giả sử toàn bộ nhiệt lượng lấy từ không khí chỉ để làm bay hơi nước. Biết lưu lượng nước bay hơi từ quạt là 0,15 g/s; Ở nhiệt độ và áp suất phòng khi đó thì nhiệt hóa hơi riêng của nước là 2,26.10<sup>6</sup> J/kg, khối lượng riêng của không khí trong phòng là 1,2 kg/m3 và nhiệt dung riêng của không khí là 1005 J/(kg.K).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046223382-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối lượng nước bay hơi trong thời gian 20 phút là 0,18 kg.","answer":true},{"text":"Nhiệt lượng cần thiết lấy từ không khí để làm bay hơi nước ở nhiệt độ và áp suất phòng trong thời gian 20 phút là 4068 J.","answer":false},{"text":"Khối lượng không khí trong phòng đó (kích thước: 4m x 4m x 3m) là 57,6 kg.","answer":true},{"text":"Sau 20 phút mở quạt, không khí mát từ quạt khuếch tán đều trong phòng làm nhiệt độ của phòng giảm đi khoảng 9,70C.","answer":false}],"explanation":"a) đúng<br>$m=0,15.20.60=180g=0,18kg$<br>b) sai<br>$Q=mL=0,18.2,26.10^6=406800J$<br>c) đúng<br>$m_{kk}=VD=4.4.3.1,2=57,6kg$<br>d) sai<br>$Q=m_{kk}c_{kk}\\Delta t\\Rightarrow 406800=57,6.1005.\\Delta t\\Rightarrow \\Delta t\\approx 7,03^0C$","difficultySource":"ai"},"ex":[{"exam":359,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Quạt hơi nước là thiết bị hoạt động dựa vào hiện tượng bay hơi nước để làm mát không khí. Bơm nước tuần hoàn liên tục qua tấm làm mát. Luồng gió bên ngoài phòng được quạt hút vào máy, đi qua tấm làm mát. Nước trên tấm làm mát sẽ hấp thụ nhiệt của khí nóng làm nước bay hơi và làm giảm nhiệt độ không khí. Giả sử toàn bộ nhiệt lượng lấy từ không khí chỉ để làm bay hơi nước. Biết lưu lượng nước bay hơi từ quạt là 0,15 g/s; Ở nhiệt độ và áp suất phòng khi đó thì nhiệt hóa hơi riêng của nước là 2,26.10<sup>6</sup> J/kg, khối lượng riêng của không khí trong phòng là 1,2 kg/m3 và nhiệt dung riêng của không khí là 1005 J/(kg.K).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046223382-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối lượng nước bay hơi trong thời gian 20 phút là 0,18 kg.","answer":true},{"text":"Nhiệt lượng cần thiết lấy từ không khí để làm bay hơi nước ở nhiệt độ và áp suất phòng trong thời gian 20 phút là 4068 J.","answer":false},{"text":"Khối lượng không khí trong phòng đó (kích thước: 4m x 4m x 3m) là 57,6 kg.","answer":true},{"text":"Sau 20 phút mở quạt, không khí mát từ quạt khuếch tán đều trong phòng làm nhiệt độ của phòng giảm đi khoảng 9,70C.","answer":false}],"explanation":"a) đúng<br>$m=0,15.20.60=180g=0,18kg$<br>b) sai<br>$Q=mL=0,18.2,26.10^6=406800J$<br>c) đúng<br>$m_{kk}=VD=4.4.3.1,2=57,6kg$<br>d) sai<br>$Q=m_{kk}c_{kk}\\Delta t\\Rightarrow 406800=57,6.1005.\\Delta t\\Rightarrow \\Delta t\\approx 7,03^0C$","difficultySource":"ai"}}]},{"id":636392,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"178","question":"Trong một xilanh chứa một lượng khí có áp suất p = 1,5.10<sup>5</sup> Pa, thể tích V1 = 2,6 lít. Khí được được nung nóng đẳng áp, dãn nở đẩy pit-tông dịch chuyển đều đến thể tích V2 = 3,12 lít thì nội năng của khối khí tăng thêm 100 J. Nhiệt lượng đã truyền cho khối khí khi nung nóng bằng bao nhiêu J (kết quả được viết đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"$A=−p\\left(V_2−V_1\\right)=−1,5.10^5.\\left(3,12−2,6\\right).10^{−3}=−78\\left(J\\right)$<br>$\\Delta U=Q+A\\Rightarrow 100=Q−78\\Rightarrow Q=178\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":359,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"178","question":"Trong một xilanh chứa một lượng khí có áp suất p = 1,5.10<sup>5</sup> Pa, thể tích V1 = 2,6 lít. Khí được được nung nóng đẳng áp, dãn nở đẩy pit-tông dịch chuyển đều đến thể tích V2 = 3,12 lít thì nội năng của khối khí tăng thêm 100 J. Nhiệt lượng đã truyền cho khối khí khi nung nóng bằng bao nhiêu J (kết quả được viết đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"$A=−p\\left(V_2−V_1\\right)=−1,5.10^5.\\left(3,12−2,6\\right).10^{−3}=−78\\left(J\\right)$<br>$\\Delta U=Q+A\\Rightarrow 100=Q−78\\Rightarrow Q=178\\left(J\\right)$","difficultySource":"ai"}}]},{"id":636413,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["1,9 kJ.","2,1 kJ.","3,1 kJ.","2,7 kJ."],"question":"Để hàn các linh kiện trong mạch điện tử, người thợ thường sử dụng mỏ hàn điện để làm nóng chảy dây thiếc hàn. Biết rằng loại thiếc hàn sử dụng là hỗn hợp của thiếc và chì với tỉ lệ khối lượng lần lượt là 63: 37. Biết nhiệt nóng chảy riêng của thiếc và chì lần lượt là 6,1.10<sup>4</sup> J/kg và 2,5.10<sup>4</sup> J/kg. Nhiệt lượng mỏ hàn cần cung cấp để làm nóng chảy hết 57 g thiếc hàn ở nhiệt độ nóng chảy là","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\frac{m_{th}}{m_c}=\\frac{63}{37}\\overset{m_{th}+m_c=57}\\rightarrow\\left\\{\\begin{aligned}m_{th}=35,91g <br>m_c=21,09g\\end{aligned}\\right. <br>Website: thukhoadaihoc.vn\\end{aligned}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q=m_{th}\\lambda_{th}+m_c\\lambda_c=35,91.10^{−3}.6,1.10^4+21,09.10^{−3}.2,5.10^4=2718J\\approx 2,7\\left(kJ\\right)$","difficultySource":"ai"},"ex":[{"exam":360,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":3,"options":["1,9 kJ.","2,1 kJ.","3,1 kJ.","2,7 kJ."],"question":"Để hàn các linh kiện trong mạch điện tử, người thợ thường sử dụng mỏ hàn điện để làm nóng chảy dây thiếc hàn. Biết rằng loại thiếc hàn sử dụng là hỗn hợp của thiếc và chì với tỉ lệ khối lượng lần lượt là 63: 37. Biết nhiệt nóng chảy riêng của thiếc và chì lần lượt là 6,1.10<sup>4</sup> J/kg và 2,5.10<sup>4</sup> J/kg. Nhiệt lượng mỏ hàn cần cung cấp để làm nóng chảy hết 57 g thiếc hàn ở nhiệt độ nóng chảy là","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\frac{m_{th}}{m_c}=\\frac{63}{37}\\overset{m_{th}+m_c=57}\\rightarrow\\left\\{\\begin{aligned}m_{th}=35,91g <br>m_c=21,09g\\end{aligned}\\right. <br>Website: thukhoadaihoc.vn\\end{aligned}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q=m_{th}\\lambda_{th}+m_c\\lambda_c=35,91.10^{−3}.6,1.10^4+21,09.10^{−3}.2,5.10^4=2718J\\approx 2,7\\left(kJ\\right)$","difficultySource":"ai"}}]},{"id":637348,"nq":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một máy phát điện mini sử dụng động cơ nhiệt Stirling gamma để cung cấp điện cho các khu vực nông thôn không có lưới điện. Động cơ này hoạt động bằng cách sử dụng nhiệt từ ánh sáng mặt trời tập trung để tạo ra sự chênh lệch nhiệt độ cần thiết cho chu trình Stirling. Hình vẽ dưới biểu diễn chu trình 1-2-3-4-1 của khí trong xi-lanh, trong đó 1 - 2 và 3 - 4 là quá trình đẳng nhiệt. Trạng thái (2) có nhiệt độ 300 K. Hệ số nén VR và hiệu suất η của động cơ được tính theo công thức $VR=\\frac{v_{max}}{v_{min}};\\eta =1−\\frac{T_{min}}{T_{max}}$ với Vmax, Tmax là thể tích, nhiệt độ lớn nhất trong chu trình và Vmin, Tmin là nhỏ nhất trong chu trình. Hiệu suất của chu trình là 62,5% và 1Bar = 105 Pa<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046235461-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046235641-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quá trình 3 - 4 khí trong xi-lanh nhận nhiệt từ bên ngoài.","answer":true},{"text":"Hệ số nén của độ cơ là VR = 4.","answer":false},{"text":"Số mol khí trong xi-lanh là 40.10<sup>−3</sup> mol.","answer":true},{"text":"Nhiệt độ trạng thái (4) là 3630C.","answer":false}],"explanation":"a) đúng<br>Quá trình (3) – (4) có nhiệt độ không đổi mà thể tích tăng → Thực hiện công → Nhận nhiệt<br>b) sai<br>$VR=\\frac{V_{max}}{V_{min}}=\\frac{1}{0,5}=2$<br>c) đúng<br>$n=\\frac{pV}{RT}=\\frac{2.10^5.0,5.10^{−3}}{8,31.300}\\approx 40.10^{−3}mol$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>$\\begin{aligned}\\end{aligned}H=1−\\frac{T_{min}}{T_{max}}=1−\\frac{T_2}{T_4}\\Rightarrow 0,625=1−\\frac{300}{T_4}\\Rightarrow T_4=800K=527^0CWebsite: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":361,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Vận dụng phương trình trạng thái","question":"Một máy phát điện mini sử dụng động cơ nhiệt Stirling gamma để cung cấp điện cho các khu vực nông thôn không có lưới điện. Động cơ này hoạt động bằng cách sử dụng nhiệt từ ánh sáng mặt trời tập trung để tạo ra sự chênh lệch nhiệt độ cần thiết cho chu trình Stirling. Hình vẽ dưới biểu diễn chu trình 1-2-3-4-1 của khí trong xi-lanh, trong đó 1 - 2 và 3 - 4 là quá trình đẳng nhiệt. Trạng thái (2) có nhiệt độ 300 K. Hệ số nén VR và hiệu suất η của động cơ được tính theo công thức $VR=\\frac{v_{max}}{v_{min}};\\eta =1−\\frac{T_{min}}{T_{max}}$ với Vmax, Tmax là thể tích, nhiệt độ lớn nhất trong chu trình và Vmin, Tmin là nhỏ nhất trong chu trình. Hiệu suất của chu trình là 62,5% và 1Bar = 105 Pa<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046235461-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046235641-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quá trình 3 - 4 khí trong xi-lanh nhận nhiệt từ bên ngoài.","answer":true},{"text":"Hệ số nén của độ cơ là VR = 4.","answer":false},{"text":"Số mol khí trong xi-lanh là 40.10<sup>−3</sup> mol.","answer":true},{"text":"Nhiệt độ trạng thái (4) là 3630C.","answer":false}],"explanation":"a) đúng<br>Quá trình (3) – (4) có nhiệt độ không đổi mà thể tích tăng → Thực hiện công → Nhận nhiệt<br>b) sai<br>$VR=\\frac{V_{max}}{V_{min}}=\\frac{1}{0,5}=2$<br>c) đúng<br>$n=\\frac{pV}{RT}=\\frac{2.10^5.0,5.10^{−3}}{8,31.300}\\approx 40.10^{−3}mol$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>$\\begin{aligned}\\end{aligned}H=1−\\frac{T_{min}}{T_{max}}=1−\\frac{T_2}{T_4}\\Rightarrow 0,625=1−\\frac{300}{T_4}\\Rightarrow T_4=800K=527^0CWebsite: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":637350,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Để đảm bảo an toàn và ngăn ngừa rò rỉ, các công ty dầu khí tiến hành kiểm tra định kỳ các mối hàn trên các đường ống thép công nghiệp. Trong quá trình kiểm tra, các kỹ sư sử dụng phương pháp kiểm tra không phá hủy bằng tia phóng xạ, một kỹ thuật hiện đại với nguồn phóng xạ Iridium-192 ( ${}_{77}^{192}Ir$ ) được đặt trong thiết bị chuyên dụng. Thiết bị này chiếu tia phóng xạ xuyên qua mối hàn và cảm biến đặt ở phía đối diện sẽ ghi lại hình ảnh, giúp phát hiện các khuyết tật tiềm ẩn mà mắt thường không thể nhìn thấy. Biết hạt nhân  ${}_{77}^{192}Ir$ là chất phóng xạ beta trừ β−kèm theo tia gamma γ với chu kì bán rã 73,8 ngày. Một ống phóng xạ  ${}_{77}^{192}Ir$ có hoạt độ phóng xạ giảm đi 75,0% so với khi mới sản xuất thì công ty sẽ thay mới do hết khả năng kinh tế. Khối lượng mol của   ${}_{77}^{192}Ir$ là 192 g/mol, lấy 1Ci = 3,70. 10<sup>10</sup> Bq.","difficulty":"kho","statements":[{"text":"Khi chiếu tia phóng xạ thì dòng các electron xuyên qua mối hàn và cảm biến ghi lại hình ảnh.","answer":false},{"text":"Hạt nhân   ${}_{77}^{192}Ir$ phóng ra positron tạo thành Platium ${}_{79}^{192}Pt$  .","answer":true},{"text":"Sau mỗi ngày hoạt độ phóng xạ giảm đi 0,935%.","answer":true},{"text":"Một kỹ sư của công ty nhận được một ống   ${}_{77}^{192}Ir$ khi vừa mới sản xuất có hoạt động phóng xạ","answer":false}],"explanation":"a) sai<br>Tia γ xuyên qua chứ không phải dòng electron vì tia γ có độ đâm xuyên mạnh<br>b) đúng<br>Phóng xạ β- là phón ra electron<br>c) đúng<br>$\\frac{H}{H_0}=2^{−\\frac{t}{T}}=2^{−\\frac{1}{73,8}}\\approx 0,99065=99,065%=100%−0,935%$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>$H=\\left(1−0,75\\right)H_0=0,25.50.10^{−3}.3,7.10^{10}=462,5.10^6Bq$<br>$\\begin{aligned}\\end{aligned}H=\\lambda N=\\frac{ln2}{T}.N\\Rightarrow 462,5.10^6=\\frac{ln2}{73,8.24.60.60}N\\Rightarrow N\\approx 4,25.10^{15}Website: thukhoadaihoc.vn$<br>$m=nM=\\frac{N}{N_A}.M=\\frac{4,25.10^{15}}{6,02.10^{23}}.192\\approx 1,36.10^{−6}g=1,36\\left(\\mu g\\right)$","difficultySource":"ai"},"ex":[{"exam":361,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Để đảm bảo an toàn và ngăn ngừa rò rỉ, các công ty dầu khí tiến hành kiểm tra định kỳ các mối hàn trên các đường ống thép công nghiệp. Trong quá trình kiểm tra, các kỹ sư sử dụng phương pháp kiểm tra không phá hủy bằng tia phóng xạ, một kỹ thuật hiện đại với nguồn phóng xạ Iridium-192 ( ${}_{77}^{192}Ir$ ) được đặt trong thiết bị chuyên dụng. Thiết bị này chiếu tia phóng xạ xuyên qua mối hàn và cảm biến đặt ở phía đối diện sẽ ghi lại hình ảnh, giúp phát hiện các khuyết tật tiềm ẩn mà mắt thường không thể nhìn thấy. Biết hạt nhân  ${}_{77}^{192}Ir$ là chất phóng xạ beta trừ β−kèm theo tia gamma γ với chu kì bán rã 73,8 ngày. Một ống phóng xạ  ${}_{77}^{192}Ir$ có hoạt độ phóng xạ giảm đi 75,0% so với khi mới sản xuất thì công ty sẽ thay mới do hết khả năng kinh tế. Khối lượng mol của   ${}_{77}^{192}Ir$ là 192 g/mol, lấy 1Ci = 3,70. 10<sup>10</sup> Bq.","difficulty":"kho","statements":[{"text":"Khi chiếu tia phóng xạ thì dòng các electron xuyên qua mối hàn và cảm biến ghi lại hình ảnh.","answer":false},{"text":"Hạt nhân   ${}_{77}^{192}Ir$ phóng ra positron tạo thành Platium ${}_{79}^{192}Pt$  .","answer":true},{"text":"Sau mỗi ngày hoạt độ phóng xạ giảm đi 0,935%.","answer":true},{"text":"Một kỹ sư của công ty nhận được một ống   ${}_{77}^{192}Ir$ khi vừa mới sản xuất có hoạt động phóng xạ","answer":false}],"explanation":"a) sai<br>Tia γ xuyên qua chứ không phải dòng electron vì tia γ có độ đâm xuyên mạnh<br>b) đúng<br>Phóng xạ β- là phón ra electron<br>c) đúng<br>$\\frac{H}{H_0}=2^{−\\frac{t}{T}}=2^{−\\frac{1}{73,8}}\\approx 0,99065=99,065%=100%−0,935%$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>$H=\\left(1−0,75\\right)H_0=0,25.50.10^{−3}.3,7.10^{10}=462,5.10^6Bq$<br>$\\begin{aligned}\\end{aligned}H=\\lambda N=\\frac{ln2}{T}.N\\Rightarrow 462,5.10^6=\\frac{ln2}{73,8.24.60.60}N\\Rightarrow N\\approx 4,25.10^{15}Website: thukhoadaihoc.vn$<br>$m=nM=\\frac{N}{N_A}.M=\\frac{4,25.10^{15}}{6,02.10^{23}}.192\\approx 1,36.10^{−6}g=1,36\\left(\\mu g\\right)$","difficultySource":"ai"}}]},{"id":637354,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Faraday và định luật Lenz","answer":"-3,3","question":"Một khung dây khép kín đặt trong từ trường đều có độ lớn cảm ứng từ thay đổi như hình vẽ. Tỉ số độ biến thiên từ thông trong một đơn vị thời gian từ O đến M và từ M đến N bằng bao nhiêu (kết quả làm tròn đến chữ số hàng phần mười)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046235999-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\end{aligned}\\frac{e_{OM}}{e_{MN}}=\\frac{\\frac{−\\Delta \\Phi_{OM}}{\\Delta t_{OM}}}{\\frac{−\\Delta \\Phi_{MN}}{\\Delta t_{MN}}}=\\frac{\\Delta B_{OM}}{\\Delta B_{MN}}.\\frac{\\Delta t_{MN}}{\\Delta t_{OM}}=\\frac{5}{−3}.\\frac{4}{2}\\approx −3,3Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Sử dụng các thông tin sau cho Câu 5 và Câu 6: Trong một nghiên cứu về lịch sử hình thành Trái Đất, các nhà khoa học địa chất phát hiện một mẫu đá zircon. Mẫu zircon này tìm thấy chứa uranium   ${}_{92}^{238}U$ lẫn với lead   ${}_{82}^{206}Pb$ . Biết hạt nhân  ${}_{92}^{238}U$ sau chuỗi một loạt phóng xạ alpha và beta cùng loại tạo thành  ${}_{82}^{206}Pb$ với chu kì bán rã 4,50. 10<sup>9</sup> năm và mẫu đá zircon khi mới hình thành chỉ có  ${}_{92}^{238}U$ nguyên chất không chứa  ${}_{82}^{206}Pb$ . Khối lượng mol của   ${}_{92}^{238}U$ và   ${}_{82}^{206}Pb$ lần lượt là 238 g/mol và 206 g/mol.<br>Sử dụng các thông tin sau cho Câu 5 và Câu 6: Trong một nghiên cứu về lịch sử hình thành Trái Đất, các nhà khoa học địa chất phát hiện một mẫu đá zircon. Mẫu zircon này tìm thấy chứa uranium   ${}_{92}^{238}U$ lẫn với lead   ${}_{82}^{206}Pb$ . Biết hạt nhân  ${}_{92}^{238}U$ sau chuỗi một loạt phóng xạ alpha và beta cùng loại tạo thành  ${}_{82}^{206}Pb$ với chu kì bán rã 4,50. 10<sup>9</sup> năm và mẫu đá zircon khi mới hình thành chỉ có  ${}_{92}^{238}U$ nguyên chất không chứa  ${}_{82}^{206}Pb$ . Khối lượng mol của   ${}_{92}^{238}U$ và   ${}_{82}^{206}Pb$ lần lượt là 238 g/mol và 206 g/mol.","difficultySource":"ai"},"ex":[{"exam":361,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Faraday và định luật Lenz","answer":"-3,3","question":"Một khung dây khép kín đặt trong từ trường đều có độ lớn cảm ứng từ thay đổi như hình vẽ. Tỉ số độ biến thiên từ thông trong một đơn vị thời gian từ O đến M và từ M đến N bằng bao nhiêu (kết quả làm tròn đến chữ số hàng phần mười)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046235999-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\end{aligned}\\frac{e_{OM}}{e_{MN}}=\\frac{\\frac{−\\Delta \\Phi_{OM}}{\\Delta t_{OM}}}{\\frac{−\\Delta \\Phi_{MN}}{\\Delta t_{MN}}}=\\frac{\\Delta B_{OM}}{\\Delta B_{MN}}.\\frac{\\Delta t_{MN}}{\\Delta t_{OM}}=\\frac{5}{−3}.\\frac{4}{2}\\approx −3,3Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Sử dụng các thông tin sau cho Câu 5 và Câu 6: Trong một nghiên cứu về lịch sử hình thành Trái Đất, các nhà khoa học địa chất phát hiện một mẫu đá zircon. Mẫu zircon này tìm thấy chứa uranium   ${}_{92}^{238}U$ lẫn với lead   ${}_{82}^{206}Pb$ . Biết hạt nhân  ${}_{92}^{238}U$ sau chuỗi một loạt phóng xạ alpha và beta cùng loại tạo thành  ${}_{82}^{206}Pb$ với chu kì bán rã 4,50. 10<sup>9</sup> năm và mẫu đá zircon khi mới hình thành chỉ có  ${}_{92}^{238}U$ nguyên chất không chứa  ${}_{82}^{206}Pb$ . Khối lượng mol của   ${}_{92}^{238}U$ và   ${}_{82}^{206}Pb$ lần lượt là 238 g/mol và 206 g/mol.<br>Sử dụng các thông tin sau cho Câu 5 và Câu 6: Trong một nghiên cứu về lịch sử hình thành Trái Đất, các nhà khoa học địa chất phát hiện một mẫu đá zircon. Mẫu zircon này tìm thấy chứa uranium   ${}_{92}^{238}U$ lẫn với lead   ${}_{82}^{206}Pb$ . Biết hạt nhân  ${}_{92}^{238}U$ sau chuỗi một loạt phóng xạ alpha và beta cùng loại tạo thành  ${}_{82}^{206}Pb$ với chu kì bán rã 4,50. 10<sup>9</sup> năm và mẫu đá zircon khi mới hình thành chỉ có  ${}_{92}^{238}U$ nguyên chất không chứa  ${}_{82}^{206}Pb$ . Khối lượng mol của   ${}_{92}^{238}U$ và   ${}_{82}^{206}Pb$ lần lượt là 238 g/mol và 206 g/mol.","difficultySource":"ai"}}]},{"id":637547,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Đồng vị Iodine ( ${}_{53}^{131}I$ ) là chất phóng xạ β− được sử dụng trong y học để điều trị các bệnh liên quan đến tuyến giáp. Chất này có chu kỳ bán rã là 8,04 ngày. Một bệnh nhân được chỉ định sử dụng liều Iodine-131 với độ phóng xạ ban đầu là H0 = 5,20. 10<sup>8</sup> Bq. Cho rằng 85% lượng Iodine( ${}_{53}^{131}I$ ) trong liều đó sẽ tập trung tại tuyến giáp. Bệnh nhân được kiểm tra tuyến giáp lần thứ nhất ngay sau khi dùng liều và lần thứ hai sau 48 giờ. Biết khối lượng mol nguyên tử của Iodine là 131 g/mol.","difficulty":"kho","statements":[{"text":"Hạt nhân  ${}_{53}^{131}I$ phát ra hạt electron để biến đổi thành hạt nhân ${}_{54}^{131}Xe$ .","answer":true},{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$ là 0,086 s−1.","answer":false},{"text":"Khối lượng của  ${}_{53}^{131}I$ có trong liều mà bệnh nhân đã sử dụng là 0,032 μg.","answer":false},{"text":"Sau khi dùng liều 48 giờ, lượng  ${}_{53}^{131}I$ đã lắng đọng tại tuyến giáp có độ phóng xạ là 3,97. 10<sup>8</sup> Bq.","answer":false}],"explanation":"a) Phóng xạ β⁻ là phát ra electron (và phản neutrino); hạt nhân con có cùng số khối nhưng điện tích hạt nhân tăng 1 đơn vị: 131/53 I → 131/54 Xe + 0/-1 e — khớp phát biểu. → Phát biểu đúng (Đ).<br>b) Hằng số phóng xạ: λ = ln2/T, với T=8,04 ngày = 8,04.24.60.60 giây. Thay số: λ = ln2/(8,04.86400) ≈ 9,98.10⁻⁷ s⁻¹, không phải 0,086 s⁻¹ như phát biểu nêu. → Phát biểu sai (S).<br>c) Từ H0=λN0 suy ra N0=H0/λ ≈ 5,21.10¹⁴ hạt; số mol n0=N0/NA ≈ 8,65.10⁻¹⁰ mol; khối lượng m0=n0.M ≈ 0,113 μg, không phải 0,032 μg như phát biểu nêu. → Phát biểu sai (S).<br>d) Chỉ 85% lượng Iodine tập trung tại tuyến giáp; độ phóng xạ còn lại sau t=48 giờ = 2 ngày: H = 0,85.H0.2^(-t/T) = 0,85.5,2.10⁸.2^(-2/8,04) ≈ 3,72.10⁸ Bq, không phải 3,97.10⁸ Bq như phát biểu nêu. → Phát biểu sai (S).<br>a) đúng<br>${}_{53}^{131}I\\rightarrow_{54}^{131}Xe+_{−1}^0e$<br>b) sai<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{8,04.24.60.60}\\approx 9,98.10^{−7}s^{−1}$<br>c) sai<br>$\\begin{aligned}\\end{aligned}H_0=\\lambda N_0\\Rightarrow 5,2.10^8=9,98.10^{−7}.N_0\\Rightarrow N_0=5,21.10^{14}Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$n_0=\\frac{N_0}{N_A}=\\frac{5,21.10^{14}}{6,02.10^{23}}\\approx 8,65.10^{−10}mol$<br>$m_0=n_0M=8,65.10^{−10}.131\\approx 0,113.10^{−6}g=0,113\\left(\\mu g\\right)$<br>d) sai<br>$H=0,85H_0.2^{−\\frac{t}{T}}=0,85.5,2.10^8.2^{−\\frac{48}{8,04.24}}\\approx 3,72.10^8Bq$","difficultySource":"ai"},"ex":[{"exam":362,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Đồng vị Iodine ( ${}_{53}^{131}I$ ) là chất phóng xạ β− được sử dụng trong y học để điều trị các bệnh liên quan đến tuyến giáp. Chất này có chu kỳ bán rã là 8,04 ngày. Một bệnh nhân được chỉ định sử dụng liều Iodine-131 với độ phóng xạ ban đầu là H0 = 5,20. 10<sup>8</sup> Bq. Cho rằng 85% lượng Iodine( ${}_{53}^{131}I$ ) trong liều đó sẽ tập trung tại tuyến giáp. Bệnh nhân được kiểm tra tuyến giáp lần thứ nhất ngay sau khi dùng liều và lần thứ hai sau 48 giờ. Biết khối lượng mol nguyên tử của Iodine là 131 g/mol.","difficulty":"kho","statements":[{"text":"Hạt nhân  ${}_{53}^{131}I$ phát ra hạt electron để biến đổi thành hạt nhân ${}_{54}^{131}Xe$ .","answer":true},{"text":"Hằng số phóng xạ của  ${}_{53}^{131}I$ là 0,086 s−1.","answer":false},{"text":"Khối lượng của  ${}_{53}^{131}I$ có trong liều mà bệnh nhân đã sử dụng là 0,032 μg.","answer":false},{"text":"Sau khi dùng liều 48 giờ, lượng  ${}_{53}^{131}I$ đã lắng đọng tại tuyến giáp có độ phóng xạ là 3,97. 10<sup>8</sup> Bq.","answer":false}],"explanation":"a) Phóng xạ β⁻ là phát ra electron (và phản neutrino); hạt nhân con có cùng số khối nhưng điện tích hạt nhân tăng 1 đơn vị: 131/53 I → 131/54 Xe + 0/-1 e — khớp phát biểu. → Phát biểu đúng (Đ).<br>b) Hằng số phóng xạ: λ = ln2/T, với T=8,04 ngày = 8,04.24.60.60 giây. Thay số: λ = ln2/(8,04.86400) ≈ 9,98.10⁻⁷ s⁻¹, không phải 0,086 s⁻¹ như phát biểu nêu. → Phát biểu sai (S).<br>c) Từ H0=λN0 suy ra N0=H0/λ ≈ 5,21.10¹⁴ hạt; số mol n0=N0/NA ≈ 8,65.10⁻¹⁰ mol; khối lượng m0=n0.M ≈ 0,113 μg, không phải 0,032 μg như phát biểu nêu. → Phát biểu sai (S).<br>d) Chỉ 85% lượng Iodine tập trung tại tuyến giáp; độ phóng xạ còn lại sau t=48 giờ = 2 ngày: H = 0,85.H0.2^(-t/T) = 0,85.5,2.10⁸.2^(-2/8,04) ≈ 3,72.10⁸ Bq, không phải 3,97.10⁸ Bq như phát biểu nêu. → Phát biểu sai (S).<br>a) đúng<br>${}_{53}^{131}I\\rightarrow_{54}^{131}Xe+_{−1}^0e$<br>b) sai<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{8,04.24.60.60}\\approx 9,98.10^{−7}s^{−1}$<br>c) sai<br>$\\begin{aligned}\\end{aligned}H_0=\\lambda N_0\\Rightarrow 5,2.10^8=9,98.10^{−7}.N_0\\Rightarrow N_0=5,21.10^{14}Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$n_0=\\frac{N_0}{N_A}=\\frac{5,21.10^{14}}{6,02.10^{23}}\\approx 8,65.10^{−10}mol$<br>$m_0=n_0M=8,65.10^{−10}.131\\approx 0,113.10^{−6}g=0,113\\left(\\mu g\\right)$<br>d) sai<br>$H=0,85H_0.2^{−\\frac{t}{T}}=0,85.5,2.10^8.2^{−\\frac{48}{8,04.24}}\\approx 3,72.10^8Bq$","difficultySource":"ai"}}]},{"id":637548,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Một chiếc ghế nâng hạ bằng khí thông qua chuyển động lên xuống của xi lanh nối với mặt ghế. Thanh nén khí cố định trên đế bịt kín một lượng khí trong xi lanh (như hình vẽ). Bỏ qua ma sát giữa thanh nén và xi lanh. Tổng khối lượng của mặt ghế và xi lanh là 5 kg, tiết diện của thanh nén là 20 cm2 . Một học sinh nặng 50 kg ngồi lên ghế (hai chân để lơ lửng không chạm mặt sàn) thì khi ổn định ghế hạ xuống 15 cm. Coi nhiệt độ của khí trong xi lanh không đổi, áp suất khí quyển là 105 Pa và g = 10 $m/s^2$.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046243971-hinh-17.png\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Quá trình ghế hạ xuống, khí trong xi lanh nhận công.","answer":true},{"text":"Khi ghế để trống, áp suất của khí trong xi lanh là 1,25.10<sup>5</sup> Pa.","answer":true},{"text":"Khi học sinh ngồi trên ghế, áp suất của khí trong xi lanh là 3,5.10<sup>5</sup> Pa.","answer":false},{"text":"Khi ghế để trống, cột khí trong xi lanh dài là 23,3 cm.","answer":false}],"explanation":"a) Khi ghế hạ xuống, thể tích khí trong xi lanh giảm, tức ngoại lực nén khí lại nên khí trong xi lanh nhận công. → Phát biểu đúng (Đ).<br>b) Khi ghế để trống: p1 = p0 + (m_gh.g)/S = 10^5 + (5.10)/(20.10⁻⁴) = 10^5 + 0,25.10^5 = 1,25.10^5 Pa — khớp phát biểu. → Phát biểu đúng (Đ).<br>c) Khi học sinh ngồi lên ghế, tổng khối lượng đè lên là m_gh+m_hs=55kg: p2 = p0 + (m_gh+m_hs).g/S = 10^5 + (55.10)/(20.10⁻⁴) = 3,75.10^5 Pa, không phải 3,5.10^5 Pa như phát biểu nêu. → Phát biểu sai (S).<br>d) Nhiệt độ không đổi: áp dụng định luật Boyle p1.S.l1 = p2.S.l2, với l2 = l1-15. Thay số: 1,25.10^5.l1 = 3,75.10^5.(l1-15) ⇒ l1 = 22,5 cm, không phải 23,3 cm như phát biểu nêu. → Phát biểu sai (S).<br>a) đúng<br>Quá trình ghế hạ xuống, khí trong xi lanh nhận công.<br>b) đúng<br>$p_1=p_0+\\frac{m_{gh}.g}{S}=10^5+\\frac{5.10}{20.10^{−4}}=1,25.10^5Pa$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) sai<br>$\\begin{aligned}\\end{aligned}p_2=p_0+\\frac{\\left(m_{gh}+m_{hs}\\right)g}{S}=10^5+\\frac{\\left(5+50\\right).10}{20.10^{−4}}=3,75.10^5PaWebsite: thukhoadaihoc.vn$<br>d) sai<br>$pV=const\\Rightarrow p_1Sℓ_1=p_2Sℓ_2\\Rightarrow 1,25.10^5.ℓ_1=3,75.10^5\\left(ℓ_1−15\\right)\\Rightarrow ℓ_1=22,5\\left(cm\\right)$","difficultySource":"ai"},"ex":[{"exam":362,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Một chiếc ghế nâng hạ bằng khí thông qua chuyển động lên xuống của xi lanh nối với mặt ghế. Thanh nén khí cố định trên đế bịt kín một lượng khí trong xi lanh (như hình vẽ). Bỏ qua ma sát giữa thanh nén và xi lanh. Tổng khối lượng của mặt ghế và xi lanh là 5 kg, tiết diện của thanh nén là 20 cm2 . Một học sinh nặng 50 kg ngồi lên ghế (hai chân để lơ lửng không chạm mặt sàn) thì khi ổn định ghế hạ xuống 15 cm. Coi nhiệt độ của khí trong xi lanh không đổi, áp suất khí quyển là 105 Pa và g = 10 m/s2.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046243971-hinh-17.png\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Quá trình ghế hạ xuống, khí trong xi lanh nhận công.","answer":true},{"text":"Khi ghế để trống, áp suất của khí trong xi lanh là 1,25.10<sup>5</sup> Pa.","answer":true},{"text":"Khi học sinh ngồi trên ghế, áp suất của khí trong xi lanh là 3,5.10<sup>5</sup> Pa.","answer":false},{"text":"Khi ghế để trống, cột khí trong xi lanh dài là 23,3 cm.","answer":false}],"explanation":"a) Khi ghế hạ xuống, thể tích khí trong xi lanh giảm, tức ngoại lực nén khí lại nên khí trong xi lanh nhận công. → Phát biểu đúng (Đ).<br>b) Khi ghế để trống: p1 = p0 + (m_gh.g)/S = 10^5 + (5.10)/(20.10⁻⁴) = 10^5 + 0,25.10^5 = 1,25.10^5 Pa — khớp phát biểu. → Phát biểu đúng (Đ).<br>c) Khi học sinh ngồi lên ghế, tổng khối lượng đè lên là m_gh+m_hs=55kg: p2 = p0 + (m_gh+m_hs).g/S = 10^5 + (55.10)/(20.10⁻⁴) = 3,75.10^5 Pa, không phải 3,5.10^5 Pa như phát biểu nêu. → Phát biểu sai (S).<br>d) Nhiệt độ không đổi: áp dụng định luật Boyle p1.S.l1 = p2.S.l2, với l2 = l1-15. Thay số: 1,25.10^5.l1 = 3,75.10^5.(l1-15) ⇒ l1 = 22,5 cm, không phải 23,3 cm như phát biểu nêu. → Phát biểu sai (S).<br>a) đúng<br>Quá trình ghế hạ xuống, khí trong xi lanh nhận công.<br>b) đúng<br>$p_1=p_0+\\frac{m_{gh}.g}{S}=10^5+\\frac{5.10}{20.10^{−4}}=1,25.10^5Pa$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) sai<br>$\\begin{aligned}\\end{aligned}p_2=p_0+\\frac{\\left(m_{gh}+m_{hs}\\right)g}{S}=10^5+\\frac{\\left(5+50\\right).10}{20.10^{−4}}=3,75.10^5PaWebsite: thukhoadaihoc.vn$<br>d) sai<br>$pV=const\\Rightarrow p_1Sℓ_1=p_2Sℓ_2\\Rightarrow 1,25.10^5.ℓ_1=3,75.10^5\\left(ℓ_1−15\\right)\\Rightarrow ℓ_1=22,5\\left(cm\\right)$","difficultySource":"ai"}}]},{"id":637550,"nq":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"7,5","question":"Một Xi lanh kín, bên trong có một pít-tông có thể dịch chuyển dùng để chứa một lượng khí. Ban đầu, lượng khí trong xi lanh có thể tích V1 = 0,5 lít, áp suất p1 = 3 atm . Giữ cho nhiệt độ không đổi, nén pít-tông để thể tích khí giảm đến V2 = 0,2 lít, áp suất khí trong xi lanh lúc đó là p2. Giá trị của áp suất p2 bằng bao nhiêu atm? (làm tròn kết quả đến chữ số hàng phần mười)","difficulty":"de","explanation":"Nhiệt độ không đổi: áp dụng định luật Boyle: p1V1 = p2V2.<br>Thay số: 3.0,5 = p2.0,2.<br>p2 = 7,5 atm. Đáp số: 7,5.<br>$p_1V_1=p_2V_2\\Rightarrow 3.0,5=p_2.0,2\\Rightarrow p_2=7,5atm$<br>Sử dụng thông tin sau cho Câu 3 và Câu 4: Một khung dây phẳng có diện tích tiết diện 20 cm2, gồm 500 vòng dây. Trong khoảng thời gian 0,010 s, khung dây quay từ vị trí có mặt phẳng khung dây vuông góc với từ trường Trái Đất đến vị trí có mặt phẳng khung dây song song với từ trường Trái Đất lần đầu tiên. Biết từ trường Trái Đất tại vị trí đặt khung dây có độ lớn 5,0.10<sup>−5</sup>T.<br>Sử dụng thông tin sau cho Câu 3 và Câu 4: Một khung dây phẳng có diện tích tiết diện 20 cm2, gồm 500 vòng dây. Trong khoảng thời gian 0,010 s, khung dây quay từ vị trí có mặt phẳng khung dây vuông góc với từ trường Trái Đất đến vị trí có mặt phẳng khung dây song song với từ trường Trái Đất lần đầu tiên. Biết từ trường Trái Đất tại vị trí đặt khung dây có độ lớn 5,0.10<sup>−5</sup>T.","difficultySource":"ai"},"ex":[{"exam":362,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"7,5","question":"Một Xi lanh kín, bên trong có một pít-tông có thể dịch chuyển dùng để chứa một lượng khí. Ban đầu, lượng khí trong xi lanh có thể tích V1 = 0,5 lít, áp suất p1 = 3 atm . Giữ cho nhiệt độ không đổi, nén pít-tông để thể tích khí giảm đến V2 = 0,2 lít, áp suất khí trong xi lanh lúc đó là p2. Giá trị của áp suất p2 bằng bao nhiêu atm? (làm tròn kết quả đến chữ số hàng phần mười)","difficulty":"de","explanation":"Nhiệt độ không đổi: áp dụng định luật Boyle: p1V1 = p2V2.<br>Thay số: 3.0,5 = p2.0,2.<br>p2 = 7,5 atm. Đáp số: 7,5.<br>$p_1V_1=p_2V_2\\Rightarrow 3.0,5=p_2.0,2\\Rightarrow p_2=7,5atm$<br>Sử dụng thông tin sau cho Câu 3 và Câu 4: Một khung dây phẳng có diện tích tiết diện 20 cm2, gồm 500 vòng dây. Trong khoảng thời gian 0,010 s, khung dây quay từ vị trí có mặt phẳng khung dây vuông góc với từ trường Trái Đất đến vị trí có mặt phẳng khung dây song song với từ trường Trái Đất lần đầu tiên. Biết từ trường Trái Đất tại vị trí đặt khung dây có độ lớn 5,0.10<sup>−5</sup>T.<br>Sử dụng thông tin sau cho Câu 3 và Câu 4: Một khung dây phẳng có diện tích tiết diện 20 cm2, gồm 500 vòng dây. Trong khoảng thời gian 0,010 s, khung dây quay từ vị trí có mặt phẳng khung dây vuông góc với từ trường Trái Đất đến vị trí có mặt phẳng khung dây song song với từ trường Trái Đất lần đầu tiên. Biết từ trường Trái Đất tại vị trí đặt khung dây có độ lớn 5,0.10<sup>−5</sup>T.","difficultySource":"ai"}}]},{"id":638926,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một khung dây hình tròn có diện tích 50 cm2 gồm 1000 vòng dây. Khung dây được đặt trong một từ trường đều có vectơ cảm ứng từ B vuông góc với mặt phẳng khung dây và hướng từ sau ra trước (hình vẽ), có độ lớn B = 10-4T. Cho B giảm đều về 0 trong thời gian 0,1 s.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046258833-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Trong thời gian B giảm, trong khung dây xảy ra hiện tượng cảm ứng điện từ.","answer":true},{"text":"Nhìn vào mặt phẳng hình vẽ, dòng điện cảm ứng có chiều cùng chiều kim đồng hồ.","answer":false},{"text":"Độ lớn độ biến thiên từ thông qua khung dây trong 0,1 s trên là 5.10<sup>−4</sup> Wb","answer":true},{"text":"Độ lớn suất điện động cảm ứng sinh ra trong khung dây trong thời gian B giảm là 5mV.","answer":true}],"explanation":"a) đúng<br>Trong thời gian B giảm, trong khung dây xảy ra hiện tượng cảm ứng điện từ.<br>b) sai<br>B giảm  $\\Rightarrow$  Từ thông giảm  $\\Rightarrow \\vec{B}_{cu}↑↑\\vec{B}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Áp dụng quy tắc bàn tay phải được dòng điện cảm ứng có chiều ngược chiều kim đồng hồ<br>c) đúng<br>$\\left|\\Delta \\Phi \\right|=\\left|NBS\\right|=1000.10^{−4}.50.10^{−4}=5.10^{−4}Wb$<br>d) đúng<br>$e=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\frac{5.10^{−4}}{0,1}=5.10^{−3}V=5mV$","difficultySource":"ai"},"ex":[{"exam":363,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một khung dây hình tròn có diện tích 50 cm2 gồm 1000 vòng dây. Khung dây được đặt trong một từ trường đều có vectơ cảm ứng từ B vuông góc với mặt phẳng khung dây và hướng từ sau ra trước (hình vẽ), có độ lớn B = 10-4T. Cho B giảm đều về 0 trong thời gian 0,1 s.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046258833-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Trong thời gian B giảm, trong khung dây xảy ra hiện tượng cảm ứng điện từ.","answer":true},{"text":"Nhìn vào mặt phẳng hình vẽ, dòng điện cảm ứng có chiều cùng chiều kim đồng hồ.","answer":false},{"text":"Độ lớn độ biến thiên từ thông qua khung dây trong 0,1 s trên là 5.10<sup>−4</sup> Wb","answer":true},{"text":"Độ lớn suất điện động cảm ứng sinh ra trong khung dây trong thời gian B giảm là 5mV.","answer":true}],"explanation":"a) đúng<br>Trong thời gian B giảm, trong khung dây xảy ra hiện tượng cảm ứng điện từ.<br>b) sai<br>B giảm  $\\Rightarrow$  Từ thông giảm  $\\Rightarrow \\vec{B}_{cu}↑↑\\vec{B}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Áp dụng quy tắc bàn tay phải được dòng điện cảm ứng có chiều ngược chiều kim đồng hồ<br>c) đúng<br>$\\left|\\Delta \\Phi \\right|=\\left|NBS\\right|=1000.10^{−4}.50.10^{−4}=5.10^{−4}Wb$<br>d) đúng<br>$e=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\frac{5.10^{−4}}{0,1}=5.10^{−3}V=5mV$","difficultySource":"ai"}}]},{"id":638927,"nq":{"form":"bai_tap","type":"true_false","topic":"Hiện tượng phóng xạ. Chu kì bán rã","question":"Đồng vị americium ( ${}_{95}^{241}Am$ ) là chất phóng xạ α có hằng số phóng xạ 5,086.10<sup>−11</sup>s-1. Trong cảm biến báo khói ion hóa, một lượng  ${}_{95}^{241}Am$  được đặt giữa hai bản kim loại được nối với hai cực của pin. Các hạt α phóng ra làm ion hóa không khí giữa hai bản kim loại, tạo ra một dòng điện chạy giữa hai bản kim loại đó và chuông báo không kêu. Nếu có khói bay vào giữa hai bản kim loại thì cường độ dòng điện qua cảm biến giảm đi. Cảm biến sẽ phát hiện sự suy giảm dòng điện và kích hoạt chuông báo cháy. Biết khối lượng mol nguyên tử của americium là 241 g/mol và một năm có 365 ngày.","difficulty":"kho","statements":[{"text":"Hạt α là hạt nhân ${}_2^4He$ .","answer":true},{"text":"Chu kì bán rã của  ${}_{95}^{241}Am$ là 4322 năm.","answer":false},{"text":"Giả sử nguồn  ${}_{95}^{241}Am$ ban đầu có khối lượng 0,125 µg, độ phóng xạ ban đầu là 1,59.10<sup>4</sup> Bq.","answer":true},{"text":"Để đảm bảo cho cảm biến hoạt động tốt thì sau 10 năm người ta phải thay cảm biến mới. Khi đó độ phóng xạ của nguồn  ${}_{95}^{241}Am$ trong cảm biến cũ đã giảm 98,4% so với độ phóng xạ ban đầu.","answer":false}],"explanation":"a) đúng<br>Hạt α là hạt nhân ${}_2^4He$ .<br>b) sai<br>$T=\\frac{ln2}{\\lambda }=\\frac{ln2}{5,086.10^{−11}}\\approx 1,363.10^{10}\\approx 432$  năm<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>$n_0=\\frac{m}{M}=\\frac{0,125.10^{−6}}{241}\\approx 5,187.10^{−10}mol$<br>$N_0=n_0N_A=5,187.10^{−10}.6,02.10^{23}\\approx 3,12.10^{14}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$H_0=\\lambda N_0=5,086.10^{−11}.3,12.10^{14}\\approx 1,59.10^4Bq$<br>d) sai<br>$\\frac{H}{H_0}=2^{−\\frac{t}{T}}=2^{−\\frac{10}{432}}\\approx 0,984=98,4%=100%−1,6%\\Rightarrow$  Giảm 1,6%","difficultySource":"ai"},"ex":[{"exam":363,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Hiện tượng phóng xạ. Chu kì bán rã","question":"Đồng vị americium ( ${}_{95}^{241}Am$ ) là chất phóng xạ α có hằng số phóng xạ 5,086.10<sup>−11</sup>s-1. Trong cảm biến báo khói ion hóa, một lượng  ${}_{95}^{241}Am$  được đặt giữa hai bản kim loại được nối với hai cực của pin. Các hạt α phóng ra làm ion hóa không khí giữa hai bản kim loại, tạo ra một dòng điện chạy giữa hai bản kim loại đó và chuông báo không kêu. Nếu có khói bay vào giữa hai bản kim loại thì cường độ dòng điện qua cảm biến giảm đi. Cảm biến sẽ phát hiện sự suy giảm dòng điện và kích hoạt chuông báo cháy. Biết khối lượng mol nguyên tử của americium là 241 g/mol và một năm có 365 ngày.","difficulty":"kho","statements":[{"text":"Hạt α là hạt nhân ${}_2^4He$ .","answer":true},{"text":"Chu kì bán rã của  ${}_{95}^{241}Am$ là 4322 năm.","answer":false},{"text":"Giả sử nguồn  ${}_{95}^{241}Am$ ban đầu có khối lượng 0,125 µg, độ phóng xạ ban đầu là 1,59.10<sup>4</sup> Bq.","answer":true},{"text":"Để đảm bảo cho cảm biến hoạt động tốt thì sau 10 năm người ta phải thay cảm biến mới. Khi đó độ phóng xạ của nguồn  ${}_{95}^{241}Am$ trong cảm biến cũ đã giảm 98,4% so với độ phóng xạ ban đầu.","answer":false}],"explanation":"a) đúng<br>Hạt α là hạt nhân ${}_2^4He$ .<br>b) sai<br>$T=\\frac{ln2}{\\lambda }=\\frac{ln2}{5,086.10^{−11}}\\approx 1,363.10^{10}\\approx 432$  năm<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>$n_0=\\frac{m}{M}=\\frac{0,125.10^{−6}}{241}\\approx 5,187.10^{−10}mol$<br>$N_0=n_0N_A=5,187.10^{−10}.6,02.10^{23}\\approx 3,12.10^{14}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$H_0=\\lambda N_0=5,086.10^{−11}.3,12.10^{14}\\approx 1,59.10^4Bq$<br>d) sai<br>$\\frac{H}{H_0}=2^{−\\frac{t}{T}}=2^{−\\frac{10}{432}}\\approx 0,984=98,4%=100%−1,6%\\Rightarrow$  Giảm 1,6%","difficultySource":"ai"}}]},{"id":638929,"nq":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Hình vẽ bên là thí nghiệm xác định nhiệt hoá hơi riêng của nước. Dây điện trở có công suất 25 W làm nóng nước trong một nhiệt lượng kế (đã được mở nắp) và được đặt trên đĩa cân. Bỏ qua điện trở của các dây nối. Khi nước sôi, số chỉ khối lượng trên cân giảm dần theo thời gian và được ghi lại 2 giá trị trong bảng sau:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046259162-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong quá trình nước trong nhiệt lượng kế sôi thì nhiệt độ của nước tăng dần.","answer":false},{"text":"Năng lượng điện mà dây điện trở tiêu thụ trong thời gian 500 s là 12500 J.","answer":true},{"text":"Số chỉ trên cân giảm vì nước trong nhiệt lượng kế hóa hơi.","answer":true},{"text":"Xem toàn bộ năng lượng dây điện trở cung cấp cho nước trong quá trình sôi trên đều để làm bay hơi nước. Giá trị nhiệt hoá hơi riêng L của nước trong lần đo này là 2,40.10<sup>5</sup> J/kg","answer":false}],"explanation":"a) sai<br>Trong quá trình nước trong nhiệt lượng kế sôi thì nhiệt độ của nước không đổi<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>$A=Pt=25.500=12500J$<br>c) đúng<br>Số chỉ trên cân giảm vì nước trong nhiệt lượng kế hóa hơi.<br>d) sai<br>$L=\\frac{Q}{\\Delta m}=\\frac{12500}{\\left(131,36−126,05\\right).10^{−3}}\\approx 2,35.10^6\\left(J/kg\\right)$","difficultySource":"ai"},"ex":[{"exam":363,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Hình vẽ bên là thí nghiệm xác định nhiệt hoá hơi riêng của nước. Dây điện trở có công suất 25 W làm nóng nước trong một nhiệt lượng kế (đã được mở nắp) và được đặt trên đĩa cân. Bỏ qua điện trở của các dây nối. Khi nước sôi, số chỉ khối lượng trên cân giảm dần theo thời gian và được ghi lại 2 giá trị trong bảng sau:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046259162-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong quá trình nước trong nhiệt lượng kế sôi thì nhiệt độ của nước tăng dần.","answer":false},{"text":"Năng lượng điện mà dây điện trở tiêu thụ trong thời gian 500 s là 12500 J.","answer":true},{"text":"Số chỉ trên cân giảm vì nước trong nhiệt lượng kế hóa hơi.","answer":true},{"text":"Xem toàn bộ năng lượng dây điện trở cung cấp cho nước trong quá trình sôi trên đều để làm bay hơi nước. Giá trị nhiệt hoá hơi riêng L của nước trong lần đo này là 2,40.10<sup>5</sup> J/kg","answer":false}],"explanation":"a) sai<br>Trong quá trình nước trong nhiệt lượng kế sôi thì nhiệt độ của nước không đổi<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>$A=Pt=25.500=12500J$<br>c) đúng<br>Số chỉ trên cân giảm vì nước trong nhiệt lượng kế hóa hơi.<br>d) sai<br>$L=\\frac{Q}{\\Delta m}=\\frac{12500}{\\left(131,36−126,05\\right).10^{−3}}\\approx 2,35.10^6\\left(J/kg\\right)$","difficultySource":"ai"}}]},{"id":638930,"nq":{"form":"bai_tap","type":"short_answer","topic":"Động năng trung bình phân tử và nhiệt độ","answer":"273","question":"Nếu động năng tịnh tiến trung bình của mỗi phân tử khí lí tưởng trong một bình kín là 5,65.10<sup>−21</sup> J thì nhiệt độ của khí là bao nhiêu kelvin (làm tròn kết quả đến chữ số hàng đơn vị)? Biết trong hệ SI, giá trị của hằng số Boltzmann là k = 1,38.10<sup>−23</sup> J/K.","difficulty":"de","explanation":"$W_d=\\frac{3}{2}kT\\Rightarrow 5,65.10^{−21}=\\frac{3}{2}.1,38.10^{−23}T\\Rightarrow T\\approx 273K$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":363,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Động năng trung bình phân tử và nhiệt độ","answer":"273","question":"Nếu động năng tịnh tiến trung bình của mỗi phân tử khí lí tưởng trong một bình kín là 5,65.10<sup>−21</sup> J thì nhiệt độ của khí là bao nhiêu kelvin (làm tròn kết quả đến chữ số hàng đơn vị)? Biết trong hệ SI, giá trị của hằng số Boltzmann là k = 1,38.10<sup>−23</sup> J/K.","difficulty":"de","explanation":"$W_d=\\frac{3}{2}kT\\Rightarrow 5,65.10^{−21}=\\frac{3}{2}.1,38.10^{−23}T\\Rightarrow T\\approx 273K$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":638932,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"0,52","question":"Sự biến thiên nhiệt độ của một khối nước đá theo nhiệt lượng cung cấp được biểu diễn trên đồ thị ở hình bên. Biết nhiệt nóng chảy riêng của nước đá là λ = 3,3.10<sup>5</sup> J/kg. Khối lượng của khối nước đá là bao nhiêu ki-lô-gam (làm tròn kết quả đến chữ số hàng phần trăm)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046259472-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Đồ thị $t(Q)$: nước đá nóng chảy ở $0^\\circ$C nên nhiệt độ không đổi trong lúc nóng chảy; khi đã tan hết, nước nóng lên và đồ thị tăng. Trên hình, phần nóng lên bắt đầu tại $Q=170$ kJ, nên nhiệt nóng chảy toàn bộ khối đá là $Q_{nc}=170$ kJ $=1{,}7\\cdot10^5$ J.</p><p class=\"text-base leading-relaxed my-2\">Công thức nóng chảy: $Q_{nc}=m\\lambda$, nên $m=\\dfrac{Q_{nc}}{\\lambda}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow m=\\dfrac{1{,}7\\cdot10^{5}}{3{,}3\\cdot10^{5}}\\approx0{,}515$ kg, làm tròn đến hàng phần trăm là $0{,}52$ kg.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra: từ 170 kJ đến 191 kJ nước tăng $10^\\circ$C, $mc\\Delta t=0{,}515\\cdot4200\\cdot10\\approx21$ kJ, khớp. Đáp số: 0,52 kg.</p>","difficultySource":"ai"},"ex":[{"exam":363,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"0,52","question":"Sự biến thiên nhiệt độ của một khối nước đá theo nhiệt lượng cung cấp được biểu diễn trên đồ thị ở hình bên. Biết nhiệt nóng chảy riêng của nước đá là λ = 3,3.10<sup>5</sup> J/kg. Khối lượng của khối nước đá là bao nhiêu ki-lô-gam (làm tròn kết quả đến chữ số hàng phần trăm)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046259472-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$m_d=\\frac{Q_A}{\\lambda }=\\frac{170.10^3}{3,3.10^5}\\approx 0,52kg$","difficultySource":"ai"}}]},{"id":640141,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":1,"options":["1,1.10<sup>−2</sup>Wb","1, 1.10<sup>−6</sup> Wb","1, 1.10<sup>−6</sup> T.","1, 1.10<sup>−2</sup> T."],"question":"Một vòng dây phẳng giới hạn diện tích S = 64 cm2 đặt trong một từ trường đều có cảm ứng từ B = 2.10<sup>−4</sup> T. Biết vectơ đơn vị pháp tuyến của mặt phẳng vòng dây hợp với vectơ cảm ứng từ một góc α = 300. Từ thông qua vòng dây là bao nhiêu?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ thông qua diện tích S của vòng dây trong từ trường đều: $\\Phi = B S \\cos\\alpha$, trong đó $\\alpha$ là góc giữa vectơ pháp tuyến của mặt phẳng vòng dây và vectơ cảm ứng từ.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $S = 64\\ \\text{cm}^2 = 64.10^{-4}\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $\\Phi = 2.10^{-4}\\cdot 64.10^{-4}\\cdot\\cos 30^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\Phi = 128.10^{-8}\\cdot 0{,}866 \\approx 1{,}1.10^{-6}\\ \\text{Wb}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: từ thông qua vòng dây khoảng $1{,}1.10^{-6}$ Wb, đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":364,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":1,"options":["1,1.10<sup>−2</sup>Wb","1, 1.10<sup>−6</sup> Wb","1, 1.10<sup>−6</sup> T.","1, 1.10<sup>−2</sup> T."],"question":"Một vòng dây phẳng giới hạn diện tích S = 64 cm2 đặt trong một từ trường đều có cảm ứng từ B = 2.10<sup>−4</sup> T. Biết vectơ đơn vị pháp tuyến của mặt phẳng vòng dây hợp với vectơ cảm ứng từ một góc α = 300. Từ thông qua vòng dây là bao nhiêu?","difficulty":"trung-binh","explanation":"$\\Phi =BScos\\alpha =2.10^{−4}.64.10^{−4}.cos30^0\\approx 1,1.10^{−6}Wb$","difficultySource":"ai"}}]},{"id":640144,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","answer":2,"options":["7, 44.10<sup>−14</sup> m.","3, 66.10<sup>−14</sup> m.","7,44. 10<sup>−15</sup> m.","3, 66.10<sup>−15</sup> m."],"question":"Bán kính của hạt nhân  ${}_{92}^{238}U$ là","difficulty":"de","explanation":"$R=1,2.10^{−15}.A^{\\frac{1}{3}}=1,2.10^{−15}.238^{\\frac{1}{3}}\\approx 7,44.10^{−15}m$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":364,"idx":17,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","answer":2,"options":["7, 44.10<sup>−14</sup> m.","3, 66.10<sup>−14</sup> m.","7,44. 10<sup>−15</sup> m.","3, 66.10<sup>−15</sup> m."],"question":"Bán kính của hạt nhân  ${}_{92}^{238}U$ là","difficulty":"de","explanation":"$R=1,2.10^{−15}.A^{\\frac{1}{3}}=1,2.10^{−15}.238^{\\frac{1}{3}}\\approx 7,44.10^{−15}m$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":640151,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"1950","question":"Một nhà máy điện hạt nhân dùng năng lượng phân hạch của hạt nhân  23592 U với hiệu suất 30%. Trung bình mỗi hạt nhân   ${}_{92}^{235}U$ khi phân hạch tỏa ra năng lượng 200 MeV. Trong 365 ngày hoạt động, nhà máy tiêu thụ 2500 kg 23592 U nguyên chất. Cho biết số Avogadro NA = 6,02.10<sup>23</sup> mol−1, 1eV = 1,6.10<sup>−19</sup>J. Công suất phát điện của nhà máy là bao nhiêu megawatt (MW) (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"kho","explanation":"$n=\\frac{m}{M}=\\frac{2500.10^3}{235}\\approx 10638\\left(mol\\right)$<br>$N=nN_A=10638.6,02.10^{23}\\approx 6,4.10^{27}$<br>$Q=N\\Delta E=6,4.10^{27}.200.1,6.10^{−19}\\approx 2,05.10^{11}MJ$<br>$A=HQ=0,3.2,05.10^{11}=6,15.10^{10}\\left(MJ\\right)$<br>$P=\\frac{A}{t}=\\frac{6,15.10^{10}}{365.24.60.60}\\approx 1950MW$","difficultySource":"ai"},"ex":[{"exam":364,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"1950","question":"Một nhà máy điện hạt nhân dùng năng lượng phân hạch của hạt nhân  23592 U với hiệu suất 30%. Trung bình mỗi hạt nhân   ${}_{92}^{235}U$ khi phân hạch tỏa ra năng lượng 200 MeV. Trong 365 ngày hoạt động, nhà máy tiêu thụ 2500 kg 23592 U nguyên chất. Cho biết số Avogadro NA = 6,02.10<sup>23</sup> mol−1, 1eV = 1,6.10<sup>−19</sup>J. Công suất phát điện của nhà máy là bao nhiêu megawatt (MW) (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"kho","explanation":"$n=\\frac{m}{M}=\\frac{2500.10^3}{235}\\approx 10638\\left(mol\\right)$<br>$N=nN_A=10638.6,02.10^{23}\\approx 6,4.10^{27}$<br>$Q=N\\Delta E=6,4.10^{27}.200.1,6.10^{−19}\\approx 2,05.10^{11}MJ$<br>$A=HQ=0,3.2,05.10^{11}=6,15.10^{10}\\left(MJ\\right)$<br>$P=\\frac{A}{t}=\\frac{6,15.10^{10}}{365.24.60.60}\\approx 1950MW$","difficultySource":"ai"}}]},{"id":642029,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm và đơn vị đo năng lượng","answer":3,"options":["56,8.10<sup>−17</sup>J .","57.10<sup>−26</sup>J .","5,7.10<sup>−14</sup> J .","5,7.10<sup>−17</sup>J ."],"question":"Một photon có bước sóng 3,5nm , biết tốc độ ánh sáng trong chân không là c = 3.10<sup>8</sup> m/s , hằng số Planck h = 6,626.10<sup>−34</sup> J s. Năng lượng của photon đó là","difficulty":"de","explanation":"$W=\\frac{hc}{A}=\\frac{6,626.10^{−34}.3.10^8}{3,5.10^{−9}}=5,6.10^{−17}=5,7.10^{−17}\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":365,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm và đơn vị đo năng lượng","answer":3,"options":["56,8.10<sup>−17</sup>J .","57.10<sup>−26</sup>J .","5,7.10<sup>−14</sup> J .","5,7.10<sup>−17</sup>J ."],"question":"Một photon có bước sóng 3,5nm , biết tốc độ ánh sáng trong chân không là c = 3.10<sup>8</sup> m/s , hằng số Planck h = 6,626.10<sup>−34</sup> J s. Năng lượng của photon đó là","difficulty":"de","explanation":"$W=\\frac{hc}{A}=\\frac{6,626.10^{−34}.3.10^8}{3,5.10^{−9}}=5,6.10^{−17}=5,7.10^{−17}\\left(J\\right)$","difficultySource":"ai"}}]},{"id":642032,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng áp và định luật Charles","answer":0,"options":["2.10<sup>5</sup> N/m2 .","4.10<sup>5</sup> N/m2 .","8.10<sup>5</sup> N/m2 .","105 N/m2 ."],"question":"Một bình kín chứa một lượng khí Hydrogen xác định có T1 = 500K , p1 = 105 N/m2 người ta làm nóng khí đến T2 = 1000K . Coi thể tích, khối lượng khí Hydrogen không đổi. Áp suất p2 của khí Hydrogen là","difficulty":"de","explanation":"$V=const\\Rightarrow \\frac{p_1}{T_1}=\\frac{p_2}{T_2}\\Rightarrow \\frac{1.10^5}{500}=\\frac{p_2}{1000}\\Rightarrow p_2=2.10^5\\left(N/m^2\\right)$","difficultySource":"ai"},"ex":[{"exam":365,"idx":6,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng áp và định luật Charles","answer":0,"options":["2.10<sup>5</sup> N/m2 .","4.10<sup>5</sup> N/m2 .","8.10<sup>5</sup> N/m2 .","105 N/m2 ."],"question":"Một bình kín chứa một lượng khí Hydrogen xác định có T1 = 500K , p1 = 105 N/m2 người ta làm nóng khí đến T2 = 1000K . Coi thể tích, khối lượng khí Hydrogen không đổi. Áp suất p2 của khí Hydrogen là","difficulty":"de","explanation":"$V=const\\Rightarrow \\frac{p_1}{T_1}=\\frac{p_2}{T_2}\\Rightarrow \\frac{1.10^5}{500}=\\frac{p_2}{1000}\\Rightarrow p_2=2.10^5\\left(N/m^2\\right)$","difficultySource":"ai"}}]},{"id":642035,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Sóng âm: sóng siêu âm và ứng dụng (ôn tập lớp 11)","answer":0,"options":["640m .","1280m .","870m .","1450m ."],"question":"Một thiết bị phát sóng siêu âm, đặt sát mặt nước biển phát một tín hiệu xuống đáy biển theo phương thẳng đứng. Sau 0,8s kể từ lúc phát tín hiệu, thiết bị nhận được tín hiệu phản xạ từ đáy biển. Cho biết tốc độ truyền của sóng siêu âm trong nước biển bằng 1,6.10<sup>3</sup> m/s. Độ sâu của đáy biển tại nơi khảo sát là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Sóng siêu âm đi từ mặt nước xuống đáy biển rồi phản xạ ngược lên. Quãng đường tổng cộng bằng hai lần độ sâu, nên độ sâu được tính theo công thức $h = \\dfrac{v \\cdot t}{2}$, trong đó $v$ là tốc độ truyền sóng và $t$ là thời gian từ lúc phát đến lúc nhận tín hiệu phản xạ.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $v = 1{,}6\\cdot 10^3\\ \\text{m/s}$ và $t = 0{,}8\\ \\text{s}$:</p><p class=\"text-base leading-relaxed my-2\">$h = \\dfrac{1{,}6\\cdot 10^3 \\cdot 0{,}8}{2} = 640\\ \\text{m}$</p><p class=\"text-base leading-relaxed my-2\">Vậy độ sâu của đáy biển tại nơi khảo sát là $640\\ \\text{m}$. Chọn đáp án <b>A</b>.</p>","difficultySource":"ai"},"ex":[{"exam":365,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Sóng âm: sóng siêu âm và ứng dụng (ôn tập lớp 11)","answer":0,"options":["640m .","1280m .","870m .","1450m ."],"question":"Một thiết bị phát sóng siêu âm, đặt sát mặt nước biển phát một tín hiệu xuống đáy biển theo phương thẳng đứng. Sau 0,8s kể từ lúc phát tín hiệu, thiết bị nhận được tín hiệu phản xạ từ đáy biển. Cho biết tốc độ truyền của sóng siêu âm trong nước biển bằng 1,6.10<sup>3</sup> m/s. Độ sâu của đáy biển tại nơi khảo sát là","difficulty":"de","explanation":"Độ sâu:  $2d=vt\\Rightarrow d=\\frac{vt}{2}=\\frac{1,6.10^3.0,8}{2}=640m$","difficultySource":"ai"}}]},{"id":642036,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["1,1.10<sup>4</sup> J .","9,9.10<sup>3</sup>J .","9,9.10<sup>6</sup>J .","1,1.10<sup>7</sup> J ."],"question":"Biết nhiệt nóng chảy riêng của nước đá ở 00C là 3,3.10<sup>5</sup> J kg . Nhiệt lượng cần cung cấp để 30g nước đá tan chảy hoàn toàn ở 00C là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt lượng cần cung cấp để một vật nóng chảy hoàn toàn ở nhiệt độ nóng chảy được tính theo công thức:</p><p class=\"text-base leading-relaxed my-2\">$Q = \\lambda m$</p><p class=\"text-base leading-relaxed my-2\">trong đó $\\lambda$ là nhiệt nóng chảy riêng (J/kg), $m$ là khối lượng (kg).</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 30\\,\\text{g} = 0{,}03\\,\\text{kg}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $Q = 3{,}3\\cdot 10^{5}\\cdot 0{,}03 = 9900\\,\\text{J} = 9{,}9\\cdot 10^{3}\\,\\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy nhiệt lượng cần cung cấp là $9{,}9\\cdot 10^{3}\\,\\text{J}$, đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":365,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["1,1.10<sup>4</sup> J .","9,9.10<sup>3</sup>J .","9,9.10<sup>6</sup>J .","1,1.10<sup>7</sup> J ."],"question":"Biết nhiệt nóng chảy riêng của nước đá ở 00C là 3,3.10<sup>5</sup> J kg . Nhiệt lượng cần cung cấp để 30g nước đá tan chảy hoàn toàn ở 00C là","difficulty":"de","explanation":"$Q_{nc}=m\\lambda =0,03.3,3.10^5=9,9.10^3J$","difficultySource":"ai"}}]},{"id":642050,"nq":{"form":"bai_tap","type":"short_answer","topic":"Cường độ điện trường của điện tích điểm","answer":"6,4","question":"Một giọt nước hình cầu có bán kính 1,0 µm mang điện âm với độ lớn điện tích là 6,4.10<sup>−19</sup>C. Lấy g = 9,8$m/s^2$, khối lượng riêng của nước là 1,0.10<sup>3</sup> kg/m3. Cường độ điện trường (theo phương thẳng đứng) có độ lớn tối thiểu để giọt nước không rơi là x.10<sup>4</sup>V m . Tìm x (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224473658-hinh-15.png\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:141.6px;height:auto\" /><br>$m=D.V=D.\\frac{4}{3}\\pi R^3=10^3.\\frac{4}{3}.\\pi .{\\left(10^{−6}\\right)}^3=\\frac{4}{3\\pi }.10^{−12}kg$<br>Giọt dầu cân bằng:  $F_d=P\\Rightarrow q.E=mg\\Rightarrow E=\\frac{mg}{q}=\\frac{\\frac{4}{3}\\pi .10^{−12}.9,8}{6,4.10^{−19}}=x.10^4\\Rightarrow x=0,64$","difficultySource":"ai"},"ex":[{"exam":365,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Cường độ điện trường của điện tích điểm","answer":"6,4","question":"Một giọt nước hình cầu có bán kính 1,0 µm mang điện âm với độ lớn điện tích là 6,4.10<sup>−19</sup>C. Lấy g = 9,8m/s2, khối lượng riêng của nước là 1,0.10<sup>3</sup> kg/m3. Cường độ điện trường (theo phương thẳng đứng) có độ lớn tối thiểu để giọt nước không rơi là x.10<sup>4</sup>V m . Tìm x (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224473658-hinh-15.png\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:141.6px;height:auto\" /><br>$m=D.V=D.\\frac{4}{3}\\pi R^3=10^3.\\frac{4}{3}.\\pi .{\\left(10^{−6}\\right)}^3=\\frac{4}{3\\pi }.10^{−12}kg$<br>Giọt dầu cân bằng:  $F_d=P\\Rightarrow q.E=mg\\Rightarrow E=\\frac{mg}{q}=\\frac{\\frac{4}{3}\\pi .10^{−12}.9,8}{6,4.10^{−19}}=x.10^4\\Rightarrow x=0,64$","difficultySource":"ai"}}]},{"id":642760,"nq":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"2,42","question":"Một người bình thường khi thở ra, dung tích của phổi là 2,4 lít và áp suất của không khí trong phổi là 101,7.10<sup>3</sup> Pa. Biết khi hít vào, áp suất không khí trong phổi là 101,01.10<sup>3</sup> Pa. Giả thiết khối lượng không khí là không đổi, dung tích của phổi khi hít vào là bao nhiêu lít? (kết quả lấy 2 chữ số sau dấu phẩy thập phân)","difficulty":"de","explanation":"$\\begin{aligned}\\end{aligned}p_1V_1=p_2V_2\\Rightarrow 101,7.2,4=101,01.V_2Website: thukhoadaihoc.vn$<br>$\\Rightarrow V_2=2,42\\left(lit\\right)$","difficultySource":"ai"},"ex":[{"exam":366,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"2,42","question":"Một người bình thường khi thở ra, dung tích của phổi là 2,4 lít và áp suất của không khí trong phổi là 101,7.10<sup>3</sup> Pa. Biết khi hít vào, áp suất không khí trong phổi là 101,01.10<sup>3</sup> Pa. Giả thiết khối lượng không khí là không đổi, dung tích của phổi khi hít vào là bao nhiêu lít? (kết quả lấy 2 chữ số sau dấu phẩy thập phân)","difficulty":"de","explanation":"$\\begin{aligned}\\end{aligned}p_1V_1=p_2V_2\\Rightarrow 101,7.2,4=101,01.V_2Website: thukhoadaihoc.vn$<br>$\\Rightarrow V_2=2,42\\left(lit\\right)$","difficultySource":"ai"}}]},{"id":642761,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"41,9","question":"Các nhà máy điện hạt nhân thường được xây dựng cạnh hồ, sông và bờ biển vì nhà máy điện hạt nhân toả ra rất nhiều nhiệt, cần nhiều nước để làm mát và ngưng tụ hơi nước sau khi đi qua tua bin máy phát điện. Hình bên là sơ đồ hệ thống ngưng tụ hơi nước, trong 1 h đã có 1000 m³ nước biển đi qua bồn ngưng tụ. Độ chênh lệch nhiệt độ giữa nước biển đầu vào và đầu ra có giá trị ổn định là 400C. Cho nhiệt dung riêng của nước biển là 3900 (J/kg.K), khối lượng riêng của nước biển là 1030 (kg/m³), nhiệt hóa hơi riêng của nước là 2,3.10<sup>6</sup> (J/kg), nhiệt độ của hơi nước là 1000C và chỉ có 60% lượng nhiệt truyền cho nước biển là của hơi nước. Trong khoảng thời gian trên lượng hơi nước đã bị ngưng tụ là x.10<sup>3</sup> kg. Tìm x (kết quả làm tròn đến 1 chữ số sau dấu phẩy thập phân)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046296753-hinh-17.jpg\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Khối lượng nước biển:  $m=V.D$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow$   $\\left(1000.1030\\right).3900.40Q_{truyen}.60%\\Rightarrow La cua hoi nuoc=m.2,3.10^6/60%\\Rightarrow m=41,9.10^3\\left(kg\\right)$","difficultySource":"ai"},"ex":[{"exam":366,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"41,9","question":"Các nhà máy điện hạt nhân thường được xây dựng cạnh hồ, sông và bờ biển vì nhà máy điện hạt nhân toả ra rất nhiều nhiệt, cần nhiều nước để làm mát và ngưng tụ hơi nước sau khi đi qua tua bin máy phát điện. Hình bên là sơ đồ hệ thống ngưng tụ hơi nước, trong 1 h đã có 1000 m³ nước biển đi qua bồn ngưng tụ. Độ chênh lệch nhiệt độ giữa nước biển đầu vào và đầu ra có giá trị ổn định là 400C. Cho nhiệt dung riêng của nước biển là 3900 (J/kg.K), khối lượng riêng của nước biển là 1030 (kg/m³), nhiệt hóa hơi riêng của nước là 2,3.10<sup>6</sup> (J/kg), nhiệt độ của hơi nước là 1000C và chỉ có 60% lượng nhiệt truyền cho nước biển là của hơi nước. Trong khoảng thời gian trên lượng hơi nước đã bị ngưng tụ là x.10<sup>3</sup> kg. Tìm x (kết quả làm tròn đến 1 chữ số sau dấu phẩy thập phân)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046296753-hinh-17.jpg\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Khối lượng nước biển:  $m=V.D$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow$   $\\left(1000.1030\\right).3900.40Q_{truyen}.60%\\Rightarrow La cua hoi nuoc=m.2,3.10^6/60%\\Rightarrow m=41,9.10^3\\left(kg\\right)$","difficultySource":"ai"}}]},{"id":645504,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":0,"options":["11,20C","6,20C.","4,50C","8,30C"],"question":"Vào mùa hè, trong các nhà hàng, nhân viên thường cho lon bia vào thùng cách nhiệt chứa đá lạnh (còn gọi là lắc-xê) để làm lạnh bia với mục đích là phục vụ khách hàng uống bia ngon hơn. Biết nhiệt dung riêng của bia, đá lạnh, nước và vỏ lon lần lượt là 4100 J/(kg.K), 1800 J/(kg.K), 4200 J/(kg.K), và 880 J/(kg.K);  nhiệt nóng chảy riêng của đá là 3,34.10<sup>5</sup> J/kg, khối lượng của một vỏ lon bia là m = 14g<br>khối lượng riêng của nước và của bia bằng nhau và bằng ρ =1 kg/dm3. Nhiệt lượng thất thoát ra môi trường bên ngoài không đáng kể. Để làm lạnh một két bia (24 lon, mỗi lon có dung tích 330 ml) ở nhiệt độ 35 0C, nhân viên nhà hàng dùng 2 kg đá ở nhiệt độ - 50C. Nhiệt độ của bia khi hệ đạt trạng thái cân bằng nhiệt là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046308298-hinh-2.webp\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"$m_b=V_bD=24.330.10^{−3}=7,92kg$<br>$m_dc_d\\Delta t_d+m_d\\lambda +m_dc_nt=\\left(m_bc_b+m_vc_v\\right)\\Delta t$<br>$\\Rightarrow 2.1800.5+2.3,34.10^5+2.4200.t=\\left(7,92.4100+24.0,014.880\\right)\\left(35−t\\right)\\Rightarrow t\\approx 11,2^0C$","difficultySource":"ai"},"ex":[{"exam":367,"idx":6,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":0,"options":["11,20C","6,20C.","4,50C","8,30C"],"question":"Vào mùa hè, trong các nhà hàng, nhân viên thường cho lon bia vào thùng cách nhiệt chứa đá lạnh (còn gọi là lắc-xê) để làm lạnh bia với mục đích là phục vụ khách hàng uống bia ngon hơn. Biết nhiệt dung riêng của bia, đá lạnh, nước và vỏ lon lần lượt là 4100 J/(kg.K), 1800 J/(kg.K), 4200 J/(kg.K), và 880 J/(kg.K);  nhiệt nóng chảy riêng của đá là 3,34.10<sup>5</sup> J/kg, khối lượng của một vỏ lon bia là m = 14g<br>khối lượng riêng của nước và của bia bằng nhau và bằng ρ =1 kg/dm3. Nhiệt lượng thất thoát ra môi trường bên ngoài không đáng kể. Để làm lạnh một két bia (24 lon, mỗi lon có dung tích 330 ml) ở nhiệt độ 35 0C, nhân viên nhà hàng dùng 2 kg đá ở nhiệt độ - 50C. Nhiệt độ của bia khi hệ đạt trạng thái cân bằng nhiệt là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046308298-hinh-2.webp\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"$m_b=V_bD=24.330.10^{−3}=7,92kg$<br>$m_dc_d\\Delta t_d+m_d\\lambda +m_dc_nt=\\left(m_bc_b+m_vc_v\\right)\\Delta t$<br>$\\Rightarrow 2.1800.5+2.3,34.10^5+2.4200.t=\\left(7,92.4100+24.0,014.880\\right)\\left(35−t\\right)\\Rightarrow t\\approx 11,2^0C$","difficultySource":"ai"}}]},{"id":645507,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","answer":3,"options":["MeV/c2.","kg.","amu.","MeV/C."],"question":"Đơn vị nào sau đây không phải là đơn vị khối lượng nguyên tử?","difficulty":"de","explanation":"+ Đơn vị của khối lượng nguyên tử thường dùng là u, ngoài ra còn có  $\\frac{MeV}{c^2}$  và kg, amu (Vì khối lượng của nguyên tử rất nhỏ nên để biểu thị khối lượng nguyên tử người ta sử dụng đơn vị khối lượng nguyên tử, viết tắt là amu.1 amu = 1,6605 × 10<sup>−24</sup> gam)","difficultySource":"ai"},"ex":[{"exam":367,"idx":9,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Kích thước, khối lượng hạt nhân và đơn vị u","answer":3,"options":["MeV/c2.","kg.","amu.","MeV/C."],"question":"Đơn vị nào sau đây không phải là đơn vị khối lượng nguyên tử?","difficulty":"de","explanation":"+ Đơn vị của khối lượng nguyên tử thường dùng là u, ngoài ra còn có  $\\frac{MeV}{c^2}$  và kg, amu (Vì khối lượng của nguyên tử rất nhỏ nên để biểu thị khối lượng nguyên tử người ta sử dụng đơn vị khối lượng nguyên tử, viết tắt là amu.1 amu = 1,6605 × 10<sup>−24</sup> gam)","difficultySource":"ai"}}]},{"id":645517,"nq":{"form":"bai_tap","type":"true_false","topic":"Phản ứng phân hạch, phản ứng nhiệt hạch","question":"Vào năm 1927 Mark Oliphant dưới sự hướng dẫn của nhà bác học Rudefort đã dùng máy gia tốc để các hạt nhân ${}_1^2H$  bắn vào hạt nhân  ${}_1^3H$ tương tác với nhau tạo ra phản ứng hạt nhân theo phương trình  ${}_1^2H+{}_1^3H\\rightarrow {}_Z^AX+{}_0^1n$ . Mỗi phản ứng tỏa năng lượng 4 MeV.","difficulty":"kho","statements":[{"text":"Phản ứng trên là phản phản ứng tổng hợp hạt nhân.","answer":true},{"text":"Hạt nhân X có 2 proton và 2 neutron.","answer":true},{"text":"Năng lượng tỏa ra khi tổng hợp được 100g X từ phản ứng  trên bằng 1,284. 10<sup>13</sup>J.","answer":false},{"text":"Ta giả sử rằng để tổng hợp được 100g X ở trên ta dùng  ${}_1^2H$  tách được từ nước nặng D2O có trong  nước tự nhiên. Biết trong nước tự nhiên thì nước nặng chiểm 0,015% về khối lượng. Khối lượng nước tự nhiên ít nhất cần dùng bằng 1669 kg.","answer":false}],"explanation":"a) đúng<br>Phản ứng  ${}_1^2H+{}_1^3H\\rightarrow {}_Z^AX+{}_0^1n$ là phản phản ứng tổng hợp hạt nhân.<br>b) đúng<br>$\\left\\{\\begin{aligned}2+3=A+1 <br>1+1=Z+0\\end{aligned}\\right.\\Rightarrow \\left\\{\\begin{aligned}A=4 <br>Z=2\\end{aligned}\\right.\\Rightarrow N=A−Z=2$<br>c) sai<br>$n=\\frac{m}{M}=\\frac{100}{4}=25\\left(mol\\right)$<br>$N=n.N_A=25.6,02.10^{23}=1,505.10^{25}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q=N\\Delta E=1,505.10^{25}.4.1,6.10^{−13}=9,632.10^{12}J$<br>d) sai<br>$n_{D_2O}=\\frac{n}{2}=\\frac{25}{2}=12,5 mol$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$m_{D_2O}=n_{D_2O}.M_{D_2O}=12,5.\\left(2.2+16\\right)=250g$<br>$m_{nuoc}=\\frac{m_{D_2O}}{\\frac{0,015}{100}}=\\frac{250}{\\frac{0,015}{100}}\\approx 1667.10^3g=1667kg$","difficultySource":"ai"},"ex":[{"exam":367,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Phản ứng phân hạch, phản ứng nhiệt hạch","question":"Vào năm 1927 Mark Oliphant dưới sự hướng dẫn của nhà bác học Rudefort đã dùng máy gia tốc để các hạt nhân ${}_1^2H$  bắn vào hạt nhân  ${}_1^3H$ tương tác với nhau tạo ra phản ứng hạt nhân theo phương trình  ${}_1^2H+{}_1^3H\\rightarrow {}_Z^AX+{}_0^1n$ . Mỗi phản ứng tỏa năng lượng 4 MeV.","difficulty":"kho","statements":[{"text":"Phản ứng trên là phản phản ứng tổng hợp hạt nhân.","answer":true},{"text":"Hạt nhân X có 2 proton và 2 neutron.","answer":true},{"text":"Năng lượng tỏa ra khi tổng hợp được 100g X từ phản ứng  trên bằng 1,284. 10<sup>13</sup>J.","answer":false},{"text":"Ta giả sử rằng để tổng hợp được 100g X ở trên ta dùng  ${}_1^2H$  tách được từ nước nặng D2O có trong  nước tự nhiên. Biết trong nước tự nhiên thì nước nặng chiểm 0,015% về khối lượng. Khối lượng nước tự nhiên ít nhất cần dùng bằng 1669 kg.","answer":false}],"explanation":"a) đúng<br>Phản ứng  ${}_1^2H+{}_1^3H\\rightarrow {}_Z^AX+{}_0^1n$ là phản phản ứng tổng hợp hạt nhân.<br>b) đúng<br>$\\left\\{\\begin{aligned}2+3=A+1 <br>1+1=Z+0\\end{aligned}\\right.\\Rightarrow \\left\\{\\begin{aligned}A=4 <br>Z=2\\end{aligned}\\right.\\Rightarrow N=A−Z=2$<br>c) sai<br>$n=\\frac{m}{M}=\\frac{100}{4}=25\\left(mol\\right)$<br>$N=n.N_A=25.6,02.10^{23}=1,505.10^{25}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q=N\\Delta E=1,505.10^{25}.4.1,6.10^{−13}=9,632.10^{12}J$<br>d) sai<br>$n_{D_2O}=\\frac{n}{2}=\\frac{25}{2}=12,5 mol$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$m_{D_2O}=n_{D_2O}.M_{D_2O}=12,5.\\left(2.2+16\\right)=250g$<br>$m_{nuoc}=\\frac{m_{D_2O}}{\\frac{0,015}{100}}=\\frac{250}{\\frac{0,015}{100}}\\approx 1667.10^3g=1667kg$","difficultySource":"ai"}}]},{"id":647458,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông. Hiện tượng cảm ứng điện từ","answer":0,"options":["B = 60μT.","B = 56μT.","B = 50μT.","B = 62μT."],"question":"Để giám sát quá trình hô hấp của bệnh nhân, các nhân viên y tế sử dụng một đai mỏng gồm 200 vòng dây kim loại quấn liên tiếp nhau được buộc xung quanh ngực của bệnh nhân như hình bên. Khi bệnh nhân hít vào, diện tích của các vòng dây tăng lên một lượng 50 cm2. Biết từ trường Trái Đất tại vị trí đang xét được xem gần đúng là đều và có độ lớn cảm ứng từ là B, các đường sức từ hợp với mặt phẳng cuộn dây một góc 300. Giả sử thời gian để một bệnh nhân hít vào là 1,25 s, khi đó độ lớn suất điện động cảm ứng trung bình sinh ra bởi cuộn dây trong quá trình nói trên là 2,4.10<sup>−5</sup> V. Giá trị của cảm ứng từ B của từ trường Trái Đất là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046321501-hinh-1.jpg\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$e=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\frac{NB\\Delta Scos\\alpha }{\\Delta t}$<br>$\\Rightarrow 2,4.10^{−5}=\\frac{200.B.50.10^{−4}.cos\\left(90^0−30^0\\right)}{1,25}$<br>$B=6.10^{−5}T=60\\left(\\mu T\\right)$","difficultySource":"ai"},"ex":[{"exam":369,"idx":1,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông. Hiện tượng cảm ứng điện từ","answer":0,"options":["B = 60μT.","B = 56μT.","B = 50μT.","B = 62μT."],"question":"Để giám sát quá trình hô hấp của bệnh nhân, các nhân viên y tế sử dụng một đai mỏng gồm 200 vòng dây kim loại quấn liên tiếp nhau được buộc xung quanh ngực của bệnh nhân như hình bên. Khi bệnh nhân hít vào, diện tích của các vòng dây tăng lên một lượng 50 cm2. Biết từ trường Trái Đất tại vị trí đang xét được xem gần đúng là đều và có độ lớn cảm ứng từ là B, các đường sức từ hợp với mặt phẳng cuộn dây một góc 300. Giả sử thời gian để một bệnh nhân hít vào là 1,25 s, khi đó độ lớn suất điện động cảm ứng trung bình sinh ra bởi cuộn dây trong quá trình nói trên là 2,4.10<sup>−5</sup> V. Giá trị của cảm ứng từ B của từ trường Trái Đất là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046321501-hinh-1.jpg\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$e=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\frac{NB\\Delta Scos\\alpha }{\\Delta t}$<br>$\\Rightarrow 2,4.10^{−5}=\\frac{200.B.50.10^{−4}.cos\\left(90^0−30^0\\right)}{1,25}$<br>$B=6.10^{−5}T=60\\left(\\mu T\\right)$","difficultySource":"ai"}}]},{"id":647461,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Áp suất và động năng phân tử khí","answer":2,"options":["5, 42.1028.","4,01.10<sup>25</sup>.","1,14.10<sup>25</sup>.","4, 11.1025."],"question":"Một bình kín chứa khí hydrogen với thể tích 0,5 m3 và áp suất 1,013.10<sup>5</sup> Pa. Cho biết khối lượng mol của khí hydrogen là 2 g/mol, giá trị trung bình của các bình phương tốc độ các phân tử khí là 4.10<sup>6</sup> m2/s2. Số phân tử khí chứa trong bình là","difficulty":"kho","explanation":"$p=\\frac{1}{3}D\\overline{v^2}\\Rightarrow 1,013.10^5=\\frac{1}{3}.D.4.10^6\\Rightarrow D=0,075975\\left(kg/m^3\\right)$<br>$m=DV=0,075975.0,5=0,0379875kg$<br>$n=\\frac{m}{M}=\\frac{0,0379875}{2}=0,01899375\\left(mol\\right)$<br>$N=n.N_A=,01899375.6,02.10^{23}\\approx 1,14.10^{25}$","difficultySource":"ai"},"ex":[{"exam":369,"idx":4,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Áp suất và động năng phân tử khí","answer":2,"options":["5, 42.1028.","4,01.10<sup>25</sup>.","1,14.10<sup>25</sup>.","4, 11.1025."],"question":"Một bình kín chứa khí hydrogen với thể tích 0,5 m3 và áp suất 1,013.10<sup>5</sup> Pa. Cho biết khối lượng mol của khí hydrogen là 2 g/mol, giá trị trung bình của các bình phương tốc độ các phân tử khí là 4.10<sup>6</sup> m2/s2. Số phân tử khí chứa trong bình là","difficulty":"kho","explanation":"$p=\\frac{1}{3}D\\overline{v^2}\\Rightarrow 1,013.10^5=\\frac{1}{3}.D.4.10^6\\Rightarrow D=0,075975\\left(kg/m^3\\right)$<br>$m=DV=0,075975.0,5=0,0379875kg$<br>$n=\\frac{m}{M}=\\frac{0,0379875}{2}=0,01899375\\left(mol\\right)$<br>$N=n.N_A=,01899375.6,02.10^{23}\\approx 1,14.10^{25}$","difficultySource":"ai"}}]},{"id":647474,"nq":{"form":"bai_tap","type":"true_false","topic":"Tính lực từ F = BIl·sinθ","question":"Cho dòng điện có cường độ 10 A chạy qua một đoạn dây dẫn thẳng chiều dài 10 cm được đặt trong từ trường đều có cảm ứng từ B = 0,3.10<sup>−2</sup> T, đường sức từ vuông góc với dây dẫn và có chiều hướng từ trong ra ngoài như hình vẽ.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046322464-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Chiều của lực từ được xác định bằng quy tắc bàn tay trái.","answer":true},{"text":"Lực từ tác dụng lên đoạn dây dẫn mang dòng điện có chiều từ trái sang phải.","answer":false},{"text":"Lực từ tác dụng lên đoạn dây dẫn mang dòng điện có độ lớn là 3 mN.","answer":true},{"text":"Nếu đưa thêm một từ trường đều có cảm ứng từ B′ = 0,4. 10<sup>−2</sup>T vuông góc với từ trường ban đầu thì lực từ tác dụng lên đoạn dây dẫn là 5 mN.","answer":false}],"explanation":"a) đúng<br>Chiều của lực từ được xác định bằng quy tắc bàn tay trái.<br>b) sai<br>Lực từ tác dụng lên đoạn dây dẫn mang dòng điện có chiều hướng xuongs dưới<br>c) đúng<br>$F=IℓB=10.0,1.0,3.10^{−2}=3.10^{−3}N=3mM$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>Chưa kết luận dược góc giữa  $\\vec{B}$  tổng hợp và i","difficultySource":"ai"},"ex":[{"exam":369,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Tính lực từ F = BIl·sinθ","question":"Cho dòng điện có cường độ 10 A chạy qua một đoạn dây dẫn thẳng chiều dài 10 cm được đặt trong từ trường đều có cảm ứng từ B = 0,3.10<sup>−2</sup> T, đường sức từ vuông góc với dây dẫn và có chiều hướng từ trong ra ngoài như hình vẽ.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046322464-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Chiều của lực từ được xác định bằng quy tắc bàn tay trái.","answer":true},{"text":"Lực từ tác dụng lên đoạn dây dẫn mang dòng điện có chiều từ trái sang phải.","answer":false},{"text":"Lực từ tác dụng lên đoạn dây dẫn mang dòng điện có độ lớn là 3 mN.","answer":true},{"text":"Nếu đưa thêm một từ trường đều có cảm ứng từ B′ = 0,4. 10<sup>−2</sup>T vuông góc với từ trường ban đầu thì lực từ tác dụng lên đoạn dây dẫn là 5 mN.","answer":false}],"explanation":"a) đúng<br>Chiều của lực từ được xác định bằng quy tắc bàn tay trái.<br>b) sai<br>Lực từ tác dụng lên đoạn dây dẫn mang dòng điện có chiều hướng xuongs dưới<br>c) đúng<br>$F=IℓB=10.0,1.0,3.10^{−2}=3.10^{−3}N=3mM$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>Chưa kết luận dược góc giữa  $\\vec{B}$  tổng hợp và i","difficultySource":"ai"}}]},{"id":648298,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Một bình kín cổ đại chứa một chất lỏng, được cho là nước. Một nhà khảo cổ học đã yêu cầu các nhà khoa học xác định thể tích chất lỏng trong bình mà không được mở bình. Một nhà khoa học quyết định sử dụng một đồng vị sodium − $(_{11}^{24}Na)$   phóng xạ β- với chu kỳ bán rã là 14,8 giờ. Đầu tiên, nhà khoa học đã trộn một hợp chất chứa 3,0.10<sup>−10</sup>g sodium − 24 với 1500 cm³ nước. Sau đó, bơm 15 cm³ dung dịch vào bình qua lớp niêm phong và lắc nhẹ bình.","difficulty":"kho","statements":[{"text":"Nhà khoa học lắc nhẹ bình để chất phóng xạ sodium-24 lắng xuống đáy bình.","answer":false},{"text":"Hạt nhân con tạo thành của chất phóng xạ  $(_{11}^{24}Na)$  là Magnesium - 24 ( ${}_{12}^{24}Mg$ ).","answer":true},{"text":"Hằng số phóng xạ của đồng vị Sodium-24 là 1,3.10<sup>−5</sup>s-1","answer":true},{"text":"Sau khi bơm dung dịch có chất phóng xạ vào bình 3,5 giờ, nhà khoa học rút 15 cm³ hỗn hợp chất lỏng ra khỏi bình và đo độ phóng xạ của nó thì thu được kết quả là 3600 Bq. Thể tích chất lỏng có trong bình ban đầu xấp xỉ 3,46 lít.","answer":false}],"explanation":"a) sai<br>Nhà khoa học lắc nhẹ bình để chất phóng xạ sodium − 24 phân bố đều trong bình.<br>b) đúng<br>Phương trình phân rã phóng xạ:<br>${}_{11}^{24}Na\\rightarrow {}_{−1}^0e+{}_Z^AX$<br>Phương trình định luật bảo toàn số khối và điện tích cho phản ứng hạt nhân:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\left\\{\\begin{aligned}24=0+A <br>11=−1+Z\\end{aligned}\\right.\\Rightarrow \\left\\{\\begin{aligned}A=24 <br>Z=12\\end{aligned}\\right.$  Vậy  $X=_{12}^{24}Mg$<br>c) đúng<br>Hằng số phóng xạ của đồng vị sodium – 24<br>$\\lambda =\\frac{0,693}{T}=\\frac{0,693}{14,8.3600}=1,3.10^{−5}.s^{−1}$<br>d) sai<br>Độ phóng xạ ban đầu của mẫu sodium – 24<br>Độ phóng xạ ban đầu =  $=\\frac{3,0.10^{−10}}{24}.6,02.10^{23}.1,3.10^{−5}=9,87825kBq$<br>Lượng phóng xạ này được chia đều cho  $1500cm^3$ nước ⇒ độ phóng xạ ban đầu của  $15cm^3$  nước bơm vào bình là:  $H_0=\\frac{15}{1500}.97825.10^3=978250Bq$<br>Một cách tương tự, ta cũng có độ phóng xạ của  $15cm^3$  nước lấy ra trong bình sau 3,5 giờ là<br>$H=\\frac{15}{15+V}.H_02^{−\\frac{t}{T}}$<br>Với 𝑉 là thể tích của nước có sẵn trong bình (đại lượng cần xác định).<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Từ giả thiết của bài toán, ta có:<br>$\\begin{aligned}\\end{aligned}3600=\\frac{15}{15+V}.978250.2^{−\\frac{3,5}{14,8}}\\Rightarrow V=3,44\\left(ℓ\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":370,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Một bình kín cổ đại chứa một chất lỏng, được cho là nước. Một nhà khảo cổ học đã yêu cầu các nhà khoa học xác định thể tích chất lỏng trong bình mà không được mở bình. Một nhà khoa học quyết định sử dụng một đồng vị sodium − $(_{11}^{24}Na)$   phóng xạ β- với chu kỳ bán rã là 14,8 giờ. Đầu tiên, nhà khoa học đã trộn một hợp chất chứa 3,0.10<sup>−10</sup>g sodium − 24 với 1500 cm³ nước. Sau đó, bơm 15 cm³ dung dịch vào bình qua lớp niêm phong và lắc nhẹ bình.","difficulty":"kho","statements":[{"text":"Nhà khoa học lắc nhẹ bình để chất phóng xạ sodium-24 lắng xuống đáy bình.","answer":false},{"text":"Hạt nhân con tạo thành của chất phóng xạ  $(_{11}^{24}Na)$  là Magnesium - 24 ( ${}_{12}^{24}Mg$ ).","answer":true},{"text":"Hằng số phóng xạ của đồng vị Sodium-24 là 1,3.10<sup>−5</sup>s-1","answer":true},{"text":"Sau khi bơm dung dịch có chất phóng xạ vào bình 3,5 giờ, nhà khoa học rút 15 cm³ hỗn hợp chất lỏng ra khỏi bình và đo độ phóng xạ của nó thì thu được kết quả là 3600 Bq. Thể tích chất lỏng có trong bình ban đầu xấp xỉ 3,46 lít.","answer":false}],"explanation":"a) sai<br>Nhà khoa học lắc nhẹ bình để chất phóng xạ sodium − 24 phân bố đều trong bình.<br>b) đúng<br>Phương trình phân rã phóng xạ:<br>${}_{11}^{24}Na\\rightarrow {}_{−1}^0e+{}_Z^AX$<br>Phương trình định luật bảo toàn số khối và điện tích cho phản ứng hạt nhân:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\left\\{\\begin{aligned}24=0+A <br>11=−1+Z\\end{aligned}\\right.\\Rightarrow \\left\\{\\begin{aligned}A=24 <br>Z=12\\end{aligned}\\right.$  Vậy  $X=_{12}^{24}Mg$<br>c) đúng<br>Hằng số phóng xạ của đồng vị sodium – 24<br>$\\lambda =\\frac{0,693}{T}=\\frac{0,693}{14,8.3600}=1,3.10^{−5}.s^{−1}$<br>d) sai<br>Độ phóng xạ ban đầu của mẫu sodium – 24<br>Độ phóng xạ ban đầu =  $=\\frac{3,0.10^{−10}}{24}.6,02.10^{23}.1,3.10^{−5}=9,87825kBq$<br>Lượng phóng xạ này được chia đều cho  $1500cm^3$ nước ⇒ độ phóng xạ ban đầu của  $15cm^3$  nước bơm vào bình là:  $H_0=\\frac{15}{1500}.97825.10^3=978250Bq$<br>Một cách tương tự, ta cũng có độ phóng xạ của  $15cm^3$  nước lấy ra trong bình sau 3,5 giờ là<br>$H=\\frac{15}{15+V}.H_02^{−\\frac{t}{T}}$<br>Với 𝑉 là thể tích của nước có sẵn trong bình (đại lượng cần xác định).<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Từ giả thiết của bài toán, ta có:<br>$\\begin{aligned}\\end{aligned}3600=\\frac{15}{15+V}.978250.2^{−\\frac{3,5}{14,8}}\\Rightarrow V=3,44\\left(ℓ\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":650367,"nq":{"form":"bai_tap","type":"true_false","topic":"Động năng trung bình phân tử và nhiệt độ","question":"Một lượng khí lí tưởng có áp suất 2,00MPa, số phân tử khí trong 1,00 cm3 là 4,84.10<sup>20</sup>.","difficulty":"kho","statements":[{"text":"Nếu giữ nhiệt độ không đổi thì động năng tịnh tiến trung bình của phân tử khí vẫn không đổi.","answer":true},{"text":"Khi tốc độ trung bình của phân tử tăng lên gấp đôi, áp suất cũng tăng lên gấp đôi.","answer":false},{"text":"Động năng tịnh tiến trung bình của phân tử khí là 6,20.10<sup>−21</sup>J.","answer":true},{"text":"Nhiệt độ của khí là 299 K.","answer":true}],"explanation":"a) đúng<br>$W_d=\\frac{3}{2}kT$<br>b) sai<br>$p=\\frac{1}{3}D\\overline{v^2}$<br>c) đúng<br>$\\begin{aligned}\\end{aligned}\\mu =\\frac{N}{V}=\\frac{4,84.10^{20}}{10^{−6}}=4,84.10^{26}m^{−3}Website: thukhoadaihoc.vn$<br>$W_d=\\frac{3}{2}kT=\\frac{3p}{2\\mu }=\\frac{3.2.10^6}{2.4,84.10^{26}}\\approx 6,2.10^{−21}J$<br>d) đúng<br>$p=\\mu kT\\Rightarrow 2.10^6=4,84.10^{26}.1,38.10^{−23}.T\\Rightarrow T\\approx 299K$","difficultySource":"ai"},"ex":[{"exam":371,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Động năng trung bình phân tử và nhiệt độ","question":"Một lượng khí lí tưởng có áp suất 2,00MPa, số phân tử khí trong 1,00 cm3 là 4,84.10<sup>20</sup>.","difficulty":"kho","statements":[{"text":"Nếu giữ nhiệt độ không đổi thì động năng tịnh tiến trung bình của phân tử khí vẫn không đổi.","answer":true},{"text":"Khi tốc độ trung bình của phân tử tăng lên gấp đôi, áp suất cũng tăng lên gấp đôi.","answer":false},{"text":"Động năng tịnh tiến trung bình của phân tử khí là 6,20.10<sup>−21</sup>J.","answer":true},{"text":"Nhiệt độ của khí là 299 K.","answer":true}],"explanation":"a) đúng<br>$W_d=\\frac{3}{2}kT$<br>b) sai<br>$p=\\frac{1}{3}D\\overline{v^2}$<br>c) đúng<br>$\\begin{aligned}\\end{aligned}\\mu =\\frac{N}{V}=\\frac{4,84.10^{20}}{10^{−6}}=4,84.10^{26}m^{−3}Website: thukhoadaihoc.vn$<br>$W_d=\\frac{3}{2}kT=\\frac{3p}{2\\mu }=\\frac{3.2.10^6}{2.4,84.10^{26}}\\approx 6,2.10^{−21}J$<br>d) đúng<br>$p=\\mu kT\\Rightarrow 2.10^6=4,84.10^{26}.1,38.10^{−23}.T\\Rightarrow T\\approx 299K$","difficultySource":"ai"}}]},{"id":650369,"nq":{"form":"bai_tap","type":"true_false","topic":"Suất điện động do thanh dẫn chuyển động","question":"Hình bên dưới biểu diễn một thanh dẫn điện CD trượt trên hai thanh kim loại, theo chiều vuông góc với cảm ứng từ. Biết cảm ứng từ có độ lớn B = 0,40 T, CD = AB = 0,20 m. Thanh CD đang chuyển động về bên trái với vận tốc có độ lớn 0,2 m/s và có hướng như hình vẽ. Toàn bộ mạch có điện trở 2,0Ω. Các thanh kim loại không nhiễm từ, bỏ qua ma sát.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046346492-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khi thanh CD chuyển động trên thanh xuất hiện dòng điện do hiện tượng cảm ứng điện từ.","answer":true},{"text":"Suất điện động cảm ứng trong thanh CD có độ lớn là 1,6.10<sup>−3</sup> V.","answer":false},{"text":"Dòng điện xuất hiện trong mạch có chiều ACDB, nếu coi CD là nguồn điện thì D đóng vai trò cực dương.","answer":true},{"text":"Lực kéo để thanh MN chuyển động đều với tốc độ đã cho là 6,4. 10<sup>−4</sup> N.","answer":true}],"explanation":"a) đúng<br>Khi thanh CD chuyển động trên thanh xuất hiện dòng điện do hiện tượng cảm ứng điện từ.<br>b) sai<br>$e=Bℓv=0,4.0,2.0,2=0,016V$<br>c) đúng<br>Dòng điện đi vào cực âm và đi ra cực cương nguồn điện  $\\Rightarrow$  D là cực dương<br>d) đúng<br>$i=\\frac{e}{R}=\\frac{0,016}{2}=0,008A$<br>$F=iℓB=0,008.0,2.0,4=6,4.10^{−4}N$","difficultySource":"ai"},"ex":[{"exam":371,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Suất điện động do thanh dẫn chuyển động","question":"Hình bên dưới biểu diễn một thanh dẫn điện CD trượt trên hai thanh kim loại, theo chiều vuông góc với cảm ứng từ. Biết cảm ứng từ có độ lớn B = 0,40 T, CD = AB = 0,20 m. Thanh CD đang chuyển động về bên trái với vận tốc có độ lớn 0,2 m/s và có hướng như hình vẽ. Toàn bộ mạch có điện trở 2,0Ω. Các thanh kim loại không nhiễm từ, bỏ qua ma sát.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046346492-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khi thanh CD chuyển động trên thanh xuất hiện dòng điện do hiện tượng cảm ứng điện từ.","answer":true},{"text":"Suất điện động cảm ứng trong thanh CD có độ lớn là 1,6.10<sup>−3</sup> V.","answer":false},{"text":"Dòng điện xuất hiện trong mạch có chiều ACDB, nếu coi CD là nguồn điện thì D đóng vai trò cực dương.","answer":true},{"text":"Lực kéo để thanh MN chuyển động đều với tốc độ đã cho là 6,4. 10<sup>−4</sup> N.","answer":true}],"explanation":"a) đúng<br>Khi thanh CD chuyển động trên thanh xuất hiện dòng điện do hiện tượng cảm ứng điện từ.<br>b) sai<br>$e=Bℓv=0,4.0,2.0,2=0,016V$<br>c) đúng<br>Dòng điện đi vào cực âm và đi ra cực cương nguồn điện  $\\Rightarrow$  D là cực dương<br>d) đúng<br>$i=\\frac{e}{R}=\\frac{0,016}{2}=0,008A$<br>$F=iℓB=0,008.0,2.0,4=6,4.10^{−4}N$","difficultySource":"ai"}}]},{"id":651012,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":3,"options":["0,20 A","1,25 Α","0,86 A","0,62 A"],"question":"Một sợi dây dẫn đồng nhất, tiết diện ngang 1 mm2 điện trở suất ρ = 2.10<sup>−8</sup> Ω.m được uốn thành một vòng tròn kín (như hình vẽ), bán kính 25cm. Đặt vòng dây nói trên vào một từ trường đều sao cho các đường sức từ vuông góc với mặt phẳng vòng dây. Cảm ứng từ của từ trường biến thiên theo thời gian theo quy luật: B = kt, với t tính bằng đơn vị giây (s) và k = 0,1(T/s). Cường độ dòng điện cảm ứng xuất hiện trong vòng dây dẫn có độ lớn gần nhất với giá trị nào sau đây?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046357115-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"+ Điện trở:  $R=\\rho \\frac{ℓ}{S_0}=\\rho .\\frac{2\\pi R}{S_0}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>+ Từ thông:  $\\Phi =BS=t.S=k.\\pi R^2.t$<br>+  $e_c={\\Phi_{\\left(t\\right)}}^/=k.\\pi R^2$<br>+  $I_C=\\frac{e_C}{R}=\\frac{kS_0R}{2\\rho }=\\frac{0,1.10^{−6}.0,25}{2.2.10^{−8}}=0,625AWebsite: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":372,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":3,"options":["0,20 A","1,25 Α","0,86 A","0,62 A"],"question":"Một sợi dây dẫn đồng nhất, tiết diện ngang 1 mm2 điện trở suất ρ = 2.10<sup>−8</sup> Ω.m được uốn thành một vòng tròn kín (như hình vẽ), bán kính 25cm. Đặt vòng dây nói trên vào một từ trường đều sao cho các đường sức từ vuông góc với mặt phẳng vòng dây. Cảm ứng từ của từ trường biến thiên theo thời gian theo quy luật: B = kt, với t tính bằng đơn vị giây (s) và k = 0,1(T/s). Cường độ dòng điện cảm ứng xuất hiện trong vòng dây dẫn có độ lớn gần nhất với giá trị nào sau đây?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046357115-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"+ Điện trở:  $R=\\rho \\frac{ℓ}{S_0}=\\rho .\\frac{2\\pi R}{S_0}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>+ Từ thông:  $\\Phi =BS=t.S=k.\\pi R^2.t$<br>+  $e_c={\\Phi_{\\left(t\\right)}}^/=k.\\pi R^2$<br>+  $I_C=\\frac{e_C}{R}=\\frac{kS_0R}{2\\rho }=\\frac{0,1.10^{−6}.0,25}{2.2.10^{−8}}=0,625AWebsite: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":651013,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":1,"options":["7,34.1025 J.","7,34.10<sup>25</sup> MeV.","4,52.10<sup>25</sup> MeV.","4,52.1025 J."],"question":"Xét phản ứng nhiệt hạch:  ${}_1^2H+{}_1^2H\\rightarrow {}_2^4He$ có năng lượng toả ra là 3,25 MeV. Nếu quá trình nhiệt hạch sử dụng hết 150g  ${}_1^2H$ thì tổng năng lượng tỏa ra là bao nhiêu? Biết khối lượng mol của  ${}_1^2H$  là 2 g/mol.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Số hạt nhân $^2_1H$ trong $150\\ \\text{g}$: $N = \\dfrac{m}{M}N_A = \\dfrac{150}{2}\\cdot 6{,}02\\cdot 10^{23} \\approx 4{,}515\\cdot 10^{25}$.</p><p class=\"text-base leading-relaxed my-2\">Mỗi phản ứng dùng $2$ hạt nhân $^2_1H$ và toả $3{,}25\\ \\text{MeV}$, nên số phản ứng là $\\dfrac{N}{2}$.</p><p class=\"text-base leading-relaxed my-2\">$W = \\dfrac{N}{2}\\cdot 3{,}25 \\approx 7{,}34\\cdot 10^{25}\\ \\text{MeV}$.</p><p class=\"text-base leading-relaxed my-2\">Sai vì: phương án A cho đúng số $7{,}34\\cdot 10^{25}$ nhưng đơn vị J, trong khi số này tính bằng MeV ($1\\ \\text{MeV}=1{,}6\\cdot 10^{-13}\\ \\text{J}$ nên bằng khoảng $1{,}2\\cdot 10^{13}\\ \\text{J}$). Các phương án có $4{,}52\\cdot 10^{25}$ chính là số hạt nhân $N$, chưa chia $2$ để ra số phản ứng và chưa nhân với $3{,}25\\ \\text{MeV}$ nên không phải năng lượng.</p><p class=\"text-base leading-relaxed my-2\">Chọn B.</p>","difficultySource":"ai"},"ex":[{"exam":372,"idx":17,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":1,"options":["7,34.1025 J.","7,34.10<sup>25</sup> MeV.","4,52.10<sup>25</sup> MeV.","4,52.1025 J."],"question":"Xét phản ứng nhiệt hạch:  ${}_1^2H+{}_1^2H\\rightarrow {}_2^4He$ có năng lượng toả ra là 3,25 MeV. Nếu quá trình nhiệt hạch sử dụng hết 150g  ${}_1^2H$ thì tổng năng lượng tỏa ra là bao nhiêu? Biết khối lượng mol của  ${}_1^2H$  là 2 g/mol.","difficulty":"trung-binh","explanation":"+ Số hạt nhân  ${}_1^2H:N=\\frac{m}{M}.N_A=\\frac{150}{2}.6,02.10^{23}=4,515.10^{25}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>+ 1 phản ứng cần 2 hạt nhân  ${}_1^2H$ , đồng thời tỏa ra  $\\Delta E=3,25MeV$<br>$\\Rightarrow$  Từ N hạt nhân  ${}_1^2H$  thì tỏa ra  $W=\\frac{N}{2}.\\Delta E=7,34.10^{25}MeV$","difficultySource":"ai"}}]},{"id":651014,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một quạt hơi nước là thiết bị hoạt động dựa trên nguyên tắc bốc hơi nước tự nhiên để làm mát không khí. Lúc vận hành, cánh quạt quay tròn sẽ khởi tạo lực hút không khí đi vào máy qua 3 cửa hút gió. Ngay ở cửa lấy khí có bố trí tấm làm mát. Tấm làm mát này được thiết kế với hình thức như rất nhiều đường ống dẫn khí với mặt cắt như tổ ong. Tấm làm mát cũng có thể dẫn và thấm đẫm nước. Khi không khí nóng bên ngoài luồn qua tấm làm mát đã có nước sẽ tạo ra hiện tượng bay hơi nước hoàn toàn tự nhiên ở trong các ống dẫn không khí. Nước lúc này đang từ thể lỏng sẽ chuyển đổi thành thể<br>khí. Khi nước bay hơi, nhiệt lượng được lấy từ không khí xung quanh, làm giảm nhiệt độ không khí.  Người ta dùng quạt hơi nước để làm mát một phòng kín, kích thước 4m×5m×4m. Giả sử toàn bộ nhiệt lượng lấy từ không khí để làm bay hơi nước và nhiệt độ của nước luôn là 350C. Biết lượng nước bay hơi từ quạt trong mỗi giây là 0,7 g ; nhiệt hóa hơi của nước ở nhiệt độ 350C là 2,26.10<sup>6</sup> J/kg; khối lượng riêng của không khí trong phòng là 1,2 kg/m3 và nhiệt dung riêng của không khí là 1005 J/(kg.K).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046357276-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Khối lượng nước trong quạt bị bay hơi trong thời gian 1 phút là 0,042 kg.","answer":true},{"text":"Nhiệt lượng cần thiết lấy từ không khí để làm bay hơi 0,5 kg nước là 6.10<sup>5</sup> J.","answer":false},{"text":"Khối lượng không khí có trong phòng là 65 kg.","answer":false},{"text":"Nếu sự thay đổi nhiệt độ không khí chỉ do sự hấp thụ nhiệt của nước khi bay hơi thì sau 10 phút mở quạt, nhiệt độ không khí trong phòng giảm đi 9,8°C (làm tròn kết quả đến chữ số hàng phần mười)","answer":false}],"explanation":"a) đúng<br>Trong 1 phút:  $m=0,7.60=42g=0,042kg$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>$Q=mL=0,5.2,26.10^6=1,13.10^6J$<br>c) sai<br>$m_k=D.V=1,2.\\left(4.5.4\\right)=96kg$<br>d) sai<br>$\\begin{aligned}\\end{aligned}Q=m_k.c_k.\\Delta T\\Rightarrow \\Delta T=\\frac{Q}{m_k.c_k}=\\frac{1,13.10^6}{96.1005}=11,7^0CWebsite: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":372,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một quạt hơi nước là thiết bị hoạt động dựa trên nguyên tắc bốc hơi nước tự nhiên để làm mát không khí. Lúc vận hành, cánh quạt quay tròn sẽ khởi tạo lực hút không khí đi vào máy qua 3 cửa hút gió. Ngay ở cửa lấy khí có bố trí tấm làm mát. Tấm làm mát này được thiết kế với hình thức như rất nhiều đường ống dẫn khí với mặt cắt như tổ ong. Tấm làm mát cũng có thể dẫn và thấm đẫm nước. Khi không khí nóng bên ngoài luồn qua tấm làm mát đã có nước sẽ tạo ra hiện tượng bay hơi nước hoàn toàn tự nhiên ở trong các ống dẫn không khí. Nước lúc này đang từ thể lỏng sẽ chuyển đổi thành thể<br>khí. Khi nước bay hơi, nhiệt lượng được lấy từ không khí xung quanh, làm giảm nhiệt độ không khí.  Người ta dùng quạt hơi nước để làm mát một phòng kín, kích thước 4m×5m×4m. Giả sử toàn bộ nhiệt lượng lấy từ không khí để làm bay hơi nước và nhiệt độ của nước luôn là 350C. Biết lượng nước bay hơi từ quạt trong mỗi giây là 0,7 g ; nhiệt hóa hơi của nước ở nhiệt độ 350C là 2,26.10<sup>6</sup> J/kg; khối lượng riêng của không khí trong phòng là 1,2 kg/m3 và nhiệt dung riêng của không khí là 1005 J/(kg.K).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046357276-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Khối lượng nước trong quạt bị bay hơi trong thời gian 1 phút là 0,042 kg.","answer":true},{"text":"Nhiệt lượng cần thiết lấy từ không khí để làm bay hơi 0,5 kg nước là 6.10<sup>5</sup> J.","answer":false},{"text":"Khối lượng không khí có trong phòng là 65 kg.","answer":false},{"text":"Nếu sự thay đổi nhiệt độ không khí chỉ do sự hấp thụ nhiệt của nước khi bay hơi thì sau 10 phút mở quạt, nhiệt độ không khí trong phòng giảm đi 9,8°C (làm tròn kết quả đến chữ số hàng phần mười)","answer":false}],"explanation":"a) đúng<br>Trong 1 phút:  $m=0,7.60=42g=0,042kg$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>$Q=mL=0,5.2,26.10^6=1,13.10^6J$<br>c) sai<br>$m_k=D.V=1,2.\\left(4.5.4\\right)=96kg$<br>d) sai<br>$\\begin{aligned}\\end{aligned}Q=m_k.c_k.\\Delta T\\Rightarrow \\Delta T=\\frac{Q}{m_k.c_k}=\\frac{1,13.10^6}{96.1005}=11,7^0CWebsite: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":651023,"nq":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"5,15","question":"Trong việc điều trị bệnh ung thư bằng phương pháp xạ trị hiện nay, người ta thường sử dụng máy gia tốc hạt trong việc tạo ra các hạt mang năng lượng cao để bắn phá các tế bào ung thư. Tuy nhiên, trước khi máy gia tốc hạt ra đời thì việc điều trị ung thư trong các bệnh viện trước đây lại sử dụng một nguồn phát ra tia gamma như đồng vị phóng xạ  ${}_{27}^{60}Co$  có chu kì bán rã là 5,27 năm (mỗi năm xem như có 365 ngày). Các tia gamma phát ra từ quá trình phóng xạ của  ${}_{27}^{60}Co$  được sử dụng để tiêu diệt tế bào ung thư. Số lượng hạt nhân  ${}_{27}^{60}Co$ chứa trong một nguồn phóng xạ có hoạt độ phóng xạ là 5800 Ci (1 Ci = 3,7.10<sup>10</sup> Bq) tại bệnh viện là x.10<sup>22</sup> hạt. Tìm giá trị của x (làm tròn kết quả đến chữ số hàng phần trăm).","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\end{aligned}N=\\frac{H}{\\lambda }=\\frac{H.T}{ln2}=\\frac{5800.3,7.10^{10}.5,27.365.86400}{ln2}=x.10^{22}\\Rightarrow x=5,15Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":372,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"5,15","question":"Trong việc điều trị bệnh ung thư bằng phương pháp xạ trị hiện nay, người ta thường sử dụng máy gia tốc hạt trong việc tạo ra các hạt mang năng lượng cao để bắn phá các tế bào ung thư. Tuy nhiên, trước khi máy gia tốc hạt ra đời thì việc điều trị ung thư trong các bệnh viện trước đây lại sử dụng một nguồn phát ra tia gamma như đồng vị phóng xạ  ${}_{27}^{60}Co$  có chu kì bán rã là 5,27 năm (mỗi năm xem như có 365 ngày). Các tia gamma phát ra từ quá trình phóng xạ của  ${}_{27}^{60}Co$  được sử dụng để tiêu diệt tế bào ung thư. Số lượng hạt nhân  ${}_{27}^{60}Co$ chứa trong một nguồn phóng xạ có hoạt độ phóng xạ là 5800 Ci (1 Ci = 3,7.10<sup>10</sup> Bq) tại bệnh viện là x.10<sup>22</sup> hạt. Tìm giá trị của x (làm tròn kết quả đến chữ số hàng phần trăm).","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\end{aligned}N=\\frac{H}{\\lambda }=\\frac{H.T}{ln2}=\\frac{5800.3,7.10^{10}.5,27.365.86400}{ln2}=x.10^{22}\\Rightarrow x=5,15Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":651896,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật phóng xạ và chu kì bán rã","answer":3,"options":["9, 59.1021.","1, 71.1020.","1, 71.1021.","9, 59.1020."],"question":"Một mẫu phóng xạ Radon ( ${}_{86}^{222}Rn$ ), ban đầu có khối lượng 1 gam. Biết chu kì bán rã của  ${}_{86}^{222}Rn$ là T = 3,8 ngày và lấy NA = 6,02.10<sup>23</sup> mol−1. Sau khoảng thời gian 5,7 ngày số nguyên tử  ${}_{86}^{222}Rn$ còn lại có giá trị xấp xỉ là","difficulty":"trung-binh","explanation":"Công thức: N = N0·2^(−t/T), với N0 = (m0/A)·NA.<br>Thay số: N0 = (1/222)·6,02.10^23 ≈ 2,712.10^21 hạt; N = 2,712.10^21 · 2^(−5,7/3,8) = 2,712.10^21 · 2^(−1,5).<br>Kết quả: N ≈ 9,59.10^20 hạt. Đáp số: chọn D.<br>$n=\\frac{m}{M}=\\frac{1}{222}mol$<br>$N_0=nN_A=\\frac{1}{22}.6,02.10^{23}\\approx 2,712.10^{21}$<br>$N=N_0.2^{−\\frac{t}{T}}=2,712.10^{21}.2^{−\\frac{5,7}{3,8}}\\approx 9,59.10^{20}$","difficultySource":"ai"},"ex":[{"exam":373,"idx":0,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật phóng xạ và chu kì bán rã","answer":3,"options":["9, 59.1021.","1, 71.1020.","1, 71.1021.","9, 59.1020."],"question":"Một mẫu phóng xạ Radon ( ${}_{86}^{222}Rn$ ), ban đầu có khối lượng 1 gam. Biết chu kì bán rã của  ${}_{86}^{222}Rn$ là T = 3,8 ngày và lấy NA = 6,02.10<sup>23</sup> mol−1. Sau khoảng thời gian 5,7 ngày số nguyên tử  ${}_{86}^{222}Rn$ còn lại có giá trị xấp xỉ là","difficulty":"trung-binh","explanation":"Công thức: N = N0·2^(−t/T), với N0 = (m0/A)·NA.<br>Thay số: N0 = (1/222)·6,02.10^23 ≈ 2,712.10^21 hạt; N = 2,712.10^21 · 2^(−5,7/3,8) = 2,712.10^21 · 2^(−1,5).<br>Kết quả: N ≈ 9,59.10^20 hạt. Đáp số: chọn D.<br>$n=\\frac{m}{M}=\\frac{1}{222}mol$<br>$N_0=nN_A=\\frac{1}{22}.6,02.10^{23}\\approx 2,712.10^{21}$<br>$N=N_0.2^{−\\frac{t}{T}}=2,712.10^{21}.2^{−\\frac{5,7}{3,8}}\\approx 9,59.10^{20}$","difficultySource":"ai"}}]},{"id":651905,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":1,"options":["2,15.10<sup>23</sup>.","1.37.1026.","1, 37.1023.","2, 15.1026."],"question":"Một lượng khí CO2 trong bình kín có khối lượng là 10 kg. Biết 1 mol khí có NA = 6, 02.1023 phân tử. Khối lượng mol của Carbon là 12 g/mol và của Oxygen là 16 g/mol. Số phân tử khí có trong bình là","difficulty":"trung-binh","explanation":"Công thức: n = m/M (M là khối lượng mol phân tử); N = n·NA.<br>M(CO2) = 12 + 2·16 = 44 g/mol; n = 10000 g / 44 g/mol ≈ 227,27 mol; N = 227,27·6,02.10^23.<br>Kết quả: N ≈ 1,37.10^26 phân tử → chọn B.<br>$n=\\frac{m}{M}=\\frac{10.10^3}{12+16.2}=\\frac{2500}{11}mol$<br>$N=nN_A=\\frac{2500}{11}.6,02.10^{23}\\approx 1,37.10^{26}$","difficultySource":"ai"},"ex":[{"exam":373,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Mol, số Avogadro và lượng chất khí","answer":1,"options":["2,15.10<sup>23</sup>.","1.37.1026.","1, 37.1023.","2, 15.1026."],"question":"Một lượng khí CO2 trong bình kín có khối lượng là 10 kg. Biết 1 mol khí có NA = 6, 02.1023 phân tử. Khối lượng mol của Carbon là 12 g/mol và của Oxygen là 16 g/mol. Số phân tử khí có trong bình là","difficulty":"trung-binh","explanation":"Công thức: n = m/M (M là khối lượng mol phân tử); N = n·NA.<br>M(CO2) = 12 + 2·16 = 44 g/mol; n = 10000 g / 44 g/mol ≈ 227,27 mol; N = 227,27·6,02.10^23.<br>Kết quả: N ≈ 1,37.10^26 phân tử → chọn B.<br>$n=\\frac{m}{M}=\\frac{10.10^3}{12+16.2}=\\frac{2500}{11}mol$<br>$N=nN_A=\\frac{2500}{11}.6,02.10^{23}\\approx 1,37.10^{26}$","difficultySource":"ai"}}]},{"id":651906,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Lực từ. Cảm ứng từ","answer":0,"options":["Lực đẩy có đọ lớn 8.10<sup>−7</sup> N.","Lực hút có độ lớn 4.10<sup>−6</sup> N.","Lực đẩy có độ lớn 4.10<sup>−6</sup> N.","Lực hút có độ lớn 8.10<sup>−7</sup> N."],"question":"Hai dây dẫn thẳng, dài song song và cách nhau 10 cm trong chân không, dòng điện trong hai dây dẫn ngược chiều và có cường độ I1 = I2 = 2A. Lực từ tác dụng lên 10 cm chiều dài mỗi dây là","difficulty":"de","explanation":"Công thức lực từ giữa hai dây song song: F = 2.10^−7·(I1·I2/d)·L.<br>Thay số: F = 2.10^−7·(2·2/0,1)·0,1 = 2.10^−7·4 = 8.10^−7 N; hai dòng ngược chiều nên lực là lực đẩy.<br>Kết quả: lực đẩy 8.10^−7 N → chọn A.<br>$F=2.10^{−7}.\\frac{I_1I_2}{r}.ℓ=2.10^{−7}.\\frac{2.2}{0,1}.0,1=8.10^{−7}N$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":373,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Lực từ. Cảm ứng từ","answer":0,"options":["Lực đẩy có đọ lớn 8.10<sup>−7</sup> N.","Lực hút có độ lớn 4.10<sup>−6</sup> N.","Lực đẩy có độ lớn 4.10<sup>−6</sup> N.","Lực hút có độ lớn 8.10<sup>−7</sup> N."],"question":"Hai dây dẫn thẳng, dài song song và cách nhau 10 cm trong chân không, dòng điện trong hai dây dẫn ngược chiều và có cường độ I1 = I2 = 2A. Lực từ tác dụng lên 10 cm chiều dài mỗi dây là","difficulty":"de","explanation":"Công thức lực từ giữa hai dây song song: F = 2.10^−7·(I1·I2/d)·L.<br>Thay số: F = 2.10^−7·(2·2/0,1)·0,1 = 2.10^−7·4 = 8.10^−7 N; hai dòng ngược chiều nên lực là lực đẩy.<br>Kết quả: lực đẩy 8.10^−7 N → chọn A.<br>$F=2.10^{−7}.\\frac{I_1I_2}{r}.ℓ=2.10^{−7}.\\frac{2.2}{0,1}.0,1=8.10^{−7}N$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":651915,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một khung dây dẫn kín hình vuông có cạnh dài 10 cm gồm 500 vòng được đặt trong từ trường có cảm ứng từ thay đổi được, vecto cảm ứng từ ⃗B⃗  trùng với vecto pháp tuyến ⃗n  của mặt phẳng khung dây. Điện trở suất và tiết diện của dây kim loại có giá trị lần lượt là 2.10<sup>−8</sup>Ω m và 0,4 mm2. Cảm ứng từ biến thiên theo thời gian có đồ thị như hình vẽ dưới đây.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046366343-hinh-2.png\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong khoảng thời gian từ 0 đến 1 s, từ thông qua khung dây kín sẽ tăng đều.","answer":false},{"text":"Suất điện động cảm ứng trong khung dây kín trong khoảng thời gian từ 0 đến 1 s có độ lớn 1,5 V.","answer":true},{"text":"Điện trở của khung dây có độ lớn là 20Ω.","answer":false},{"text":"Công suất tỏa nhiệt sinh ra trong khung dây có giá trị là 225 mW.","answer":true}],"explanation":"Công thức: suất điện động cảm ứng e = N|ΔΦ/Δt| = N·S·|ΔB|/Δt; điện trở dây R = ρL/A (L: tổng chiều dài dây, A: tiết diện dây); công suất tỏa nhiệt P = e²/R.<br>Từ đồ thị: B giảm đều từ 0,5 T (t=0) xuống 0,2 T (t=1s) nên từ thông Φ=B·S giảm đều, không tăng (a sai). S = 0,1² = 0,01 m²; e = 500×0,01×(0,5−0,2)/1 = 1,5 V (b đúng).<br>Chiều dài dây L = N×chu vi 1 vòng = 500×4×0,1 = 200 m; R = ρL/A = 2.10⁻⁸×200/(0,4.10⁻⁶) = 10 Ω, không phải 20 Ω (c sai). P = e²/R = 1,5²/10 = 0,225 W = 225 mW (d đúng). Kết quả: a) S, b) Đ, c) S, d) Đ.<br>a) sai<br>Từ thông giảm<br>b) đúng<br>$e=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\left|\\frac{N\\Delta BS}{\\Delta t}\\right|=\\frac{500.\\left(0,5−0,2\\right).0,1^2}{1}=1,5V$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) sai<br>$R=\\frac{\\rho ℓ}{S}=\\frac{2.10^{−8}.500.4.0,1}{0,4.10^{−6}}=10\\Omega$<br>d) đúng<br>$\\begin{aligned}\\end{aligned}p=\\frac{e^2}{R}=\\frac{1,5^2}{10}=0,225W=225mWWebsite: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":373,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một khung dây dẫn kín hình vuông có cạnh dài 10 cm gồm 500 vòng được đặt trong từ trường có cảm ứng từ thay đổi được, vecto cảm ứng từ ⃗B⃗  trùng với vecto pháp tuyến ⃗n  của mặt phẳng khung dây. Điện trở suất và tiết diện của dây kim loại có giá trị lần lượt là 2.10<sup>−8</sup>Ω m và 0,4 mm2. Cảm ứng từ biến thiên theo thời gian có đồ thị như hình vẽ dưới đây.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046366343-hinh-2.png\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong khoảng thời gian từ 0 đến 1 s, từ thông qua khung dây kín sẽ tăng đều.","answer":false},{"text":"Suất điện động cảm ứng trong khung dây kín trong khoảng thời gian từ 0 đến 1 s có độ lớn 1,5 V.","answer":true},{"text":"Điện trở của khung dây có độ lớn là 20Ω.","answer":false},{"text":"Công suất tỏa nhiệt sinh ra trong khung dây có giá trị là 225 mW.","answer":true}],"explanation":"Công thức: suất điện động cảm ứng e = N|ΔΦ/Δt| = N·S·|ΔB|/Δt; điện trở dây R = ρL/A (L: tổng chiều dài dây, A: tiết diện dây); công suất tỏa nhiệt P = e²/R.<br>Từ đồ thị: B giảm đều từ 0,5 T (t=0) xuống 0,2 T (t=1s) nên từ thông Φ=B·S giảm đều, không tăng (a sai). S = 0,1² = 0,01 m²; e = 500×0,01×(0,5−0,2)/1 = 1,5 V (b đúng).<br>Chiều dài dây L = N×chu vi 1 vòng = 500×4×0,1 = 200 m; R = ρL/A = 2.10⁻⁸×200/(0,4.10⁻⁶) = 10 Ω, không phải 20 Ω (c sai). P = e²/R = 1,5²/10 = 0,225 W = 225 mW (d đúng). Kết quả: a) S, b) Đ, c) S, d) Đ.<br>a) sai<br>Từ thông giảm<br>b) đúng<br>$e=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\left|\\frac{N\\Delta BS}{\\Delta t}\\right|=\\frac{500.\\left(0,5−0,2\\right).0,1^2}{1}=1,5V$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) sai<br>$R=\\frac{\\rho ℓ}{S}=\\frac{2.10^{−8}.500.4.0,1}{0,4.10^{−6}}=10\\Omega$<br>d) đúng<br>$\\begin{aligned}\\end{aligned}p=\\frac{e^2}{R}=\\frac{1,5^2}{10}=0,225W=225mWWebsite: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":651917,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Một chiếc ghế nâng hạ bằng khí (như hình vẽ dưới đây) thông qua chuyển động lên xuống của xi lanh nối với mặt ghế. Thanh nén khí cố định trên để bịt kín một lượng khí lí tưởng trong xi lanh. Bỏ qua ma sát giữa thanh nén và xi lanh. Tổng khối lượng của mặt ghế và xi lanh là 6 kg, tiết diện của thanh nén là 30cm2. Một học sinh nặng 54 kg ngồi lên ghế (hai chân để lơ lửng không chạm mặt sàn), khi ổn định ghế hạ xuống 12 cm so với lúc đầu. Coi nhiệt độ của khí trong xi lanh không đổi, áp suất khí quyển là 105 Pa, lấy g = 10 $m/s^2$.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046366565-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Khi ghế để trống, áp suất của khí trong xi lanh bằng áp suất khí quyển.","answer":false},{"text":"Khi học sinh ngồi trên ghế, áp suất của khí trong xi lanh là 2.10<sup>5</sup> Pa.","answer":false},{"text":"Khi ghế để trống, cột khí trong xi lanh dài 20 cm.","answer":true},{"text":"Quá trình ghế hạ xuống, khí trong xi lanh nhận công.","answer":true}],"explanation":"Công thức: cân bằng lực trên cụm ghế + xi lanh khối lượng M treo trên khí nén: p_khí·S = p_khí quyển·S + Mg → p_khí = p0 + Mg/S. Định luật Boyle (đẳng nhiệt): p1L1 = p2L2.<br>a) Ghế trống (M=6kg): p_khí = 10^5 + 6×10/(3.10⁻³) = 10^5 + 2.10^4 = 1,2.10^5 Pa ≠ 10^5 Pa → sai. b) Có học sinh (M=60kg): p_khí' = 10^5 + 60×10/(3.10⁻³) = 10^5 + 2.10^5 = 3.10^5 Pa ≠ 2.10^5 Pa → sai.<br>c) Gọi L là chiều dài cột khí lúc đầu: 1,2.10^5·L = 3.10^5·(L−0,12) → 1,2L = 3L−0,36 → L = 0,36/1,8 = 0,2 m = 20 cm → đúng. d) Khi ghế hạ xuống, thể tích khí giảm (bị nén) nên ngoại lực thực hiện công dương lên khí → khí nhận công → đúng. Kết quả: a) S, b) S, c) Đ, d) Đ.<br>a) sai<br>$p_1=p_0+\\frac{m_{gh}g}{S}=10^5+\\frac{6.10}{30.10^{−4}}=1,2.10^5Pa$<br>b) sai<br>$p_2=p_0+\\frac{\\left(m_{hs}+m_{gh}\\right)}{S}=10^5+\\frac{\\left(54+6\\right).10}{30.10^{−4}}=3.10^5Pa$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>$p_1V_1=p_2V_2\\Rightarrow p_1Sℓ_1=p_2Sℓ_2$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow 1,2.10^5.ℓ_1=3.10^5.\\left(ℓ_1−12\\right)\\Rightarrow ℓ_1=20cmWebsite: thukhoadaihoc.vn$<br>Thể tích giảm  $\\Rightarrow$  Khí nhận công<br>d) đúng","difficultySource":"ai"},"ex":[{"exam":373,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Boyle. Định luật Charles","question":"Một chiếc ghế nâng hạ bằng khí (như hình vẽ dưới đây) thông qua chuyển động lên xuống của xi lanh nối với mặt ghế. Thanh nén khí cố định trên để bịt kín một lượng khí lí tưởng trong xi lanh. Bỏ qua ma sát giữa thanh nén và xi lanh. Tổng khối lượng của mặt ghế và xi lanh là 6 kg, tiết diện của thanh nén là 30cm2. Một học sinh nặng 54 kg ngồi lên ghế (hai chân để lơ lửng không chạm mặt sàn), khi ổn định ghế hạ xuống 12 cm so với lúc đầu. Coi nhiệt độ của khí trong xi lanh không đổi, áp suất khí quyển là 105 Pa, lấy g = 10 m/s2.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046366565-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Khi ghế để trống, áp suất của khí trong xi lanh bằng áp suất khí quyển.","answer":false},{"text":"Khi học sinh ngồi trên ghế, áp suất của khí trong xi lanh là 2.10<sup>5</sup> Pa.","answer":false},{"text":"Khi ghế để trống, cột khí trong xi lanh dài 20 cm.","answer":true},{"text":"Quá trình ghế hạ xuống, khí trong xi lanh nhận công.","answer":true}],"explanation":"Công thức: cân bằng lực trên cụm ghế + xi lanh khối lượng M treo trên khí nén: p_khí·S = p_khí quyển·S + Mg → p_khí = p0 + Mg/S. Định luật Boyle (đẳng nhiệt): p1L1 = p2L2.<br>a) Ghế trống (M=6kg): p_khí = 10^5 + 6×10/(3.10⁻³) = 10^5 + 2.10^4 = 1,2.10^5 Pa ≠ 10^5 Pa → sai. b) Có học sinh (M=60kg): p_khí' = 10^5 + 60×10/(3.10⁻³) = 10^5 + 2.10^5 = 3.10^5 Pa ≠ 2.10^5 Pa → sai.<br>c) Gọi L là chiều dài cột khí lúc đầu: 1,2.10^5·L = 3.10^5·(L−0,12) → 1,2L = 3L−0,36 → L = 0,36/1,8 = 0,2 m = 20 cm → đúng. d) Khi ghế hạ xuống, thể tích khí giảm (bị nén) nên ngoại lực thực hiện công dương lên khí → khí nhận công → đúng. Kết quả: a) S, b) S, c) Đ, d) Đ.<br>a) sai<br>$p_1=p_0+\\frac{m_{gh}g}{S}=10^5+\\frac{6.10}{30.10^{−4}}=1,2.10^5Pa$<br>b) sai<br>$p_2=p_0+\\frac{\\left(m_{hs}+m_{gh}\\right)}{S}=10^5+\\frac{\\left(54+6\\right).10}{30.10^{−4}}=3.10^5Pa$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>$p_1V_1=p_2V_2\\Rightarrow p_1Sℓ_1=p_2Sℓ_2$<br>$\\begin{aligned}\\end{aligned}\\Rightarrow 1,2.10^5.ℓ_1=3.10^5.\\left(ℓ_1−12\\right)\\Rightarrow ℓ_1=20cmWebsite: thukhoadaihoc.vn$<br>Thể tích giảm  $\\Rightarrow$  Khí nhận công<br>d) đúng","difficultySource":"ai"}}]},{"id":651919,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"2,3","question":"Cho 10 gam Oxygen ở nhiệt độ 150C và áp suất 2,77.10<sup>5</sup> N/m2 dãn nở đẳng áp đến thể tích 6 lít. Biết khối lượng mol của phân tử Oxygen là 32 g/mol, nhiệt dung riêng đẳng áp của khí là cp = 0,9 kJ/(kg. K). Độ biến thiên nội năng của khí là bao nhiêu kJ? (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"kho","explanation":"Công thức: số mol n = m/M; thể tích ban đầu từ pt trạng thái khí lí tưởng V1 = nRT1/p1; đẳng áp nên T2 = T1·V2/V1; độ biến thiên nội năng khí lí tưởng ΔU = m·cv·ΔT với cv = cp − R/M.<br>Thay số: n = 10/32 = 0,3125 mol; T1 = 15+273 = 288 K; V1 = 0,3125×8,31×288/2,77.10^5 ≈ 2,7.10⁻³ m³ = 2,7 lít; T2 = 288×6/2,7 ≈ 640 K → ΔT = 352 K.<br>cv = 900 − 8,31/0,032 ≈ 640,3 J/(kg.K); ΔU = 0,01×640,3×352 ≈ 2253,9 J ≈ 2,3 kJ.<br>$n=\\frac{m}{M}=\\frac{10}{32}=0,3125 mol$<br>$\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}=nR\\Rightarrow \\frac{2,77.10^5.V_1}{15+273}=\\frac{2,77.10^5.6.10^{−3}}{T_2}=0,3125.8,31\\Rightarrow \\left\\{\\begin{aligned}V_1=2,7.10^{−3}m^3 <br>T_2=640K\\end{aligned}\\right.$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$A=−p\\left(V_2−V_1\\right)=−2,77.10^6.\\left(6−2,7\\right).10^{−3}=−914,1J$<br>$Q=mc_p\\left(T_2−T_1\\right)=10.10^{−3}.0,9.10^3.\\left(640−15−273\\right)=3168J$<br>$\\begin{aligned}\\end{aligned}\\Delta U=Q+A=3168−914,1=2253,9J\\approx 2,3kJWebsite: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":373,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng ΔU = A + Q","answer":"2,3","question":"Cho 10 gam Oxygen ở nhiệt độ 150C và áp suất 2,77.10<sup>5</sup> N/m2 dãn nở đẳng áp đến thể tích 6 lít. Biết khối lượng mol của phân tử Oxygen là 32 g/mol, nhiệt dung riêng đẳng áp của khí là cp = 0,9 kJ/(kg. K). Độ biến thiên nội năng của khí là bao nhiêu kJ? (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"kho","explanation":"Công thức: số mol n = m/M; thể tích ban đầu từ pt trạng thái khí lí tưởng V1 = nRT1/p1; đẳng áp nên T2 = T1·V2/V1; độ biến thiên nội năng khí lí tưởng ΔU = m·cv·ΔT với cv = cp − R/M.<br>Thay số: n = 10/32 = 0,3125 mol; T1 = 15+273 = 288 K; V1 = 0,3125×8,31×288/2,77.10^5 ≈ 2,7.10⁻³ m³ = 2,7 lít; T2 = 288×6/2,7 ≈ 640 K → ΔT = 352 K.<br>cv = 900 − 8,31/0,032 ≈ 640,3 J/(kg.K); ΔU = 0,01×640,3×352 ≈ 2253,9 J ≈ 2,3 kJ.<br>$n=\\frac{m}{M}=\\frac{10}{32}=0,3125 mol$<br>$\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}=nR\\Rightarrow \\frac{2,77.10^5.V_1}{15+273}=\\frac{2,77.10^5.6.10^{−3}}{T_2}=0,3125.8,31\\Rightarrow \\left\\{\\begin{aligned}V_1=2,7.10^{−3}m^3 <br>T_2=640K\\end{aligned}\\right.$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$A=−p\\left(V_2−V_1\\right)=−2,77.10^6.\\left(6−2,7\\right).10^{−3}=−914,1J$<br>$Q=mc_p\\left(T_2−T_1\\right)=10.10^{−3}.0,9.10^3.\\left(640−15−273\\right)=3168J$<br>$\\begin{aligned}\\end{aligned}\\Delta U=Q+A=3168−914,1=2253,9J\\approx 2,3kJWebsite: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":652261,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":1,"options":["2,4.10<sup>13</sup> Bq.","2,8.10<sup>13</sup> Bq.","2,4.10<sup>18</sup> Bq.","2,8.10<sup>18</sup> Bq."],"question":"Chất phóng xạ   ${}_{84}^{210}{Po}$  phóng xạ tia  $\\alpha$  và biến thành hạt nhân chì Pb. Biết chu kì bán rã của chất phóng xạ là 138 ngày và ban đầu có 168 mg  ${}_{84}^{210}{Po}$ . Độ phóng xạ ban đầu của  ${}_{84}^{210}{Po}$  bằng","difficulty":"trung-binh","explanation":"Độ phóng xạ ban đầu của  ${}_{84}^{210}{Po}$ :  $H_0=\\lambda N_0=\\frac{\\ln\\left(2\\right)}{T}.\\frac{m_0.N_A}{A_{Po}}=\\frac{\\ln\\left(2\\right)\\times 0,168\\times {6,02.10}^{23}}{(138\\times 86400)\\times 210}={2,8.10}^{13}Bq$<br>Sử dụng các thông tin sau cho câu 13 và câu 14: Tại nhiều khách sạn hiện nay, hệ thống mở cửa sử dụng thẻ từ thông minh. Trên thẻ từ có một dải từ chứa các hạt từ tính nhỏ và chúng được từ hóa trở thành một chuỗi nam châm nhỏ nối tiếp nhau. Bên trong đầu đọc có một cuộn dây, khi quẹt thẻ quét qua đầu đọc dẫn đến xuất hiện dòng điện giúp tín hiệu sẽ được truyền đi và cửa sẽ mở.<br>Biết khi thẻ được quét qua đầu đọc, từ thông xuyên qua cuộn dây trong đầu đọc thay đổi đều từ 0 đến 2.10<sup>−5</sup> Wb trong khoảng thời gian 0,10s.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046388029-hinh-4.jpg\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":374,"idx":11,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":1,"options":["2,4.10<sup>13</sup> Bq.","2,8.10<sup>13</sup> Bq.","2,4.10<sup>18</sup> Bq.","2,8.10<sup>18</sup> Bq."],"question":"Chất phóng xạ   ${}_{84}^{210}{Po}$  phóng xạ tia  $\\alpha$  và biến thành hạt nhân chì Pb. Biết chu kì bán rã của chất phóng xạ là 138 ngày và ban đầu có 168 mg  ${}_{84}^{210}{Po}$ . Độ phóng xạ ban đầu của  ${}_{84}^{210}{Po}$  bằng","difficulty":"trung-binh","explanation":"Độ phóng xạ ban đầu của  ${}_{84}^{210}{Po}$ :  $H_0=\\lambda N_0=\\frac{\\ln\\left(2\\right)}{T}.\\frac{m_0.N_A}{A_{Po}}=\\frac{\\ln\\left(2\\right)\\times 0,168\\times {6,02.10}^{23}}{(138\\times 86400)\\times 210}={2,8.10}^{13}Bq$<br>Sử dụng các thông tin sau cho câu 13 và câu 14: Tại nhiều khách sạn hiện nay, hệ thống mở cửa sử dụng thẻ từ thông minh. Trên thẻ từ có một dải từ chứa các hạt từ tính nhỏ và chúng được từ hóa trở thành một chuỗi nam châm nhỏ nối tiếp nhau. Bên trong đầu đọc có một cuộn dây, khi quẹt thẻ quét qua đầu đọc dẫn đến xuất hiện dòng điện giúp tín hiệu sẽ được truyền đi và cửa sẽ mở.<br>Biết khi thẻ được quét qua đầu đọc, từ thông xuyên qua cuộn dây trong đầu đọc thay đổi đều từ 0 đến 2.10<sup>−5</sup> Wb trong khoảng thời gian 0,10s.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046388029-hinh-4.jpg\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":652277,"nq":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Vào thời kháng chiến chống Mỹ, địa đạo Củ Chi là nơi đóng quân chiến lược, trong đó có các bệnh viện dã chiến nằm sâu dưới lòng đất. Địa đạo được thiết kế hẹp và kín, nhằm tránh sự phát hiện từ phía trên, nên không khí lưu thông rất hạn chế. Để đảm bảo sự sống cho thương binh và y bác sĩ, lực lượng du kích phải dùng ống thông khí dẫn từ mặt đất xuống. Một bệnh viện dã chiến có một căn hầm nhỏ kín có thể tích khoảng 15 m3, bên trong chứa khí Oxygen tinh khiết ở nhiệt độ 30°C, áp suất 1 atm. Do bị bom đánh phá, đường ống thông khí bị sập, không thể dẫn thêm khí vào trong. Nhiệt độ trong hầm do hơi người và thiết bị tăng dần đến 42°C sau 6 giờ. Xem khí Oxygen là khí lý tưởng và thể tích của ống dẫn rất nhỏ so với thể tích của căn hầm.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046388568-hinh-7.jpg\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Áp suất của khí Oxygen trong hầm sau 6 giờ xấp xỉ bằng 1,04 atm.","answer":true},{"text":"Nếu cửa thông khí sau 6 giờ bất ngờ được khai thông trở lại, khí Oxygen trong hầm sẽ có xu hướng thoát nhanh ra ngoài theo đường thông khí.","answer":true},{"text":"Tổng số phân tử Oxygen trong căn hầm xấp xỉ 3,63.10<sup>26</sup> phân tử.","answer":true},{"text":"Nếu một chiến sĩ cần 6,0.10<sup>22</sup> phân tử oxygen/phút để duy trì sự sống cơ bản thì căn hầm có thể cung cấp đủ oxygen cho 20 người trong 6 giờ.","answer":false}],"explanation":"a) đúng<br>Áp dụng phương trình trạng thái khí lí tưởng cho khí Oxygen trong hầm:<br>$\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}$<br>Do thể tích của hầm không đổi:   $\\frac{p_1}{T_1}=\\frac{p_2}{T_2}⟹p_2\\approx 1,04 atm.$<br>b) đúng<br>Do áp suất trong hầm sau 6 giờ lớn hơn áp suất khí quyển tại mặt đất nên nếu vô tình nấp hầm được mở, do sự chênh lệch áp suất mà khí sẽ có xu hướng thoát nhanh ra ngoài theo đường dẫn khí.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>Số phân tử Oxygen có trong hầm:<br>$p_1V_1=\\frac{N}{N_A}RT_1⟹N=\\frac{p_1.V_1.N_A}{R.T_1}=\\frac{1\\times {15.10}^3\\times {6,02.10}^{23}}{0,082\\times \\left(30+273\\right)}={3,63.10}^{26} phân tử$<br>d) sai<br>Số người có thể chứa trong 6 giờ:<br>$Số người=\\frac{N}{{6,0.10}^{22}\\times 60\\times 6}\\approx 16,8⟹Tối đa 16 người.$","difficultySource":"ai"},"ex":[{"exam":374,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Vào thời kháng chiến chống Mỹ, địa đạo Củ Chi là nơi đóng quân chiến lược, trong đó có các bệnh viện dã chiến nằm sâu dưới lòng đất. Địa đạo được thiết kế hẹp và kín, nhằm tránh sự phát hiện từ phía trên, nên không khí lưu thông rất hạn chế. Để đảm bảo sự sống cho thương binh và y bác sĩ, lực lượng du kích phải dùng ống thông khí dẫn từ mặt đất xuống. Một bệnh viện dã chiến có một căn hầm nhỏ kín có thể tích khoảng 15 m3, bên trong chứa khí Oxygen tinh khiết ở nhiệt độ 30°C, áp suất 1 atm. Do bị bom đánh phá, đường ống thông khí bị sập, không thể dẫn thêm khí vào trong. Nhiệt độ trong hầm do hơi người và thiết bị tăng dần đến 42°C sau 6 giờ. Xem khí Oxygen là khí lý tưởng và thể tích của ống dẫn rất nhỏ so với thể tích của căn hầm.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046388568-hinh-7.jpg\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Áp suất của khí Oxygen trong hầm sau 6 giờ xấp xỉ bằng 1,04 atm.","answer":true},{"text":"Nếu cửa thông khí sau 6 giờ bất ngờ được khai thông trở lại, khí Oxygen trong hầm sẽ có xu hướng thoát nhanh ra ngoài theo đường thông khí.","answer":true},{"text":"Tổng số phân tử Oxygen trong căn hầm xấp xỉ 3,63.10<sup>26</sup> phân tử.","answer":true},{"text":"Nếu một chiến sĩ cần 6,0.10<sup>22</sup> phân tử oxygen/phút để duy trì sự sống cơ bản thì căn hầm có thể cung cấp đủ oxygen cho 20 người trong 6 giờ.","answer":false}],"explanation":"a) đúng<br>Áp dụng phương trình trạng thái khí lí tưởng cho khí Oxygen trong hầm:<br>$\\frac{p_1V_1}{T_1}=\\frac{p_2V_2}{T_2}$<br>Do thể tích của hầm không đổi:   $\\frac{p_1}{T_1}=\\frac{p_2}{T_2}⟹p_2\\approx 1,04 atm.$<br>b) đúng<br>Do áp suất trong hầm sau 6 giờ lớn hơn áp suất khí quyển tại mặt đất nên nếu vô tình nấp hầm được mở, do sự chênh lệch áp suất mà khí sẽ có xu hướng thoát nhanh ra ngoài theo đường dẫn khí.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>Số phân tử Oxygen có trong hầm:<br>$p_1V_1=\\frac{N}{N_A}RT_1⟹N=\\frac{p_1.V_1.N_A}{R.T_1}=\\frac{1\\times {15.10}^3\\times {6,02.10}^{23}}{0,082\\times \\left(30+273\\right)}={3,63.10}^{26} phân tử$<br>d) sai<br>Số người có thể chứa trong 6 giờ:<br>$Số người=\\frac{N}{{6,0.10}^{22}\\times 60\\times 6}\\approx 16,8⟹Tối đa 16 người.$","difficultySource":"ai"}}]},{"id":652284,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Tại cửa hàng PNJ trên đường Nguyễn Trãi (Quận 1, TP. Hồ Chí Minh), một kỹ thuật viên chế tác đang thực hiện quy trình đúc một vàng nhẫn 1 lượng (tương đương 37,5 g) từ vàng 9999 nguyên chất. Quy trình thực hiện gồm 4 bước:<br>(1) Cân và kiểm tra độ tinh khiết của vàng;<br>Bảng tra nhiệt độ nóng chảy kim loại<br>Kim loại\tNhiệt độ nóng chảy<br>Sắt\t$1538℃$<br>Đồng\t$1085℃$<br>Vàng\t$1064℃$<br>Nhôm\t$660℃$<br>Phát biểu\tĐúng\tSai<br>a) Ban đầu nhiệt độ của nguyên liệu bằng với nhiệt độ của môi trường, nhiệt lượng cần thiết để nung và nấu chảy hoàn toàn 1 lượng vàng là khoảng 74 kJ.<br>b) Nếu khuôn nhẫn làm bằng nhôm thì sản phẩm sẽ bị mất độ tinh khiết.<br>c) Để cung cấp đủ nhiệt lượng trên với hiệu suất 75% thì cần 2,2 gam gas.<br>d) Trong các bước trên, sự thay đổi trạng thái vật chất chỉ xảy ra ở bước (2).","difficulty":"kho","statements":[{"text":"(2) Đưa vàng vào lò nung để nung chảy hoàn toàn;","answer":false},{"text":"(3) Rót vàng lỏng vào khuôn nhẫn;","answer":true},{"text":"(4) Làm nguội và đánh bóng sản phẩm.","answer":false},{"text":"Biết nhiệt dung riêng của vàng là 130 J/kg.K, nhiệt nóng chảy riêng của vàng là 6,4.10<sup>4</sup> J/kg, hiệu suất của lò nung là 75%, nhiệt lượng tỏa ra khi đốt cháy hoàn toàn 1g gas là 46 kJ, nhiệt độ môi trường tại TP.HCM là  $32℃$  và bỏ qua hao hụt trong quá trình chế tác.","answer":false}],"explanation":"a) sai<br>Nhiệt lượng cần thiết để nung và nấu chảy hoàn toàn 1 lượng vàng:<br>$Q=mc\\Delta t+\\lambda m=37,5.10^{-3}\\times 130\\times \\left(1337-305\\right)+6,4.10^4\\times 37,5.10^{-3}=7431 J=7,4 Kj$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>Do nhiệt độ nóng chảy của nhôm nhỏ hơn nhiệt độ nóng chảy của vàng. Nên khi ta rót vàng lỏng vào trong khuôn nhôm thì một phần của khuôn nhôm có thể bị nóng chảy và lẫn vào bên trong vàng. Từ đó làm giảm độ tinh khiết của vàng.<br>c) sai<br>Nhiệt lượng thực tế cần cung cấp để nấu chảy hoàn toàn 1 lượng vàng:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$H=\\frac{Q}{Q_{tt}}⟹Q_{tt}=\\frac{Q}{H}=\\frac{7431}{0,75}=9908 J;$<br>Khối lượng khí gas cần để cung cấp đủ nhiệt lượng trên:<br>$m=\\frac{9908}{{46.10}^3}\\approx 0,22 g$<br>d) sai<br>(1) Cân, kiểm tra độ tinh khiết của vàng – không làm thay đổi trạng thái của nguyên liệu;<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>(2) Đưa vàng vào lò nung để nung chảy hoàn toàn – nguyên liệu từ thể rắn chuyển sang thể lỏng;<br>(3) Rót vàng lỏng vào khuôn nhẫn – không làm thay đổi trạng thái của nguyên liệu;<br>(4) Làm nguội và đánh bóng sản phẩm – nguyên liệu tử thể lỏng chuyển sang thể rắn (tại giai đoạn làm nguội).<br>Vậy tại bước (2) và (4) đều có sự chuyển thể.","difficultySource":"ai"},"ex":[{"exam":374,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Tại cửa hàng PNJ trên đường Nguyễn Trãi (Quận 1, TP. Hồ Chí Minh), một kỹ thuật viên chế tác đang thực hiện quy trình đúc một vàng nhẫn 1 lượng (tương đương 37,5 g) từ vàng 9999 nguyên chất. Quy trình thực hiện gồm 4 bước:<br>(1) Cân và kiểm tra độ tinh khiết của vàng;<br>Bảng tra nhiệt độ nóng chảy kim loại<br>Kim loại\tNhiệt độ nóng chảy<br>Sắt\t$1538℃$<br>Đồng\t$1085℃$<br>Vàng\t$1064℃$<br>Nhôm\t$660℃$<br>Phát biểu\tĐúng\tSai<br>a) Ban đầu nhiệt độ của nguyên liệu bằng với nhiệt độ của môi trường, nhiệt lượng cần thiết để nung và nấu chảy hoàn toàn 1 lượng vàng là khoảng 74 kJ.<br>b) Nếu khuôn nhẫn làm bằng nhôm thì sản phẩm sẽ bị mất độ tinh khiết.<br>c) Để cung cấp đủ nhiệt lượng trên với hiệu suất 75% thì cần 2,2 gam gas.<br>d) Trong các bước trên, sự thay đổi trạng thái vật chất chỉ xảy ra ở bước (2).","difficulty":"kho","statements":[{"text":"(2) Đưa vàng vào lò nung để nung chảy hoàn toàn;","answer":false},{"text":"(3) Rót vàng lỏng vào khuôn nhẫn;","answer":true},{"text":"(4) Làm nguội và đánh bóng sản phẩm.","answer":false},{"text":"Biết nhiệt dung riêng của vàng là 130 J/kg.K, nhiệt nóng chảy riêng của vàng là 6,4.10<sup>4</sup> J/kg, hiệu suất của lò nung là 75%, nhiệt lượng tỏa ra khi đốt cháy hoàn toàn 1g gas là 46 kJ, nhiệt độ môi trường tại TP.HCM là  $32℃$  và bỏ qua hao hụt trong quá trình chế tác.","answer":false}],"explanation":"a) sai<br>Nhiệt lượng cần thiết để nung và nấu chảy hoàn toàn 1 lượng vàng:<br>$Q=mc\\Delta t+\\lambda m=37,5.10^{-3}\\times 130\\times \\left(1337-305\\right)+6,4.10^4\\times 37,5.10^{-3}=7431 J=7,4 Kj$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>Do nhiệt độ nóng chảy của nhôm nhỏ hơn nhiệt độ nóng chảy của vàng. Nên khi ta rót vàng lỏng vào trong khuôn nhôm thì một phần của khuôn nhôm có thể bị nóng chảy và lẫn vào bên trong vàng. Từ đó làm giảm độ tinh khiết của vàng.<br>c) sai<br>Nhiệt lượng thực tế cần cung cấp để nấu chảy hoàn toàn 1 lượng vàng:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$H=\\frac{Q}{Q_{tt}}⟹Q_{tt}=\\frac{Q}{H}=\\frac{7431}{0,75}=9908 J;$<br>Khối lượng khí gas cần để cung cấp đủ nhiệt lượng trên:<br>$m=\\frac{9908}{{46.10}^3}\\approx 0,22 g$<br>d) sai<br>(1) Cân, kiểm tra độ tinh khiết của vàng – không làm thay đổi trạng thái của nguyên liệu;<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>(2) Đưa vàng vào lò nung để nung chảy hoàn toàn – nguyên liệu từ thể rắn chuyển sang thể lỏng;<br>(3) Rót vàng lỏng vào khuôn nhẫn – không làm thay đổi trạng thái của nguyên liệu;<br>(4) Làm nguội và đánh bóng sản phẩm – nguyên liệu tử thể lỏng chuyển sang thể rắn (tại giai đoạn làm nguội).<br>Vậy tại bước (2) và (4) đều có sự chuyển thể.","difficultySource":"ai"}}]},{"id":652294,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một bộ thí nghiệm gồm một ống dây quấn nhiều vòng, rỗng lõi, hai đầu nối với hai đèn LED màu đỏ và xanh được mắc ngược chiều nhau. Khi một thanh nam châm thẳng có ghi rõ cực Bắc (N) và Nam (S) được đưa nhanh vào trong lõi ống dây, ta thấy một đèn sáng lên; khi rút nam châm ra, đèn còn lại sáng. Nếu tiếp tục thao tác này liên tục, hai đèn LED sẽ sáng luân phiên.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046388843-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong thí nghiệm, khi thanh nam châm chuyển động ra – vào lồng ống dây, trong mạch xuất hiện dòng điện cảm ứng.","answer":true},{"text":"Hai đèn LED sáng luân phiên vì dòng điện cảm ứng chỉ đủ cung cấp năng lượng cho một bóng đèn tại mỗi thời điểm.","answer":false},{"text":"Nếu ta tịnh tiến nam châm cách xa ống dây một khoảng và xoay nam châm quanh trục thẳng đứng thì hai đèn LED cũng sẽ sáng luân phiên.","answer":true},{"text":"Giả sử thay hai đèn LED bằng ampere kế, người ta đo được dòng điện cực đại là 30 mA khi rút nam châm ra khỏi ống dây trong 0,05 s. Biết từ thông cực đại xuyên qua mỗi vòng dây là 6,0.10<sup>−5</sup> Wb và điện trở trong mạch là 20 Ω thì ta có thể kết luận số vòng dây quấn là 450 vòng.","answer":false}],"explanation":"a) đúng<br>Khi nam châm chuyển động ra – vào lồng ống dây  từ thông xuyên qua tiết diện ống dây biến thiên. Dựa theo hiện tượng cản ứng điện từ thì trong ống dây sẽ xuất hiện dòng điện cảm ứng.<br>b) sai<br>Do đèn LED là Diode có khả năng phát ra ánh sáng và chỉ cho dùng điện đi qua theo một chiều. Theo đề bài, hai đèn này được mắc ngược chiều nhau. Khi ta luân phiên kéo – rút nam châm qua lồng ống dây thì trong ống dây sẽ xuất hiện dòng điện cảm ứng đổi chiều liên tục. Khi này, hai đèn LED sẽ sáng luân phiên nhau do dòng điện đổi chiều liên tục.<br>c) đúng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046389075-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Nếu ta xoay nam châm quanh trục thẳng đứng thì từ thông xuyên qua ống dây sẽ biến thiên và trong ống dây sẽ xuất hiện dòng điện cảm ứng đổi chiều liên tục làm cho hai đèn sáng luân phiên.<br>d) sai<br>Suất điện động cảm ứng có độ lớn:<br>$e$ c=−N∆Φ∆t⟺R.Ic=N∆Φ∆t<br>Số vòng dây quấn:<br>N=R.Ic.∆t∆Φ=20×30.10<sup>−3</sup>×0,056,0.10<sup>−5</sup>=500 vòng.","difficultySource":"ai"},"ex":[{"exam":374,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một bộ thí nghiệm gồm một ống dây quấn nhiều vòng, rỗng lõi, hai đầu nối với hai đèn LED màu đỏ và xanh được mắc ngược chiều nhau. Khi một thanh nam châm thẳng có ghi rõ cực Bắc (N) và Nam (S) được đưa nhanh vào trong lõi ống dây, ta thấy một đèn sáng lên; khi rút nam châm ra, đèn còn lại sáng. Nếu tiếp tục thao tác này liên tục, hai đèn LED sẽ sáng luân phiên.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046388843-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong thí nghiệm, khi thanh nam châm chuyển động ra – vào lồng ống dây, trong mạch xuất hiện dòng điện cảm ứng.","answer":true},{"text":"Hai đèn LED sáng luân phiên vì dòng điện cảm ứng chỉ đủ cung cấp năng lượng cho một bóng đèn tại mỗi thời điểm.","answer":false},{"text":"Nếu ta tịnh tiến nam châm cách xa ống dây một khoảng và xoay nam châm quanh trục thẳng đứng thì hai đèn LED cũng sẽ sáng luân phiên.","answer":true},{"text":"Giả sử thay hai đèn LED bằng ampere kế, người ta đo được dòng điện cực đại là 30 mA khi rút nam châm ra khỏi ống dây trong 0,05 s. Biết từ thông cực đại xuyên qua mỗi vòng dây là 6,0.10<sup>−5</sup> Wb và điện trở trong mạch là 20 Ω thì ta có thể kết luận số vòng dây quấn là 450 vòng.","answer":false}],"explanation":"a) đúng<br>Khi nam châm chuyển động ra – vào lồng ống dây  từ thông xuyên qua tiết diện ống dây biến thiên. Dựa theo hiện tượng cản ứng điện từ thì trong ống dây sẽ xuất hiện dòng điện cảm ứng.<br>b) sai<br>Do đèn LED là Diode có khả năng phát ra ánh sáng và chỉ cho dùng điện đi qua theo một chiều. Theo đề bài, hai đèn này được mắc ngược chiều nhau. Khi ta luân phiên kéo – rút nam châm qua lồng ống dây thì trong ống dây sẽ xuất hiện dòng điện cảm ứng đổi chiều liên tục. Khi này, hai đèn LED sẽ sáng luân phiên nhau do dòng điện đổi chiều liên tục.<br>c) đúng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046389075-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Nếu ta xoay nam châm quanh trục thẳng đứng thì từ thông xuyên qua ống dây sẽ biến thiên và trong ống dây sẽ xuất hiện dòng điện cảm ứng đổi chiều liên tục làm cho hai đèn sáng luân phiên.<br>d) sai<br>Suất điện động cảm ứng có độ lớn:<br>$e$ c=−N∆Φ∆t⟺R.Ic=N∆Φ∆t<br>Số vòng dây quấn:<br>N=R.Ic.∆t∆Φ=20×30.10<sup>−3</sup>×0,056,0.10<sup>−5</sup>=500 vòng.","difficultySource":"ai"}}]},{"id":652296,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Ngày 12/9/2014, một sự cố nghiêm trọng xảy ra tại TP.HCM khi Công ty TNHH Apave Châu Á – Thái Bình Dương báo cáo bị thất lạc một thiết bị chứa nguồn phóng xạ Iridium - ${}_{}^{192}{Ir}$  dùng trong kiểm tra mối hàn công nghiệp. Theo hồ sơ ghi nhận vào thời điểm bàn giao thiết bị, nguồn  ${}_{}^{192}{Ir}$  có khối lượng ban đầu 5,0 g, được cất giữ trong một thiết bị bọc chì chuyên dụng. Chu kỳ bán rã của  ${}_{}^{192}{Ir}$  là khoảng 74 ngày và mỗi phân rã phát ra tia gamma mạnh. Một năm sau sự cố, các nhà chức trách tiến hành rà soát lại các thiết bị còn tồn đọng, đồng thời đo hoạt độ còn lại để xác định mức độ nguy hiểm.","difficulty":"kho","statements":[{"text":"Hằng số phóng xạ của  ${}_{}^{192}{Ir}$  xấp xỉ bằng 9,4.10<sup>−3</sup> s-1.","answer":false},{"text":"Bức xạ gamma trong quá trình phân rã có khả năng gây tổn thương sinh học ở khoảng cách vài mét nếu không được che chắn đúng cách.","answer":true},{"text":"Sau đúng 1 năm (365 ngày), lượng  ${}_{}^{192}{Ir}$  còn lại trong nguồn ban đầu chỉ khoảng 4,84 g.","answer":false},{"text":"Sau khi tìm lại được nguồn phóng xạ, cơ quan chức năng đo được hoạt độ còn lại là 0,038 TBq. Biết giới hạn cho phép để công bố “nguồn an toàn” là dưới 0,005 TBq. Vậy cần ít nhất 217 ngày mới có thể tháo gỡ cách ly và xử lý như chất thải thông thường.","answer":true}],"explanation":"a) sai<br>Hằng số phóng xạ của  ${}_{}^{192}{Ir}$ :<br>$\\lambda =\\frac{\\ln\\left(2\\right)}{T}=\\frac{\\ln\\left(2\\right)}{74\\times 86400}={1,08.10}^{-7} s^{-1}$<br>b) đúng<br>Tia gamma là bức xạ ion hóa và có thể gây tổn thương cho các cơ quan, tế bào và tăng nguy cơ ung thư ở con người nếu tiếp xúc với mức độ cao.<br>c) sai<br>Khối lượng  ${}_{}^{192}{Ir}$  còn lại trong nguồn:  $m=m_0.2^{-\\frac{t}{T}}=5,0\\times 2^{-\\frac{365}{74}}=0,16 g$<br>d) đúng<br>Để có thể tháo gỡ cách ly và xử lý nguồn như chất thải thông thường:<br>$H<0,005⟺H_0.2^{-\\frac{t}{T}}<H\\Leftrightarrow 0,038\\times 2^{-\\frac{t}{74}}<0,005⟹t>216,5 ngày.$<br>Vậy cần ít nhất 217 ngày mới có thể tháo gỡ cách ly và xử lý nguồn như chất thải thông thường.","difficultySource":"ai"},"ex":[{"exam":374,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Ngày 12/9/2014, một sự cố nghiêm trọng xảy ra tại TP.HCM khi Công ty TNHH Apave Châu Á – Thái Bình Dương báo cáo bị thất lạc một thiết bị chứa nguồn phóng xạ Iridium - ${}_{}^{192}{Ir}$  dùng trong kiểm tra mối hàn công nghiệp. Theo hồ sơ ghi nhận vào thời điểm bàn giao thiết bị, nguồn  ${}_{}^{192}{Ir}$  có khối lượng ban đầu 5,0 g, được cất giữ trong một thiết bị bọc chì chuyên dụng. Chu kỳ bán rã của  ${}_{}^{192}{Ir}$  là khoảng 74 ngày và mỗi phân rã phát ra tia gamma mạnh. Một năm sau sự cố, các nhà chức trách tiến hành rà soát lại các thiết bị còn tồn đọng, đồng thời đo hoạt độ còn lại để xác định mức độ nguy hiểm.","difficulty":"kho","statements":[{"text":"Hằng số phóng xạ của  ${}_{}^{192}{Ir}$  xấp xỉ bằng 9,4.10<sup>−3</sup> s-1.","answer":false},{"text":"Bức xạ gamma trong quá trình phân rã có khả năng gây tổn thương sinh học ở khoảng cách vài mét nếu không được che chắn đúng cách.","answer":true},{"text":"Sau đúng 1 năm (365 ngày), lượng  ${}_{}^{192}{Ir}$  còn lại trong nguồn ban đầu chỉ khoảng 4,84 g.","answer":false},{"text":"Sau khi tìm lại được nguồn phóng xạ, cơ quan chức năng đo được hoạt độ còn lại là 0,038 TBq. Biết giới hạn cho phép để công bố “nguồn an toàn” là dưới 0,005 TBq. Vậy cần ít nhất 217 ngày mới có thể tháo gỡ cách ly và xử lý như chất thải thông thường.","answer":true}],"explanation":"a) sai<br>Hằng số phóng xạ của  ${}_{}^{192}{Ir}$ :<br>$\\lambda =\\frac{\\ln\\left(2\\right)}{T}=\\frac{\\ln\\left(2\\right)}{74\\times 86400}={1,08.10}^{-7} s^{-1}$<br>b) đúng<br>Tia gamma là bức xạ ion hóa và có thể gây tổn thương cho các cơ quan, tế bào và tăng nguy cơ ung thư ở con người nếu tiếp xúc với mức độ cao.<br>c) sai<br>Khối lượng  ${}_{}^{192}{Ir}$  còn lại trong nguồn:  $m=m_0.2^{-\\frac{t}{T}}=5,0\\times 2^{-\\frac{365}{74}}=0,16 g$<br>d) đúng<br>Để có thể tháo gỡ cách ly và xử lý nguồn như chất thải thông thường:<br>$H<0,005⟺H_0.2^{-\\frac{t}{T}}<H\\Leftrightarrow 0,038\\times 2^{-\\frac{t}{74}}<0,005⟹t>216,5 ngày.$<br>Vậy cần ít nhất 217 ngày mới có thể tháo gỡ cách ly và xử lý nguồn như chất thải thông thường.","difficultySource":"ai"}}]},{"id":655624,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Phản ứng phân hạch, phản ứng nhiệt hạch","answer":3,"options":["Phản ứng 1 là phản ứng nhiệt hạch, năng lượng tỏa ra khi sử dụng hết 50 g  ${}_{92}^{235}U$  xấp xỉ bằng 2,56.10<sup>25</sup> MeV.","Phản ứng 2 là phản ứng phân hạch, năng lượng tỏa ra khi thu được 50 g  ${}_1^2D$  xấp xỉ bằng 3,36.10<sup>25</sup> MeV.","Xét về năng lượng tỏa ra của một phản ứng thì phản ứng nhiệt hạch có giá trị lớn hơn phản ứng phân hạch.","Tổng năng lượng tỏa ra ở phản ứng 2 lớn gấp khoảng 1,3 lần tổng năng lượng tỏa ra ở phản ứng 1."],"question":"Xét lần lượt hai phản ứng sau:<br>+ Phản ứng 1:  ${}_{92}^{235}U$  +  ${}_0^1n$    ${}_{60}^{143}{Nd}$  +  ${}_{40}^{90}{Zr}$  + 3 ${}_0^1n$  + 8 ${}_{-1}^0e$  +  $8\\overline{{}_e}$  + 200 MeV. Khối lượng của  ${}_{92}^{235}U$  được sử dụng trong phản ứng 1 là 50 g.<br>+ Phản ứng 2:  ${}_1^1H$  +  ${}_0^1n$    ${}_1^2D$  + 2,23 MeV. Khối lượng của  ${}_1^2D$  tạo thành từ phản ứng 2 là 50 g.<br>Nhận định nào sau đây đúng?","difficulty":"kho","explanation":"Năng lượng tỏa ra khi sử dụng hết 50 g  ${}_{92}^{235}U$  là:<br>$E_1=N_{U235}.200=\\frac{m}{M}.N_A.200=\\frac{50}{235}.6,02.{10}^{23}.200\\approx 2,56.{10}^{25}$  MeV.<br>Năng lượng tỏa ra khi thu được 50 g  ${}_1^2D$  là:<br>$E_2=N_{D2}.2,23=\\frac{m}{M}.N_A.2,23=\\frac{50}{2}.6,02.{10}^{23}.2,23\\approx 3,36.{10}^{25}$  MeV.<br>Tổng năng lượng tỏa ra ở phản ứng 2 lớn gấp  $\\frac{E_2}{E_1}=\\frac{3,36.{10}^{25}}{2,56.{10}^{25}}\\approx 1,3$  lần tổng năng lượng tỏa ra ở phản ứng 1. Vậy nhận định D đúng.<br>Nhận định A sai. Vì phản ứng 1 là phản ứng phân hạch.<br>Nhận định B sai. Vì phản ứng 2 là phản ứng nhiệt hạch.<br>Nhận định C sai. Vì khi xét về năng lượng tỏa ra của một phản ứng thì phản ứng nhiệt hạch (phản ứng 2, toả ra 2,23 MeV) có giá trị nhỏ hơn phản ứng phân hạch (phản ứng 1, toả ra 200 MeV).<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":376,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Phản ứng phân hạch, phản ứng nhiệt hạch","answer":3,"options":["Phản ứng 1 là phản ứng nhiệt hạch, năng lượng tỏa ra khi sử dụng hết 50 g  ${}_{92}^{235}U$  xấp xỉ bằng 2,56.10<sup>25</sup> MeV.","Phản ứng 2 là phản ứng phân hạch, năng lượng tỏa ra khi thu được 50 g  ${}_1^2D$  xấp xỉ bằng 3,36.10<sup>25</sup> MeV.","Xét về năng lượng tỏa ra của một phản ứng thì phản ứng nhiệt hạch có giá trị lớn hơn phản ứng phân hạch.","Tổng năng lượng tỏa ra ở phản ứng 2 lớn gấp khoảng 1,3 lần tổng năng lượng tỏa ra ở phản ứng 1."],"question":"Xét lần lượt hai phản ứng sau:<br>+ Phản ứng 1:  ${}_{92}^{235}U$  +  ${}_0^1n$    ${}_{60}^{143}{Nd}$  +  ${}_{40}^{90}{Zr}$  + 3 ${}_0^1n$  + 8 ${}_{-1}^0e$  +  $8\\overline{{}_e}$  + 200 MeV. Khối lượng của  ${}_{92}^{235}U$  được sử dụng trong phản ứng 1 là 50 g.<br>+ Phản ứng 2:  ${}_1^1H$  +  ${}_0^1n$    ${}_1^2D$  + 2,23 MeV. Khối lượng của  ${}_1^2D$  tạo thành từ phản ứng 2 là 50 g.<br>Nhận định nào sau đây đúng?","difficulty":"kho","explanation":"Năng lượng tỏa ra khi sử dụng hết 50 g  ${}_{92}^{235}U$  là:<br>$E_1=N_{U235}.200=\\frac{m}{M}.N_A.200=\\frac{50}{235}.6,02.{10}^{23}.200\\approx 2,56.{10}^{25}$  MeV.<br>Năng lượng tỏa ra khi thu được 50 g  ${}_1^2D$  là:<br>$E_2=N_{D2}.2,23=\\frac{m}{M}.N_A.2,23=\\frac{50}{2}.6,02.{10}^{23}.2,23\\approx 3,36.{10}^{25}$  MeV.<br>Tổng năng lượng tỏa ra ở phản ứng 2 lớn gấp  $\\frac{E_2}{E_1}=\\frac{3,36.{10}^{25}}{2,56.{10}^{25}}\\approx 1,3$  lần tổng năng lượng tỏa ra ở phản ứng 1. Vậy nhận định D đúng.<br>Nhận định A sai. Vì phản ứng 1 là phản ứng phân hạch.<br>Nhận định B sai. Vì phản ứng 2 là phản ứng nhiệt hạch.<br>Nhận định C sai. Vì khi xét về năng lượng tỏa ra của một phản ứng thì phản ứng nhiệt hạch (phản ứng 2, toả ra 2,23 MeV) có giá trị nhỏ hơn phản ứng phân hạch (phản ứng 1, toả ra 200 MeV).<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":655625,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":1,"options":["3,87.10<sup>16</sup> Bq.","3,87.10<sup>13</sup> Bq.","1,39.10<sup>20</sup> Bq.","1,39.10<sup>17</sup> Bq."],"question":"Chất phóng xạ chứa đồng vị  ${}_{11}^{24}{Na}$  được sử dụng làm chất đánh dấu điện giải có chu kì bán rã là 15 giờ. Một bệnh nhân được tiêm 5 mℓ dược chất chứa hoàn toàn  ${}_{11}^{24}{Na}$  với nồng độ 1,002.10<sup>3</sup> moℓ/ℓ. Độ phóng xạ của liều dược chất tại thời điểm tiêm là","difficulty":"trung-binh","explanation":"Số moℓ  ${}_{11}^{24}{Na}$  trong 5 mℓ:  $n=C_M.V=1,002.{10}^{-3}.5.{10}^{-3}=5,01.{10}^{-6}$  moℓ.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Độ phóng xạ của liều dược chất tại thời điểm tiêm là:<br>$H=.N=\\frac{\\ln\\left(2\\right)}{T}.n.N_A=\\frac{\\ln\\left(2\\right)}{15.3600}.5,01.{10}^{-6}.6,02.{10}^{23}\\approx 3,87.{10}^{13}$  Bq.","difficultySource":"ai"},"ex":[{"exam":376,"idx":17,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":1,"options":["3,87.10<sup>16</sup> Bq.","3,87.10<sup>13</sup> Bq.","1,39.10<sup>20</sup> Bq.","1,39.10<sup>17</sup> Bq."],"question":"Chất phóng xạ chứa đồng vị  ${}_{11}^{24}{Na}$  được sử dụng làm chất đánh dấu điện giải có chu kì bán rã là 15 giờ. Một bệnh nhân được tiêm 5 mℓ dược chất chứa hoàn toàn  ${}_{11}^{24}{Na}$  với nồng độ 1,002.10<sup>3</sup> moℓ/ℓ. Độ phóng xạ của liều dược chất tại thời điểm tiêm là","difficulty":"trung-binh","explanation":"Số moℓ  ${}_{11}^{24}{Na}$  trong 5 mℓ:  $n=C_M.V=1,002.{10}^{-3}.5.{10}^{-3}=5,01.{10}^{-6}$  moℓ.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Độ phóng xạ của liều dược chất tại thời điểm tiêm là:<br>$H=.N=\\frac{\\ln\\left(2\\right)}{T}.n.N_A=\\frac{\\ln\\left(2\\right)}{15.3600}.5,01.{10}^{-6}.6,02.{10}^{23}\\approx 3,87.{10}^{13}$  Bq.","difficultySource":"ai"}}]},{"id":655627,"nq":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một khối khí lí tưởng xác định thực hiện chu trình gồm các trạng thái (1)  (2)  (3)  (4)  (5). Đồ thị biểu diễn quá trình (1)  (2) là một đường hypebol. Nhiệt độ của khối khí ở trạng thái (1) là 27 C.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046430781-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"ố mol của khối khí lí tưởng xấp xỉ bằng 0,18 mol.","answer":true},{"text":"Thể tích của khối khí ở trạng thái (2) bằng 4,5.10<sup>3</sup> m3.","answer":true},{"text":"Khi khối khí biến đổi từ trạng thái (2) sang trạng thái (3), động năng tịnh tiến trung bình của mỗi phân tử khí tăng 3 lần.","answer":true},{"text":"Nhiệt độ của khối khí ở trạng thái (5) là 300 K.","answer":false}],"explanation":"a) đúng<br>Số mol của khối khí lí tưởng xấp xỉ bằng:<br>$p_1.V_1=n.R.T_1$    $n=\\frac{p_1.V_1}{R.T_1}=\\frac{3.{10}^5.1,5.{10}^{-3}}{8,31.\\left(27+273\\right)}=\\frac{50}{277}\\approx 0,18$  mol.<br>b) đúng<br>Do đồ thị biểu diễn quá trình (1)  (2) là một đường hypebol (trong hệ tọa độ p – V) nên đây là quá trình đẳng nhiệt. Khi đó, thể tích của khối khí ở trạng thái (2) là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$p_1.V_1=p_2.V_2$    $V_2=\\frac{p_1.V_1}{p_2}=\\frac{3.{10}^5.1,5.{10}^{-3}}{{10}^5}=4,5.{10}^{-3}$  m3.<br>c) đúng<br>Khi khối khí biến đổi từ trạng thái (2) sang trạng thái (3), ta có:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\frac{E_{đ3}}{E_{đ2}}=\\frac{\\frac{3}{2}kT_3}{\\frac{3}{2}kT_2}=\\frac{T_3}{T_2}$<br>Theo đồ thị, từ trạng thái (2) sang trạng thái (3) là quá trình đẳng tích, nên ta có:<br>$\\frac{p_3}{T_3}=\\frac{p_2}{T_2}$    $\\frac{T_3}{T_2}=\\frac{p_3}{p_2}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Suy ra:  $\\frac{E_{đ3}}{E_{đ2}}=\\frac{p_3}{p_2}=\\frac{3.{10}^5}{{10}^5}=3$<br>Vậy khi khối khí biến đổi từ trạng thái (2) sang trạng thái (3), động năng tịnh tiến trung bình của mỗi phân tử khí tăng 3 lần.<br>d) sai<br>Nhiệt độ của khối khí ở trạng thái (5) là:<br>$p_5.V_5=n.R.T_5$    $T_5=\\frac{p_5.V_5}{n.R}=\\frac{3.{10}^5.1,5.4,5.{10}^{-3}}{\\frac{50}{277}.8,31}=1350$  K.","difficultySource":"ai"},"ex":[{"exam":376,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một khối khí lí tưởng xác định thực hiện chu trình gồm các trạng thái (1)  (2)  (3)  (4)  (5). Đồ thị biểu diễn quá trình (1)  (2) là một đường hypebol. Nhiệt độ của khối khí ở trạng thái (1) là 27 C.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046430781-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"ố mol của khối khí lí tưởng xấp xỉ bằng 0,18 mol.","answer":true},{"text":"Thể tích của khối khí ở trạng thái (2) bằng 4,5.10<sup>3</sup> m3.","answer":true},{"text":"Khi khối khí biến đổi từ trạng thái (2) sang trạng thái (3), động năng tịnh tiến trung bình của mỗi phân tử khí tăng 3 lần.","answer":true},{"text":"Nhiệt độ của khối khí ở trạng thái (5) là 300 K.","answer":false}],"explanation":"a) đúng<br>Số mol của khối khí lí tưởng xấp xỉ bằng:<br>$p_1.V_1=n.R.T_1$    $n=\\frac{p_1.V_1}{R.T_1}=\\frac{3.{10}^5.1,5.{10}^{-3}}{8,31.\\left(27+273\\right)}=\\frac{50}{277}\\approx 0,18$  mol.<br>b) đúng<br>Do đồ thị biểu diễn quá trình (1)  (2) là một đường hypebol (trong hệ tọa độ p – V) nên đây là quá trình đẳng nhiệt. Khi đó, thể tích của khối khí ở trạng thái (2) là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$p_1.V_1=p_2.V_2$    $V_2=\\frac{p_1.V_1}{p_2}=\\frac{3.{10}^5.1,5.{10}^{-3}}{{10}^5}=4,5.{10}^{-3}$  m3.<br>c) đúng<br>Khi khối khí biến đổi từ trạng thái (2) sang trạng thái (3), ta có:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\frac{E_{đ3}}{E_{đ2}}=\\frac{\\frac{3}{2}kT_3}{\\frac{3}{2}kT_2}=\\frac{T_3}{T_2}$<br>Theo đồ thị, từ trạng thái (2) sang trạng thái (3) là quá trình đẳng tích, nên ta có:<br>$\\frac{p_3}{T_3}=\\frac{p_2}{T_2}$    $\\frac{T_3}{T_2}=\\frac{p_3}{p_2}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Suy ra:  $\\frac{E_{đ3}}{E_{đ2}}=\\frac{p_3}{p_2}=\\frac{3.{10}^5}{{10}^5}=3$<br>Vậy khi khối khí biến đổi từ trạng thái (2) sang trạng thái (3), động năng tịnh tiến trung bình của mỗi phân tử khí tăng 3 lần.<br>d) sai<br>Nhiệt độ của khối khí ở trạng thái (5) là:<br>$p_5.V_5=n.R.T_5$    $T_5=\\frac{p_5.V_5}{n.R}=\\frac{3.{10}^5.1,5.4,5.{10}^{-3}}{\\frac{50}{277}.8,31}=1350$  K.","difficultySource":"ai"}}]}]$j$::jsonb) loop
    h := public.question_content_hash(r->'nq');
    if exists (select 1 from public.question_bank where content_hash = h and id <> (r->>'id')::bigint) then raise notice 'TRUNG %', r->>'id'; continue; end if;
    update public.question_bank set question = r->'nq', content_hash = h, updated_at = now() where id = (r->>'id')::bigint;
    for e in select * from jsonb_array_elements(r->'ex') loop
      update public.exams set questions = jsonb_set(questions, array[e->>'idx'], e->'el') where id = (e->>'exam')::bigint;
    end loop;
  end loop;
end $do$;
alter table public.exams enable trigger trg_exams_sync_bank;
commit;
